CREATE OR REPLACE FUNCTION "private"."send_push_webhook"("payload" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'private', 'public', 'net'
    AS $$
DECLARE
  cfg record;
  v_secret text;
BEGIN
  SELECT webhook_url, webhook_secret
  INTO cfg
  FROM private.push_config
  WHERE id = 1;

  IF cfg.webhook_url IS NULL OR cfg.webhook_secret IS NULL THEN
    RETURN;
  END IF;

  -- Prevent accidental copy/paste whitespace/newlines from breaking auth.
  v_secret := btrim(cfg.webhook_secret);

  PERFORM net.http_post(
    url := cfg.webhook_url,
    body := payload,
    params := '{}'::jsonb,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-push-secret', v_secret
    )
  );
EXCEPTION
  WHEN others THEN
    RETURN;
END;
$$;


ALTER FUNCTION "private"."send_push_webhook"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_profile_country_lock_policy"("p_profile_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_profile public.profiles%rowtype;
  v_region_lower text;
  v_should_lock boolean := false;
  v_next_policy text;
  v_next_origin_country text;
  v_next_origin_country_code text;
  v_next_origin_country_source text;
begin
  if p_profile_id is null then
    return;
  end if;

  select *
    into v_profile
  from public.profiles
  where id = p_profile_id
  limit 1;

  if v_profile.id is null then
    return;
  end if;

  v_region_lower := lower(btrim(coalesce(v_profile.region, '')));
  v_should_lock :=
    coalesce(v_profile.current_country_code, '') = 'GH'
    and lower(btrim(coalesce(v_profile.current_country, ''))) = 'ghana'
    and lower(btrim(coalesce(v_profile.location, ''))) = 'ghana'
    and v_profile.city is null
    and v_region_lower in (
      'ahafo',
      'ashanti',
      'bono',
      'bono east',
      'central',
      'eastern',
      'greater accra',
      'north east',
      'northern',
      'oti',
      'savannah',
      'upper east',
      'upper west',
      'volta',
      'western',
      'western north'
    )
    and coalesce(v_profile.location_precision::text, '') <> 'EXACT';

  if v_should_lock then
    v_next_policy := 'ghana_locked';
    v_next_origin_country := 'Ghana';
    v_next_origin_country_code := 'GH';
    v_next_origin_country_source := case
      when coalesce(v_profile.origin_country_source, 'unknown') = 'explicit' then 'explicit'
      else 'residence_backfill'
    end;
  elsif v_profile.country_lock_policy = 'ghana_locked'
    and v_profile.location_precision = 'EXACT'
    and coalesce(v_profile.current_country_code, '') <> ''
    and v_profile.current_country_code <> 'GH' then
    v_next_policy := 'ghana_unlocked_precise_abroad';
    v_next_origin_country := v_profile.origin_country;
    v_next_origin_country_code := v_profile.origin_country_code;
    v_next_origin_country_source := v_profile.origin_country_source;
  else
    v_next_policy := case
      when v_profile.country_lock_policy in ('ghana_locked', 'ghana_unlocked_precise_abroad') then v_profile.country_lock_policy
      else 'none'
    end;
    v_next_origin_country := v_profile.origin_country;
    v_next_origin_country_code := v_profile.origin_country_code;
    v_next_origin_country_source := v_profile.origin_country_source;
  end if;

  perform set_config('app.server_managed_update', 'on', true);

  update public.profiles
  set country_lock_policy = v_next_policy,
      current_country = case when v_next_policy = 'ghana_locked' then 'Ghana' else current_country end,
      current_country_code = case when v_next_policy = 'ghana_locked' then 'GH' else current_country_code end,
      origin_country = case when v_next_policy = 'ghana_locked' then v_next_origin_country else origin_country end,
      origin_country_code = case when v_next_policy = 'ghana_locked' then v_next_origin_country_code else origin_country_code end,
      origin_country_source = case when v_next_policy = 'ghana_locked' then v_next_origin_country_source else origin_country_source end,
      updated_at = timezone('utc'::text, now())
  where id = p_profile_id
    and (
      country_lock_policy is distinct from v_next_policy
      or (v_next_policy = 'ghana_locked' and current_country is distinct from 'Ghana')
      or (v_next_policy = 'ghana_locked' and coalesce(current_country_code, '') <> 'GH')
      or (v_next_policy = 'ghana_locked' and origin_country is distinct from v_next_origin_country)
      or (v_next_policy = 'ghana_locked' and coalesce(origin_country_code, '') is distinct from coalesce(v_next_origin_country_code, ''))
      or (v_next_policy = 'ghana_locked' and coalesce(origin_country_source, '') is distinct from coalesce(v_next_origin_country_source, ''))
    );
end;
$$;


ALTER FUNCTION "public"."apply_profile_country_lock_policy"("p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."backfill_profile_country_codes"("p_profile_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_rows integer := 0;
begin
  with source as (
    select
      profile.id,
      public.normalize_vibes_country_code(profile.current_country, profile.current_country_code) as next_current_country_code,
      public.normalize_vibes_country_code(profile.origin_country, profile.origin_country_code) as next_origin_country_code,
      case
        when nullif(btrim(coalesce(profile.current_country, '')), '') is null
          then public.normalize_vibes_country_name(profile.current_country, profile.current_country_code)
        else profile.current_country
      end as next_current_country,
      case
        when nullif(btrim(coalesce(profile.origin_country, '')), '') is null
          then public.normalize_vibes_country_name(profile.origin_country, profile.origin_country_code)
        else profile.origin_country
      end as next_origin_country
    from public.profiles profile
    where profile.deleted_at is null
      and (p_profile_ids is null or profile.id = any(p_profile_ids))
  ),
  updated as (
    update public.profiles profile
    set current_country_code = source.next_current_country_code,
        origin_country_code = source.next_origin_country_code,
        current_country = source.next_current_country,
        origin_country = source.next_origin_country,
        updated_at = timezone('utc'::text, now())
    from source
    where profile.id = source.id
      and (
        profile.current_country_code is distinct from source.next_current_country_code
        or profile.origin_country_code is distinct from source.next_origin_country_code
        or profile.current_country is distinct from source.next_current_country
        or profile.origin_country is distinct from source.next_origin_country
      )
    returning 1
  )
  select count(*) into v_rows
  from updated;

  return v_rows;
end;
$$;


ALTER FUNCTION "public"."backfill_profile_country_codes"("p_profile_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."backfill_profile_ghana_locality_promotions"("p_profile_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_rows integer := 0;
begin
  with candidates as (
    select
      profile.id,
      nullif(btrim(coalesce(profile.region, '')), '') as region_raw,
      nullif(lower(btrim(split_part(coalesce(profile.region, ''), ',', 1))), '') as region_head
    from public.profiles profile
    where profile.deleted_at is null
      and coalesce(profile.location_precision::text, '') = 'CITY'
      and nullif(btrim(coalesce(profile.city, '')), '') is null
      and nullif(btrim(coalesce(profile.region, '')), '') is not null
      and public.normalize_vibes_country_code(
        profile.current_country,
        profile.current_country_code
      ) = 'GH'
      and lower(coalesce(public.normalize_vibes_country_name(
        profile.current_country,
        profile.current_country_code
      ), '')) = 'ghana'
      and lower(coalesce(profile.location, '')) = 'ghana'
      and (p_profile_ids is null or profile.id = any(p_profile_ids))
  ),
  promoted as (
    select
      candidates.id,
      candidates.region_raw as next_city,
      candidates.region_raw as next_location
    from candidates
    where candidates.region_head is not null
      and candidates.region_head !~ '(region|district|province|state|county|municipality|metropolitan)'
      and candidates.region_head <> any(array[
        'africa',
        'north america',
        'south america',
        'europe',
        'asia',
        'oceania',
        'middle east',
        'ghana',
        'gh',
        'ahafo',
        'ashanti',
        'bono',
        'bono east',
        'central',
        'eastern',
        'greater accra',
        'north east',
        'northern',
        'oti',
        'savannah',
        'upper east',
        'upper west',
        'volta',
        'western',
        'western north'
      ])
  ),
  updated as (
    update public.profiles profile
    set city = promoted.next_city,
        location = promoted.next_location,
        updated_at = timezone('utc'::text, now())
    from promoted
    where profile.id = promoted.id
      and (
        profile.city is distinct from promoted.next_city
        or profile.location is distinct from promoted.next_location
      )
    returning 1
  )
  select count(*) into v_rows
  from updated;

  return v_rows;
end;
$$;


ALTER FUNCTION "public"."backfill_profile_ghana_locality_promotions"("p_profile_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."backfill_profile_location_labels"("p_profile_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_rows integer := 0;
begin
  with source as (
    select
      profile.id,
      profile.location_precision::text as location_precision,
      nullif(btrim(coalesce(profile.city, '')), '') as city_raw,
      nullif(btrim(coalesce(profile.region, '')), '') as region_raw,
      nullif(btrim(coalesce(profile.location, '')), '') as location_raw,
      public.normalize_vibes_country_name(
        profile.current_country,
        profile.current_country_code
      ) as current_country_norm,
      public.normalize_vibes_country_code(
        profile.current_country,
        profile.current_country_code
      ) as current_country_code_norm
    from public.profiles profile
    where profile.deleted_at is null
      and (p_profile_ids is null or profile.id = any(p_profile_ids))
  ),
  classified as (
    select
      source.*,
      nullif(lower(btrim(split_part(coalesce(source.city_raw, ''), ',', 1))), '') as city_head,
      nullif(lower(btrim(split_part(coalesce(source.region_raw, ''), ',', 1))), '') as region_head,
      nullif(lower(btrim(split_part(coalesce(source.location_raw, ''), ',', 1))), '') as location_head,
      nullif(lower(btrim(coalesce(source.current_country_norm, ''))), '') as country_head,
      nullif(lower(btrim(coalesce(source.current_country_code_norm, ''))), '') as country_code_head
    from source
  ),
  cleaned as (
    select
      classified.id,
      classified.location_precision,
      classified.current_country_norm,
      case
        when classified.city_raw is null then null
        when classified.city_head is null then null
        when classified.city_head = any(array[
          'africa',
          'north america',
          'south america',
          'europe',
          'asia',
          'oceania',
          'middle east'
        ]) then null
        when classified.city_head ~ '(region|district|province|state|county|municipality|metropolitan)' then null
        when classified.country_head is not null and classified.city_head = classified.country_head then null
        when classified.country_code_head is not null and classified.city_head = classified.country_code_head then null
        when classified.region_head is not null and classified.city_head = classified.region_head then null
        when classified.country_code_head = 'gh' and classified.city_head = any(array[
          'ahafo',
          'ashanti',
          'bono',
          'bono east',
          'central',
          'eastern',
          'greater accra',
          'north east',
          'northern',
          'oti',
          'savannah',
          'upper east',
          'upper west',
          'volta',
          'western',
          'western north'
        ]) then null
        else classified.city_raw
      end as next_city,
      case
        when classified.region_raw is null then null
        when classified.region_head is null then null
        when classified.region_head = any(array[
          'africa',
          'north america',
          'south america',
          'europe',
          'asia',
          'oceania',
          'middle east'
        ]) then null
        when classified.country_head is not null and classified.region_head = classified.country_head then null
        when classified.country_code_head is not null and classified.region_head = classified.country_code_head then null
        else classified.region_raw
      end as next_region,
      case
        when classified.location_raw is null then null
        when classified.location_head is null then null
        when classified.location_head = any(array[
          'africa',
          'north america',
          'south america',
          'europe',
          'asia',
          'oceania',
          'middle east'
        ]) then null
        when classified.location_head ~ '(region|district|province|state|county|municipality|metropolitan)' then null
        when classified.country_head is not null and classified.location_head = classified.country_head then classified.current_country_norm
        when classified.country_code_head is not null and classified.location_head = classified.country_code_head then classified.current_country_norm
        when classified.region_head is not null and classified.location_head = classified.region_head then null
        when classified.country_code_head = 'gh' and classified.location_head = any(array[
          'ahafo',
          'ashanti',
          'bono',
          'bono east',
          'central',
          'eastern',
          'greater accra',
          'north east',
          'northern',
          'oti',
          'savannah',
          'upper east',
          'upper west',
          'volta',
          'western',
          'western north'
        ]) then null
        else classified.location_raw
      end as next_location_seed
    from classified
  ),
  resolved as (
    select
      cleaned.id,
      cleaned.next_city,
      cleaned.next_region,
      case
        when cleaned.location_precision = 'CITY'
          and cleaned.next_city is null
          and cleaned.current_country_norm is not null
          then cleaned.current_country_norm
        else coalesce(
          cleaned.next_location_seed,
          cleaned.next_city,
          cleaned.current_country_norm
        )
      end as next_location
    from cleaned
  ),
  updated as (
    update public.profiles profile
    set city = resolved.next_city,
        region = resolved.next_region,
        location = resolved.next_location,
        updated_at = timezone('utc'::text, now())
    from resolved
    where profile.id = resolved.id
      and (
        profile.city is distinct from resolved.next_city
        or profile.region is distinct from resolved.next_region
        or profile.location is distinct from resolved.next_location
      )
    returning 1
  )
  select count(*) into v_rows
  from updated;

  return v_rows;
end;
$$;


ALTER FUNCTION "public"."backfill_profile_location_labels"("p_profile_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."backfill_profile_region_city_promotions"("p_profile_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_rows integer := 0;
begin
  with candidates as (
    select
      profile.id,
      nullif(btrim(coalesce(profile.region, '')), '') as region_raw,
      nullif(lower(btrim(split_part(coalesce(profile.region, ''), ',', 1))), '') as region_head,
      public.normalize_vibes_country_name(
        profile.current_country,
        profile.current_country_code
      ) as current_country_norm,
      public.normalize_vibes_country_code(
        profile.current_country,
        profile.current_country_code
      ) as current_country_code_norm
    from public.profiles profile
    where profile.deleted_at is null
      and coalesce(profile.location_precision::text, '') = 'CITY'
      and nullif(btrim(coalesce(profile.city, '')), '') is null
      and nullif(btrim(coalesce(profile.region, '')), '') is not null
      and (
        profile.location is null
        or nullif(lower(btrim(coalesce(profile.location, ''))), '') = nullif(lower(btrim(coalesce(profile.current_country, ''))), '')
        or nullif(lower(btrim(coalesce(profile.location, ''))), '') = lower(coalesce(profile.current_country_code, ''))
      )
      and (p_profile_ids is null or profile.id = any(p_profile_ids))
  ),
  eligible as (
    select
      candidates.*
    from candidates
    where candidates.region_head is not null
      and candidates.region_head <> any(array[
        'africa',
        'north america',
        'south america',
        'europe',
        'asia',
        'oceania',
        'middle east',
        'england',
        'scotland',
        'wales',
        'northern ireland'
      ])
      and candidates.region_head !~ '(region|district|province|state|county|municipality|metropolitan)'
      and (
        candidates.current_country_norm is null
        or candidates.region_head <> lower(candidates.current_country_norm)
      )
      and (
        candidates.current_country_code_norm is null
        or candidates.region_head <> lower(candidates.current_country_code_norm)
      )
      and not (
        candidates.current_country_code_norm = 'GH'
        and candidates.region_head = any(array[
          'ahafo',
          'ashanti',
          'bono',
          'bono east',
          'central',
          'eastern',
          'greater accra',
          'north east',
          'northern',
          'oti',
          'savannah',
          'upper east',
          'upper west',
          'volta',
          'western',
          'western north'
        ])
      )
  ),
  supported_by_profiles as (
    select
      eligible.id,
      count(*)::integer as support_rows
    from eligible
    join public.profiles profile_support
      on profile_support.deleted_at is null
     and profile_support.id <> eligible.id
     and nullif(lower(btrim(coalesce(profile_support.city, ''))), '') = eligible.region_head
     and (
       (
         eligible.current_country_code_norm is not null
         and public.normalize_vibes_country_code(
           profile_support.current_country,
           profile_support.current_country_code
         ) = eligible.current_country_code_norm
       )
       or (
         eligible.current_country_code_norm is null
         and eligible.current_country_norm is not null
         and lower(coalesce(public.normalize_vibes_country_name(
           profile_support.current_country,
           profile_support.current_country_code
         ), '')) = lower(eligible.current_country_norm)
       )
     )
    group by eligible.id
  ),
  supported_by_ghana_locations as (
    select
      eligible.id,
      count(*)::integer as support_rows
    from eligible
    join public.ghana_locations ghana_location
      on eligible.current_country_code_norm = 'GH'
     and lower(btrim(ghana_location.name)) = eligible.region_head
     and lower(btrim(coalesce(ghana_location.type, ''))) not in (
       'region',
       'district',
       'province',
       'state',
       'county',
       'municipality',
       'metropolitan'
     )
     and lower(btrim(coalesce(ghana_location.type, ''))) !~ '(region|district|province|state|county|municipality|metropolitan)'
    group by eligible.id
  ),
  promoted as (
    select
      eligible.id,
      eligible.region_raw as next_city,
      eligible.region_raw as next_location
    from eligible
    left join supported_by_profiles profile_support
      on profile_support.id = eligible.id
    left join supported_by_ghana_locations ghana_support
      on ghana_support.id = eligible.id
    where coalesce(profile_support.support_rows, 0) > 0
       or coalesce(ghana_support.support_rows, 0) > 0
  ),
  updated as (
    update public.profiles profile
    set city = promoted.next_city,
        location = promoted.next_location,
        updated_at = timezone('utc'::text, now())
    from promoted
    where profile.id = promoted.id
      and (
        profile.city is distinct from promoted.next_city
        or profile.location is distinct from promoted.next_location
      )
    returning 1
  )
  select count(*) into v_rows
  from updated;

  return v_rows;
end;
$$;


ALTER FUNCTION "public"."backfill_profile_region_city_promotions"("p_profile_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bump_phone_verifications_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."bump_phone_verifications_updated_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bump_rate_limit"("p_key" "text", "p_window_seconds" integer, "p_limit" integer) RETURNS TABLE("allowed" boolean, "current_count" integer, "window_bucket_out" bigint)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_bucket bigint;
BEGIN
  v_bucket := floor(extract(epoch from now()) / p_window_seconds);

  INSERT INTO public.rate_limits (key, window_seconds, window_bucket, count, last_request_at)
  VALUES (p_key, p_window_seconds, v_bucket, 1, now())
  ON CONFLICT (key, window_seconds, window_bucket)
  DO UPDATE SET
    count = public.rate_limits.count + 1,
    last_request_at = now()
  RETURNING (public.rate_limits.count <= p_limit), public.rate_limits.count, public.rate_limits.window_bucket
  INTO allowed, current_count, window_bucket_out;

  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."bump_rate_limit"("p_key" "text", "p_window_seconds" integer, "p_limit" integer) OWNER TO "postgres";


