CREATE OR REPLACE FUNCTION "public"."calculate_cultural_compatibility"("user1_id" "uuid", "user2_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  profile1 RECORD;
  profile2 RECORD;
  score DECIMAL(3,2) := 0.0;
BEGIN
  SELECT * INTO profile1 FROM user_location_profiles WHERE user_id = user1_id;
  SELECT * INTO profile2 FROM user_location_profiles WHERE user_id = user2_id;

  IF profile1 IS NULL OR profile2 IS NULL THEN
    RETURN 0.0;
  END IF;

  -- Same hometown (highest weight)
  IF profile1.hometown = profile2.hometown THEN
    score := score + 0.4;
  END IF;

  -- Same region
  IF profile1.ghana_region = profile2.ghana_region THEN
    score := score + 0.3;
  END IF;

  -- Same tribe
  IF profile1.tribe = profile2.tribe THEN
    score := score + 0.2;
  END IF;

  -- Diaspora connection
  IF profile1.diaspora_status = 'DIASPORA' AND profile2.diaspora_status = 'DIASPORA' THEN
    score := score + 0.1;
  END IF;

  RETURN LEAST(score, 1.0); -- Cap at 1.0
END;
$$;


ALTER FUNCTION "public"."calculate_cultural_compatibility"("user1_id" "uuid", "user2_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_distance_km"("location1" "public"."geography", "location2" "public"."geography") RETURNS numeric
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF location1 IS NULL OR location2 IS NULL THEN
    RETURN NULL;
  END IF;

  -- Use ST_Distance which returns distance in meters, convert to km
  RETURN ROUND((ST_Distance(location1, location2) / 1000.0)::DECIMAL, 2);
END;
$$;


ALTER FUNCTION "public"."calculate_distance_km"("location1" "public"."geography", "location2" "public"."geography") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_user_distance"("user1_id" "uuid", "user2_id" "uuid", "include_cultural_context" boolean DEFAULT false) RETURNS TABLE("distance_km" numeric, "accuracy" "text", "method" "text", "confidence_score" numeric, "cultural_context" "jsonb")
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  profile1 RECORD;
  profile2 RECORD;
  calc_distance DECIMAL(10,2);
  calc_accuracy TEXT;
  calc_method TEXT;
  calc_confidence DECIMAL(3,2);
  cultural_data JSONB;
BEGIN
  -- Get both user profiles
  SELECT * INTO profile1 FROM user_location_profiles WHERE user_id = user1_id;
  SELECT * INTO profile2 FROM user_location_profiles WHERE user_id = user2_id;

  IF profile1 IS NULL OR profile2 IS NULL THEN
    RETURN;
  END IF;

  -- Calculate distance based on available data
  IF profile1.current_location IS NOT NULL AND profile2.current_location IS NOT NULL THEN
    -- GPS to GPS (most accurate)
    calc_distance := calculate_distance_km(profile1.current_location, profile2.current_location);
    calc_accuracy := 'gps_exact';
    calc_method := 'gps_coordinates';
    calc_confidence := 0.95;

  ELSIF profile1.current_location IS NOT NULL AND profile2.home_location IS NOT NULL THEN
    -- GPS to home location
    calc_distance := calculate_distance_km(profile1.current_location, profile2.home_location);
    calc_accuracy := 'gps_city';
    calc_method := 'gps_coordinates';
    calc_confidence := 0.85;

  ELSIF profile1.home_location IS NOT NULL AND profile2.home_location IS NOT NULL THEN
    -- Home to home
    calc_distance := calculate_distance_km(profile1.home_location, profile2.home_location);
    calc_accuracy := 'city_city';
    calc_method := 'city_centers';
    calc_confidence := 0.75;

  ELSE
    -- Fallback to region centers
    SELECT calculate_distance_km(
      (SELECT location FROM ghana_locations WHERE name = profile1.ghana_region AND type = 'region' LIMIT 1),
      (SELECT location FROM ghana_locations WHERE name = profile2.ghana_region AND type = 'region' LIMIT 1)
    ) INTO calc_distance;

    calc_accuracy := 'region_region';
    calc_method := 'region_capitals';
    calc_confidence := 0.5;
  END IF;

  -- Calculate cultural context if requested
  IF include_cultural_context THEN
    cultural_data := jsonb_build_object(
      'same_hometown', COALESCE(profile1.hometown = profile2.hometown, FALSE),
      'same_region', COALESCE(profile1.ghana_region = profile2.ghana_region, FALSE),
      'same_tribe', COALESCE(profile1.tribe = profile2.tribe, FALSE),
      'diaspora_connection', COALESCE(
        profile1.diaspora_status = 'DIASPORA' AND profile2.diaspora_status = 'DIASPORA',
        FALSE
      ),
      'cultural_distance_score', CASE
        WHEN profile1.hometown = profile2.hometown THEN 1.0
        WHEN profile1.ghana_region = profile2.ghana_region THEN 0.8
        WHEN profile1.tribe = profile2.tribe THEN 0.7
        ELSE 0.3
      END
    );
  END IF;

  RETURN QUERY SELECT calc_distance, calc_accuracy, calc_method, calc_confidence, cultural_data;
END;
$$;


ALTER FUNCTION "public"."calculate_user_distance"("user1_id" "uuid", "user2_id" "uuid", "include_cultural_context" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_invite_to_circle"("p_circle_id" "uuid", "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
begin
  if p_circle_id is null or p_user_id is null then
    return false;
  end if;

  return public.is_circle_owner(p_circle_id, p_user_id)
    or public.is_circle_member(p_circle_id, p_user_id);
end;
$$;


