CREATE OR REPLACE FUNCTION "public"."can_manage_circle_pulse"("p_circle_id" "uuid", "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_exists boolean := false;
begin
  if p_circle_id is null or p_user_id is null then
    return false;
  end if;

  if public.is_admin_user(p_user_id) or public.is_circle_owner(p_circle_id, p_user_id) then
    return true;
  end if;

  select exists (
    select 1
    from public.circle_members cm
    join public.profiles p on p.id = cm.profile_id
    where cm.circle_id = p_circle_id
      and p.user_id = p_user_id
      and cm.status = 'active'
      and lower(cm.role) in ('leader', 'host', 'admin', 'moderator')
  ) into v_exists;

  return coalesce(v_exists, false);
end;
$$;


ALTER FUNCTION "public"."can_manage_circle_pulse"("p_circle_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_post_moment"("p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_profile_id uuid;
begin
  if p_user_id is null then
    return false;
  end if;

  if exists (
    select 1
    from public.internal_admins ia
    where ia.user_id = p_user_id
  ) then
    return true;
  end if;

  select p.id
    into v_profile_id
  from public.profiles p
  where p.user_id = p_user_id
    and p.deleted_at is null
  limit 1;

  if v_profile_id is null then
    return false;
  end if;

  return exists (
    select 1
    from public.swipes s
    where (s.swiper_id = v_profile_id or s.target_id = v_profile_id)
      and s.action in ('LIKE', 'SUPERLIKE')
  )
  or exists (
    select 1
    from public.intent_requests ir
    where (ir.actor_id = v_profile_id or ir.recipient_id = v_profile_id)
      and ir.status in ('pending', 'accepted', 'matched')
  )
  or exists (
    select 1
    from public.profile_signal_gestures psg
    where (psg.sender_profile_id = v_profile_id or psg.receiver_profile_id = v_profile_id)
      and psg.status in ('sent', 'seen')
      and psg.expires_at > timezone('utc'::text, now())
  );
end;
$$;


ALTER FUNCTION "public"."can_post_moment"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_view_moment"("p_moment_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_moment public.moments%rowtype;
  v_viewer_id uuid := auth.uid();
begin
  if v_viewer_id is null or p_moment_id is null then
    return false;
  end if;

  select *
    into v_moment
  from public.moments moment
  where moment.id = p_moment_id
    and moment.is_deleted = false
    and moment.expires_at > timezone('utc'::text, now())
  limit 1;

  if v_moment.id is null then
    return false;
  end if;

  if v_moment.type in ('photo', 'video')
    and nullif(btrim(coalesce(v_moment.media_url, '')), '') is null then
    return false;
  end if;

  if v_moment.user_id = v_viewer_id or v_moment.visibility = 'public' then
    return true;
  end if;

  if v_moment.visibility = 'matches'
    and exists (
      select 1
      from public.circles circle_row
      left join public.profiles circle_owner on circle_owner.id = circle_row.created_by_profile_id
      left join public.circle_members viewer_member
        on viewer_member.circle_id = circle_row.id
       and viewer_member.status = 'active'
       and viewer_member.is_visible is not false
      left join public.profiles viewer_profile on viewer_profile.id = viewer_member.profile_id
      left join public.circle_members moment_member
        on moment_member.circle_id = circle_row.id
       and moment_member.status = 'active'
       and moment_member.is_visible is not false
      left join public.profiles moment_profile on moment_profile.id = moment_member.profile_id
      where coalesce(circle_row.archived_at, 'infinity'::timestamptz) > timezone('utc'::text, now())
        and (
          circle_row.created_by_user_id = v_viewer_id
          or circle_owner.user_id = v_viewer_id
          or viewer_member.user_id = v_viewer_id
          or viewer_profile.user_id = v_viewer_id
        )
        and (
          circle_row.created_by_user_id = v_moment.user_id
          or circle_owner.user_id = v_moment.user_id
          or moment_member.user_id = v_moment.user_id
          or moment_profile.user_id = v_moment.user_id
        )
    ) then
    return true;
  end if;

  if v_moment.visibility = 'matches' then
    return public.is_match(v_viewer_id, v_moment.user_id);
  end if;

  return false;
end;
$$;


ALTER FUNCTION "public"."can_view_moment"("p_moment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."circle_pulse_comment_reaction_summary_json"("p_comment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  select coalesce(
    (
      select jsonb_agg(
        jsonb_build_object(
          'reaction', ranked.reaction,
          'count', ranked.reaction_count
        )
        order by ranked.reaction_count desc, ranked.sort_order asc
      )
      from (
        select
          cpcr.reaction,
          count(*)::integer as reaction_count,
          case cpcr.reaction
            when 'heart' then 1
            when 'laugh' then 2
            when 'love' then 3
            when 'thumbs_up' then 4
            when 'fire' then 5
            when 'clap' then 6
            else 99
          end as sort_order
        from public.circle_pulse_comment_reactions cpcr
        where cpcr.comment_id = p_comment_id
        group by cpcr.reaction
      ) ranked
    ),
    '[]'::jsonb
  );
$$;


ALTER FUNCTION "public"."circle_pulse_comment_reaction_summary_json"("p_comment_id" "uuid") OWNER TO "postgres";


