CREATE TABLE IF NOT EXISTS "public"."messages" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "text" "text" DEFAULT ''::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "sender_id" "uuid" NOT NULL,
    "receiver_id" "uuid" NOT NULL,
    "is_read" boolean DEFAULT false NOT NULL,
    "delivered_at" timestamp with time zone,
    "message_type" "text" DEFAULT 'text'::"text" NOT NULL,
    "audio_path" "text",
    "audio_duration" numeric,
    "audio_waveform" "jsonb",
    "deleted_for_all" boolean DEFAULT false NOT NULL,
    "deleted_at" timestamp with time zone,
    "deleted_by" "uuid",
    "reply_to_message_id" "uuid",
    "edited_at" timestamp with time zone,
    "view_once" boolean DEFAULT false NOT NULL,
    "e2ee" boolean DEFAULT false NOT NULL,
    "media_kind" "text",
    "storage_path" "text",
    "enc" "jsonb",
    "status" "text" DEFAULT 'sent'::"text" NOT NULL,
    "viewed_at" timestamp with time zone,
    "viewed_by" "uuid",
    "is_view_once" boolean DEFAULT false NOT NULL,
    "encrypted_media" boolean DEFAULT false NOT NULL,
    "encrypted_media_path" "text",
    "encrypted_key_sender" "text",
    "encrypted_key_receiver" "text",
    "encrypted_key_nonce" "text",
    "encrypted_media_nonce" "text",
    "encrypted_media_alg" "text",
    "encrypted_media_mime" "text",
    "encrypted_media_size" integer,
    "client_message_id" "text",
    "read_at" timestamp with time zone,
    CONSTRAINT "cannot_message_self" CHECK (("sender_id" <> "receiver_id")),
    CONSTRAINT "message_encrypted_media_only" CHECK (((NOT "encrypted_media") OR ("message_type" = ANY (ARRAY['image'::"text", 'video'::"text"])))),
    CONSTRAINT "message_encrypted_media_requires_keys" CHECK (((NOT "encrypted_media") OR (("encrypted_key_sender" IS NOT NULL) AND ("encrypted_key_receiver" IS NOT NULL) AND ("encrypted_key_nonce" IS NOT NULL) AND ("encrypted_media_nonce" IS NOT NULL) AND ("encrypted_media_path" IS NOT NULL)))),
    CONSTRAINT "message_encrypted_media_requires_view_once" CHECK (((NOT "encrypted_media") OR ("is_view_once" = true))),
    CONSTRAINT "message_status_valid" CHECK (("status" = ANY (ARRAY['sent'::"text", 'delivered'::"text", 'viewed'::"text"]))),
    CONSTRAINT "message_type_valid" CHECK (("message_type" = ANY (ARRAY['text'::"text", 'voice'::"text", 'image'::"text", 'video'::"text", 'mood_sticker'::"text", 'location'::"text", 'view_once'::"text"]))),
    CONSTRAINT "message_view_once_media_only" CHECK (((NOT "is_view_once") OR ("message_type" = ANY (ARRAY['image'::"text", 'video'::"text"])))),
    CONSTRAINT "message_view_once_requires_encryption" CHECK (((NOT "is_view_once") OR ("encrypted_media" = true))),
    CONSTRAINT "messages_read_requires_timestamp" CHECK (((NOT "is_read") OR ("read_at" IS NOT NULL)))
);

