    new.discoverable_in_vibes = false;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_matchmaking_visibility"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_profiles_discoverability"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  -- Never allow incomplete profiles into Vibes.
  if new.profile_completed is distinct from true then
    new.discoverable_in_vibes := false;
    return new;
  end if;

  -- Keep helper/matchmaking-mode profiles out of Vibes.
  if coalesce(new.matchmaking_mode, false) = true then
    new.discoverable_in_vibes := false;
    return new;
  end if;

  -- When a profile transitions to "completed", default it to discoverable unless explicitly enabled already.
  -- This keeps the default behavior (users appear in Vibes once onboarding is done) while still hiding partial rows.
  if tg_op = 'UPDATE' and (old.profile_completed is distinct from true) and new.profile_completed is true then
    if new.discoverable_in_vibes is distinct from true then
      new.discoverable_in_vibes := true;
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_profiles_discoverability"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_circle_pulse_push"("p_target_user_id" "uuid", "p_actor_user_id" "uuid", "p_pref_kind" "text", "p_title" "text", "p_body" "text", "p_data" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_catalog'
    AS $$
begin
  if p_target_user_id is null
    or p_actor_user_id is null
    or p_target_user_id = p_actor_user_id then
    return false;
  end if;

  if exists (
    select 1
    from public.notification_prefs np
    where np.user_id = p_target_user_id
      and (
        np.push_enabled = false
        or (p_pref_kind = 'messages' and np.messages = false)
        or (p_pref_kind = 'reactions' and np.reactions = false)
        or (p_pref_kind = 'circle_discussions' and np.circle_discussions = false)
      )
  ) then
    return false;
  end if;

  if public.is_quiet_hours(p_target_user_id) then
    return false;
  end if;

  if exists (
    select 1
    from public.blocks b
    where (b.blocker_id = p_target_user_id and b.blocked_id = p_actor_user_id)
       or (b.blocker_id = p_actor_user_id and b.blocked_id = p_target_user_id)
  ) then
    return false;
  end if;

  perform private.send_push_webhook(
    jsonb_build_object(
      'user_id', p_target_user_id,
      'title', p_title,
      'body', p_body,
      'data', p_data
    )
  );

  return true;
end;
$$;


ALTER FUNCTION "public"."enqueue_circle_pulse_push"("p_target_user_id" "uuid", "p_actor_user_id" "uuid", "p_pref_kind" "text", "p_title" "text", "p_body" "text", "p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_vibes_v4_metric_refresh"("p_profile_id" "uuid", "p_visibility_dirty" boolean DEFAULT false, "p_quality_dirty" boolean DEFAULT false, "p_viewer_behavior_dirty" boolean DEFAULT false, "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if p_profile_id is null then
    return;
  end if;

  insert into public.vibes_v4_metric_refresh_queue (
    profile_id,
    visibility_dirty,
    quality_dirty,
    viewer_behavior_dirty,
    reason,
    requested_at,
    locked_at,
    processed_at,
    last_error
  )
  values (
    p_profile_id,
    coalesce(p_visibility_dirty, false),
    coalesce(p_quality_dirty, false),
    coalesce(p_viewer_behavior_dirty, false),
    nullif(btrim(coalesce(p_reason, '')), ''),
    timezone('utc'::text, now()),
    null,
    null,
    null
  )
  on conflict (profile_id) do update
    set visibility_dirty = public.vibes_v4_metric_refresh_queue.visibility_dirty or excluded.visibility_dirty,
        quality_dirty = public.vibes_v4_metric_refresh_queue.quality_dirty or excluded.quality_dirty,
        viewer_behavior_dirty = public.vibes_v4_metric_refresh_queue.viewer_behavior_dirty or excluded.viewer_behavior_dirty,
        reason = coalesce(excluded.reason, public.vibes_v4_metric_refresh_queue.reason),
        requested_at = timezone('utc'::text, now()),
        locked_at = null,
        processed_at = null,
        last_error = null;
end;
$$;


ALTER FUNCTION "public"."enqueue_vibes_v4_metric_refresh"("p_profile_id" "uuid", "p_visibility_dirty" boolean, "p_quality_dirty" boolean, "p_viewer_behavior_dirty" boolean, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_circle_pulse_welcome_member"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_joined_at timestamptz;
  v_expires_at timestamptz;
  v_welcome_member_id uuid;
  v_pulse_item_id uuid;
begin
  if not (
    new.status = 'active'
    and lower(coalesce(new.role, 'member')) = 'member'
    and (
      tg_op = 'INSERT'
      or old.status is distinct from 'active'
    )
  ) then
    return new;
  end if;

  v_joined_at := coalesce(new.joined_at, timezone('utc'::text, now()));
  v_expires_at := greatest(
    v_joined_at + interval '14 days',
    timezone('utc'::text, now()) + interval '1 minute'
  );

  insert into public.circle_pulse_welcome_members (
    circle_id,
    membership_id,
    profile_id,
    joined_at,
    expires_at
  )
  values (
    new.circle_id,
    new.id,
    new.profile_id,
    v_joined_at,
    v_expires_at
  )
  on conflict (membership_id)
  do update set status = 'active',
                joined_at = excluded.joined_at,
                expires_at = excluded.expires_at
  returning id, pulse_item_id
  into v_welcome_member_id, v_pulse_item_id;

  if v_pulse_item_id is null then
    insert into public.circle_pulse_items (
      circle_id,
      item_type,
      title,
      body,
      status,
      priority,
      starts_at,
      expires_at
    )
    values (
      new.circle_id,
      'welcome',
      'Welcome new member',
      'Say hello and help this new member feel at home in this Circle.',
      'active',
      80,
      v_joined_at,
      v_expires_at
    )
    returning id into v_pulse_item_id;

    update public.circle_pulse_welcome_members
    set pulse_item_id = v_pulse_item_id
    where id = v_welcome_member_id;
  else
    update public.circle_pulse_items
    set circle_id = new.circle_id,
        item_type = 'welcome',
        title = 'Welcome new member',
        body = 'Say hello and help this new member feel at home in this Circle.',
        status = 'active',
        priority = 80,
        starts_at = v_joined_at,
        expires_at = v_expires_at,
        updated_at = timezone('utc'::text, now())
    where id = v_pulse_item_id;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."ensure_circle_pulse_welcome_member"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."estimate_vibes_distance_km"("p_distance_km" double precision, "p_same_city" boolean, "p_same_region" boolean, "p_same_country" boolean) RETURNS double precision
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  select
    case
      when p_distance_km is not null then p_distance_km
      when coalesce(p_same_city, false) then 8::double precision
      when coalesce(p_same_region, false) then 45::double precision
      when coalesce(p_same_country, false) then 180::double precision
      else null::double precision
    end
$$;


ALTER FUNCTION "public"."estimate_vibes_distance_km"("p_distance_km" double precision, "p_same_city" boolean, "p_same_region" boolean, "p_same_country" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_active_subscription_plan"("p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS "public"."subscription_type"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_plan public.subscription_type := 'FREE';
begin
  if p_user_id is null then
    return 'FREE';
  end if;

  select s.type
    into resolved_plan
  from public.subscriptions s
  where s.user_id = p_user_id
    and s.is_active = true
    and s.ends_at > timezone('utc'::text, now())
  order by
    case s.type
      when 'GOLD' then 2
      when 'SILVER' then 1
      else 0
    end desc,
    s.ends_at desc
  limit 1;

  return coalesce(resolved_plan, 'FREE');
end;
$$;


ALTER FUNCTION "public"."get_active_subscription_plan"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_circle_location_affinities"("p_profile_id" "uuid", "p_circle_ids" "uuid"[], "p_scope" "text" DEFAULT 'my_country'::"text") RETURNS TABLE("circle_id" "uuid", "reason_code" "text", "strength" double precision, "short_text" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  with viewer as (
    select
      f.*,
      coalesce(
        array_remove(
          array[
            public.normalize_location_key(f.current_country_code),
            public.normalize_location_key(f.current_country),
            public.normalize_location_key(f.region)
          ],
          null
        ),
        array[]::text[]
      ) as diaspora_keys
    from public.profile_location_features f
    where f.profile_id = p_profile_id
      and f.user_id = auth.uid()
    limit 1
  ),
  candidate_ids as (
    select distinct candidate_id as circle_id
    from unnest(coalesce(p_circle_ids, array[]::uuid[])) candidate_id
    where candidate_id is not null
  ),
  scoped as (
    select
      c.circle_id,
      c.city,
      c.region,
      c.country_name,
      c.country_code,
      c.visibility_scope,
      c.diaspora_tags,
      c.city_key,
      c.region_key,
      c.country_key,
      c.normalized_country_code,
      (
        c.city_key is not null
        and v.city_key is not null
        and c.city_key = v.city_key
      ) as same_city,
      (
        c.region_key is not null
        and v.region_key is not null
        and c.region_key = v.region_key
      ) as same_region,
      (
        (c.normalized_country_code <> '' and v.country_code <> '' and c.normalized_country_code = v.country_code)
        or (c.country_key is not null and v.country_key is not null and c.country_key = v.country_key)
      ) as same_country,
      (
        c.visibility_scope = 'diaspora'
        or cardinality(coalesce(c.diaspora_tags, '{}'::text[])) > 0
        or exists (
          select 1
          from unnest(coalesce(c.diaspora_tags, '{}'::text[])) as tag(value)
          where public.normalize_location_key(tag.value) = any(v.diaspora_keys)
        )
      ) as diaspora_match
    from candidate_ids ids
    join public.circle_location_features c
      on c.circle_id = ids.circle_id
    join viewer v on true
  )
  select
    scoped.circle_id,
    case
      when lower(coalesce(p_scope, 'my_country')) = 'diaspora' and scoped.diaspora_match then 'diaspora_circle'
      when scoped.same_city then 'same_city'
      when scoped.same_region then 'same_region'
      when scoped.same_country then 'same_country'
      when scoped.diaspora_match then 'diaspora_circle'
      else null
    end as reason_code,
    case
      when lower(coalesce(p_scope, 'my_country')) = 'diaspora' and scoped.diaspora_match then 28
      when scoped.same_city then 30
      when scoped.same_region then 16
      when scoped.same_country then 35
      when scoped.diaspora_match then 12
      else null
    end as strength,
    case
      when lower(coalesce(p_scope, 'my_country')) = 'diaspora' and scoped.diaspora_match then
        case
          when scoped.region is not null then scoped.region || ' diaspora circle'
          else 'Diaspora circle for you'
        end
      when scoped.same_city then 'Near you in ' || scoped.city
      when scoped.same_region then scoped.region || '-based circle'
      when scoped.same_country then
        case
          when scoped.country_name is not null then scoped.country_name || '-based circle'
          else 'In your country'
        end
      when scoped.diaspora_match then
        case
          when scoped.region is not null then scoped.region || ' diaspora circle'
          else 'Diaspora circle for you'
        end
      else null
    end as short_text
  from scoped
  where
    (lower(coalesce(p_scope, 'my_country')) = 'diaspora' and scoped.diaspora_match)
    or scoped.same_city
    or scoped.same_region
    or scoped.same_country
    or scoped.diaspora_match;
$$;


ALTER FUNCTION "public"."get_circle_location_affinities"("p_profile_id" "uuid", "p_circle_ids" "uuid"[], "p_scope" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_circle_location_affinity"("p_profile_id" "uuid", "p_circle_id" "uuid", "p_scope" "text" DEFAULT 'my_country'::"text") RETURNS TABLE("reason_code" "text", "strength" double precision, "short_text" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  select
    affinity.reason_code,
    affinity.strength,
    affinity.short_text
  from public.get_circle_location_affinities(
    p_profile_id,
    array[p_circle_id],
    p_scope
  ) affinity
  limit 1;
$$;


ALTER FUNCTION "public"."get_circle_location_affinity"("p_profile_id" "uuid", "p_circle_id" "uuid", "p_scope" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_circle_pulse_comment_projection"("p_comment_id" "uuid", "p_viewer_user_id" "uuid", "p_viewer_profile_id" "uuid") RETURNS TABLE("id" "uuid", "pulse_item_id" "uuid", "circle_id" "uuid", "profile_id" "uuid", "display_name" "text", "avatar_url" "text", "body" "text", "parent_comment_id" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "edited_at" timestamp with time zone, "is_own" boolean, "can_remove" boolean, "can_edit" boolean, "can_pin" boolean, "pinned_at" timestamp with time zone, "report_count" integer, "reaction_count" integer, "my_reaction" "text", "reply_preview_profile_id" "uuid", "reply_preview_display_name" "text", "reply_preview_body" "text", "reaction_summary" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  select
    cpc.id,
    cpc.pulse_item_id,
    cpc.circle_id,
    cpc.profile_id,
    coalesce(nullif(btrim(author_profile.full_name), ''), 'Member') as display_name,
    author_profile.avatar_url,
    cpc.body,
    cpc.parent_comment_id,
    cpc.created_at,
    cpc.updated_at,
    cpc.edited_at,
    cpc.user_id = p_viewer_user_id as is_own,
    (
      cpc.user_id = p_viewer_user_id
      or public.can_manage_circle_pulse(cpc.circle_id, p_viewer_user_id)
    ) as can_remove,
    cpc.user_id = p_viewer_user_id as can_edit,
    public.can_manage_circle_pulse(cpc.circle_id, p_viewer_user_id) as can_pin,
    cpc.pinned_at,
    cpc.report_count,
    cpc.reaction_count,
    viewer_reaction.reaction as my_reaction,
    parent_comment.profile_id as reply_preview_profile_id,
    coalesce(nullif(btrim(parent_profile.full_name), ''), 'Member') as reply_preview_display_name,
    parent_comment.body as reply_preview_body,
    public.circle_pulse_comment_reaction_summary_json(cpc.id) as reaction_summary
  from public.circle_pulse_comments cpc
  join public.profiles author_profile
    on author_profile.id = cpc.profile_id
  left join public.circle_pulse_comment_reactions viewer_reaction
    on viewer_reaction.comment_id = cpc.id
   and viewer_reaction.profile_id = p_viewer_profile_id
  left join public.circle_pulse_comments parent_comment
    on parent_comment.id = cpc.parent_comment_id
   and parent_comment.status = 'active'
  left join public.profiles parent_profile
    on parent_profile.id = parent_comment.profile_id
  where cpc.id = p_comment_id
    and cpc.status = 'active';
$$;


ALTER FUNCTION "public"."get_circle_pulse_comment_projection"("p_comment_id" "uuid", "p_viewer_user_id" "uuid", "p_viewer_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_moment_relationship_cue"("p_profile_id" "uuid", "p_peer_profile_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_cue text;
  v_liked_you boolean;
  v_you_liked boolean;
begin
  if p_profile_id is null or p_peer_profile_id is null or p_profile_id = p_peer_profile_id then
    return null;
  end if;

  select ranked_intent.cue
    into v_cue
  from (
    select
      case
        when coalesce(ir.status, '') = 'matched' then 'You matched'
        when coalesce(ir.status, '') = 'accepted' then 'Door reopened'
        when ir.actor_id = p_profile_id then 'You reached out'
        else 'They reached out'
      end as cue,
      case
        when coalesce(ir.status, '') = 'matched' then 3
        when coalesce(ir.status, '') = 'accepted' then 2
        else 1
      end as priority,
      ir.created_at
    from public.intent_requests ir
    where ((ir.actor_id = p_profile_id and ir.recipient_id = p_peer_profile_id)
        or (ir.actor_id = p_peer_profile_id and ir.recipient_id = p_profile_id))
      and coalesce(ir.status, '') in ('pending', 'accepted', 'matched')
    order by priority desc, ir.created_at desc
    limit 1
  ) ranked_intent;

  if v_cue is not null then
    return v_cue;
  end if;

  select
    coalesce(bool_or(s.swiper_id = p_profile_id and s.target_id = p_peer_profile_id), false),
    coalesce(bool_or(s.swiper_id = p_peer_profile_id and s.target_id = p_profile_id), false)
  into v_you_liked, v_liked_you
  from public.swipes s
  where ((s.swiper_id = p_profile_id and s.target_id = p_peer_profile_id)
      or (s.swiper_id = p_peer_profile_id and s.target_id = p_profile_id))
    and s.action in ('LIKE', 'SUPERLIKE');

  return case
    when v_liked_you and v_you_liked then 'You liked each other'
    when v_liked_you then 'Liked you'
    when v_you_liked then 'You liked them'
    else null
  end;
end;
$$;


ALTER FUNCTION "public"."get_moment_relationship_cue"("p_profile_id" "uuid", "p_peer_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_nearby_users"("p_user_id" "uuid", "p_radius_km" numeric DEFAULT 50, "p_limit" integer DEFAULT 20) RETURNS TABLE("user_id" "uuid", "distance_km" numeric)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  user_location GEOGRAPHY(POINT, 4326);
BEGIN
  -- Get the user's current location
  SELECT current_location INTO user_location
  FROM user_location_profiles
  WHERE user_location_profiles.user_id = p_user_id;

  IF user_location IS NULL THEN
    RETURN;
  END IF;

  -- Find nearby users
  RETURN QUERY
  SELECT
    ulp.user_id,
    calculate_distance_km(user_location, ulp.current_location) as distance_km
  FROM user_location_profiles ulp
  WHERE ulp.user_id != p_user_id
    AND ulp.current_location IS NOT NULL
    AND ST_DWithin(user_location, ulp.current_location, p_radius_km * 1000) -- Convert km to meters
    AND ulp.privacy_level IN ('exact', 'city') -- Respect privacy settings
  ORDER BY ulp.current_location <-> user_location
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."get_nearby_users"("p_user_id" "uuid", "p_radius_km" numeric, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_ranked_circles_for_profile"("p_profile_id" "uuid", "p_scope" "text" DEFAULT 'my_country'::"text", "p_limit" integer DEFAULT 48) RETURNS TABLE("id" "uuid", "name" "text", "slug" "text", "description" "text", "short_description" "text", "visibility" "text", "category" "text", "created_by_profile_id" "uuid", "cover_image_url" "text", "icon_url" "text", "image_path" "text", "image_updated_at" timestamp with time zone, "circle_type" "text", "status" "text", "visibility_scope" "text", "country_code" "text", "country_name" "text", "region" "text", "city" "text", "diaspora_tags" "text"[], "culture_tags" "text"[], "faith_tags" "text"[], "interest_tags" "text"[], "audience_tags" "text"[], "is_official" boolean, "is_partner" boolean, "is_featured" boolean, "requires_join_approval" boolean, "member_count" integer, "active_this_week_count" integer, "gathering_count" integer, "archived_at" timestamp with time zone, "relevance_score" double precision, "location_insight" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  with viewer as (
    select
      f.*,
      coalesce(
        array_remove(
          array[
            public.normalize_location_key(f.current_country_code),
            public.normalize_location_key(f.current_country),
            public.normalize_location_key(f.region)
          ],
          null
        ),
        array[]::text[]
      ) as diaspora_keys
    from public.profile_location_features f
    where f.profile_id = p_profile_id
      and f.user_id = auth.uid()
    limit 1
  ),
  scoped as (
    select
      c.*,
      v.city as viewer_city,
      v.region as viewer_region,
      v.current_country as viewer_country,
      v.city_key as viewer_city_key,
      v.region_key as viewer_region_key,
      v.country_key as viewer_country_key,
      v.country_code as viewer_country_code,
      (
        c.city_key is not null
        and v.city_key is not null
        and c.city_key = v.city_key
      ) as same_city,
      (
        c.region_key is not null
        and v.region_key is not null
        and c.region_key = v.region_key
      ) as same_region,
      (
        (c.normalized_country_code <> '' and v.country_code <> '' and c.normalized_country_code = v.country_code)
        or (c.country_key is not null and v.country_key is not null and c.country_key = v.country_key)
      ) as same_country,
      (
        c.visibility_scope = 'diaspora'
        or cardinality(coalesce(c.diaspora_tags, '{}'::text[])) > 0
        or exists (
          select 1
          from unnest(coalesce(c.diaspora_tags, '{}'::text[])) as tag(value)
          where public.normalize_location_key(tag.value) = any(v.diaspora_keys)
        )
      ) as diaspora_match
    from public.circle_location_features c
    join viewer v on true
    where c.status = 'approved'
      and c.archived_at is null
      and (
        lower(coalesce(p_scope, 'my_country')) = 'global'
        or (
          lower(coalesce(p_scope, 'my_country')) = 'diaspora'
          and (
            c.visibility_scope = 'diaspora'
            or cardinality(coalesce(c.diaspora_tags, '{}'::text[])) > 0
            or exists (
              select 1
              from unnest(coalesce(c.diaspora_tags, '{}'::text[])) as tag(value)
              where public.normalize_location_key(tag.value) = any(v.diaspora_keys)
            )
          )
        )
        or (
          lower(coalesce(p_scope, 'my_country')) in ('my_country', 'near_me')
          and (
            c.visibility_scope = 'global'
            or v.country_code = ''
            or c.normalized_country_code = ''
            or c.normalized_country_code = v.country_code
            or (c.country_key is not null and v.country_key is not null and c.country_key = v.country_key)
          )
          and (
            lower(coalesce(p_scope, 'my_country')) <> 'near_me'
            or c.visibility_scope = 'global'
            or v.city_key is null
            or c.city_key is null
            or c.city_key = v.city_key
          )
        )
      )
  ),
  ranked as (
    select
      scoped.*,
      (
        case when scoped.is_official then 25 else 0 end
        + case when scoped.is_featured then 20 else 0 end
        + least(18, greatest(0, coalesce(scoped.active_this_week_count, 0)))
        + least(12, floor(greatest(0, coalesce(scoped.member_count, 0)) / 10.0))
        + case
            when lower(coalesce(p_scope, 'my_country')) = 'diaspora' and scoped.diaspora_match then 28
            when scoped.same_city then 30
            when scoped.same_region then 16
            when scoped.same_country then 35
            when scoped.diaspora_match then 12
            else 0
          end
        + case
            when lower(coalesce(p_scope, 'my_country')) = 'near_me' and scoped.visibility_scope = 'local' then 15
            when lower(coalesce(p_scope, 'my_country')) = 'my_country' and scoped.visibility_scope = 'country' then 12
            when lower(coalesce(p_scope, 'my_country')) = 'global' and scoped.visibility_scope = 'global' then 20
            when lower(coalesce(p_scope, 'my_country')) <> 'global' and scoped.visibility_scope = 'global' then -8
            else 0
          end
      )::double precision as relevance_score,
      case
        when lower(coalesce(p_scope, 'my_country')) = 'diaspora' and scoped.diaspora_match then
          case
            when scoped.region is not null then scoped.region || ' diaspora circle'
            else 'Diaspora circle for you'
          end
        when scoped.same_city then 'Near you in ' || scoped.city
        when scoped.same_region then scoped.region || '-based circle'
        when scoped.same_country then
          case
            when scoped.country_name is not null then scoped.country_name || '-based circle'
            else 'In your country'
          end
        when scoped.diaspora_match then
          case
            when scoped.region is not null then scoped.region || ' diaspora circle'
            else 'Diaspora circle for you'
          end
        else null
      end as location_insight
    from scoped
  )
  select
    ranked.circle_id as id,
    ranked.name,
    ranked.slug,
    ranked.description,
    ranked.short_description,
    ranked.visibility,
    ranked.category,
    ranked.created_by_profile_id,
    ranked.cover_image_url,
    ranked.icon_url,
    ranked.image_path,
    ranked.image_updated_at,
    ranked.circle_type,
    ranked.status,
    ranked.visibility_scope,
    ranked.country_code,
    ranked.country_name,
    ranked.region,
    ranked.city,
    ranked.diaspora_tags,
    ranked.culture_tags,
    ranked.faith_tags,
    ranked.interest_tags,
    ranked.audience_tags,
    ranked.is_official,
    ranked.is_partner,
    ranked.is_featured,
    ranked.requires_join_approval,
    ranked.member_count,
    ranked.active_this_week_count,
    ranked.gathering_count,
    ranked.archived_at,
    ranked.relevance_score,
    ranked.location_insight
  from ranked
  order by ranked.relevance_score desc, ranked.is_featured desc, ranked.member_count desc, ranked.created_at desc
  limit greatest(coalesce(p_limit, 48), 1);
$$;


ALTER FUNCTION "public"."get_ranked_circles_for_profile"("p_profile_id" "uuid", "p_scope" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_recs_active"("p_user_id" "uuid", "p_window_minutes" integer DEFAULT 30) RETURNS TABLE("id" "uuid", "user_id" "uuid", "full_name" "text", "age" integer, "bio" "text", "avatar_url" "text", "profile_video" "text", "location" "text", "latitude" double precision, "longitude" double precision, "region" "text", "tribe" "text", "religion" "text", "personality_type" "text", "is_active" boolean, "online" boolean, "last_active" timestamp with time zone, "verified" boolean, "verification_level" integer, "ai_score" numeric, "distance_km" double precision)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  my_lat double precision;
  my_lon double precision;
  my_user_id uuid;
  my_gender gender;
  cutoff timestamptz;
begin
  if auth.uid() is null then
    return;
  end if;

  select latitude, longitude, user_id, gender
    into my_lat, my_lon, my_user_id, my_gender
  from public.profiles
  where id = p_user_id
    and user_id = auth.uid()
  limit 1;

  if my_user_id is null then
    return;
  end if;

  cutoff := now() - (p_window_minutes || ' minutes')::interval;

  return query
    select
      p.id,
      p.user_id,
      p.full_name,
      p.age,
      p.bio,
      p.avatar_url,
      p.profile_video,
      p.location,
      p.latitude,
      p.longitude,
      p.region,
      p.tribe,
      p.religion::text as religion,
      p.personality_type,
      p.is_active,
      p.online,
      p.last_active,
      (coalesce(p.verification_level, 0) > 0) as verified,
      p.verification_level,
      p.ai_score,
      (
        case
          when my_lat is null or my_lon is null or p.latitude is null or p.longitude is null then null::double precision
          else (6371 * 2 * asin(sqrt(
            power(sin(radians(p.latitude - my_lat) / 2), 2) +
            cos(radians(my_lat)) * cos(radians(p.latitude)) *
            power(sin(radians(p.longitude - my_lon) / 2), 2)
          )))
        end
      ) as distance_km
    from public.profiles p
    where p.id <> p_user_id
      and p.deleted_at is null
      and (p.is_active = true or p.online = true or (p.last_active is not null and p.last_active >= cutoff))
      and p.profile_completed is true
      and coalesce(p.discoverable_in_vibes, true) = true
      and coalesce(p.matchmaking_mode, false) = false
      and (
        my_gender is null
        or my_gender not in ('MALE', 'FEMALE')
        or p.gender is null
        or (my_gender = 'MALE' and p.gender = 'FEMALE')
        or (my_gender = 'FEMALE' and p.gender = 'MALE')
      )
    order by p.online desc, coalesce(p.last_active, cutoff) desc, distance_km asc nulls last, p.updated_at desc
    limit 50;
end;
$$;


ALTER FUNCTION "public"."get_recs_active"("p_user_id" "uuid", "p_window_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_recs_active_scored"("p_user_id" "uuid", "p_window_minutes" integer DEFAULT 30) RETURNS TABLE("id" "uuid", "user_id" "uuid", "full_name" "text", "age" integer, "bio" "text", "avatar_url" "text", "profile_video" "text", "location" "text", "latitude" double precision, "longitude" double precision, "region" "text", "tribe" "text", "religion" "text", "personality_type" "text", "is_active" boolean, "online" boolean, "last_active" timestamp with time zone, "verified" boolean, "verification_level" integer, "ai_score" numeric, "distance_km" double precision, "location_affinity_reason_code" "text", "location_affinity_strength" double precision, "location_affinity_short_text" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  my_lat double precision;
  my_lon double precision;
  my_user_id uuid;
  my_min_age integer;
  my_max_age integer;
  my_gender gender;
  cutoff timestamptz;
begin
  if auth.uid() is null then
    return;
  end if;

  select pr.latitude, pr.longitude, pr.user_id, pr.min_age_interest, pr.max_age_interest, pr.gender
    into my_lat, my_lon, my_user_id, my_min_age, my_max_age, my_gender
  from public.profiles pr
  where pr.id = p_user_id
    and pr.user_id = auth.uid()
  limit 1;

  if my_user_id is null then
    return;
  end if;

  cutoff := now() - (p_window_minutes || ' minutes')::interval;

  return query
  with viewer_interests as (
    select pi.interest_id
    from public.profile_interests pi
    where pi.profile_id = p_user_id
  ),
  viewer_counts as (
    select count(*)::double precision as cnt
    from viewer_interests
  ),
  base_candidates as (
    select
      p.id,
      p.user_id,
      p.full_name,
      p.age,
      p.bio,
      p.avatar_url,
      p.profile_video,
      p.location,
      p.latitude,
      p.longitude,
      p.region,
      p.tribe,
      p.religion::text as religion,
      p.personality_type,
      p.is_active,
      p.online,
      p.last_active,
      (coalesce(p.verification_level, 0) > 0) as verified,
      p.verification_level,
      (
        with target_counts as (
          select count(*)::double precision as cnt
          from public.profile_interests tpi
          where tpi.profile_id = p.id
        ),
        shared as (
          select count(*)::double precision as cnt
          from public.profile_interests tpi
          join viewer_interests vi on vi.interest_id = tpi.interest_id
          where tpi.profile_id = p.id
        )
        select
          least(100, greatest(0, round(
            100 * (
              0.70 * (
                case
                  when (select vc.cnt from viewer_counts vc) <= 0 and (select tc.cnt from target_counts tc) <= 0 then 0.20
                  else (select s.cnt from shared s) / greatest((select vc.cnt from viewer_counts vc) + (select tc.cnt from target_counts tc) - (select s.cnt from shared s), 1)
                end
              )
              + 0.20 * (least(coalesce(p.verification_level, 0), 3)::double precision / 3)
              + 0.10 * (case when p.online = true then 1 else 0.4 end)
            )
          )))::numeric
      ) as ai_score,
      case
        when my_lat is null or my_lon is null or p.latitude is null or p.longitude is null then null::double precision
        else (6371 * 2 * asin(sqrt(
          power(sin(radians(p.latitude - my_lat) / 2), 2) +
          cos(radians(my_lat)) * cos(radians(p.latitude)) *
          power(sin(radians(p.longitude - my_lon) / 2), 2)
        )))
      end as distance_km,
      p.updated_at as sort_updated_at
    from public.profiles p
    where p.id <> p_user_id
      and p.deleted_at is null
      and (p.is_active = true or p.online = true or (p.last_active is not null and p.last_active >= cutoff))
      and p.profile_completed is true
      and coalesce(p.discoverable_in_vibes, true) = true
      and coalesce(p.matchmaking_mode, false) = false
      and (
        my_gender is null
        or my_gender not in ('MALE', 'FEMALE')
        or p.gender is null
        or (my_gender = 'MALE' and p.gender = 'FEMALE')
        or (my_gender = 'FEMALE' and p.gender = 'MALE')
      )
      and (my_min_age is null or p.age >= my_min_age)
      and (my_max_age is null or p.age <= my_max_age)
      and not exists (
        select 1 from public.swipes s
        where s.swiper_id = p_user_id
          and s.target_id = p.id
      )
      and (
        my_user_id is null
        or not exists (
          select 1 from public.blocks b
          where (b.blocker_id = my_user_id and b.blocked_id = p.user_id)
             or (b.blocker_id = p.user_id and b.blocked_id = my_user_id)
        )
      )
  ),
  ranked as (
    select *
    from base_candidates
    order by ai_score desc, online desc, coalesce(last_active, cutoff) desc, distance_km asc nulls last, sort_updated_at desc
    limit 50
  )
  select
    ranked.id,
    ranked.user_id,
    ranked.full_name,
    ranked.age,
    ranked.bio,
    ranked.avatar_url,
    ranked.profile_video,
    ranked.location,
    ranked.latitude,
    ranked.longitude,
    ranked.region,
    ranked.tribe,
    ranked.religion,
    ranked.personality_type,
    ranked.is_active,
    ranked.online,
    ranked.last_active,
    ranked.verified,
    ranked.verification_level,
    ranked.ai_score,
    ranked.distance_km,
    affinity.reason_code,
    affinity.strength,
    affinity.short_text
  from ranked
  left join lateral public.compute_location_affinity(p_user_id, ranked.id) affinity on true;
end;
$$;


ALTER FUNCTION "public"."get_recs_active_scored"("p_user_id" "uuid", "p_window_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_recs_for_you_scored"("p_user_id" "uuid", "p_limit" integer DEFAULT 20) RETURNS TABLE("id" "uuid", "user_id" "uuid", "full_name" "text", "age" integer, "bio" "text", "avatar_url" "text", "profile_video" "text", "location" "text", "latitude" double precision, "longitude" double precision, "region" "text", "tribe" "text", "religion" "text", "personality_type" "text", "is_active" boolean, "online" boolean, "last_active" timestamp with time zone, "verified" boolean, "verification_level" integer, "ai_score" numeric, "distance_km" double precision, "location_affinity_reason_code" "text", "location_affinity_strength" double precision, "location_affinity_short_text" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  my_lat double precision;
  my_lon double precision;
  my_user_id uuid;
  my_min_age integer;
  my_max_age integer;
  my_region text;
  my_gender gender;
begin
  if auth.uid() is null then
    return;
  end if;

  select pr.latitude, pr.longitude, pr.user_id, pr.min_age_interest, pr.max_age_interest, pr.region, pr.gender
    into my_lat, my_lon, my_user_id, my_min_age, my_max_age, my_region, my_gender
  from public.profiles pr
  where pr.id = p_user_id
    and pr.user_id = auth.uid()
  limit 1;

  if my_user_id is null then
    return;
  end if;

  return query
  with viewer_interests as (
    select pi.interest_id
    from public.profile_interests pi
    where pi.profile_id = p_user_id
  ),
  viewer_counts as (
    select count(*)::double precision as cnt
    from viewer_interests
  ),
  base_candidates as (
    select
      p.id,
      p.user_id,
      p.full_name,
      p.age,
      p.bio,
      p.avatar_url,
      p.profile_video,
      p.location,
      p.latitude,
      p.longitude,
      p.region,
      p.tribe,
      p.religion::text as religion,
      p.personality_type,
      p.is_active,
      p.online,
      p.last_active,
      (coalesce(p.verification_level, 0) > 0) as verified,
      p.verification_level,
      (
        with target_counts as (
          select count(*)::double precision as cnt
          from public.profile_interests tpi
          where tpi.profile_id = p.id
        ),
        shared as (
          select count(*)::double precision as cnt
          from public.profile_interests tpi
          join viewer_interests vi on vi.interest_id = tpi.interest_id
          where tpi.profile_id = p.id
        )
        select
          least(100, greatest(0, round(
            100 * (
              0.55 * (
                case
                  when (select vc.cnt from viewer_counts vc) <= 0 and (select tc.cnt from target_counts tc) <= 0 then 0.20
                  else (select s.cnt from shared s) / greatest((select vc.cnt from viewer_counts vc) + (select tc.cnt from target_counts tc) - (select s.cnt from shared s), 1)
                end
              )
              + 0.25 * (
                case
                  when my_lat is null or my_lon is null or p.latitude is null or p.longitude is null then 0.55
                  else greatest(0, 1 - least((6371 * 2 * asin(sqrt(
                    power(sin(radians(p.latitude - my_lat) / 2), 2) +
                    cos(radians(my_lat)) * cos(radians(p.latitude)) *
                    power(sin(radians(p.longitude - my_lon) / 2), 2)
                  ))), 250) / 250)
                end
              )
              + 0.10 * (case when my_region is not null and p.region is not null and p.region = my_region then 1 else 0.0 end)
              + 0.07 * (least(coalesce(p.verification_level, 0), 3)::double precision / 3)
              + 0.03 * (case when p.online = true then 1 else 0.4 end)
            )
          )))::numeric
      ) as ai_score,
      case
        when my_lat is null or my_lon is null or p.latitude is null or p.longitude is null then null::double precision
        else (6371 * 2 * asin(sqrt(
          power(sin(radians(p.latitude - my_lat) / 2), 2) +
          cos(radians(my_lat)) * cos(radians(p.latitude)) *
          power(sin(radians(p.longitude - my_lon) / 2), 2)
        )))
      end as distance_km,
      p.updated_at as sort_updated_at
    from public.profiles p
    where p.id <> p_user_id
      and p.deleted_at is null
      and p.is_active = true
      and p.profile_completed is true
      and coalesce(p.discoverable_in_vibes, true) = true
      and coalesce(p.matchmaking_mode, false) = false
      and (
        my_gender is null
        or my_gender not in ('MALE', 'FEMALE')
        or p.gender is null
        or (my_gender = 'MALE' and p.gender = 'FEMALE')
        or (my_gender = 'FEMALE' and p.gender = 'MALE')
      )
      and (my_min_age is null or p.age >= my_min_age)
      and (my_max_age is null or p.age <= my_max_age)
      and not exists (
        select 1 from public.swipes s
        where s.swiper_id = p_user_id
          and s.target_id = p.id
      )
      and (
        my_user_id is null
        or not exists (
          select 1 from public.blocks b
          where (b.blocker_id = my_user_id and b.blocked_id = p.user_id)
             or (b.blocker_id = p.user_id and b.blocked_id = my_user_id)
        )
      )
  ),
  ranked as (
    select *
    from base_candidates
    order by ai_score desc, distance_km asc nulls last, sort_updated_at desc
    limit p_limit
  )
  select
    ranked.id,
    ranked.user_id,
    ranked.full_name,
    ranked.age,
    ranked.bio,
    ranked.avatar_url,
    ranked.profile_video,
    ranked.location,
    ranked.latitude,
    ranked.longitude,
    ranked.region,
    ranked.tribe,
    ranked.religion,
    ranked.personality_type,
    ranked.is_active,
    ranked.online,
    ranked.last_active,
    ranked.verified,
    ranked.verification_level,
    ranked.ai_score,
    ranked.distance_km,
    affinity.reason_code,
    affinity.strength,
    affinity.short_text
  from ranked
  left join lateral public.compute_location_affinity(p_user_id, ranked.id) affinity on true;
end;
$$;


ALTER FUNCTION "public"."get_recs_for_you_scored"("p_user_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_recs_nearby"("p_user_id" "uuid", "p_limit" integer DEFAULT 20) RETURNS TABLE("id" "uuid", "user_id" "uuid", "full_name" "text", "age" integer, "bio" "text", "avatar_url" "text", "profile_video" "text", "location" "text", "latitude" double precision, "longitude" double precision, "region" "text", "tribe" "text", "religion" "text", "personality_type" "text", "is_active" boolean, "online" boolean, "last_active" timestamp with time zone, "verified" boolean, "verification_level" integer, "ai_score" numeric, "distance_km" double precision)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  my_lat double precision;
  my_lon double precision;
  my_user_id uuid;
  my_gender gender;
begin
  if auth.uid() is null then
    return;
  end if;

  select latitude, longitude, user_id, gender
    into my_lat, my_lon, my_user_id, my_gender
  from public.profiles
  where id = p_user_id
    and user_id = auth.uid()
  limit 1;

  if my_user_id is null then
    return;
  end if;

  if my_lat is null or my_lon is null then
    return query
      select p.id, p.user_id, p.full_name, p.age, p.bio, p.avatar_url, p.profile_video, p.location,
             p.latitude, p.longitude, p.region, p.tribe, p.religion, p.personality_type,
             p.is_active, p.online, null::timestamptz as last_active,
             (coalesce(p.verification_level, 0) > 0) as verified,
             p.verification_level, p.ai_score, null::double precision as distance_km
      from public.profiles p
      where p.id <> p_user_id
        and p.deleted_at is null
        and p.is_active = true
        and p.profile_completed is true
        and coalesce(p.discoverable_in_vibes, true) = true
        and coalesce(p.matchmaking_mode, false) = false
        and (
          my_gender is null
          or my_gender not in ('MALE', 'FEMALE')
          or p.gender is null
          or (my_gender = 'MALE' and p.gender = 'FEMALE')
          or (my_gender = 'FEMALE' and p.gender = 'MALE')
        )
      order by (p.region = (select region from public.profiles where id = p_user_id limit 1)) desc,
               p.online desc, p.updated_at desc
      limit p_limit;
  end if;

  return query
    select p.id, p.user_id, p.full_name, p.age, p.bio, p.avatar_url, p.profile_video, p.location,
           p.latitude, p.longitude, p.region, p.tribe, p.religion, p.personality_type,
           p.is_active, p.online, null::timestamptz as last_active,
           (coalesce(p.verification_level, 0) > 0) as verified,
           p.verification_level, p.ai_score,
           (6371 * 2 * asin(sqrt(
              power(sin(radians(p.latitude - my_lat) / 2), 2) +
              cos(radians(my_lat)) * cos(radians(p.latitude)) *
              power(sin(radians(p.longitude - my_lon) / 2), 2)
           ))) as distance_km
    from public.profiles p
    where p.id <> p_user_id
      and p.deleted_at is null
      and p.is_active = true
      and p.profile_completed is true
      and coalesce(p.discoverable_in_vibes, true) = true
      and coalesce(p.matchmaking_mode, false) = false
      and (
        my_gender is null
        or my_gender not in ('MALE', 'FEMALE')
        or p.gender is null
        or (my_gender = 'MALE' and p.gender = 'FEMALE')
        or (my_gender = 'FEMALE' and p.gender = 'MALE')
      )
      and p.latitude is not null and p.longitude is not null
    order by distance_km asc
    limit p_limit;
end;
$$;


ALTER FUNCTION "public"."get_recs_nearby"("p_user_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_recs_nearby_scored"("p_user_id" "uuid", "p_limit" integer DEFAULT 20) RETURNS TABLE("id" "uuid", "user_id" "uuid", "full_name" "text", "age" integer, "bio" "text", "avatar_url" "text", "profile_video" "text", "location" "text", "latitude" double precision, "longitude" double precision, "region" "text", "tribe" "text", "religion" "text", "personality_type" "text", "is_active" boolean, "online" boolean, "last_active" timestamp with time zone, "verified" boolean, "verification_level" integer, "ai_score" numeric, "distance_km" double precision, "location_affinity_reason_code" "text", "location_affinity_strength" double precision, "location_affinity_short_text" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  my_lat double precision;
  my_lon double precision;
  my_user_id uuid;
  my_min_age integer;
  my_max_age integer;
  my_region text;
  my_gender gender;
begin
  if auth.uid() is null then
    return;
  end if;

  select pr.latitude, pr.longitude, pr.user_id, pr.min_age_interest, pr.max_age_interest, pr.region, pr.gender
    into my_lat, my_lon, my_user_id, my_min_age, my_max_age, my_region, my_gender
  from public.profiles pr
  where pr.id = p_user_id
    and pr.user_id = auth.uid()
  limit 1;

  if my_user_id is null then
    return;
  end if;

  return query
  with viewer_interests as (
    select pi.interest_id
    from public.profile_interests pi
    where pi.profile_id = p_user_id
  ),
  viewer_counts as (
    select count(*)::double precision as cnt
    from viewer_interests
  ),
  base_candidates as (
    select
      p.id,
      p.user_id,
      p.full_name,
      p.age,
      p.bio,
      p.avatar_url,
      p.profile_video,
      p.location,
      p.latitude,
      p.longitude,
      p.region,
      p.tribe,
      p.religion::text as religion,
      p.personality_type,
      p.is_active,
      p.online,
      p.last_active,
      (coalesce(p.verification_level, 0) > 0) as verified,
      p.verification_level,
      (
        with target_counts as (
          select count(*)::double precision as cnt
          from public.profile_interests tpi
          where tpi.profile_id = p.id
        ),
        shared as (
          select count(*)::double precision as cnt
          from public.profile_interests tpi
          join viewer_interests vi on vi.interest_id = tpi.interest_id
          where tpi.profile_id = p.id
        )
        select
          least(100, greatest(0, round(
            100 * (
              0.50 * (
                case
                  when (select vc.cnt from viewer_counts vc) <= 0 and (select tc.cnt from target_counts tc) <= 0 then 0.20
                  else (select s.cnt from shared s) / greatest((select vc.cnt from viewer_counts vc) + (select tc.cnt from target_counts tc) - (select s.cnt from shared s), 1)
                end
              )
              + 0.35 * (
                case
                  when my_lat is null or my_lon is null or p.latitude is null or p.longitude is null then 0.55
                  else greatest(0, 1 - least((6371 * 2 * asin(sqrt(
                    power(sin(radians(p.latitude - my_lat) / 2), 2) +
                    cos(radians(my_lat)) * cos(radians(p.latitude)) *
                    power(sin(radians(p.longitude - my_lon) / 2), 2)
                  ))), 250) / 250)
                end
              )
              + 0.10 * (least(coalesce(p.verification_level, 0), 3)::double precision / 3)
              + 0.05 * (case when p.online = true then 1 else 0.4 end)
            )
          )))::numeric
      ) as ai_score,
      case
        when my_lat is null or my_lon is null or p.latitude is null or p.longitude is null then null::double precision
        else (6371 * 2 * asin(sqrt(
          power(sin(radians(p.latitude - my_lat) / 2), 2) +
          cos(radians(my_lat)) * cos(radians(p.latitude)) *
          power(sin(radians(p.longitude - my_lon) / 2), 2)
        )))
      end as distance_km,
      p.updated_at as sort_updated_at
    from public.profiles p
    where p.id <> p_user_id
      and p.deleted_at is null
      and p.is_active = true
      and p.profile_completed is true
      and coalesce(p.discoverable_in_vibes, true) = true
      and coalesce(p.matchmaking_mode, false) = false
      and (
        my_gender is null
        or my_gender not in ('MALE', 'FEMALE')
        or p.gender is null
        or (my_gender = 'MALE' and p.gender = 'FEMALE')
        or (my_gender = 'FEMALE' and p.gender = 'MALE')
      )
      and (my_min_age is null or p.age >= my_min_age)
      and (my_max_age is null or p.age <= my_max_age)
      and not exists (
        select 1 from public.swipes s
        where s.swiper_id = p_user_id
          and s.target_id = p.id
      )
      and (
        my_user_id is null
        or not exists (
          select 1 from public.blocks b
          where (b.blocker_id = my_user_id and b.blocked_id = p.user_id)
             or (b.blocker_id = p.user_id and b.blocked_id = my_user_id)
        )
      )
  ),
  ranked as (
    select *
    from base_candidates
    order by ai_score desc, distance_km asc nulls last, sort_updated_at desc
    limit p_limit
  )
  select
    ranked.id,
    ranked.user_id,
    ranked.full_name,
    ranked.age,
    ranked.bio,
    ranked.avatar_url,
    ranked.profile_video,
    ranked.location,
    ranked.latitude,
    ranked.longitude,
    ranked.region,
    ranked.tribe,
    ranked.religion,
    ranked.personality_type,
    ranked.is_active,
    ranked.online,
    ranked.last_active,
    ranked.verified,
    ranked.verification_level,
    ranked.ai_score,
    ranked.distance_km,
    affinity.reason_code,
    affinity.strength,
    affinity.short_text
  from ranked
  left join lateral public.compute_location_affinity(p_user_id, ranked.id) affinity on true;
end;
$$;


ALTER FUNCTION "public"."get_recs_nearby_scored"("p_user_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_subscription_badge_plan"("p_user_id" "uuid" DEFAULT "auth"."uid"(), "p_include_sandbox_preview" boolean DEFAULT false) RETURNS "public"."subscription_type"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  resolved_plan public.subscription_type := 'FREE';
begin
  if p_user_id is null then
    return 'FREE';
  end if;

  select s.type
    into resolved_plan
  from public.subscriptions s
  where s.user_id = p_user_id
    and s.is_active = true
    and s.ends_at > timezone('utc'::text, now())
  order by
    case s.type
      when 'GOLD' then 2
      when 'SILVER' then 1
      else 0
    end desc,
    s.ends_at desc
  limit 1;

  if resolved_plan is not null then
    return resolved_plan;
  end if;

  if coalesce(p_include_sandbox_preview, false) then
    select s.type
      into resolved_plan
    from public.subscriptions s
    where s.user_id = p_user_id
      and s.source = 'revenuecat'
      and upper(coalesce(s.external_environment, '')) = 'SANDBOX'
    order by
      case s.type
        when 'GOLD' then 2
        when 'SILVER' then 1
        else 0
      end desc,
      coalesce(s.ends_at, s.started_at) desc,
      s.updated_at desc nulls last
    limit 1;
  end if;

  return coalesce(resolved_plan, 'FREE');
end;
$$;


ALTER FUNCTION "public"."get_subscription_badge_plan"("p_user_id" "uuid", "p_include_sandbox_preview" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_vibes_recommendations_v2"("p_user_id" "uuid", "p_segment" "text" DEFAULT 'for_you'::"text", "p_limit" integer DEFAULT 30, "p_active_window_minutes" integer DEFAULT 30) RETURNS TABLE("id" "uuid", "user_id" "uuid", "full_name" "text", "age" integer, "bio" "text", "avatar_url" "text", "profile_video" "text", "location" "text", "latitude" double precision, "longitude" double precision, "region" "text", "tribe" "text", "religion" "text", "personality_type" "text", "is_active" boolean, "online" boolean, "last_active" timestamp with time zone, "verified" boolean, "verification_level" integer, "ai_score" numeric, "distance_km" double precision, "city" "text", "current_country" "text", "current_country_code" "text", "location_precision" "text", "recommendation_reasons" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  my_lat double precision;
  my_lon double precision;
  my_user_id uuid;
  my_min_age integer;
  my_max_age integer;
  my_region text;
  my_gender gender;
  v_segment text := coalesce(nullif(btrim(p_segment), ''), 'for_you');
  v_limit integer := greatest(1, least(coalesce(p_limit, 30), 80));
  cutoff timestamptz;
begin
  if auth.uid() is null then
    return;
  end if;

  if v_segment not in ('for_you', 'nearby', 'active_now') then
    v_segment := 'for_you';
  end if;

  select pr.latitude, pr.longitude, pr.user_id, pr.min_age_interest, pr.max_age_interest, pr.region, pr.gender
    into my_lat, my_lon, my_user_id, my_min_age, my_max_age, my_region, my_gender
  from public.profiles pr
  where pr.id = p_user_id
    and pr.user_id = auth.uid()
  limit 1;

  if my_user_id is null then
    return;
  end if;

  cutoff := now() - (greatest(5, least(coalesce(p_active_window_minutes, 30), 240)) || ' minutes')::interval;

  return query
  with viewer_interests as (
    select pi.interest_id
    from public.profile_interests pi
    where pi.profile_id = p_user_id
  ),
  viewer_counts as (
    select count(*)::double precision as cnt
    from viewer_interests
  ),
  viewer_feedback as (
    select
      ve.target_profile_id,
      count(*) filter (where ve.event_type = 'card_seen')::integer as seen_count,
      count(*) filter (where ve.event_type = 'profile_opened')::integer as opened_count,
      count(*) filter (where ve.event_type in ('intro_played', 'intro_completed'))::integer as intro_count,
      count(*) filter (where ve.event_type in ('like', 'signal_sent', 'intent_sent'))::integer as positive_count,
      count(*) filter (where ve.event_type = 'pass')::integer as pass_count,
      max(ve.created_at) as last_event_at
    from public.vibes_events ve
    where ve.viewer_profile_id = p_user_id
      and ve.created_at >= now() - interval '45 days'
    group by ve.target_profile_id
  ),
  market_feedback as (
    select
      ve.target_profile_id,
      count(*) filter (where ve.event_type = 'card_seen')::double precision as impressions,
      count(*) filter (where ve.event_type = 'profile_opened')::double precision as opens,
      count(*) filter (where ve.event_type in ('like', 'signal_sent', 'intent_sent'))::double precision as positives
    from public.vibes_events ve
    where ve.created_at >= now() - interval '21 days'
    group by ve.target_profile_id
  ),
  active_moments as (
    select distinct m.user_id
    from public.moments m
    where m.is_deleted = false
      and m.expires_at > now()
      and m.visibility in ('public', 'matches', 'vibe_check_approved')
  ),
  candidate_base as (
    select
      p.*,
      (
        case
          when my_lat is null or my_lon is null or p.latitude is null or p.longitude is null then null::double precision
          else (6371 * 2 * asin(sqrt(
            power(sin(radians(p.latitude - my_lat) / 2), 2) +
            cos(radians(my_lat)) * cos(radians(p.latitude)) *
            power(sin(radians(p.longitude - my_lon) / 2), 2)
          )))
        end
      ) as distance_km,
      exists (select 1 from active_moments am where am.user_id = p.user_id) as has_active_moment
    from public.profiles p
    where p.id <> p_user_id
      and p.deleted_at is null
      and p.profile_completed is true
      and coalesce(p.discoverable_in_vibes, true) = true
      and coalesce(p.matchmaking_mode, false) = false
      and (
        v_segment <> 'active_now'
        or (p.last_active is not null and p.last_active >= cutoff)
      )
      and (
        my_gender is null
        or my_gender not in ('MALE', 'FEMALE')
        or p.gender is null
        or (my_gender = 'MALE' and p.gender = 'FEMALE')
        or (my_gender = 'FEMALE' and p.gender = 'MALE')
      )
      and (my_min_age is null or p.age >= my_min_age)
      and (my_max_age is null or p.age <= my_max_age)
      and not exists (
        select 1 from public.swipes s
        where s.swiper_id = p_user_id
          and s.target_id = p.id
          and (
            s.action::text in ('LIKE', 'SUPERLIKE')
            or (
              s.action::text = 'PASS'
              and s.created_at >= now() - interval '21 days'
            )
          )
      )
      and not exists (
        select 1 from public.intent_requests ir
        where ir.status = 'pending'
          and ir.expires_at > now()
          and (
            (ir.actor_id = p_user_id and ir.recipient_id = p.id)
            or (ir.actor_id = p.id and ir.recipient_id = p_user_id)
          )
      )
      and not exists (
        select 1 from public.profile_signal_gestures psg
        where psg.status in ('sent', 'seen')
          and psg.expires_at > now()
          and (
            (psg.sender_profile_id = p_user_id and psg.receiver_profile_id = p.id)
            or (psg.sender_profile_id = p.id and psg.receiver_profile_id = p_user_id)
          )
      )
      and not exists (
        select 1 from public.matches mt
        where mt.status in ('PENDING', 'ACCEPTED')
          and (
            (mt.user1_id = p_user_id and mt.user2_id = p.id)
            or (mt.user1_id = p.id and mt.user2_id = p_user_id)
          )
      )
      and not exists (
        select 1 from public.blocks b
        where (b.blocker_id = my_user_id and b.blocked_id = p.user_id)
           or (b.blocker_id = p.user_id and b.blocked_id = my_user_id)
      )
  ),
  scored as (
    select
      c.*,
      coalesce(vf.seen_count, 0) as viewer_seen_count,
      coalesce(vf.opened_count, 0) as viewer_opened_count,
      coalesce(vf.intro_count, 0) as viewer_intro_count,
      coalesce(vf.positive_count, 0) as viewer_positive_count,
      coalesce(vf.pass_count, 0) as viewer_pass_count,
      coalesce(mf.impressions, 0) as market_impressions,
      coalesce(mf.opens, 0) as market_opens,
      coalesce(mf.positives, 0) as market_positives,
      (
        with target_counts as (
          select count(*)::double precision as cnt
          from public.profile_interests tpi
          where tpi.profile_id = c.id
        ),
        shared as (
          select count(*)::double precision as cnt
          from public.profile_interests tpi
          join viewer_interests vi on vi.interest_id = tpi.interest_id
          where tpi.profile_id = c.id
        )
        select
          case
            when (select vc.cnt from viewer_counts vc) <= 0 and (select tc.cnt from target_counts tc) <= 0 then 0.20
            else (select s.cnt from shared s) / greatest((select vc.cnt from viewer_counts vc) + (select tc.cnt from target_counts tc) - (select s.cnt from shared s), 1)
          end
      ) as interest_score,
      (
        case
          when c.distance_km is null then 0.52
          when c.distance_km <= 10 then 1
          when c.distance_km <= 25 then 0.92
          when c.distance_km <= 100 then 0.74
          when c.distance_km <= 500 then 0.48
          when c.distance_km <= 2000 then 0.25
          else 0.08
        end
      ) as distance_score,
      (
        case
          when c.last_active is not null and c.last_active >= now() - interval '3 minutes' then 1
          when c.last_active is not null and c.last_active >= now() - interval '15 minutes' then 0.82
          when c.last_active is not null and c.last_active >= now() - interval '60 minutes' then 0.55
          when c.last_active is not null and c.last_active >= now() - interval '24 hours' then 0.25
          else 0
        end
      ) as activity_score,
      (
        least(coalesce(c.verification_level, 0), 3)::double precision / 3
      ) as verification_score,
      (
        (case when coalesce(c.profile_video, '') <> '' then 0.35 else 0 end) +
        (case when length(coalesce(c.bio, '')) >= 80 then 0.25 when length(coalesce(c.bio, '')) >= 30 then 0.12 else 0 end) +
        (case when c.has_active_moment then 0.24 else 0 end)
      ) as richness_score
    from candidate_base c
    left join viewer_feedback vf on vf.target_profile_id = c.id
    left join market_feedback mf on mf.target_profile_id = c.id
  ),
  ranked as (
    select
      s.*,
      (
        case v_segment
          when 'nearby' then
            100 * (
              0.43 * s.distance_score +
              0.20 * s.interest_score +
              0.13 * s.activity_score +
              0.10 * s.verification_score +
              0.08 * s.richness_score +
              0.06 * least((s.market_opens + s.market_positives * 1.5) / greatest(s.market_impressions, 8), 1)
            )
          when 'active_now' then
            100 * (
              0.38 * s.activity_score +
              0.22 * s.interest_score +
              0.15 * s.distance_score +
              0.10 * s.verification_score +
              0.09 * s.richness_score +
              0.06 * least((s.market_opens + s.market_positives * 1.5) / greatest(s.market_impressions, 8), 1)
            )
          else
            100 * (
              0.32 * s.interest_score +
              0.17 * s.distance_score +
              0.15 * s.activity_score +
              0.12 * s.verification_score +
              0.13 * s.richness_score +
              0.11 * least((s.market_opens + s.market_positives * 1.5) / greatest(s.market_impressions, 8), 1)
            )
        end
        + least(s.viewer_opened_count, 3) * 2.4
        + least(s.viewer_intro_count, 2) * 2.0
        + least(s.viewer_positive_count, 2) * 4.2
        - least(s.viewer_seen_count, 5) * 1.1
        - least(s.viewer_pass_count, 3) * 7.0
        + ((abs(hashtext(s.id::text || current_date::text)) % 100)::double precision / 100.0) * 2.5
      ) as final_score
    from scored s
  )
  select
    r.id,
    r.user_id,
    r.full_name,
    r.age,
    r.bio,
    r.avatar_url,
    r.profile_video,
    r.location,
    r.latitude,
    r.longitude,
    r.region,
    r.tribe,
    r.religion::text as religion,
    r.personality_type,
    (r.last_active is not null and r.last_active >= now() - interval '15 minutes') as is_active,
    (r.last_active is not null and r.last_active >= now() - interval '3 minutes') as online,
    r.last_active,
    (coalesce(r.verification_level, 0) > 0) as verified,
    r.verification_level,
    least(100, greatest(0, round(r.final_score)))::numeric as ai_score,
    r.distance_km,
    r.city,
    r.current_country,
    r.current_country_code,
    r.location_precision::text as location_precision,
    jsonb_build_object(
      'segment', v_segment,
      'interest', r.interest_score,
      'distance', r.distance_score,
      'activity', r.activity_score,
      'richness', r.richness_score,
      'viewer_seen_count', r.viewer_seen_count,
      'has_active_moment', r.has_active_moment
    ) as recommendation_reasons
  from ranked r
  order by
    case when v_segment = 'nearby' and r.distance_km is null then 1 else 0 end,
    r.final_score desc,
    r.distance_km asc nulls last,
    r.last_active desc nulls last,
    r.updated_at desc
  limit v_limit;
end;
$$;


ALTER FUNCTION "public"."get_vibes_recommendations_v2"("p_user_id" "uuid", "p_segment" "text", "p_limit" integer, "p_active_window_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_vibes_recommendations_v3"("p_user_id" "uuid", "p_segment" "text" DEFAULT 'for_you'::"text", "p_limit" integer DEFAULT 30, "p_active_window_minutes" integer DEFAULT 30) RETURNS TABLE("id" "uuid", "user_id" "uuid", "full_name" "text", "age" integer, "bio" "text", "avatar_url" "text", "profile_video" "text", "location" "text", "latitude" double precision, "longitude" double precision, "region" "text", "tribe" "text", "religion" "text", "personality_type" "text", "is_active" boolean, "online" boolean, "last_active" timestamp with time zone, "verified" boolean, "verification_level" integer, "ai_score" numeric, "distance_km" double precision, "city" "text", "current_country" "text", "current_country_code" "text", "location_precision" "text", "recommendation_reasons" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  my_lat double precision;
  my_lon double precision;
  my_user_id uuid;
  my_min_age integer;
  my_max_age integer;
  my_region text;
  my_gender gender;
  my_city text;
  my_location_precision text;
  my_country text;
  my_country_code text;
  my_origin_country text;
  my_origin_country_code text;
  my_looking_for text;
  my_region_norm text;
  my_city_norm text;
  my_country_norm text;
  my_country_code_norm text;
  my_origin_country_norm text;
  my_origin_country_code_norm text;
  my_looking_for_norm text;
  my_is_diaspora boolean := false;
  my_has_usable_coordinates boolean := false;
  v_segment text := coalesce(nullif(btrim(p_segment), ''), 'for_you');
  v_limit integer := greatest(1, least(coalesce(p_limit, 30), 80));
  v_nearby_radius_km double precision := 250;
  v_nearby_lat_delta double precision := 0;
  v_nearby_lon_delta double precision := 0;
  v_seed_limit integer;
  v_candidate_ids uuid[] := '{}'::uuid[];
  cutoff timestamptz;
begin
  if auth.uid() is null then
    return;
  end if;

  if v_segment not in ('for_you', 'nearby', 'active_now') then
    v_segment := 'for_you';
  end if;

  select
    profile.latitude,
    profile.longitude,
    profile.user_id,
    profile.min_age_interest,
    profile.max_age_interest,
    profile.region,
    profile.gender,
    profile.city,
    profile.location_precision::text,
    profile.current_country,
    profile.current_country_code,
    profile.origin_country,
    profile.origin_country_code,
    profile.looking_for
  into
    my_lat,
    my_lon,
    my_user_id,
    my_min_age,
    my_max_age,
    my_region,
    my_gender,
    my_city,
    my_location_precision,
    my_country,
    my_country_code,
    my_origin_country,
    my_origin_country_code,
    my_looking_for
  from public.profiles profile
  where profile.id = p_user_id
    and profile.user_id = auth.uid()
    and profile.deleted_at is null
  limit 1;

  if my_user_id is null then
    return;
  end if;

  my_region_norm := nullif(lower(btrim(coalesce(my_region, ''))), '');
  my_city_norm := nullif(lower(btrim(coalesce(my_city, ''))), '');
  my_country_norm := nullif(lower(btrim(coalesce(
    public.normalize_vibes_country_name(my_country, my_country_code),
    ''
  ))), '');
  my_country_code_norm := public.normalize_vibes_country_code(my_country, my_country_code);
  my_origin_country_norm := nullif(lower(btrim(coalesce(
    public.normalize_vibes_country_name(my_origin_country, my_origin_country_code),
    ''
  ))), '');
  my_origin_country_code_norm := public.normalize_vibes_country_code(
    my_origin_country,
    my_origin_country_code
  );
  my_looking_for_norm := nullif(lower(btrim(coalesce(my_looking_for, ''))), '');

  if my_origin_country_code_norm is null and my_country_code_norm = 'GH' then
    my_origin_country_code_norm := 'GH';
  end if;

  if my_origin_country_norm is null and my_country_norm = 'ghana' then
    my_origin_country_norm := 'ghana';
  end if;

  my_region_norm := case
    when my_region_norm is null then null
    when my_region_norm in ('africa', 'north america', 'south america', 'europe', 'asia', 'oceania', 'middle east') then null
    when my_country_norm is not null and my_region_norm = my_country_norm then null
    when my_country_code_norm is not null and my_region_norm = lower(my_country_code_norm) then null
    else my_region_norm
  end;

  my_city_norm := case
    when my_city_norm is null then null
    when my_city_norm in ('africa', 'north america', 'south america', 'europe', 'asia', 'oceania', 'middle east') then null
    when my_region_norm is not null and my_city_norm = my_region_norm then null
    when my_country_norm is not null and my_city_norm = my_country_norm then null
    when my_country_code_norm is not null and my_city_norm = lower(my_country_code_norm) then null
    when my_city_norm ~ '(region|district|province|state|county|municipality|metropolitan)' then null
    else my_city_norm
  end;

  my_has_usable_coordinates := public.has_usable_vibes_coordinates(my_lat, my_lon);

  if my_has_usable_coordinates then
    v_nearby_lat_delta := least(v_nearby_radius_km / 111.0, 10.0);
    v_nearby_lon_delta := least(
      v_nearby_radius_km
        / greatest(111.0 * greatest(abs(cos(radians(my_lat))), 0.2), 1.0),
      10.0
    );
  end if;

  if v_segment = 'nearby' and not my_has_usable_coordinates then
    return;
  end if;

  my_is_diaspora := (
    my_origin_country_code_norm is not null
    and my_country_code_norm is not null
    and my_origin_country_code_norm <> my_country_code_norm
  ) or (
    my_origin_country_code_norm is null
    and my_country_code_norm is null
    and my_origin_country_norm is not null
    and my_country_norm is not null
    and my_origin_country_norm <> my_country_norm
  );

  cutoff := now() - (greatest(5, least(coalesce(p_active_window_minutes, 30), 240)) || ' minutes')::interval;
  v_seed_limit := greatest(v_limit * 6, 180);
  v_seed_limit := least(v_seed_limit, 360);

  select coalesce(array_agg(seed.id), '{}'::uuid[])
    into v_candidate_ids
  from (
    with viewer_state as (
      select
        summary_row.target_profile_id,
        summary_row.pass_count,
        summary_row.last_pass_at
      from public.viewer_profile_behavior_summary summary_row
      where summary_row.viewer_profile_id = p_user_id
    ),
    seed_base_raw as (
      select
        profile.id,
        profile.last_active,
        profile.updated_at,
        profile.created_at,
        profile.looking_for,
        coalesce(profile.verification_level, 0) as verification_level,
        loc.raw_distance_km,
        coalesce(seed_quality_metrics.impressions_30d, 0) as market_impressions,
        coalesce(seed_quality_metrics.market_quality_score, 0)::double precision as market_quality_score,
        coalesce(seed_entitlements.has_active_boost, false) as has_active_boost,
        coalesce(seed_entitlements.premium_rank, 0) as premium_rank,
        coalesce(seed_entitlements.boost_type, 'manual') as boost_type,
        coalesce(seed_entitlements.boost_audience_mode, 'for_you') as boost_audience_mode,
        coalesce(seed_entitlements.boost_focus_mode, 'profile') as boost_focus_mode,
        (coalesce(profile.profile_video, '') <> '') as has_intro_media,
        (
          length(btrim(coalesce(profile.looking_for, ''))) >= 8
          or profile.relationship_compass is not null
        ) as has_intent_content,
        (
          my_looking_for_norm is not null
          and nullif(lower(btrim(coalesce(profile.looking_for, ''))), '') = my_looking_for_norm
        ) as same_looking_for,
        (
          my_city_norm is not null
          and loc.candidate_city_norm = my_city_norm
          and (
            (my_country_code_norm is not null and loc.candidate_country_code_norm is not null and loc.candidate_country_code_norm = my_country_code_norm)
            or (
              my_country_code_norm is null
              and loc.candidate_country_code_norm is null
              and my_country_norm is not null
              and loc.candidate_country_norm = my_country_norm
            )
          )
        ) as same_city,
        (
          my_region_norm is not null
          and loc.candidate_region_norm = my_region_norm
          and (
            (my_country_code_norm is not null and loc.candidate_country_code_norm is not null and loc.candidate_country_code_norm = my_country_code_norm)
            or (
              my_country_code_norm is null
              and loc.candidate_country_code_norm is null
              and my_country_norm is not null
              and loc.candidate_country_norm = my_country_norm
            )
          )
        ) as same_region,
        (
          (my_country_code_norm is not null and loc.candidate_country_code_norm is not null and loc.candidate_country_code_norm = my_country_code_norm)
          or (
            my_country_code_norm is null
            and loc.candidate_country_code_norm is null
            and my_country_norm is not null
            and loc.candidate_country_norm = my_country_norm
          )
        ) as same_country,
        (
          (my_origin_country_code_norm is not null and loc.candidate_origin_country_code_norm is not null and loc.candidate_origin_country_code_norm = my_origin_country_code_norm)
          or (
            my_origin_country_code_norm is null
            and loc.candidate_origin_country_code_norm is null
            and my_origin_country_norm is not null
            and loc.candidate_origin_country_norm = my_origin_country_norm
          )
        ) as same_origin_country,
        (
          (my_origin_country_code_norm is not null and loc.candidate_country_code_norm is not null and loc.candidate_country_code_norm = my_origin_country_code_norm)
          or (
            my_origin_country_code_norm is null
            and loc.candidate_country_code_norm is null
            and my_origin_country_norm is not null
            and loc.candidate_country_norm = my_origin_country_norm
          )
          or (
            my_country_code_norm is not null
            and loc.candidate_origin_country_code_norm is not null
            and loc.candidate_origin_country_code_norm = my_country_code_norm
          )
          or (
            my_country_code_norm is null
            and loc.candidate_origin_country_code_norm is null
            and my_country_norm is not null
            and loc.candidate_origin_country_norm = my_country_norm
          )
        ) as origin_residence_bridge
      from public.profiles profile
      cross join lateral (
        with canonical as (
          select
            public.normalize_vibes_country_code(
              profile.current_country,
              profile.current_country_code
            ) as current_country_code_norm,
            nullif(lower(btrim(coalesce(
              public.normalize_vibes_country_name(
                profile.current_country,
                profile.current_country_code
              ),
              ''
            ))), '') as current_country_norm,
            public.normalize_vibes_country_code(
              profile.origin_country,
              profile.origin_country_code
            ) as origin_country_code_norm,
            nullif(lower(btrim(coalesce(
              public.normalize_vibes_country_name(
                profile.origin_country,
                profile.origin_country_code
              ),
              ''
            ))), '') as origin_country_norm
        )
        select
          canonical.current_country_code_norm as candidate_country_code_norm,
          canonical.current_country_norm as candidate_country_norm,
          case
            when canonical.origin_country_code_norm is not null
              then canonical.origin_country_code_norm
            when canonical.current_country_code_norm = 'GH'
              then 'GH'
            else null
          end as candidate_origin_country_code_norm,
          case
            when canonical.origin_country_norm is not null
              then canonical.origin_country_norm
            when canonical.current_country_norm = 'ghana'
              then 'ghana'
            else null
          end as candidate_origin_country_norm,
          case
            when nullif(lower(btrim(coalesce(profile.region, ''))), '') is null then null
            when nullif(lower(btrim(coalesce(profile.region, ''))), '') in ('africa', 'north america', 'south america', 'europe', 'asia', 'oceania', 'middle east') then null
            when nullif(lower(btrim(coalesce(profile.region, ''))), '') = canonical.current_country_norm then null
            when nullif(lower(btrim(coalesce(profile.region, ''))), '') = lower(canonical.current_country_code_norm) then null
            else nullif(lower(btrim(coalesce(profile.region, ''))), '')
          end as candidate_region_norm,
          case
            when nullif(lower(btrim(coalesce(profile.city, ''))), '') is null then null
            when nullif(lower(btrim(coalesce(profile.city, ''))), '') in ('africa', 'north america', 'south america', 'europe', 'asia', 'oceania', 'middle east') then null
            when nullif(lower(btrim(coalesce(profile.city, ''))), '') = nullif(lower(btrim(coalesce(profile.region, ''))), '') then null
            when nullif(lower(btrim(coalesce(profile.city, ''))), '') = canonical.current_country_norm then null
            when nullif(lower(btrim(coalesce(profile.city, ''))), '') = lower(canonical.current_country_code_norm) then null
            when nullif(lower(btrim(coalesce(profile.city, ''))), '') ~ '(region|district|province|state|county|municipality|metropolitan)' then null
            else nullif(lower(btrim(coalesce(profile.city, ''))), '')
          end as candidate_city_norm,
          public.vibes_real_distance_km(
            my_lat,
            my_lon,
            profile.latitude,
            profile.longitude
          ) as raw_distance_km
        from canonical
      ) loc
      left join viewer_state
        on viewer_state.target_profile_id = profile.id
      left join public.profile_visibility_entitlements seed_entitlements
        on seed_entitlements.profile_id = profile.id
      left join public.profile_recommendation_quality_metrics seed_quality_metrics
        on seed_quality_metrics.profile_id = profile.id
      where profile.id <> p_user_id
        and profile.deleted_at is null
        and profile.profile_completed is true
        and coalesce(profile.discoverable_in_vibes, true) = true
        and coalesce(profile.matchmaking_mode, false) = false
        and (
          v_segment <> 'nearby'
          or (
            public.has_usable_vibes_coordinates(profile.latitude, profile.longitude)
            and profile.latitude between my_lat - v_nearby_lat_delta and my_lat + v_nearby_lat_delta
            and profile.longitude between my_lon - v_nearby_lon_delta and my_lon + v_nearby_lon_delta
          )
        )
        and (
          v_segment <> 'active_now'
          or (profile.last_active is not null and profile.last_active >= cutoff)
        )
        and (
          my_gender is null
          or my_gender not in ('MALE', 'FEMALE')
          or profile.gender is null
          or (my_gender = 'MALE' and profile.gender = 'FEMALE')
          or (my_gender = 'FEMALE' and profile.gender = 'MALE')
        )
        and (my_min_age is null or profile.age >= my_min_age)
        and (my_max_age is null or profile.age <= my_max_age)
        and not exists (
          select 1
          from public.swipes swipe_row
          where swipe_row.swiper_id = p_user_id
            and swipe_row.target_id = profile.id
            and swipe_row.action::text in ('LIKE', 'SUPERLIKE')
        )
        and not exists (
          select 1
          from public.swipes swipe_row
          where swipe_row.swiper_id = p_user_id
            and swipe_row.target_id = profile.id
            and swipe_row.action::text = 'PASS'
            and swipe_row.created_at >= now() - interval '7 days'
        )
        and not (
          coalesce(viewer_state.last_pass_at, '-infinity'::timestamptz) >= now() - interval '3 days'
          or (
            coalesce(viewer_state.pass_count, 0) >= 2
            and coalesce(viewer_state.last_pass_at, '-infinity'::timestamptz) >= now() - interval '21 days'
          )
        )
        and not exists (
          select 1
          from public.intent_requests request_row
          where request_row.status = 'pending'
            and request_row.expires_at > now()
            and (
              (request_row.actor_id = p_user_id and request_row.recipient_id = profile.id)
              or (request_row.actor_id = profile.id and request_row.recipient_id = p_user_id)
            )
        )
        and not exists (
          select 1
          from public.profile_signal_gestures gesture_row
          where gesture_row.status in ('sent', 'seen')
            and gesture_row.expires_at > now()
            and (
              (gesture_row.sender_profile_id = p_user_id and gesture_row.receiver_profile_id = profile.id)
              or (gesture_row.sender_profile_id = profile.id and gesture_row.receiver_profile_id = p_user_id)
            )
        )
        and not exists (
          select 1
          from public.matches match_row
          where match_row.status in ('PENDING', 'ACCEPTED')
            and (
              (match_row.user1_id = p_user_id and match_row.user2_id = profile.id)
              or (match_row.user1_id = profile.id and match_row.user2_id = p_user_id)
            )
        )
        and not exists (
          select 1
          from public.blocks block_row
          where (block_row.blocker_id = my_user_id and block_row.blocked_id = profile.user_id)
             or (block_row.blocker_id = profile.user_id and block_row.blocked_id = my_user_id)
        )
    ),
    seed_base as (
      select
        seed_base_raw.*,
        (seed_base_raw.raw_distance_km is not null) as has_real_distance,
        case
          when v_segment = 'nearby' then seed_base_raw.raw_distance_km
          else public.estimate_vibes_distance_km(
            seed_base_raw.raw_distance_km,
            seed_base_raw.same_city,
            seed_base_raw.same_region,
            seed_base_raw.same_country
          )
        end as distance_km
      from seed_base_raw
    ),
    seed_lanes as (
      select
        seed_base.*,
        case
          when seed_base.same_city then 'city'
          when seed_base.same_region then 'region'
          when seed_base.same_country then 'country'
          when seed_base.same_origin_country then 'origin'
          when seed_base.origin_residence_bridge then 'bridge'
          else 'global'
        end as locality_bucket,
        case
          when v_segment = 'nearby' then
            case
              when seed_base.distance_km is not null and seed_base.distance_km <= 10 then 'hyper_local'
              when seed_base.distance_km is not null and seed_base.distance_km <= 25 then 'local'
              when seed_base.distance_km is not null and seed_base.distance_km <= 100 then 'regional'
              when seed_base.distance_km is not null and seed_base.distance_km <= 250 then 'extended'
              else 'global'
            end
          when v_segment = 'active_now' then
            case
              when seed_base.last_active >= now() - interval '3 minutes' and seed_base.same_city then 'live_city'
              when seed_base.last_active >= now() - interval '10 minutes'
                and seed_base.distance_km is not null
                and seed_base.distance_km <= 25 then 'live_local'
              when seed_base.last_active >= now() - interval '10 minutes' then 'live_global'
              when seed_base.last_active >= now() - interval '30 minutes' and seed_base.same_region then 'warm_region'
              when seed_base.last_active >= now() - interval '30 minutes' then 'warm_global'
              when seed_base.distance_km is not null and seed_base.distance_km <= 100 then 'recent_local'
              else 'recent_global'
            end
          else
            case
              when seed_base.same_city or seed_base.same_region then 'local_core'
              when seed_base.same_country then 'local_country'
              when seed_base.same_origin_country or seed_base.origin_residence_bridge then 'origin_bridge'
              when seed_base.market_impressions < 8
                and (
                  seed_base.last_active >= now() - interval '24 hours'
                  or seed_base.market_quality_score >= 0.18
                  or seed_base.has_active_boost
                  or seed_base.premium_rank > 0
                  or seed_base.verification_level > 0
                  or seed_base.created_at >= now() - interval '14 days'
                ) then 'explore'
              when seed_base.market_quality_score >= 0.32 or seed_base.verification_level > 0 then 'proven_global'
              else 'global'
            end
        end as seed_lane
      from seed_base
      where v_segment <> 'nearby'
         or (
           seed_base.has_real_distance
           and seed_base.raw_distance_km <= v_nearby_radius_km
         )
    ),
    seed_ranked as (
      select
        seed_lanes.*,
        row_number() over (
          partition by seed_lanes.locality_bucket
          order by
            case when seed_lanes.distance_km is null then 1 else 0 end,
            seed_lanes.distance_km asc nulls last,
            seed_lanes.last_active desc nulls last,
            seed_lanes.updated_at desc
        ) as locality_rank,
        row_number() over (
          partition by seed_lanes.seed_lane
          order by
            case
              when v_segment = 'active_now' and seed_lanes.last_active >= now() - interval '3 minutes' then 0
              when v_segment = 'active_now' and seed_lanes.last_active >= now() - interval '10 minutes' then 1
              when v_segment = 'active_now' and seed_lanes.last_active >= now() - interval '30 minutes' then 2
              else 3
            end,
            case
              when seed_lanes.has_active_boost
                and seed_lanes.boost_audience_mode = 'second_look'
                and seed_lanes.same_looking_for
                then 0
              when seed_lanes.has_active_boost
                and seed_lanes.boost_audience_mode = 'intent_match'
                and seed_lanes.same_looking_for
                then 0
              else 1
            end,
            case
              when v_segment = 'for_you'
                and seed_lanes.locality_bucket in ('city', 'region', 'country')
                then seed_lanes.distance_km
            end asc nulls last,
            seed_lanes.market_quality_score desc,
            seed_lanes.last_active desc nulls last,
            case when seed_lanes.distance_km is null then 1 else 0 end,
            seed_lanes.distance_km asc nulls last,
            seed_lanes.updated_at desc
        ) as seed_lane_rank
      from seed_lanes
    )
    select seed_ranked.id
    from seed_ranked
    order by
      case when v_segment = 'nearby' and seed_ranked.distance_km is null then 1 else 0 end,
      case
        when v_segment = 'for_you' and seed_ranked.seed_lane = 'local_core'
          and seed_ranked.seed_lane_rank <= greatest(1, ceil(v_seed_limit * 0.24)::integer) then 0
        when v_segment = 'for_you' and seed_ranked.seed_lane = 'local_country'
          and seed_ranked.seed_lane_rank <= greatest(1, ceil(v_seed_limit * 0.16)::integer) then 1
        when v_segment = 'for_you' and seed_ranked.seed_lane = 'origin_bridge'
          and seed_ranked.seed_lane_rank <= greatest(1, ceil(v_seed_limit * 0.12)::integer) then 2
        when v_segment = 'for_you' and seed_ranked.seed_lane = 'explore'
          and seed_ranked.seed_lane_rank <= greatest(1, ceil(v_seed_limit * 0.12)::integer) then 3
        when v_segment = 'for_you' and seed_ranked.seed_lane = 'proven_global'
          and seed_ranked.seed_lane_rank <= greatest(1, ceil(v_seed_limit * 0.18)::integer) then 4
        when v_segment = 'for_you' and seed_ranked.seed_lane = 'global'
          and seed_ranked.seed_lane_rank <= greatest(1, ceil(v_seed_limit * 0.18)::integer) then 5
        when v_segment = 'for_you' then 6
        when v_segment = 'nearby' and seed_ranked.seed_lane = 'hyper_local'
          and seed_ranked.seed_lane_rank <= greatest(1, ceil(v_seed_limit * 0.36)::integer) then 0
        when v_segment = 'nearby' and seed_ranked.seed_lane = 'local'
          and seed_ranked.seed_lane_rank <= greatest(1, ceil(v_seed_limit * 0.28)::integer) then 1
        when v_segment = 'nearby' and seed_ranked.seed_lane = 'regional'
          and seed_ranked.seed_lane_rank <= greatest(1, ceil(v_seed_limit * 0.18)::integer) then 2
        when v_segment = 'nearby' and seed_ranked.seed_lane = 'extended'
          and seed_ranked.seed_lane_rank <= greatest(1, ceil(v_seed_limit * 0.12)::integer) then 3
        when v_segment = 'nearby' and seed_ranked.seed_lane = 'global'
          and seed_ranked.seed_lane_rank <= greatest(1, ceil(v_seed_limit * 0.06)::integer) then 4
        when v_segment = 'nearby' then 5
        when v_segment = 'active_now' and seed_ranked.seed_lane = 'live_city'
          and seed_ranked.seed_lane_rank <= greatest(1, ceil(v_seed_limit * 0.22)::integer) then 0
        when v_segment = 'active_now' and seed_ranked.seed_lane = 'live_local'
          and seed_ranked.seed_lane_rank <= greatest(1, ceil(v_seed_limit * 0.18)::integer) then 1
        when v_segment = 'active_now' and seed_ranked.seed_lane = 'live_global'
          and seed_ranked.seed_lane_rank <= greatest(1, ceil(v_seed_limit * 0.18)::integer) then 2
        when v_segment = 'active_now' and seed_ranked.seed_lane = 'warm_region'
          and seed_ranked.seed_lane_rank <= greatest(1, ceil(v_seed_limit * 0.14)::integer) then 3
        when v_segment = 'active_now' and seed_ranked.seed_lane = 'warm_global'
          and seed_ranked.seed_lane_rank <= greatest(1, ceil(v_seed_limit * 0.14)::integer) then 4
        when v_segment = 'active_now' and seed_ranked.seed_lane = 'recent_local'
          and seed_ranked.seed_lane_rank <= greatest(1, ceil(v_seed_limit * 0.08)::integer) then 5
        when v_segment = 'active_now' and seed_ranked.seed_lane = 'recent_global'
          and seed_ranked.seed_lane_rank <= greatest(1, ceil(v_seed_limit * 0.06)::integer) then 6
        when v_segment = 'active_now' then 7
        else 0
      end,
      case when v_segment in ('for_you', 'nearby', 'active_now') then seed_ranked.seed_lane_rank end asc,
      case when seed_ranked.has_active_boost and seed_ranked.boost_type = 'smart' then 0 else 1 end,
      case when v_segment = 'nearby' then seed_ranked.distance_km end asc nulls last,
      case
        when v_segment = 'for_you' then
          case seed_ranked.locality_bucket
            when 'city' then 0
            when 'region' then 1
            when 'country' then 2
            when 'origin' then 3
            when 'bridge' then 4
            else 5
          end
      end asc,
      case when v_segment = 'for_you' then seed_ranked.locality_rank end asc,
      case when v_segment = 'active_now' then seed_ranked.distance_km end asc nulls last,
      case
        when v_segment = 'for_you'
          and seed_ranked.locality_bucket in ('city', 'region', 'country')
          then seed_ranked.distance_km
      end asc nulls last,
      seed_ranked.last_active desc nulls last,
      seed_ranked.updated_at desc
    limit v_seed_limit
  ) seed;

  if coalesce(array_length(v_candidate_ids, 1), 0) = 0 then
    return;
  end if;

  return query
  with viewer_interests as (
    select interest_row.interest_id
    from public.profile_interests interest_row
    where interest_row.profile_id = p_user_id
  ),
  viewer_counts as (
    select count(*)::double precision as cnt
    from viewer_interests
  ),
  viewer_feedback as (
    select
      summary_row.target_profile_id,
      summary_row.seen_count,
      summary_row.profile_open_count,
      summary_row.full_open_count,
      summary_row.intro_count,
      summary_row.profile_saved_count,
      summary_row.signal_opened_count,
      summary_row.intent_opened_count,
      summary_row.positive_count,
      summary_row.pass_count,
      summary_row.undo_count,
      summary_row.avg_dwell_ms,
      summary_row.long_dwell_count,
      summary_row.last_event_at,
      summary_row.last_positive_at,
      summary_row.last_pass_at,
      summary_row.refreshed_at
    from public.viewer_profile_behavior_summary summary_row
    where summary_row.viewer_profile_id = p_user_id
      and summary_row.target_profile_id = any(v_candidate_ids)
  ),
  active_moments as (
    select distinct moment_row.user_id
    from public.moments moment_row
    where moment_row.user_id in (
      select distinct candidate_profile.user_id
      from public.profiles candidate_profile
      where candidate_profile.id = any(v_candidate_ids)
        and candidate_profile.deleted_at is null
    )
      and public.can_view_moment(moment_row.id)
  ),
  candidate_base_raw as (
    select
      profile.*,
      coalesce(entitlements.premium_plan, 'FREE') as premium_plan,
      coalesce(entitlements.premium_rank, 0) as premium_rank,
      entitlements.boost_ends_at,
      coalesce(entitlements.has_active_boost, false) as has_active_boost,
      coalesce(entitlements.boost_type, 'manual') as boost_type,
      coalesce(entitlements.boost_audience_mode, 'for_you') as boost_audience_mode,
      coalesce(entitlements.boost_focus_mode, 'profile') as boost_focus_mode,
      entitlements.refreshed_at as premium_snapshot_refreshed_at,
      quality_metrics.impressions_30d,
      quality_metrics.opens_30d,
      quality_metrics.positives_30d,
      quality_metrics.long_dwells_30d,
      quality_metrics.conversation_pairs_60d,
      quality_metrics.deep_conversation_pairs_60d,
      quality_metrics.accepted_matches_60d,
      quality_metrics.market_quality_score as market_quality_score_raw,
      quality_metrics.refreshed_at as quality_metrics_refreshed_at,
      loc.raw_distance_km,
      exists (
        select 1
        from active_moments active_moment
        where active_moment.user_id = profile.user_id
      ) as has_active_moment,
      (
        my_looking_for_norm is not null
        and nullif(lower(btrim(coalesce(profile.looking_for, ''))), '') = my_looking_for_norm
      ) as same_looking_for,
      (coalesce(profile.profile_video, '') <> '') as has_intro_media,
      (
        length(btrim(coalesce(profile.looking_for, ''))) >= 8
        or profile.relationship_compass is not null
      ) as has_intent_content,
      (
        my_city_norm is not null
        and loc.candidate_city_norm = my_city_norm
        and (
          (my_country_code_norm is not null and loc.candidate_country_code_norm is not null and loc.candidate_country_code_norm = my_country_code_norm)
          or (
            my_country_code_norm is null
            and loc.candidate_country_code_norm is null
            and my_country_norm is not null
            and loc.candidate_country_norm = my_country_norm
          )
        )
      ) as same_city,
      (
        my_region_norm is not null
        and loc.candidate_region_norm = my_region_norm
        and (
          (my_country_code_norm is not null and loc.candidate_country_code_norm is not null and loc.candidate_country_code_norm = my_country_code_norm)
          or (
            my_country_code_norm is null
            and loc.candidate_country_code_norm is null
            and my_country_norm is not null
            and loc.candidate_country_norm = my_country_norm
          )
        )
      ) as same_region,
      (
        (my_country_code_norm is not null and loc.candidate_country_code_norm is not null and loc.candidate_country_code_norm = my_country_code_norm)
        or (
          my_country_code_norm is null
          and loc.candidate_country_code_norm is null
          and my_country_norm is not null
          and loc.candidate_country_norm = my_country_norm
        )
      ) as same_country,
      (
        (my_origin_country_code_norm is not null and loc.candidate_origin_country_code_norm is not null and loc.candidate_origin_country_code_norm = my_origin_country_code_norm)
        or (
          my_origin_country_code_norm is null
          and loc.candidate_origin_country_code_norm is null
          and my_origin_country_norm is not null
          and loc.candidate_origin_country_norm = my_origin_country_norm
        )
      ) as same_origin_country,
      (
        (my_origin_country_code_norm is not null and loc.candidate_country_code_norm is not null and loc.candidate_country_code_norm = my_origin_country_code_norm)
        or (
          my_origin_country_code_norm is null
          and loc.candidate_country_code_norm is null
          and my_origin_country_norm is not null
          and loc.candidate_country_norm = my_origin_country_norm
        )
        or (
          my_country_code_norm is not null
          and loc.candidate_origin_country_code_norm is not null
          and loc.candidate_origin_country_code_norm = my_country_code_norm
        )
        or (
          my_country_code_norm is null
          and loc.candidate_origin_country_code_norm is null
          and my_country_norm is not null
          and loc.candidate_origin_country_norm = my_country_norm
        )
      ) as origin_residence_bridge,
      loc.candidate_is_diaspora,
      loc.candidate_city_group,
      loc.candidate_country_group,
      loc.candidate_region_group
    from public.profiles profile
    cross join lateral (
      with canonical as (
        select
          public.normalize_vibes_country_code(
            profile.current_country,
            profile.current_country_code
          ) as current_country_code_norm,
          nullif(lower(btrim(coalesce(
            public.normalize_vibes_country_name(
              profile.current_country,
              profile.current_country_code
            ),
            ''
          ))), '') as current_country_norm,
          public.normalize_vibes_country_code(
            profile.origin_country,
            profile.origin_country_code
          ) as origin_country_code_norm,
          nullif(lower(btrim(coalesce(
            public.normalize_vibes_country_name(
              profile.origin_country,
              profile.origin_country_code
            ),
            ''
          ))), '') as origin_country_norm
      )
      select
        canonical.current_country_code_norm as candidate_country_code_norm,
        canonical.current_country_norm as candidate_country_norm,
        case
          when canonical.origin_country_code_norm is not null
            then canonical.origin_country_code_norm
          when canonical.current_country_code_norm = 'GH'
            then 'GH'
          else null
        end as candidate_origin_country_code_norm,
        case
          when canonical.origin_country_norm is not null
            then canonical.origin_country_norm
          when canonical.current_country_norm = 'ghana'
            then 'ghana'
          else null
        end as candidate_origin_country_norm,
        case
          when nullif(lower(btrim(coalesce(profile.region, ''))), '') is null then null
          when nullif(lower(btrim(coalesce(profile.region, ''))), '') in ('africa', 'north america', 'south america', 'europe', 'asia', 'oceania', 'middle east') then null
          when nullif(lower(btrim(coalesce(profile.region, ''))), '') = canonical.current_country_norm then null
          when nullif(lower(btrim(coalesce(profile.region, ''))), '') = lower(canonical.current_country_code_norm) then null
          else nullif(lower(btrim(coalesce(profile.region, ''))), '')
        end as candidate_region_norm,
        case
          when nullif(lower(btrim(coalesce(profile.city, ''))), '') is null then null
          when nullif(lower(btrim(coalesce(profile.city, ''))), '') in ('africa', 'north america', 'south america', 'europe', 'asia', 'oceania', 'middle east') then null
          when nullif(lower(btrim(coalesce(profile.city, ''))), '') = nullif(lower(btrim(coalesce(profile.region, ''))), '') then null
          when nullif(lower(btrim(coalesce(profile.city, ''))), '') = canonical.current_country_norm then null
          when nullif(lower(btrim(coalesce(profile.city, ''))), '') = lower(canonical.current_country_code_norm) then null
          when nullif(lower(btrim(coalesce(profile.city, ''))), '') ~ '(region|district|province|state|county|municipality|metropolitan)' then null
          else nullif(lower(btrim(coalesce(profile.city, ''))), '')
        end as candidate_city_norm,
        public.vibes_real_distance_km(
          my_lat,
          my_lon,
          profile.latitude,
          profile.longitude
        ) as raw_distance_km,
        coalesce(
          case
            when nullif(lower(btrim(coalesce(profile.city, ''))), '') is null then null
            when nullif(lower(btrim(coalesce(profile.city, ''))), '') in ('africa', 'north america', 'south america', 'europe', 'asia', 'oceania', 'middle east') then null
            when nullif(lower(btrim(coalesce(profile.city, ''))), '') = nullif(lower(btrim(coalesce(profile.region, ''))), '') then null
            when nullif(lower(btrim(coalesce(profile.city, ''))), '') = canonical.current_country_norm then null
            when nullif(lower(btrim(coalesce(profile.city, ''))), '') = lower(canonical.current_country_code_norm) then null
            when nullif(lower(btrim(coalesce(profile.city, ''))), '') ~ '(region|district|province|state|county|municipality|metropolitan)' then null
            else nullif(lower(btrim(coalesce(profile.city, ''))), '')
          end,
          coalesce(
            case
              when nullif(lower(btrim(coalesce(profile.region, ''))), '') is null then null
              when nullif(lower(btrim(coalesce(profile.region, ''))), '') in ('africa', 'north america', 'south america', 'europe', 'asia', 'oceania', 'middle east') then null
              when nullif(lower(btrim(coalesce(profile.region, ''))), '') = canonical.current_country_norm then null
              when nullif(lower(btrim(coalesce(profile.region, ''))), '') = lower(canonical.current_country_code_norm) then null
              else nullif(lower(btrim(coalesce(profile.region, ''))), '')
            end,
            coalesce(
              canonical.current_country_code_norm,
              canonical.current_country_norm
            )
          ),
          '<<none>>'
        ) as candidate_city_group,
        coalesce(
          canonical.current_country_code_norm,
          canonical.current_country_norm,
          '<<none>>'
        ) as candidate_country_group,
        coalesce(
          case
            when nullif(lower(btrim(coalesce(profile.region, ''))), '') is null then null
            when nullif(lower(btrim(coalesce(profile.region, ''))), '') in ('africa', 'north america', 'south america', 'europe', 'asia', 'oceania', 'middle east') then null
            when nullif(lower(btrim(coalesce(profile.region, ''))), '') = canonical.current_country_norm then null
            when nullif(lower(btrim(coalesce(profile.region, ''))), '') = lower(canonical.current_country_code_norm) then null
            else nullif(lower(btrim(coalesce(profile.region, ''))), '')
          end,
          coalesce(
            canonical.current_country_code_norm,
            canonical.current_country_norm
          ),
          '<<none>>'
        ) as candidate_region_group,
        (
          (
            case
              when canonical.origin_country_code_norm is not null
                then canonical.origin_country_code_norm
              when canonical.current_country_code_norm = 'GH'
                then 'GH'
              else null
            end
          ) is not null
          and canonical.current_country_code_norm is not null
          and (
            case
              when canonical.origin_country_code_norm is not null
                then canonical.origin_country_code_norm
              when canonical.current_country_code_norm = 'GH'
                then 'GH'
              else null
            end
          ) <> canonical.current_country_code_norm
        ) as candidate_is_diaspora
      from canonical
    ) loc
    left join public.profile_visibility_entitlements entitlements
      on entitlements.profile_id = profile.id
    left join public.profile_recommendation_quality_metrics quality_metrics
      on quality_metrics.profile_id = profile.id
    where profile.id = any(v_candidate_ids)
      and profile.deleted_at is null
  ),
  candidate_base as (
    select candidate_scored.*
    from (
      select
        candidate_base_raw.*,
        (candidate_base_raw.raw_distance_km is not null) as has_real_distance,
        case
          when v_segment = 'nearby' then candidate_base_raw.raw_distance_km
          else public.estimate_vibes_distance_km(
            candidate_base_raw.raw_distance_km,
            candidate_base_raw.same_city,
            candidate_base_raw.same_region,
            candidate_base_raw.same_country
          )
        end as distance_km
      from candidate_base_raw
    ) candidate_scored
    where v_segment <> 'nearby'
       or (
         candidate_scored.has_real_distance
         and candidate_scored.raw_distance_km <= v_nearby_radius_km
       )
  ),
  scored as (
    select
      candidate_base.*,
      coalesce(viewer_feedback.seen_count, 0) as viewer_seen_count,
      coalesce(viewer_feedback.profile_open_count, 0) as viewer_opened_count,
      coalesce(viewer_feedback.full_open_count, 0) as viewer_full_open_count,
      coalesce(viewer_feedback.intro_count, 0) as viewer_intro_count,
      coalesce(viewer_feedback.profile_saved_count, 0) as viewer_saved_count,
      coalesce(viewer_feedback.signal_opened_count, 0) as viewer_signal_opened_count,
      coalesce(viewer_feedback.intent_opened_count, 0) as viewer_intent_opened_count,
      coalesce(viewer_feedback.positive_count, 0) as viewer_positive_count,
      coalesce(viewer_feedback.pass_count, 0) as viewer_pass_count,
      coalesce(viewer_feedback.undo_count, 0) as viewer_undo_count,
      coalesce(viewer_feedback.avg_dwell_ms, 0) as viewer_avg_dwell_ms,
      coalesce(viewer_feedback.long_dwell_count, 0) as viewer_long_dwell_count,
      viewer_feedback.last_event_at as viewer_last_event_at,
      viewer_feedback.last_positive_at as viewer_last_positive_at,
      viewer_feedback.last_pass_at as viewer_last_pass_at,
      viewer_feedback.refreshed_at as behavior_summary_refreshed_at,
      coalesce(candidate_base.impressions_30d, 0) as market_impressions,
      coalesce(candidate_base.opens_30d, 0) as market_opens,
      coalesce(candidate_base.positives_30d, 0) as market_positives,
      coalesce(candidate_base.long_dwells_30d, 0) as market_long_dwells,
      coalesce(candidate_base.conversation_pairs_60d, 0) as market_conversation_pairs,
      coalesce(candidate_base.deep_conversation_pairs_60d, 0) as market_deep_conversation_pairs,
      coalesce(candidate_base.accepted_matches_60d, 0) as market_accepted_matches,
      coalesce(
        coalesce(candidate_base.positives_30d, 0)::double precision
          / nullif(coalesce(candidate_base.impressions_30d, 0)::double precision, 0),
        0
      ) as market_positive_rate,
      (
        coalesce(candidate_base.impressions_30d, 0) < 8
        and (
          candidate_base.last_active >= now() - interval '24 hours'
          or coalesce(candidate_base.market_quality_score_raw, 0) >= 0.18
          or coalesce(candidate_base.has_active_boost, false)
          or coalesce(candidate_base.premium_rank, 0) > 0
          or coalesce(candidate_base.verification_level, 0) > 0
        )
      ) as exploration_candidate,
      (
        with target_counts as (
          select count(*)::double precision as cnt
          from public.profile_interests target_interest
          where target_interest.profile_id = candidate_base.id
        ),
        shared as (
          select count(*)::double precision as cnt
          from public.profile_interests target_interest
          join viewer_interests viewer_interest
            on viewer_interest.interest_id = target_interest.interest_id
          where target_interest.profile_id = candidate_base.id
        )
        select
          case
            when (select viewer_counts.cnt from viewer_counts) <= 0 and (select target_counts.cnt from target_counts) <= 0 then 0.20
            else (select shared.cnt from shared)
              / greatest(
                  (select viewer_counts.cnt from viewer_counts) +
                  (select target_counts.cnt from target_counts) -
                  (select shared.cnt from shared),
                  1
                )
          end
      ) as interest_score,
      (
        case
          when candidate_base.distance_km is null then 0.40
          when candidate_base.distance_km <= 10 then 1
          when candidate_base.distance_km <= 25 then 0.94
          when candidate_base.distance_km <= 100 then 0.80
          when candidate_base.distance_km <= 500 then 0.55
          when candidate_base.distance_km <= 2000 then 0.28
          else 0.10
        end
      ) as distance_score,
      (
        case
          when candidate_base.last_active is not null and candidate_base.last_active >= now() - interval '3 minutes' then 1
          when candidate_base.last_active is not null and candidate_base.last_active >= now() - interval '15 minutes' then 0.84
          when candidate_base.last_active is not null and candidate_base.last_active >= now() - interval '60 minutes' then 0.60
          when candidate_base.last_active is not null and candidate_base.last_active >= now() - interval '24 hours' then 0.28
          else 0
        end
      ) as activity_score,
      least(coalesce(candidate_base.verification_level, 0), 3)::double precision / 3 as verification_score,
      (
        (case when coalesce(candidate_base.profile_video, '') <> '' then 0.38 else 0 end) +
        (case
           when length(coalesce(candidate_base.bio, '')) >= 80 then 0.26
           when length(coalesce(candidate_base.bio, '')) >= 30 then 0.13
           else 0
         end) +
        (case when candidate_base.has_active_moment then 0.28 else 0 end)
      ) as richness_score,
      (
        case
          when candidate_base.same_city then 1.00
          when candidate_base.same_region then 0.84
          when candidate_base.same_country then 0.70
          when candidate_base.distance_km is not null and candidate_base.distance_km <= 50 then 0.58
          when candidate_base.distance_km is not null and candidate_base.distance_km <= 250 then 0.34
          else 0
        end
      ) as geo_affinity_score,
      (
        case
          when candidate_base.same_city then 0
          when candidate_base.same_region then 1
          when candidate_base.same_country then 2
          else 3
        end
      ) as geo_bucket,
      (
        case
          when candidate_base.same_origin_country and (my_is_diaspora or coalesce(candidate_base.candidate_is_diaspora, false)) then 1.00
          when candidate_base.same_origin_country then 0.82
          when candidate_base.origin_residence_bridge then 0.48
          else 0
        end
      ) as origin_affinity_score,
      coalesce(candidate_base.market_quality_score_raw, 0)::double precision as market_quality_score,
      (
        case candidate_base.premium_rank
          when 2 then 2.4
          when 1 then 1.1
          else 0
        end
      ) as premium_visibility_bonus
    from candidate_base
    left join viewer_feedback
      on viewer_feedback.target_profile_id = candidate_base.id
  ),
  boosted as (
    select
      boosted_base.*,
      (
        case
          when not boosted_base.has_active_boost then 0
          when boosted_base.boost_audience_mode = 'nearby' then
            case
              when v_segment = 'nearby'
                and boosted_base.distance_km is not null
                and boosted_base.distance_km <= 25 then 1.00
              when boosted_base.same_city then 1.00
              when boosted_base.same_region then 0.82
              when boosted_base.same_country then 0.58
              when boosted_base.distance_km is not null and boosted_base.distance_km <= 100 then 0.48
              else 0.12
            end
          when boosted_base.boost_audience_mode = 'active_now' then
            case
              when v_segment = 'active_now'
                and boosted_base.last_active >= now() - interval '10 minutes' then 1.00
              when boosted_base.last_active >= now() - interval '15 minutes' then 0.82
              when boosted_base.last_active >= now() - interval '60 minutes' then 0.56
              else 0.10
            end
          when boosted_base.boost_audience_mode = 'intent_match' then
            case
              when boosted_base.same_looking_for then 1.00
              when boosted_base.has_intent_content and boosted_base.viewer_intent_opened_count > 0 then 0.86
              when boosted_base.has_intent_content then 0.52
              else 0.14
            end
          when boosted_base.boost_audience_mode = 'second_look' then
            case
              when (
                boosted_base.viewer_saved_count > 0
                or boosted_base.viewer_opened_count > 0
                or boosted_base.viewer_signal_opened_count + boosted_base.viewer_intent_opened_count > 0
              )
                and boosted_base.viewer_pass_count = 0
                and coalesce(boosted_base.viewer_last_pass_at, '-infinity'::timestamptz) < now() - interval '21 days' then 1.00
              when boosted_base.viewer_seen_count >= 2
                and boosted_base.viewer_pass_count = 0 then 0.72
              else 0.12
            end
          else
            case
              when v_segment = 'for_you' then 1.00
              when boosted_base.same_city or boosted_base.same_region then 0.78
              when boosted_base.same_country then 0.54
              else 0.32
            end
        end
      ) as boost_audience_alignment,
      (
        case
          when not boosted_base.has_active_boost then 0
          when boosted_base.boost_focus_mode = 'intro' then
            case
              when boosted_base.has_intro_media and boosted_base.viewer_intro_count = 0 then 1.00
              when boosted_base.has_intro_media then 0.82
              else 0.10
            end
          when boosted_base.boost_focus_mode = 'intent' then
            case
              when boosted_base.same_looking_for then 1.00
              when boosted_base.has_intent_content and boosted_base.viewer_intent_opened_count = 0 then 0.88
              when boosted_base.has_intent_content then 0.70
              else 0.12
            end
          else
            case
              when boosted_base.has_intro_media or length(coalesce(boosted_base.bio, '')) >= 30 then 0.82
              else 0.56
            end
        end
      ) as boost_focus_alignment,
      (
        case
          when not boosted_base.has_active_boost then 0
          else
            (case when boosted_base.boost_type = 'smart' then 1.4 else 0.8 end)
            + (case when v_segment = 'for_you' then 1.8 when v_segment = 'active_now' then 1.4 else 1.2 end)
            + (
              case
                when boosted_base.boost_audience_mode = 'nearby' then
                  case
                    when v_segment = 'nearby'
                      and boosted_base.distance_km is not null
                      and boosted_base.distance_km <= 25 then 1.00
                    when boosted_base.same_city then 1.00
                    when boosted_base.same_region then 0.82
                    when boosted_base.same_country then 0.58
                    when boosted_base.distance_km is not null and boosted_base.distance_km <= 100 then 0.48
                    else 0.12
                  end
                when boosted_base.boost_audience_mode = 'active_now' then
                  case
                    when v_segment = 'active_now'
                      and boosted_base.last_active >= now() - interval '10 minutes' then 1.00
                    when boosted_base.last_active >= now() - interval '15 minutes' then 0.82
                    when boosted_base.last_active >= now() - interval '60 minutes' then 0.56
                    else 0.10
                  end
                when boosted_base.boost_audience_mode = 'intent_match' then
                  case
                    when boosted_base.same_looking_for then 1.00
                    when boosted_base.has_intent_content and boosted_base.viewer_intent_opened_count > 0 then 0.86
                    when boosted_base.has_intent_content then 0.52
                    else 0.14
                  end
                when boosted_base.boost_audience_mode = 'second_look' then
                  case
                    when (
                      boosted_base.viewer_saved_count > 0
                      or boosted_base.viewer_opened_count > 0
                      or boosted_base.viewer_signal_opened_count + boosted_base.viewer_intent_opened_count > 0
                    )
                      and boosted_base.viewer_pass_count = 0
                      and coalesce(boosted_base.viewer_last_pass_at, '-infinity'::timestamptz) < now() - interval '21 days' then 1.00
                    when boosted_base.viewer_seen_count >= 2
                      and boosted_base.viewer_pass_count = 0 then 0.72
                    else 0.12
                  end
                else
                  case
                    when v_segment = 'for_you' then 1.00
                    when boosted_base.same_city or boosted_base.same_region then 0.78
                    when boosted_base.same_country then 0.54
                    else 0.32
                  end
              end
            ) * (case when boosted_base.boost_type = 'smart' then 3.6 else 2.8 end)
            + (
              case
                when boosted_base.boost_focus_mode = 'intro' then
                  case
                    when boosted_base.has_intro_media and boosted_base.viewer_intro_count = 0 then 1.00
                    when boosted_base.has_intro_media then 0.82
                    else 0.10
                  end
                when boosted_base.boost_focus_mode = 'intent' then
                  case
                    when boosted_base.same_looking_for then 1.00
                    when boosted_base.has_intent_content and boosted_base.viewer_intent_opened_count = 0 then 0.88
                    when boosted_base.has_intent_content then 0.70
                    else 0.12
                  end
                else
                  case
                    when boosted_base.has_intro_media or length(coalesce(boosted_base.bio, '')) >= 30 then 0.82
                    else 0.56
                  end
              end
            ) * (case when boosted_base.boost_focus_mode = 'profile' then 1.2 else 1.8 end)
        end
      ) as boost_visibility_bonus
    from scored boosted_base
  ),
  ranked as (
    select
      boosted.*,
      (
        case v_segment
          when 'nearby' then
            100 * (
              0.28 * boosted.geo_affinity_score +
              0.26 * boosted.distance_score +
              0.16 * boosted.activity_score +
              0.12 * boosted.interest_score +
              0.03 * boosted.origin_affinity_score +
              0.08 * boosted.verification_score +
              0.05 * boosted.richness_score +
              0.02 * boosted.market_quality_score
            )
          when 'active_now' then
            100 * (
              0.27 * boosted.activity_score +
              0.23 * boosted.geo_affinity_score +
              0.17 * boosted.interest_score +
              0.06 * boosted.origin_affinity_score +
              0.11 * boosted.distance_score +
              0.08 * boosted.verification_score +
              0.07 * boosted.richness_score +
              0.01 * boosted.market_quality_score
            )
          else
            100 * (
              0.23 * boosted.interest_score +
              0.18 * boosted.geo_affinity_score +
              0.12 * boosted.origin_affinity_score +
              0.12 * boosted.activity_score +
              0.10 * boosted.distance_score +
              0.09 * boosted.verification_score +
              0.11 * boosted.richness_score +
              0.05 * boosted.market_quality_score
            )
        end
        + least(boosted.viewer_opened_count, 3) * 2.8
        + least(boosted.viewer_full_open_count, 3) * 1.8
        + least(boosted.viewer_intro_count, 2) * 2.0
        + least(boosted.viewer_saved_count, 2) * 3.2
        + least(boosted.viewer_signal_opened_count + boosted.viewer_intent_opened_count, 3) * 1.9
        + least(greatest(boosted.viewer_positive_count - boosted.viewer_undo_count, 0), 2) * 4.5
        + least(boosted.viewer_long_dwell_count, 3) * 1.4
        + least(boosted.viewer_avg_dwell_ms / 4000.0, 1.5) * 1.8
        + case
            when boosted.viewer_last_positive_at >= now() - interval '7 days' then 3.6
            when boosted.viewer_last_positive_at >= now() - interval '21 days' then 1.8
            else 0
          end
        + case
            when v_segment = 'for_you' and boosted.exploration_candidate then 2.2
            when v_segment = 'active_now' and boosted.exploration_candidate and boosted.activity_score >= 0.60 then 1.2
            when v_segment = 'nearby'
              and boosted.exploration_candidate
              and boosted.distance_km is not null
              and boosted.distance_km <= 25 then 0.9
            when boosted.market_impressions < 20 and boosted.market_quality_score >= 0.30 then 0.7
            else 0
          end
        + case
            when v_segment = 'active_now'
              and boosted.has_active_moment
              and boosted.last_active >= now() - interval '10 minutes' then 4.2
            when v_segment = 'active_now' and boosted.has_active_moment then 2.4
            else 0
          end
        + case
            when v_segment = 'active_now' and boosted.last_active >= now() - interval '3 minutes' then 4.0
            when v_segment = 'active_now' and boosted.last_active >= now() - interval '10 minutes' then 2.2
            when v_segment = 'active_now' and boosted.last_active >= now() - interval '20 minutes' then 0.9
            else 0
          end
        + case
            when v_segment = 'active_now' and boosted.distance_km is not null and boosted.distance_km <= 10 then 2.2
            when v_segment = 'active_now' and boosted.distance_km is not null and boosted.distance_km <= 25 then 1.2
            when v_segment = 'active_now' and boosted.distance_km is not null and boosted.distance_km <= 50 then 0.6
            else 0
          end
        - case
            when boosted.market_impressions >= 120
              and boosted.market_quality_score < 0.08
              and boosted.market_positive_rate < 0.04 then 3.0
            when boosted.market_impressions >= 60
              and boosted.market_quality_score < 0.10
              and boosted.market_positive_rate < 0.05 then 1.6
            else 0
          end
        - least(boosted.viewer_seen_count, 6) * 0.9
        - least(boosted.viewer_pass_count, 3) * 5.5
        - least(boosted.viewer_undo_count, 2) * 1.6
        - case
            when boosted.viewer_last_pass_at >= now() - interval '7 days' then 7.5
            when boosted.viewer_last_pass_at >= now() - interval '21 days' then 3.0
            else 0
          end
        + case
            when v_segment = 'for_you' and boosted.same_city then 12.0
            when v_segment = 'for_you' and boosted.same_region then 7.0
            when v_segment = 'for_you' and boosted.same_country then 4.4
            when v_segment = 'for_you' and boosted.same_origin_country and (my_is_diaspora or coalesce(boosted.candidate_is_diaspora, false)) then 5.5
            when v_segment = 'for_you' and boosted.same_origin_country then 2.8
            when v_segment = 'for_you' and boosted.origin_residence_bridge then 1.5
            when v_segment = 'active_now' and boosted.same_city then 6.0
            when v_segment = 'active_now' and boosted.same_region then 3.5
            when v_segment = 'active_now' and boosted.same_country then 2.2
            when v_segment = 'active_now' and boosted.same_origin_country then 1.6
            when v_segment = 'nearby' and boosted.same_city then 5.0
            when v_segment = 'nearby' and boosted.same_region then 2.5
            when v_segment = 'nearby' and boosted.same_origin_country then 1.0
            else 0
          end
        + case
            when v_segment = 'for_you' and boosted.same_looking_for then 2.4
            when v_segment = 'active_now' and boosted.same_looking_for then 1.2
            else 0
          end
        + case
            when boosted.market_impressions < 8 then 1.9
            when boosted.market_impressions < 20 then 0.9
            else 0
          end
        + boosted.premium_visibility_bonus
        + boosted.boost_visibility_bonus
        + ((abs(hashtext(boosted.id::text || current_date::text)) % 100)::double precision / 100.0) * 2.4
      ) as final_score
    from boosted
  ),
  diversified as (
    select
      ranked.*,
      row_number() over (
        partition by ranked.candidate_city_group
        order by ranked.final_score desc, ranked.last_active desc nulls last, ranked.updated_at desc
      ) as city_rank,
      row_number() over (
        partition by ranked.candidate_country_group
        order by ranked.final_score desc, ranked.last_active desc nulls last, ranked.updated_at desc
      ) as country_rank,
      row_number() over (
        partition by ranked.candidate_region_group
        order by ranked.final_score desc, ranked.last_active desc nulls last, ranked.updated_at desc
      ) as region_rank
    from ranked
  ),
  ordered as (
    select
      diversified.*,
      (
        diversified.final_score
        - case
            when v_segment = 'for_you' then
              greatest(diversified.city_rank - 2, 0) * 0.55
              + greatest(diversified.region_rank - 3, 0) * 0.22
              + greatest(diversified.country_rank - 4, 0) * 0.18
            when v_segment = 'active_now' then
              greatest(diversified.city_rank - 2, 0) * 0.30
              + greatest(diversified.region_rank - 3, 0) * 0.18
            else
              greatest(diversified.city_rank - 3, 0) * 0.16
              + greatest(diversified.region_rank - 4, 0) * 0.10
          end
      ) as adjusted_score
    from diversified
  )
  select
    ordered.id,
    ordered.user_id,
    ordered.full_name,
    ordered.age,
    ordered.bio,
    ordered.avatar_url,
    ordered.profile_video,
    ordered.location,
    ordered.latitude,
    ordered.longitude,
    ordered.region,
    ordered.tribe,
    ordered.religion::text as religion,
    ordered.personality_type,
    (ordered.last_active is not null and ordered.last_active >= now() - interval '15 minutes') as is_active,
    (ordered.last_active is not null and ordered.last_active >= now() - interval '3 minutes') as online,
    ordered.last_active,
    (coalesce(ordered.verification_level, 0) > 0) as verified,
    ordered.verification_level,
    least(100, greatest(0, round(ordered.adjusted_score)))::numeric as ai_score,
    ordered.distance_km,
    ordered.city,
    ordered.current_country,
    ordered.current_country_code,
    ordered.location_precision::text as location_precision,
    jsonb_build_object(
      'version', 'v4',
      'segment', v_segment,
      'premium_plan', ordered.premium_plan,
      'has_active_boost', ordered.has_active_boost,
      'boost_ends_at', ordered.boost_ends_at,
      'boost_type', ordered.boost_type,
      'boost_audience_mode', ordered.boost_audience_mode,
      'boost_focus_mode', ordered.boost_focus_mode,
      'subscription_visibility_score', null,
      'public_reasons', to_jsonb(array_remove(array[
        case when ordered.interest_score >= 0.25 then 'shared_interests' end,
        case when ordered.activity_score >= 0.60 then 'recently_active' end,
        case when ordered.same_city then 'same_city' end,
        case when not ordered.same_city and ordered.same_region then 'same_region' end,
        case when ordered.same_origin_country then 'shared_origin' end,
        case when ordered.same_looking_for then 'same_looking_for' end,
        case when ordered.has_active_moment then 'active_moment' end,
        case when ordered.has_active_boost then 'boosted' end,
        case when ordered.premium_plan in ('SILVER', 'GOLD') then 'premium' end
      ]::text[], null))
    ) as recommendation_reasons
  from ordered
  order by
    case when v_segment = 'nearby' and ordered.distance_km is null then 1 else 0 end,
    ordered.adjusted_score desc,
    case when v_segment = 'for_you' then ordered.geo_bucket else 3 end asc,
    ordered.distance_km asc nulls last,
    ordered.last_active desc nulls last,
    ordered.updated_at desc
  limit v_limit;
end;
$$;


ALTER FUNCTION "public"."get_vibes_recommendations_v3"("p_user_id" "uuid", "p_segment" "text", "p_limit" integer, "p_active_window_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_viewed_profile_prompts"("p_profile_id" "uuid", "p_viewer_profile_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "profile_id" "uuid", "prompt_key" "text", "prompt_title" "text", "prompt_type" "text", "answer" "text", "guess_mode" "text", "guess_options" "jsonb", "hint_text" "text", "reveal_policy" "text", "viewer_guess" "text", "viewer_guess_is_correct" boolean, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_authorized_viewer uuid;
begin
  if p_viewer_profile_id is not null then
    select p.id
      into v_authorized_viewer
    from public.profiles p
    where p.id = p_viewer_profile_id
      and p.user_id = auth.uid()
    limit 1;
  end if;

  return query
  select
    pp.id,
    pp.profile_id,
    pp.prompt_key,
    pp.prompt_title,
    coalesce(pp.prompt_type, 'standard') as prompt_type,
    case
      when coalesce(pp.prompt_type, 'standard') = 'standard' then pp.answer
      when coalesce(pp.reveal_policy, 'never') = 'after_correct' and coalesce(g.is_correct, false) then pp.answer
      else ''
    end as answer,
    pp.guess_mode,
    pp.guess_options,
    pp.hint_text,
    coalesce(pp.reveal_policy, 'never') as reveal_policy,
    g.guessed_value as viewer_guess,
    g.is_correct as viewer_guess_is_correct,
    pp.created_at
  from public.profile_prompts pp
  left join public.profile_prompt_guesses g
    on g.profile_prompt_id = pp.id
   and g.viewer_profile_id = v_authorized_viewer
  where pp.profile_id = p_profile_id
  order by pp.created_at desc;
end;
$$;


ALTER FUNCTION "public"."get_viewed_profile_prompts"("p_profile_id" "uuid", "p_viewer_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_circle_pulse_comment_count_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if tg_op = 'INSERT' then
    perform public.sync_circle_pulse_item_comment_count(new.pulse_item_id);
    return new;
  end if;

  if tg_op = 'DELETE' then
    perform public.sync_circle_pulse_item_comment_count(old.pulse_item_id);
    return old;
  end if;

  if tg_op = 'UPDATE' then
    if old.pulse_item_id is distinct from new.pulse_item_id then
      perform public.sync_circle_pulse_item_comment_count(old.pulse_item_id);
      perform public.sync_circle_pulse_item_comment_count(new.pulse_item_id);
    elsif old.status is distinct from new.status then
      perform public.sync_circle_pulse_item_comment_count(new.pulse_item_id);
    end if;
    return new;
  end if;

  return null;
end;
$$;


ALTER FUNCTION "public"."handle_circle_pulse_comment_count_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_mutual_swipe"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
begin
  set local search_path = public, pg_catalog;
  if new.action in ('LIKE','SUPERLIKE') then
    if exists (
      select 1 from swipes
      where swiper_id = new.target_id
        and target_id = new.swiper_id
        and action in ('LIKE','SUPERLIKE')
    ) then
      insert into matches (user1_id, user2_id, status, created_at, updated_at)
      values (
        least(new.swiper_id, new.target_id),
        greatest(new.swiper_id, new.target_id),
        'ACCEPTED'::match_status,
        now(), now()
      )
      on conflict (user1_id, user2_id) do update
      set status = 'ACCEPTED',
          updated_at = now();
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."handle_mutual_swipe"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_gold_entitlement"("p_user_id" "uuid" DEFAULT "auth"."uid"(), "p_profile_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_plan public.subscription_type := 'FREE';
  v_profile_user_id uuid;
begin
  if p_user_id is null and p_profile_id is not null then
    select p.user_id
      into v_profile_user_id
    from public.profiles p
    where p.id = p_profile_id
      and p.deleted_at is null
    limit 1;

    p_user_id := v_profile_user_id;
  end if;

  if p_user_id is null then
    return false;
  end if;

  if public.is_admin_user(p_user_id) then
    return true;
  end if;

  v_plan := public.get_active_subscription_plan(p_user_id);
  return v_plan = 'GOLD'::public.subscription_type;
end;
$$;


ALTER FUNCTION "public"."has_gold_entitlement"("p_user_id" "uuid", "p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_usable_vibes_coordinates"("p_latitude" double precision, "p_longitude" double precision) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  select
    p_latitude is not null
    and p_longitude is not null
    and p_latitude between -90 and 90
    and p_longitude between -180 and 180
    and not (p_latitude = 0 and p_longitude = 0)
$$;


ALTER FUNCTION "public"."has_usable_vibes_coordinates"("p_latitude" double precision, "p_longitude" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."infer_vibes_location_coordinates"("p_city" "text", "p_region" "text", "p_country" "text", "p_country_code" "text") RETURNS TABLE("latitude" double precision, "longitude" double precision)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  with input_normalized as (
    select
      public.normalize_vibes_country_code(p_country, p_country_code) as country_code_norm,
      nullif(lower(btrim(coalesce(
        public.normalize_vibes_country_name(p_country, p_country_code),
        ''
      ))), '') as country_norm,
      case
        when nullif(lower(btrim(coalesce(p_region, ''))), '') is null then null
        when nullif(lower(btrim(coalesce(p_region, ''))), '') in ('africa', 'north america', 'south america', 'europe', 'asia', 'oceania', 'middle east') then null
        when nullif(lower(btrim(coalesce(p_region, ''))), '') = nullif(lower(btrim(coalesce(
          public.normalize_vibes_country_name(p_country, p_country_code),
          ''
        ))), '') then null
        when public.normalize_vibes_country_code(p_country, p_country_code) is not null
          and nullif(lower(btrim(coalesce(p_region, ''))), '') = lower(public.normalize_vibes_country_code(p_country, p_country_code)) then null
        else nullif(lower(btrim(coalesce(p_region, ''))), '')
      end as region_norm,
      case
        when nullif(lower(btrim(coalesce(p_city, ''))), '') is null then null
        when nullif(lower(btrim(coalesce(p_city, ''))), '') in ('africa', 'north america', 'south america', 'europe', 'asia', 'oceania', 'middle east') then null
        when nullif(lower(btrim(coalesce(p_city, ''))), '') = nullif(lower(btrim(coalesce(p_region, ''))), '') then null
        when nullif(lower(btrim(coalesce(p_city, ''))), '') = nullif(lower(btrim(coalesce(
          public.normalize_vibes_country_name(p_country, p_country_code),
          ''
        ))), '') then null
        when public.normalize_vibes_country_code(p_country, p_country_code) is not null
          and nullif(lower(btrim(coalesce(p_city, ''))), '') = lower(public.normalize_vibes_country_code(p_country, p_country_code)) then null
        when nullif(lower(btrim(coalesce(p_city, ''))), '') ~ '(region|district|province|state|county|municipality|metropolitan)' then null
        else nullif(lower(btrim(coalesce(p_city, ''))), '')
      end as city_norm
  ),
  city_match as (
    select
      avg(profile.latitude)::double precision as latitude,
      avg(profile.longitude)::double precision as longitude,
      count(*)::integer as support_rows
    from public.profiles profile
    cross join input_normalized input
    cross join lateral (
      select
        public.normalize_vibes_country_code(
          profile.current_country,
          profile.current_country_code
        ) as current_country_code_norm,
        nullif(lower(btrim(coalesce(
          public.normalize_vibes_country_name(
            profile.current_country,
            profile.current_country_code
          ),
          ''
        ))), '') as current_country_norm,
        case
          when nullif(lower(btrim(coalesce(profile.city, ''))), '') is null then null
          when nullif(lower(btrim(coalesce(profile.city, ''))), '') in ('africa', 'north america', 'south america', 'europe', 'asia', 'oceania', 'middle east') then null
          when nullif(lower(btrim(coalesce(profile.city, ''))), '') = nullif(lower(btrim(coalesce(profile.region, ''))), '') then null
          when nullif(lower(btrim(coalesce(profile.city, ''))), '') = nullif(lower(btrim(coalesce(
            public.normalize_vibes_country_name(
              profile.current_country,
              profile.current_country_code
            ),
            ''
          ))), '') then null
          when public.normalize_vibes_country_code(profile.current_country, profile.current_country_code) is not null
            and nullif(lower(btrim(coalesce(profile.city, ''))), '') = lower(public.normalize_vibes_country_code(profile.current_country, profile.current_country_code)) then null
          when nullif(lower(btrim(coalesce(profile.city, ''))), '') ~ '(region|district|province|state|county|municipality|metropolitan)' then null
          else nullif(lower(btrim(coalesce(profile.city, ''))), '')
        end as city_norm
    ) normalized
    where profile.deleted_at is null
      and profile.latitude is not null
      and profile.longitude is not null
      and input.city_norm is not null
      and normalized.city_norm = input.city_norm
      and (
        (input.country_code_norm is not null and normalized.current_country_code_norm = input.country_code_norm)
        or (
          input.country_code_norm is null
          and normalized.current_country_code_norm is null
          and input.country_norm is not null
          and normalized.current_country_norm = input.country_norm
        )
      )
    having count(*) > 0
  ),
  region_match as (
    select
      avg(profile.latitude)::double precision as latitude,
      avg(profile.longitude)::double precision as longitude,
      count(*)::integer as support_rows
    from public.profiles profile
    cross join input_normalized input
    cross join lateral (
      select
        public.normalize_vibes_country_code(
          profile.current_country,
          profile.current_country_code
        ) as current_country_code_norm,
        nullif(lower(btrim(coalesce(
          public.normalize_vibes_country_name(
            profile.current_country,
            profile.current_country_code
          ),
          ''
        ))), '') as current_country_norm,
        case
          when nullif(lower(btrim(coalesce(profile.region, ''))), '') is null then null
          when nullif(lower(btrim(coalesce(profile.region, ''))), '') in ('africa', 'north america', 'south america', 'europe', 'asia', 'oceania', 'middle east') then null
          when nullif(lower(btrim(coalesce(profile.region, ''))), '') = nullif(lower(btrim(coalesce(
            public.normalize_vibes_country_name(
              profile.current_country,
              profile.current_country_code
            ),
            ''
          ))), '') then null
          when public.normalize_vibes_country_code(profile.current_country, profile.current_country_code) is not null
            and nullif(lower(btrim(coalesce(profile.region, ''))), '') = lower(public.normalize_vibes_country_code(profile.current_country, profile.current_country_code)) then null
          else nullif(lower(btrim(coalesce(profile.region, ''))), '')
        end as region_norm
    ) normalized
    where profile.deleted_at is null
      and profile.latitude is not null
      and profile.longitude is not null
      and input.region_norm is not null
      and normalized.region_norm = input.region_norm
      and (
        (input.country_code_norm is not null and normalized.current_country_code_norm = input.country_code_norm)
        or (
          input.country_code_norm is null
          and normalized.current_country_code_norm is null
          and input.country_norm is not null
          and normalized.current_country_norm = input.country_norm
        )
      )
    having count(*) > 0
  ),
  country_match as (
    select
      avg(profile.latitude)::double precision as latitude,
      avg(profile.longitude)::double precision as longitude,
      count(*)::integer as support_rows
    from public.profiles profile
    cross join input_normalized input
    cross join lateral (
      select
        public.normalize_vibes_country_code(
          profile.current_country,
          profile.current_country_code
        ) as current_country_code_norm,
        nullif(lower(btrim(coalesce(
          public.normalize_vibes_country_name(
            profile.current_country,
            profile.current_country_code
          ),
          ''
        ))), '') as current_country_norm
    ) normalized
    where profile.deleted_at is null
      and profile.latitude is not null
      and profile.longitude is not null
      and (
        (input.country_code_norm is not null and normalized.current_country_code_norm = input.country_code_norm)
        or (
          input.country_code_norm is null
          and normalized.current_country_code_norm is null
          and input.country_norm is not null
          and normalized.current_country_norm = input.country_norm
        )
      )
    having count(*) > 0
  )
  select match.latitude, match.longitude
  from (
    select 1 as priority, city_match.latitude, city_match.longitude, city_match.support_rows
    from city_match

    union all

    select 2 as priority, region_match.latitude, region_match.longitude, region_match.support_rows
    from region_match

    union all

    select 3 as priority, country_match.latitude, country_match.longitude, country_match.support_rows
    from country_match
  ) match
  where match.latitude is not null
    and match.longitude is not null
  order by match.priority asc, match.support_rows desc
  limit 1
$$;


ALTER FUNCTION "public"."infer_vibes_location_coordinates"("p_city" "text", "p_region" "text", "p_country" "text", "p_country_code" "text") OWNER TO "postgres";


