CREATE OR REPLACE FUNCTION "public"."is_match"("a" "uuid", "b" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  res boolean := false;
  a_profile uuid;
  b_profile uuid;
  a_candidates uuid[];
  b_candidates uuid[];
BEGIN
  IF a IS NULL OR b IS NULL THEN
    RETURN false;
  END IF;

  a_candidates := ARRAY[a];
  b_candidates := ARRAY[b];

  SELECT id INTO a_profile FROM public.profiles WHERE user_id = a;
  SELECT id INTO b_profile FROM public.profiles WHERE user_id = b;

  IF a_profile IS NOT NULL THEN
    a_candidates := array_append(a_candidates, a_profile);
  END IF;
  IF b_profile IS NOT NULL THEN
    b_candidates := array_append(b_candidates, b_profile);
  END IF;

  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'matches' AND column_name = 'user_a')
     AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'matches' AND column_name = 'user_b') THEN
    EXECUTE 'SELECT EXISTS (SELECT 1 FROM public.matches WHERE (user_a = ANY($1) AND user_b = ANY($2)) OR (user_a = ANY($2) AND user_b = ANY($1)))'
      INTO res USING a_candidates, b_candidates;

  ELSIF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'matches' AND column_name = 'user1_id')
     AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'matches' AND column_name = 'user2_id') THEN
    EXECUTE 'SELECT EXISTS (SELECT 1 FROM public.matches WHERE (user1_id = ANY($1) AND user2_id = ANY($2)) OR (user1_id = ANY($2) AND user2_id = ANY($1)))'
      INTO res USING a_candidates, b_candidates;

  ELSIF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'matches' AND column_name = 'user_id')
     AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'matches' AND column_name = 'target_id') THEN
    EXECUTE 'SELECT EXISTS (SELECT 1 FROM public.matches WHERE (user_id = ANY($1) AND target_id = ANY($2)) OR (user_id = ANY($2) AND target_id = ANY($1)))'
      INTO res USING a_candidates, b_candidates;
  ELSE
    res := false;
  END IF;

  RETURN res;
END;
$_$;


ALTER FUNCTION "public"."is_match"("a" "uuid", "b" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_quiet_hours"("p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  prefs record;
  local_time time;
BEGIN
  SELECT quiet_hours_enabled, quiet_hours_start, quiet_hours_end, quiet_hours_tz
  INTO prefs
  FROM public.notification_prefs
  WHERE user_id = p_user_id;

  IF prefs IS NULL OR prefs.quiet_hours_enabled IS DISTINCT FROM true THEN
    RETURN false;
  END IF;

  local_time := (now() AT TIME ZONE COALESCE(prefs.quiet_hours_tz, 'UTC'))::time;

  IF prefs.quiet_hours_start = prefs.quiet_hours_end THEN
    RETURN false;
  END IF;

  IF prefs.quiet_hours_start < prefs.quiet_hours_end THEN
    RETURN local_time >= prefs.quiet_hours_start AND local_time < prefs.quiet_hours_end;
  END IF;

  RETURN local_time >= prefs.quiet_hours_start OR local_time < prefs.quiet_hours_end;
END;
$$;


ALTER FUNCTION "public"."is_quiet_hours"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_trusted_boost_viewer"("p_viewer_profile_id" "uuid", "p_target_profile_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  select exists (
    select 1
    from public.profiles viewer
    left join public.internal_admins ia
      on ia.user_id = viewer.user_id
    left join public.profiles target
      on target.id = p_target_profile_id
    where viewer.id = p_viewer_profile_id
      and viewer.deleted_at is null
      and coalesce(viewer.account_state, 'active') = 'active'
      and coalesce(viewer.profile_completed, false) = true
      and viewer.duplicate_of_user_id is null
      and viewer.recovered_to_user_id is null
      and ia.user_id is null
      and (
        p_target_profile_id is null
        or (
          viewer.id <> p_target_profile_id
          and target.id is not null
          and viewer.user_id <> target.user_id
        )
      )
  );
$$;


ALTER FUNCTION "public"."is_trusted_boost_viewer"("p_viewer_profile_id" "uuid", "p_target_profile_id" "uuid") OWNER TO "postgres";


