CREATE OR REPLACE FUNCTION "public"."normalize_message_receipt_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if auth.uid() is not null
    and auth.uid() = old.receiver_id
    and auth.uid() <> old.sender_id then
    if (
      to_jsonb(new) - array['is_read', 'read_at', 'delivered_at']::text[]
    ) is distinct from (
      to_jsonb(old) - array['is_read', 'read_at', 'delivered_at']::text[]
    ) then
      raise exception 'receiver_can_only_update_receipt_fields';
    end if;

    if old.delivered_at is not null and new.delivered_at is distinct from old.delivered_at then
      raise exception 'delivered_at_is_immutable';
    end if;

    if old.read_at is not null and new.read_at is distinct from old.read_at then
      raise exception 'read_at_is_immutable';
    end if;

    if old.is_read = true and coalesce(new.is_read, false) = false then
      raise exception 'cannot_unread_message';
    end if;

    if new.read_at is not null and new.delivered_at is null then
      new.delivered_at := coalesce(old.delivered_at, new.read_at);
    end if;

    if coalesce(new.is_read, false) = true or new.read_at is not null then
      new.is_read := true;
      new.read_at := coalesce(old.read_at, new.read_at, new.delivered_at, now());
    end if;

    if new.read_at is not null and new.delivered_at is not null and new.read_at < new.delivered_at then
      new.read_at := new.delivered_at;
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."normalize_message_receipt_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_vibes_country_code"("p_country" "text", "p_country_code" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  select
    case lower(nullif(btrim(coalesce(p_country, '')), ''))
      when 'ghana' then 'GH'
      when 'united kingdom' then 'GB'
      when 'uk' then 'GB'
      when 'great britain' then 'GB'
      when 'england' then 'GB'
      when 'scotland' then 'GB'
      when 'wales' then 'GB'
      when 'united states' then 'US'
      when 'usa' then 'US'
      when 'united states of america' then 'US'
      when 'canada' then 'CA'
      when 'nigeria' then 'NG'
      when 'south africa' then 'ZA'
      when 'germany' then 'DE'
      when 'netherlands' then 'NL'
      when 'france' then 'FR'
      when 'spain' then 'ES'
      when 'italy' then 'IT'
      when 'australia' then 'AU'
      when 'united arab emirates' then 'AE'
      when 'uae' then 'AE'
      else nullif(upper(btrim(coalesce(p_country_code, ''))), '')
    end
$$;


ALTER FUNCTION "public"."normalize_vibes_country_code"("p_country" "text", "p_country_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_vibes_country_name"("p_country" "text", "p_country_code" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  select
    case
      when lower(nullif(btrim(coalesce(p_country, '')), '')) = 'ghana' then 'Ghana'
      when lower(nullif(btrim(coalesce(p_country, '')), '')) in ('united kingdom', 'uk', 'great britain', 'england', 'scotland', 'wales') then 'United Kingdom'
      when lower(nullif(btrim(coalesce(p_country, '')), '')) in ('united states', 'usa', 'united states of america') then 'United States'
      when lower(nullif(btrim(coalesce(p_country, '')), '')) = 'canada' then 'Canada'
      when lower(nullif(btrim(coalesce(p_country, '')), '')) = 'nigeria' then 'Nigeria'
      when lower(nullif(btrim(coalesce(p_country, '')), '')) = 'south africa' then 'South Africa'
      when lower(nullif(btrim(coalesce(p_country, '')), '')) = 'germany' then 'Germany'
      when lower(nullif(btrim(coalesce(p_country, '')), '')) = 'netherlands' then 'Netherlands'
      when lower(nullif(btrim(coalesce(p_country, '')), '')) = 'france' then 'France'
      when lower(nullif(btrim(coalesce(p_country, '')), '')) = 'spain' then 'Spain'
      when lower(nullif(btrim(coalesce(p_country, '')), '')) = 'italy' then 'Italy'
      when lower(nullif(btrim(coalesce(p_country, '')), '')) = 'australia' then 'Australia'
      when lower(nullif(btrim(coalesce(p_country, '')), '')) in ('united arab emirates', 'uae') then 'United Arab Emirates'
      when nullif(btrim(coalesce(p_country, '')), '') is not null then initcap(lower(btrim(p_country)))
      else
        case upper(nullif(btrim(coalesce(p_country_code, '')), ''))
          when 'GH' then 'Ghana'
          when 'GB' then 'United Kingdom'
          when 'US' then 'United States'
          when 'CA' then 'Canada'
          when 'NG' then 'Nigeria'
          when 'ZA' then 'South Africa'
          when 'DE' then 'Germany'
          when 'NL' then 'Netherlands'
          when 'FR' then 'France'
          when 'ES' then 'Spain'
          when 'IT' then 'Italy'
          when 'AU' then 'Australia'
          when 'AE' then 'United Arab Emirates'
          else null
        end
    end
$$;


ALTER FUNCTION "public"."normalize_vibes_country_name"("p_country" "text", "p_country_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_admins_on_account_recovery_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if lower(coalesce(new.status, 'pending')) <> 'pending' then
    return new;
  end if;

  perform public.notify_internal_admin_queue_item(
    'account_recovery',
    new.id,
    'New account recovery request needs review.',
    jsonb_build_object(
      'recovery_request_id', new.id,
      'requester_user_id', new.requester_user_id,
      'requester_profile_id', new.requester_profile_id
    )
  );

  return new;
end;
$$;


