    SET "search_path" TO 'public'
    AS $$
begin
  if lower(coalesce(new.status, 'pending')) <> 'pending' then
    return new;
  end if;

  perform public.notify_internal_admin_queue_item(
    'verification',
    new.id,
    'New verification request needs review.',
    jsonb_build_object(
      'verification_request_id', new.id,
      'verification_type', new.verification_type,
      'profile_id', new.profile_id,
      'requester_user_id', new.user_id
    )
  );

  return new;
end;
$$;


ALTER FUNCTION "public"."notify_admins_on_verification_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_circle_love_seat_push"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_catalog'
    AS $$
declare
  v_target_user_id uuid;
  v_circle_name text;
  v_featured_name text;
  v_event_type text;
  v_title text;
  v_body text;
begin
  select c.name
    into v_circle_name
  from public.circles c
  where c.id = new.circle_id
  limit 1;

  select p.full_name
    into v_featured_name
  from public.profiles p
  where p.id = new.featured_profile_id
  limit 1;

  if tg_op = 'INSERT' and new.status = 'pending_user_approval' then
    select p.user_id
      into v_target_user_id
    from public.profiles p
    where p.id = new.featured_profile_id
    limit 1;

    v_event_type := 'invitation';
    v_title := 'Step into the Love Seat?';
    v_body := coalesce(v_circle_name, 'Your Circle') || ' invited you to a thoughtful spotlight.';
  elsif tg_op = 'UPDATE'
    and old.status = 'pending_user_approval'
    and new.status in ('active', 'declined') then
    select p.user_id
      into v_target_user_id
    from public.profiles p
    where p.id = new.nominated_by_profile_id
    limit 1;

    v_event_type := case when new.status = 'active' then 'accepted' else 'declined' end;
    v_title := case when new.status = 'active' then 'Love Seat accepted' else 'Love Seat invitation declined' end;
    v_body := coalesce(nullif(btrim(v_featured_name), ''), 'A Circle member')
      || case when new.status = 'active' then ' accepted the Love Seat invitation.' else ' declined the Love Seat invitation.' end;
  elsif tg_op = 'UPDATE'
    and old.status = 'pending_user_approval'
    and new.status = 'archived' then
    select p.user_id
      into v_target_user_id
    from public.profiles p
    where p.id = new.featured_profile_id
    limit 1;

    v_event_type := 'withdrawn';
    v_title := 'Love Seat invitation updated';
    v_body := 'The Love Seat invitation from ' || coalesce(v_circle_name, 'your Circle') || ' is no longer active.';
  elsif tg_op = 'UPDATE'
    and old.status = 'active'
    and new.status = 'ended' then
    select p.user_id
      into v_target_user_id
    from public.profiles p
    where p.id = new.nominated_by_profile_id
    limit 1;

    v_event_type := 'ended';
    v_title := 'Love Seat ended';
    v_body := coalesce(nullif(btrim(v_featured_name), ''), 'A Circle member') || ' left the Love Seat.';
  else
    return new;
  end if;

  if v_target_user_id is null then
    return new;
  end if;

  if exists (
    select 1
    from public.notification_prefs np
    where np.user_id = v_target_user_id
      and np.push_enabled = false
  ) then
    return new;
  end if;

  if public.is_quiet_hours(v_target_user_id) then
    return new;
  end if;

  perform private.send_push_webhook(
    jsonb_build_object(
      'user_id', v_target_user_id,
      'title', v_title,
      'body', v_body,
      'data', jsonb_build_object(
        'type', 'circle_love_seat',
        'event_type', v_event_type,
        'circle_id', new.circle_id,
        'love_seat_id', new.id
      )
    )
  );

  return new;
end;
$$;


ALTER FUNCTION "public"."notify_circle_love_seat_push"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_circle_pulse_comment_push"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_catalog'
    AS $$
declare
  v_actor_name text := 'Someone';
  v_actor_avatar text;
  v_circle_name text := 'your Circle';
  v_item_type text;
  v_love_seat_id uuid;
  v_parent_user_id uuid;
  v_target_user_id uuid;
  v_notified_user_ids uuid[] := array[new.user_id];
  v_payload_base jsonb;
  v_recipient record;
begin
  select
    coalesce(nullif(btrim(p.full_name), ''), 'Someone'),
    p.avatar_url
  into v_actor_name, v_actor_avatar
  from public.profiles p
  where p.id = new.profile_id
  limit 1;

  select
    coalesce(nullif(btrim(c.name), ''), 'your Circle'),
    cpi.item_type,
    cpi.love_seat_id
  into v_circle_name, v_item_type, v_love_seat_id
  from public.circle_pulse_items cpi
  join public.circles c on c.id = cpi.circle_id
  where cpi.id = new.pulse_item_id
  limit 1;

  v_payload_base := jsonb_build_object(
    'circle_id', new.circle_id,
    'pulse_item_id', new.pulse_item_id,
    'comment_id', new.id,
    'parent_comment_id', new.parent_comment_id,
    'actor_profile_id', new.profile_id,
    'name', v_actor_name,
    'avatar_url', v_actor_avatar
  );

  if new.parent_comment_id is not null then
    select cpc.user_id
      into v_parent_user_id
    from public.circle_pulse_comments cpc
    where cpc.id = new.parent_comment_id
    limit 1;

    if v_parent_user_id is not null
      and not (v_parent_user_id = any(v_notified_user_ids)) then
      perform public.enqueue_circle_pulse_push(
        v_parent_user_id,
        new.user_id,
        'circle_discussions',
        v_actor_name,
        v_actor_name || ' replied to your comment in ' || v_circle_name || '.',
        v_payload_base || jsonb_build_object(
          'type', 'circle_pulse_discussion',
          'event_type', 'reply'
        )
      );
      v_notified_user_ids := array_append(v_notified_user_ids, v_parent_user_id);
    end if;
  end if;

  if v_item_type = 'love_seat' and v_love_seat_id is not null then
    select p.user_id
      into v_target_user_id
    from public.circle_love_seats cls
    join public.profiles p on p.id = cls.featured_profile_id
    where cls.id = v_love_seat_id
    limit 1;

    if v_target_user_id is not null
      and not (v_target_user_id = any(v_notified_user_ids)) then
      perform public.enqueue_circle_pulse_push(
        v_target_user_id,
        new.user_id,
        'circle_discussions',
        v_actor_name,
        v_actor_name || ' joined your Love Seat discussion in ' || v_circle_name || '.',
        v_payload_base || jsonb_build_object(
          'type', 'circle_pulse_discussion',
          'event_type', 'love_seat_discussion'
        )
      );
      v_notified_user_ids := array_append(v_notified_user_ids, v_target_user_id);
    end if;
  elsif v_item_type = 'welcome' then
    for v_recipient in
      select distinct p.user_id as user_id
      from public.circle_pulse_welcome_members cpwm
      join public.profiles p on p.id = cpwm.profile_id
      where cpwm.pulse_item_id = new.pulse_item_id
        and cpwm.status = 'active'
        and cpwm.expires_at > timezone('utc'::text, now())
        and p.user_id is not null
    loop
      if v_recipient.user_id is null
        or v_recipient.user_id = any(v_notified_user_ids) then
        continue;
      end if;

      perform public.enqueue_circle_pulse_push(
        v_recipient.user_id,
        new.user_id,
        'circle_discussions',
        v_actor_name,
        v_actor_name || ' posted in your welcome discussion in ' || v_circle_name || '.',
        v_payload_base || jsonb_build_object(
          'type', 'circle_pulse_discussion',
          'event_type', 'welcome_discussion'
        )
      );
      v_notified_user_ids := array_append(v_notified_user_ids, v_recipient.user_id);
    end loop;
  end if;

  if new.parent_comment_id is not null then
    for v_recipient in
      select distinct cpc.user_id as user_id
      from public.circle_pulse_comments cpc
      where cpc.pulse_item_id = new.pulse_item_id
        and cpc.status = 'active'
        and cpc.user_id is not null
        and cpc.id <> new.id
    loop
      if v_recipient.user_id is null
        or v_recipient.user_id = any(v_notified_user_ids) then
        continue;
      end if;

      perform public.enqueue_circle_pulse_push(
        v_recipient.user_id,
        new.user_id,
        'circle_discussions',
        v_actor_name,
        v_actor_name || ' replied in a Circle discussion you joined.',
        v_payload_base || jsonb_build_object(
          'type', 'circle_pulse_discussion',
          'event_type', 'participant_reply'
        )
      );
      v_notified_user_ids := array_append(v_notified_user_ids, v_recipient.user_id);
    end loop;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."notify_circle_pulse_comment_push"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_circle_pulse_comment_reaction_push"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_catalog'
    AS $$
declare
  v_actor_name text := 'Someone';
  v_actor_avatar text;
  v_circle_name text := 'your Circle';
  v_target_user_id uuid;
begin
  select
    coalesce(nullif(btrim(p.full_name), ''), 'Someone'),
    p.avatar_url
  into v_actor_name, v_actor_avatar
  from public.profiles p
  where p.id = new.profile_id
  limit 1;

  select
    cpc.user_id,
    coalesce(nullif(btrim(c.name), ''), 'your Circle')
  into v_target_user_id, v_circle_name
  from public.circle_pulse_comments cpc
  join public.circles c on c.id = cpc.circle_id
  where cpc.id = new.comment_id
  limit 1;

  perform public.enqueue_circle_pulse_push(
    v_target_user_id,
    new.user_id,
    'reactions',
    v_actor_name,
    case
      when new.reaction is not null and new.reaction <> '' then
        v_actor_name || ' reacted to your comment in ' || v_circle_name || '.'
      else
        v_actor_name || ' reacted to your comment.'
    end,
    jsonb_build_object(
      'type', 'circle_pulse_reaction',
      'circle_id', new.circle_id,
      'pulse_item_id', new.pulse_item_id,
      'comment_id', new.comment_id,
      'reaction', new.reaction,
      'actor_profile_id', new.profile_id,
      'name', v_actor_name,
      'avatar_url', v_actor_avatar
    )
  );

  return new;
end;
$$;


ALTER FUNCTION "public"."notify_circle_pulse_comment_reaction_push"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_intent_request_push"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  recipient_user_id uuid;
  actor_user_id uuid;
  actor_name text;
  actor_avatar text;
  body_text text;
begin
  if new.status is distinct from 'pending' then
    return new;
  end if;

  if new.type = 'like_with_note' then
    return new;
  end if;

  if exists (
    select 1
    from public.matches m
    where m.status in ('PENDING', 'ACCEPTED')
      and (
        (m.user1_id = new.actor_id and m.user2_id = new.recipient_id)
        or (m.user1_id = new.recipient_id and m.user2_id = new.actor_id)
      )
  ) then
    return new;
  end if;

  select p.user_id
  into recipient_user_id
  from public.profiles p
  where p.id = new.recipient_id
  limit 1;

  select p.user_id, coalesce(nullif(btrim(p.full_name), ''), 'Someone'), p.avatar_url
  into actor_user_id, actor_name, actor_avatar
  from public.profiles p
  where p.id = new.actor_id
  limit 1;

  if recipient_user_id is null or actor_user_id is null then
    return new;
  end if;

  if exists (
    select 1
    from public.notification_prefs p
    where p.user_id = recipient_user_id
      and p.push_enabled = false
  ) then
    return new;
  end if;

  if public.is_quiet_hours(recipient_user_id) then
    return new;
  end if;

  if exists (
    select 1
    from public.blocks b
    where (b.blocker_id = recipient_user_id and b.blocked_id = actor_user_id)
       or (b.blocker_id = actor_user_id and b.blocked_id = recipient_user_id)
  ) then
    return new;
  end if;

  body_text := case new.type
    when 'connect' then 'Opened the door to a thoughtful conversation.'
    when 'date_request' then 'Would like to take this beyond the app.'
    when 'circle_intro' then 'Opened a warmer introduction to connect.'
    else 'Opened a meaningful way to connect.'
  end;

  perform private.send_push_webhook(
    jsonb_build_object(
      'user_id', recipient_user_id,
      'title', actor_name,
      'body', body_text,
      'data', jsonb_build_object(
        'type', 'intent_request',
        'request_id', new.id,
        'request_type', new.type,
        'profile_id', new.actor_id,
        'peer_user_id', actor_user_id,
        'name', actor_name,
        'avatar_url', actor_avatar
      )
    )
  );

  return new;
end;
$$;


ALTER FUNCTION "public"."notify_intent_request_push"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_internal_admin_queue_item"("p_queue_type" "text", "p_record_id" "uuid", "p_text" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  admin_row record;
  v_metadata jsonb;
begin
  if p_record_id is null then
    return;
  end if;

  v_metadata := jsonb_strip_nulls(
    jsonb_build_object(
      'source', 'admin_queue_trigger',
      'queue_type', p_queue_type,
      'record_id', p_record_id
    ) || coalesce(p_metadata, '{}'::jsonb)
  );

  for admin_row in
    select ia.user_id, ia.role
    from public.internal_admins ia
  loop
    insert into public.system_messages (
      user_id,
      peer_user_id,
      event_type,
      text,
      metadata
    )
    values (
      admin_row.user_id,
      admin_row.user_id,
      'admin_queue_item',
      p_text,
      v_metadata || jsonb_build_object('admin_role', admin_row.role)
    );
  end loop;
end;
$$;


ALTER FUNCTION "public"."notify_internal_admin_queue_item"("p_queue_type" "text", "p_record_id" "uuid", "p_text" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_match_push"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  u1 uuid;
  u2 uuid;
  other_name text;
  other_avatar text;
begin
  if not (new.status = 'ACCEPTED' and (tg_op = 'INSERT' or old.status is distinct from new.status)) then
    return new;
  end if;

  select user_id into u1 from public.profiles where id = new.user1_id limit 1;
  select user_id into u2 from public.profiles where id = new.user2_id limit 1;

  if u1 is null or u2 is null then
    return new;
  end if;

  if not exists (
    select 1
    from public.notification_prefs p
    where p.user_id = u1
      and (p.push_enabled = false or p.matches = false)
  )
  and not public.is_quiet_hours(u1)
  and not exists (
    select 1
    from public.system_messages sm
    where sm.user_id = u1
      and sm.peer_user_id = u2
      and sm.event_type = 'request_accepted'
      and sm.created_at >= (now() - interval '30 seconds')
  )
  then
    select coalesce(nullif(btrim(full_name), ''), 'them'), avatar_url
    into other_name, other_avatar
    from public.profiles
    where id = new.user2_id
    limit 1;

    perform private.send_push_webhook(
      jsonb_build_object(
        'user_id', u1,
        'title', 'It''s a match',
        'body', 'You and ' || other_name || ' saw something in each other. Start with something real.',
        'data', jsonb_build_object(
          'type', 'match',
          'match_id', new.id,
          'profile_id', new.user2_id,
          'peer_user_id', u2,
          'name', other_name,
          'avatar_url', other_avatar
        )
      )
    );
  end if;

  if not exists (
    select 1
    from public.notification_prefs p
    where p.user_id = u2
      and (p.push_enabled = false or p.matches = false)
  )
  and not public.is_quiet_hours(u2)
  and not exists (
    select 1
    from public.system_messages sm
    where sm.user_id = u2
      and sm.peer_user_id = u1
      and sm.event_type = 'request_accepted'
      and sm.created_at >= (now() - interval '30 seconds')
  )
  then
    select coalesce(nullif(btrim(full_name), ''), 'them'), avatar_url
    into other_name, other_avatar
    from public.profiles
    where id = new.user1_id
    limit 1;

    perform private.send_push_webhook(
      jsonb_build_object(
        'user_id', u2,
        'title', 'It''s a match',
        'body', 'You and ' || other_name || ' saw something in each other. Start with something real.',
        'data', jsonb_build_object(
          'type', 'match',
          'match_id', new.id,
          'profile_id', new.user1_id,
          'peer_user_id', u1,
          'name', other_name,
          'avatar_url', other_avatar
        )
      )
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."notify_match_push"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_message_push"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  sender_name text;
  sender_avatar text;
  sender_profile_id uuid;
  body_text text;
  v_date_plan jsonb;
  v_place_name text;
  v_sticker jsonb;
  v_sticker_name text;
  v_sticker_emoji text;
  v_preview_text boolean;
begin
  if exists (
    select 1
    from public.notification_prefs p
    where p.user_id = new.receiver_id
      and (p.push_enabled = false or p.messages = false)
  ) then
    return new;
  end if;

  if exists (
    select 1
    from public.blocks b
    where (b.blocker_id = new.receiver_id and b.blocked_id = new.sender_id)
       or (b.blocker_id = new.sender_id and b.blocked_id = new.receiver_id)
  ) then
    return new;
  end if;

  if exists (
    select 1
    from public.chat_prefs p
    where p.user_id = new.receiver_id
      and p.peer_id = new.sender_id
      and p.muted = true
  ) then
    return new;
  end if;

  select coalesce(p.preview_text, true)
  into v_preview_text
  from public.notification_prefs p
  where p.user_id = new.receiver_id
  limit 1;

  select p.full_name, p.avatar_url, p.id
  into sender_name, sender_avatar, sender_profile_id
  from public.profiles p
  where p.user_id = new.sender_id
  limit 1;

  if sender_profile_id is null then
    select p.full_name, p.avatar_url, p.id
    into sender_name, sender_avatar, sender_profile_id
    from public.profiles p
    where p.id = new.sender_id
    limit 1;
  end if;

  sender_name := coalesce(sender_name, 'New message');

  if coalesce(v_preview_text, true) = false then
    body_text := case
      when new.message_type = 'image' then 'Sent you a photo'
      when new.message_type = 'video' then 'Sent you a video'
      when new.message_type = 'voice' then 'Sent you a voice message'
      when new.message_type = 'location' then 'Sent you a location'
      when new.message_type = 'mood_sticker' then 'Sent you a sticker'
      else 'Sent you a message'
    end;
  elsif new.message_type = 'image' then
    body_text := 'Photo';
  elsif new.message_type = 'video' then
    body_text := 'Video';
  elsif new.message_type = 'voice' then
    body_text := 'Voice message';
  elsif new.message_type = 'location' then
    body_text := 'Location';
  elsif new.message_type = 'text'
    and new.text is not null
    and new.text like 'date_plan::%' then
    begin
      v_date_plan := substring(new.text from char_length('date_plan::') + 1)::jsonb;
      v_place_name := nullif(btrim(coalesce(v_date_plan->>'placeName', '')), '');
      body_text := coalesce('Date suggestion: ' || v_place_name, 'Date suggestion');
    exception
      when others then
        body_text := 'Date suggestion';
    end;
  elsif new.message_type = 'mood_sticker'
    or (new.message_type = 'text' and new.text is not null and new.text like 'sticker::%') then
    begin
      v_sticker := substring(new.text from char_length('sticker::') + 1)::jsonb;
      v_sticker_name := nullif(btrim(coalesce(v_sticker->>'name', '')), '');
      v_sticker_emoji := nullif(btrim(coalesce(v_sticker->>'emoji', '')), '');
      body_text := case
        when v_sticker_name is not null and v_sticker_emoji is not null then 'Sticker: ' || v_sticker_name || ' ' || v_sticker_emoji
        when v_sticker_name is not null then 'Sticker: ' || v_sticker_name
        when v_sticker_emoji is not null then 'Sticker ' || v_sticker_emoji
        else 'Sticker'
      end;
    exception
      when others then
        body_text := 'Sticker';
    end;
  elsif new.message_type = 'text'
    and new.text is not null
    and new.text <> ''
    and new.text ~* '^https?://' then
    body_text := 'Photo';
  elsif new.message_type = 'text'
    and new.text is not null
    and new.text <> '' then
    body_text := new.text;
  else
    body_text := 'Sent you a message';
  end if;

  perform private.send_push_webhook(
    jsonb_build_object(
      'user_id', new.receiver_id,
      'title', sender_name,
      'body', body_text,
      'data', jsonb_build_object(
        'type', 'message',
        'message_id', new.id,
        'profile_id', sender_profile_id,
        'peer_user_id', new.sender_id,
        'name', sender_name,
        'avatar_url', sender_avatar
      )
    )
  );
  return new;
end;
$$;


ALTER FUNCTION "public"."notify_message_push"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_message_reaction_push"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  msg_sender uuid;
  msg_receiver uuid;
  target_user_id uuid;
  reactor_name text;
  reactor_avatar text;
  reactor_profile_id uuid;
  v_message_text text;
  v_message_type text;
  v_preview_text boolean;
  v_snippet text;
  v_sticker jsonb;
  v_sticker_name text;
  v_sticker_emoji text;
  v_sticker_target text;
  body_text text;
begin
  select m.sender_id, m.receiver_id, m.text, m.message_type
  into msg_sender, msg_receiver, v_message_text, v_message_type
  from public.messages m
  where m.id = new.message_id;

  if msg_sender is null or msg_receiver is null then
    return new;
  end if;

  if new.user_id = msg_sender then
    target_user_id := msg_receiver;
  else
    target_user_id := msg_sender;
  end if;

  if target_user_id is null then
    return new;
  end if;

  if exists (
    select 1
    from public.notification_prefs p
    where p.user_id = target_user_id
      and (p.push_enabled = false or p.message_reactions = false)
  ) then
    return new;
  end if;

  if exists (
    select 1
    from public.blocks b
    where (b.blocker_id = target_user_id and b.blocked_id = new.user_id)
       or (b.blocker_id = new.user_id and b.blocked_id = target_user_id)
  ) then
    return new;
  end if;

  select coalesce(p.preview_text, true)
  into v_preview_text
  from public.notification_prefs p
  where p.user_id = target_user_id
  limit 1;

  select p.full_name, p.avatar_url, p.id
  into reactor_name, reactor_avatar, reactor_profile_id
  from public.profiles p
  where p.user_id = new.user_id
  limit 1;

  if reactor_profile_id is null then
    select p.full_name, p.avatar_url, p.id
    into reactor_name, reactor_avatar, reactor_profile_id
    from public.profiles p
    where p.id = new.user_id
    limit 1;
  end if;

  reactor_name := coalesce(reactor_name, 'Someone');

  if coalesce(v_preview_text, true) = false then
    body_text := case
      when new.emoji is not null and new.emoji <> '' then reactor_name || ' reacted ' || new.emoji || ' to your message'
      else reactor_name || ' reacted to your message'
    end;
  else
    if v_message_type = 'text' and v_message_text is not null and v_message_text <> '' then
      if v_message_text like 'date_plan::%' then
        body_text := case
          when new.emoji is not null and new.emoji <> '' then reactor_name || ' reacted ' || new.emoji || ' to your date suggestion'
          else reactor_name || ' reacted to your date suggestion'
        end;
      elsif v_message_text like 'sticker::%' then
        begin
          v_sticker := substring(v_message_text from char_length('sticker::') + 1)::jsonb;
          v_sticker_name := nullif(btrim(coalesce(v_sticker->>'name', '')), '');
          v_sticker_emoji := nullif(btrim(coalesce(v_sticker->>'emoji', '')), '');
          v_sticker_target := case
            when v_sticker_name is not null then 'your ' || v_sticker_name || ' sticker'
            else 'your sticker'
          end;
          body_text := reactor_name || ' reacted' || case when new.emoji is not null and new.emoji <> '' then ' ' || new.emoji else '' end || ' to ' || v_sticker_target;
        exception
          when others then
            body_text := reactor_name || ' reacted' || case when new.emoji is not null and new.emoji <> '' then ' ' || new.emoji else '' end || ' to your sticker';
        end;
      else
        v_snippet := left(regexp_replace(v_message_text, '\s+', ' ', 'g'), 88);
        body_text := case
          when new.emoji is not null and new.emoji <> '' then reactor_name || ' reacted ' || new.emoji || ' to "' || v_snippet || '"'
          else reactor_name || ' reacted to "' || v_snippet || '"'
        end;
      end if;
    else
      body_text := case
        when v_message_type = 'mood_sticker' then reactor_name || ' reacted' || case when new.emoji is not null and new.emoji <> '' then ' ' || new.emoji else '' end || ' to your sticker'
        when v_message_type = 'image' then reactor_name || ' reacted' || case when new.emoji is not null and new.emoji <> '' then ' ' || new.emoji else '' end || ' to your photo'
        when v_message_type = 'video' then reactor_name || ' reacted' || case when new.emoji is not null and new.emoji <> '' then ' ' || new.emoji else '' end || ' to your video'
        when v_message_type = 'voice' then reactor_name || ' reacted' || case when new.emoji is not null and new.emoji <> '' then ' ' || new.emoji else '' end || ' to your voice note'
        when v_message_type = 'location' then reactor_name || ' reacted' || case when new.emoji is not null and new.emoji <> '' then ' ' || new.emoji else '' end || ' to your location'
        else case
          when new.emoji is not null and new.emoji <> '' then reactor_name || ' reacted ' || new.emoji || ' to your message'
          else reactor_name || ' reacted to your message'
        end
      end;
    end if;
  end if;

  perform private.send_push_webhook(
    jsonb_build_object(
      'user_id', target_user_id,
      'title', reactor_name,
      'body', body_text,
      'data', jsonb_build_object(
        'type', 'message_reaction',
        'reaction_id', new.id,
        'message_id', new.message_id,
        'reactor_id', new.user_id,
        'profile_id', reactor_profile_id,
        'name', reactor_name,
        'avatar_url', reactor_avatar,
        'reaction_emoji', new.emoji
      )
    )
  );
  return new;
end;
$$;


ALTER FUNCTION "public"."notify_message_reaction_push"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_moment_comment_push"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_moment record;
  v_parent_comment_user_id uuid;
  v_owner_profile_id uuid;
  v_actor_profile_id uuid;
  v_actor_name text;
  v_actor_avatar text;
  v_comment_snippet text;
  v_recipient record;
  v_preview_text boolean;
  v_inapp_enabled boolean;
  v_push_enabled boolean;
  v_moments_enabled boolean;
  v_relationship_cue text;
  v_cue_lead text;
  v_inbox_body text;
  v_push_body text;
begin
  select m.id, m.user_id, m.type, m.caption, m.text_body, m.expires_at, m.is_deleted
    into v_moment
  from public.moments m
  where m.id = new.moment_id
  limit 1;

  if not found
     or v_moment.user_id is null
     or coalesce(v_moment.is_deleted, false)
     or coalesce(new.is_deleted, false)
     or v_moment.expires_at <= timezone('utc'::text, now()) then
    return new;
  end if;

  if new.parent_comment_id is not null then
    select c.user_id
      into v_parent_comment_user_id
    from public.moment_comments c
    where c.id = new.parent_comment_id
      and coalesce(c.is_deleted, false) = false
    limit 1;
  end if;

  select p.id
    into v_owner_profile_id
  from public.profiles p
  where p.user_id = v_moment.user_id
  limit 1;

  select p.id, p.full_name, p.avatar_url
    into v_actor_profile_id, v_actor_name, v_actor_avatar
  from public.profiles p
  where p.user_id = new.user_id
  limit 1;

  v_actor_name := coalesce(nullif(btrim(v_actor_name), ''), 'Someone');
  v_comment_snippet := left(regexp_replace(coalesce(new.body, ''), '\s+', ' ', 'g'), 120);

  for v_recipient in
    with recipients as (
      select
        v_moment.user_id as recipient_user_id,
        v_owner_profile_id as recipient_profile_id,
        'moment_owner'::text as recipient_kind
      union all
      select
        v_parent_comment_user_id as recipient_user_id,
        parent_profile.id as recipient_profile_id,
        'reply_target'::text as recipient_kind
      from public.profiles parent_profile
      where v_parent_comment_user_id is not null
        and parent_profile.user_id = v_parent_comment_user_id
    )
    select distinct on (recipient_user_id)
      recipient_user_id,
      recipient_profile_id,
      recipient_kind
    from recipients
    where recipient_user_id is not null
      and recipient_user_id <> new.user_id
    order by recipient_user_id, case recipient_kind when 'moment_owner' then 0 else 1 end
  loop
    if exists (
      select 1
      from public.blocks b
      where (b.blocker_id = v_recipient.recipient_user_id and b.blocked_id = new.user_id)
         or (b.blocker_id = new.user_id and b.blocked_id = v_recipient.recipient_user_id)
    ) then
      continue;
    end if;

    v_preview_text := true;
    v_inapp_enabled := true;
    v_push_enabled := true;
    v_moments_enabled := true;

    select
      coalesce(p.preview_text, true),
      coalesce(p.inapp_enabled, true),
      coalesce(p.push_enabled, true),
      coalesce(p.moments, true)
      into
        v_preview_text,
        v_inapp_enabled,
        v_push_enabled,
        v_moments_enabled
    from public.notification_prefs p
    where p.user_id = v_recipient.recipient_user_id
    limit 1;

    v_relationship_cue := public.get_moment_relationship_cue(
      v_recipient.recipient_profile_id,
      v_actor_profile_id
    );
    v_cue_lead := case v_relationship_cue
      when 'You matched' then 'Your match'
      when 'Door reopened' then 'A reopened connection'
      when 'Liked you' then 'Someone who liked you'
      when 'You liked each other' then 'Someone you both noticed'
      when 'You liked them' then 'Someone on your radar'
      when 'You reached out' then 'Someone you reached out to'
      when 'They reached out' then 'Someone who reached out'
      else null
    end;

    v_inbox_body := case
      when v_recipient.recipient_kind = 'reply_target' then
        case
          when coalesce(v_preview_text, true) = false then
            case
              when v_cue_lead is not null then v_cue_lead || ' replied to your comment'
              else 'Replied to your comment'
            end
          when nullif(btrim(coalesce(v_comment_snippet, '')), '') is not null then
            case
              when v_cue_lead is not null then v_cue_lead || ' replied: "' || v_comment_snippet || '"'
              else 'Replied: "' || v_comment_snippet || '"'
            end
          else
            case
              when v_cue_lead is not null then v_cue_lead || ' replied to your comment'
              else 'Replied to your comment'
            end
        end
      else
        case
          when coalesce(v_preview_text, true) = false then
            case
              when v_cue_lead is not null then v_cue_lead || ' commented on your Moment'
              else 'Commented on your Moment'
            end
          when nullif(btrim(coalesce(v_comment_snippet, '')), '') is not null then
            case
              when v_cue_lead is not null then v_cue_lead || ' commented: "' || v_comment_snippet || '"'
              else 'Commented: "' || v_comment_snippet || '"'
            end
          else
            case
              when v_cue_lead is not null then v_cue_lead || ' commented on your Moment'
              else 'Commented on your Moment'
            end
        end
    end;

    if v_moments_enabled and v_inapp_enabled then
      insert into public.inbox_items (
        user_id,
        type,
        actor_id,
        entity_id,
        entity_type,
        title,
        body,
        action_required,
        metadata
      )
      values (
        v_recipient.recipient_user_id,
        'MOMENT_COMMENT',
        v_actor_profile_id,
        v_moment.id,
        'moment',
        v_actor_name,
        v_inbox_body,
        true,
        jsonb_strip_nulls(
          jsonb_build_object(
            'comment_id', new.id,
            'parent_comment_id', new.parent_comment_id,
            'moment_id', v_moment.id,
            'moment_owner_user_id', v_moment.user_id,
            'moment_type', v_moment.type,
            'name', v_actor_name,
            'avatar_url', v_actor_avatar,
            'relationship_cue', v_relationship_cue,
            'recipient_kind', v_recipient.recipient_kind,
            'route', '/moments'
          )
        )
      );
    end if;

    if not v_moments_enabled or not v_push_enabled or public.is_quiet_hours(v_recipient.recipient_user_id) then
      continue;
    end if;

    v_push_body := case
      when v_recipient.recipient_kind = 'reply_target' and coalesce(v_preview_text, true) = false then
        'Someone replied to your comment'
      when v_recipient.recipient_kind = 'moment_owner' and coalesce(v_preview_text, true) = false then
        'Someone commented on your Moment'
      else v_inbox_body
    end;

    perform private.send_push_webhook(
      jsonb_build_object(
        'user_id', v_recipient.recipient_user_id,
        'title', v_actor_name,
        'body', v_push_body,
        'data', jsonb_build_object(
          'type', 'moment_comment',
          'comment_id', new.id,
          'parent_comment_id', new.parent_comment_id,
          'moment_id', v_moment.id,
          'profile_id', v_actor_profile_id,
          'name', v_actor_name,
          'avatar_url', v_actor_avatar,
          'relationship_cue', v_relationship_cue,
          'recipient_kind', v_recipient.recipient_kind,
          'moment_owner_user_id', v_moment.user_id,
          'start_user_id', v_moment.user_id,
          'route', '/moments'
        )
      )
    );
  end loop;

  return new;
end;
$$;


ALTER FUNCTION "public"."notify_moment_comment_push"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_moment_comment_reaction_push"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_comment record;
  v_moment record;
  v_comment_owner_profile_id uuid;
  v_actor_profile_id uuid;
  v_actor_name text;
  v_actor_avatar text;
  v_preview_text boolean := true;
  v_inapp_enabled boolean := true;
  v_push_enabled boolean := true;
  v_moments_enabled boolean := true;
  v_reaction_emoji text;
  v_reaction_prefix text;
  v_relationship_cue text;
  v_cue_lead text;
  v_body text;
begin
  select c.id, c.user_id, c.moment_id, c.is_deleted
    into v_comment
  from public.moment_comments c
  where c.id = new.comment_id
  limit 1;

  if not found
     or v_comment.user_id is null
     or v_comment.user_id = new.user_id
     or coalesce(v_comment.is_deleted, false) then
    return new;
  end if;

  select m.id, m.user_id, m.type, m.caption, m.text_body, m.expires_at, m.is_deleted
    into v_moment
  from public.moments m
  where m.id = v_comment.moment_id
  limit 1;

  if not found
     or v_moment.user_id is null
     or coalesce(v_moment.is_deleted, false)
     or v_moment.expires_at <= timezone('utc'::text, now()) then
    return new;
  end if;

  if exists (
    select 1
    from public.blocks b
    where (b.blocker_id = v_comment.user_id and b.blocked_id = new.user_id)
       or (b.blocker_id = new.user_id and b.blocked_id = v_comment.user_id)
  ) then
    return new;
  end if;

  select p.id
    into v_comment_owner_profile_id
  from public.profiles p
  where p.user_id = v_comment.user_id
  limit 1;

  select p.id, p.full_name, p.avatar_url
    into v_actor_profile_id, v_actor_name, v_actor_avatar
  from public.profiles p
  where p.user_id = new.user_id
  limit 1;

  select
    coalesce(p.preview_text, true),
    coalesce(p.inapp_enabled, true),
    coalesce(p.push_enabled, true),
    coalesce(p.moments, true)
    into
      v_preview_text,
      v_inapp_enabled,
      v_push_enabled,
      v_moments_enabled
  from public.notification_prefs p
  where p.user_id = v_comment.user_id
  limit 1;

  v_actor_name := coalesce(nullif(btrim(v_actor_name), ''), 'Someone');
  v_reaction_emoji := case new.reaction
    when 'heart' then '❤️'
    when 'love' then '😍'
    when 'fire' then '🔥'
    when 'clap' then '👏'
    when 'laugh' then '😂'
    else null
  end;
  v_reaction_prefix := case
    when v_reaction_emoji is not null then 'reacted ' || v_reaction_emoji
    else 'reacted'
  end;
  v_relationship_cue := public.get_moment_relationship_cue(
    v_comment_owner_profile_id,
    v_actor_profile_id
  );
  v_cue_lead := case v_relationship_cue
    when 'You matched' then 'Your match'
    when 'Door reopened' then 'A reopened connection'
    when 'Liked you' then 'Someone who liked you'
    when 'You liked each other' then 'Someone you both noticed'
    when 'You liked them' then 'Someone on your radar'
    when 'You reached out' then 'Someone you reached out to'
    when 'They reached out' then 'Someone who reached out'
    else null
  end;

  v_body := case
    when coalesce(v_preview_text, true) = false then
      case
        when v_cue_lead is not null then v_cue_lead || ' reacted to your comment'
        else 'Reacted to your comment'
      end
    else
      case
        when v_cue_lead is not null then v_cue_lead || ' ' || v_reaction_prefix || ' to your comment'
        else initcap(v_reaction_prefix) || ' to your comment'
      end
  end;

  if v_moments_enabled and v_inapp_enabled then
    insert into public.inbox_items (
      user_id,
      type,
      actor_id,
      entity_id,
      entity_type,
      title,
      body,
      action_required,
      metadata
    )
    values (
      v_comment.user_id,
      'MOMENT_COMMENT_REACTION',
      v_actor_profile_id,
      v_moment.id,
      'moment',
      v_actor_name,
      v_body,
      false,
      jsonb_strip_nulls(
        jsonb_build_object(
          'comment_reaction_id', new.id,
          'comment_id', v_comment.id,
          'moment_id', v_moment.id,
          'moment_owner_user_id', v_moment.user_id,
          'moment_type', v_moment.type,
          'name', v_actor_name,
          'avatar_url', v_actor_avatar,
          'reaction', new.reaction,
          'reaction_emoji', v_reaction_emoji,
          'relationship_cue', v_relationship_cue,
          'route', '/moments'
        )
      )
    );
  end if;

  if not v_moments_enabled or not v_push_enabled or public.is_quiet_hours(v_comment.user_id) then
    return new;
  end if;

  perform private.send_push_webhook(
    jsonb_build_object(
      'user_id', v_comment.user_id,
      'title', v_actor_name,
      'body', v_body,
      'data', jsonb_build_object(
        'type', 'moment_comment_reaction',
        'comment_reaction_id', new.id,
        'comment_id', v_comment.id,
        'moment_id', v_moment.id,
        'profile_id', v_actor_profile_id,
        'name', v_actor_name,
        'avatar_url', v_actor_avatar,
        'reaction', new.reaction,
        'reaction_emoji', v_reaction_emoji,
        'relationship_cue', v_relationship_cue,
        'moment_owner_user_id', v_moment.user_id,
        'start_user_id', v_moment.user_id,
        'route', '/moments'
      )
    )
  );

  return new;
end;
$$;


ALTER FUNCTION "public"."notify_moment_comment_reaction_push"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_moment_post_push"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_owner_profile_id uuid;
  v_actor_name text;
  v_actor_avatar text;
  v_default_body text;
  v_body text;
  v_relationship_cue text;
  v_swipe_liked_you boolean;
  v_swipe_you_liked boolean;
  v_recipient record;
  v_has_recent_other_moment boolean;
begin
  if new.user_id is null
     or coalesce(new.is_deleted, false)
     or new.expires_at <= timezone('utc'::text, now())
     or (
       new.type in ('photo', 'video')
       and nullif(btrim(coalesce(new.media_url, '')), '') is null
     ) then
    return new;
  end if;

  select exists (
    select 1
    from public.moments m
    where m.user_id = new.user_id
      and m.id <> new.id
      and coalesce(m.is_deleted, false) = false
      and m.created_at >= timezone('utc'::text, now()) - interval '30 minutes'
  )
    into v_has_recent_other_moment;

  if coalesce(v_has_recent_other_moment, false) then
    return new;
  end if;

  select p.id, coalesce(nullif(btrim(p.full_name), ''), 'Someone'), p.avatar_url
    into v_owner_profile_id, v_actor_name, v_actor_avatar
  from public.profiles p
  where p.user_id = new.user_id
  limit 1;

  if v_owner_profile_id is null then
    return new;
  end if;

  for v_recipient in
    with candidate_profiles as (
      select case
          when s.swiper_id = v_owner_profile_id then s.target_id
          else s.swiper_id
        end as profile_id
      from public.swipes s
      where (s.swiper_id = v_owner_profile_id or s.target_id = v_owner_profile_id)
        and s.action in ('LIKE', 'SUPERLIKE')

      union

      select case
          when ir.actor_id = v_owner_profile_id then ir.recipient_id
          else ir.actor_id
        end as profile_id
      from public.intent_requests ir
      where (ir.actor_id = v_owner_profile_id or ir.recipient_id = v_owner_profile_id)
        and coalesce(ir.status, '') in ('pending', 'accepted', 'matched')
    )
    select distinct
      p.id as profile_id,
      p.user_id,
      coalesce(np.preview_text, true) as preview_text
    from candidate_profiles cp
    join public.profiles p on p.id = cp.profile_id
    left join public.notification_prefs np on np.user_id = p.user_id
    where p.user_id is not null
      and p.user_id <> new.user_id
      and coalesce(np.push_enabled, true)
      and coalesce(np.moments, true)
      and not exists (
        select 1
        from public.blocks b
        where (b.blocker_id = p.user_id and b.blocked_id = new.user_id)
           or (b.blocker_id = new.user_id and b.blocked_id = p.user_id)
      )
  loop
    if public.is_quiet_hours(v_recipient.user_id) then
      continue;
    end if;

    v_relationship_cue := null;

    select cue
      into v_relationship_cue
    from (
      select
        case
          when coalesce(ir.status, '') = 'matched' then 'You matched'
          when coalesce(ir.status, '') = 'accepted' then 'Door reopened'
          when ir.actor_id = v_recipient.profile_id then 'They reached out'
          else 'You reached out'
        end as cue,
        case
          when coalesce(ir.status, '') = 'matched' then 3
          when coalesce(ir.status, '') = 'accepted' then 2
          else 1
        end as priority,
        ir.created_at
      from public.intent_requests ir
      where ((ir.actor_id = v_owner_profile_id and ir.recipient_id = v_recipient.profile_id)
          or (ir.actor_id = v_recipient.profile_id and ir.recipient_id = v_owner_profile_id))
        and coalesce(ir.status, '') in ('pending', 'accepted', 'matched')
      order by priority desc, ir.created_at desc
      limit 1
    ) ranked_intent;

    if v_relationship_cue is null then
      select
        coalesce(bool_or(s.swiper_id = v_owner_profile_id and s.target_id = v_recipient.profile_id), false),
        coalesce(bool_or(s.swiper_id = v_recipient.profile_id and s.target_id = v_owner_profile_id), false)
      into v_swipe_you_liked, v_swipe_liked_you
      from public.swipes s
      where ((s.swiper_id = v_owner_profile_id and s.target_id = v_recipient.profile_id)
          or (s.swiper_id = v_recipient.profile_id and s.target_id = v_owner_profile_id))
        and s.action in ('LIKE', 'SUPERLIKE');

      v_relationship_cue := case
        when v_swipe_liked_you and v_swipe_you_liked then 'You liked each other'
        when v_swipe_liked_you then 'Liked you'
        when v_swipe_you_liked then 'You liked them'
        else null
      end;
    end if;

    if coalesce(v_recipient.preview_text, true) = false then
      v_body := case v_relationship_cue
        when 'You matched' then 'Your match shared a new Moment'
        when 'Door reopened' then 'A reopened connection shared a new Moment'
        when 'Liked you' then 'Someone who liked you shared a new Moment'
        when 'You liked each other' then 'Someone you both noticed shared a new Moment'
        when 'You liked them' then 'Someone on your radar shared a new Moment'
        when 'You reached out' then 'Someone you reached out to shared a new Moment'
        when 'They reached out' then 'Someone who reached out shared a new Moment'
        else 'Shared a new Moment'
      end;
    else
      v_default_body := case
        when new.type = 'text' and nullif(btrim(coalesce(new.text_body, '')), '') is not null then
          '"' || left(regexp_replace(new.text_body, '\s+', ' ', 'g'), 88) || '"'
        when nullif(btrim(coalesce(new.caption, '')), '') is not null then
          '"' || left(regexp_replace(new.caption, '\s+', ' ', 'g'), 88) || '"'
        when new.type = 'video' then 'a new video Moment'
        when new.type = 'photo' then 'a new photo Moment'
        else 'a new Moment'
      end;

      v_body := case v_relationship_cue
        when 'You matched' then 'Your match shared ' || v_default_body
        when 'Door reopened' then 'A reopened connection shared ' || v_default_body
        when 'Liked you' then 'Someone who liked you shared ' || v_default_body
        when 'You liked each other' then 'Someone you both noticed shared ' || v_default_body
        when 'You liked them' then 'Someone on your radar shared ' || v_default_body
        when 'You reached out' then 'Someone you reached out to shared ' || v_default_body
        when 'They reached out' then 'Someone who reached out shared ' || v_default_body
        else case
          when new.type = 'text' and nullif(btrim(coalesce(new.text_body, '')), '') is not null then
            'Shared a new thought: "' || left(regexp_replace(new.text_body, '\s+', ' ', 'g'), 88) || '"'
          when nullif(btrim(coalesce(new.caption, '')), '') is not null then
            'Shared a new Moment: "' || left(regexp_replace(new.caption, '\s+', ' ', 'g'), 88) || '"'
          when new.type = 'video' then 'Shared a new video Moment'
          when new.type = 'photo' then 'Shared a new photo Moment'
          else 'Shared a new Moment'
        end
      end;
    end if;

    perform private.send_push_webhook(
      jsonb_build_object(
        'user_id', v_recipient.user_id,
        'title', v_actor_name,
        'body', v_body,
        'data', jsonb_build_object(
          'type', 'moment_post',
          'moment_id', new.id,
          'profile_id', v_owner_profile_id,
          'user_id', new.user_id,
          'poster_user_id', new.user_id,
          'name', v_actor_name,
          'avatar_url', v_actor_avatar,
          'relationship_cue', v_relationship_cue,
          'start_user_id', new.user_id,
          'route', '/moments'
        )
      )
    );
  end loop;

  return new;
end;
$$;


ALTER FUNCTION "public"."notify_moment_post_push"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_moment_reaction_push"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_moment record;
  v_owner_profile_id uuid;
  v_actor_profile_id uuid;
  v_actor_name text;
  v_actor_avatar text;
  v_preview_text boolean := true;
  v_inapp_enabled boolean := true;
  v_push_enabled boolean := true;
  v_moments_enabled boolean := true;
  v_body text;
  v_reaction_prefix text;
  v_relationship_cue text;
  v_cue_lead text;
  v_has_recent_other_reaction boolean;
begin
  select m.id, m.user_id, m.type, m.caption, m.text_body, m.expires_at, m.is_deleted
    into v_moment
  from public.moments m
  where m.id = new.moment_id
  limit 1;

  if not found
     or v_moment.user_id is null
     or v_moment.user_id = new.user_id
     or coalesce(v_moment.is_deleted, false)
     or v_moment.expires_at <= timezone('utc'::text, now()) then
    return new;
  end if;

  -- Ignore no-op upserts where the emoji did not actually change.
  if tg_op = 'update' and old.emoji is not distinct from new.emoji then
    return new;
  end if;

  if exists (
    select 1
    from public.blocks b
    where (b.blocker_id = v_moment.user_id and b.blocked_id = new.user_id)
       or (b.blocker_id = new.user_id and b.blocked_id = v_moment.user_id)
  ) then
    return new;
  end if;

  select p.id
    into v_owner_profile_id
  from public.profiles p
  where p.user_id = v_moment.user_id
  limit 1;

  select p.id, p.full_name, p.avatar_url
    into v_actor_profile_id, v_actor_name, v_actor_avatar
  from public.profiles p
  where p.user_id = new.user_id
  limit 1;

  select
    coalesce(p.preview_text, true),
    coalesce(p.inapp_enabled, true),
    coalesce(p.push_enabled, true),
    coalesce(p.moments, true)
    into
      v_preview_text,
      v_inapp_enabled,
      v_push_enabled,
      v_moments_enabled
  from public.notification_prefs p
  where p.user_id = v_moment.user_id
  limit 1;

  v_actor_name := coalesce(nullif(btrim(v_actor_name), ''), 'Someone');
  v_reaction_prefix := case
    when new.emoji is not null and btrim(new.emoji) <> '' then 'reacted ' || new.emoji
    else 'reacted'
  end;
  v_relationship_cue := public.get_moment_relationship_cue(v_owner_profile_id, v_actor_profile_id);
  v_cue_lead := case v_relationship_cue
    when 'You matched' then 'Your match'
    when 'Door reopened' then 'A reopened connection'
    when 'Liked you' then 'Someone who liked you'
    when 'You liked each other' then 'Someone you both noticed'
    when 'You liked them' then 'Someone on your radar'
    when 'You reached out' then 'Someone you reached out to'
    when 'They reached out' then 'Someone who reached out'
    else null
  end;

  v_body := case
    when coalesce(v_preview_text, true) = false then
      case
        when v_cue_lead is not null then v_cue_lead || ' ' || v_reaction_prefix || ' to your Moment'
        else initcap(v_reaction_prefix) || ' to your Moment'
      end
    when v_moment.type = 'text' and nullif(btrim(coalesce(v_moment.text_body, '')), '') is not null then
      case
        when v_cue_lead is not null then
          v_cue_lead || ' ' || v_reaction_prefix || ' to "' ||
          left(regexp_replace(v_moment.text_body, '\s+', ' ', 'g'), 88) || '"'
        else
          initcap(v_reaction_prefix) || ' to "' ||
          left(regexp_replace(v_moment.text_body, '\s+', ' ', 'g'), 88) || '"'
      end
    else
      case
        when v_cue_lead is not null then v_cue_lead || ' ' || v_reaction_prefix || ' to your Moment'
        else initcap(v_reaction_prefix) || ' to your Moment'
      end
  end;

  if v_moments_enabled and v_inapp_enabled then
    insert into public.inbox_items (
      user_id,
      type,
      actor_id,
      entity_id,
      entity_type,
      title,
      body,
      action_required,
      metadata
    )
    values (
      v_moment.user_id,
      'MOMENT_REACTION',
      v_actor_profile_id,
      v_moment.id,
      'moment',
      v_actor_name,
      v_body,
      false,
      jsonb_strip_nulls(
        jsonb_build_object(
          'reaction_id', new.id,
          'emoji', new.emoji,
          'moment_id', v_moment.id,
          'moment_owner_user_id', v_moment.user_id,
          'moment_type', v_moment.type,
          'name', v_actor_name,
          'avatar_url', v_actor_avatar,
          'relationship_cue', v_relationship_cue,
          'route', '/moments'
        )
      )
    );
  end if;

  -- Keep push notifications insert-only so emoji changes do not create push noise.
  if tg_op = 'update' then
    return new;
  end if;

  if not v_moments_enabled or not v_push_enabled or public.is_quiet_hours(v_moment.user_id) then
    return new;
  end if;

  select exists (
    select 1
    from public.moment_reactions mr
    where mr.moment_id = new.moment_id
      and mr.id <> new.id
      and mr.user_id <> new.user_id
      and mr.created_at >= timezone('utc'::text, now()) - interval '30 minutes'
  )
    into v_has_recent_other_reaction;

  if coalesce(v_has_recent_other_reaction, false) then
    return new;
  end if;

  perform private.send_push_webhook(
    jsonb_build_object(
      'user_id', v_moment.user_id,
      'title', v_actor_name,
      'body', v_body,
      'data', jsonb_build_object(
        'type', 'moment_reaction',
        'reaction_id', new.id,
        'moment_id', v_moment.id,
        'profile_id', v_actor_profile_id,
        'name', v_actor_name,
        'avatar_url', v_actor_avatar,
        'emoji', new.emoji,
        'relationship_cue', v_relationship_cue,
        'moment_owner_user_id', v_moment.user_id,
        'start_user_id', v_moment.user_id,
        'route', '/moments'
      )
    )
  );

  return new;
end;
$$;


ALTER FUNCTION "public"."notify_moment_reaction_push"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_profile_gift_push"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_catalog'
    AS $$
declare
  sender_name text;
  sender_avatar text;
  gift_label text;
  v_recipient_user_id uuid;
  v_has_inbox_items boolean := to_regclass('public.inbox_items') is not null;
  v_inbox_body text;
begin
  select recipient.user_id
    into v_recipient_user_id
  from public.profiles recipient
  where recipient.id = new.profile_id
  limit 1;

  sender_name := coalesce(nullif(btrim(new.sender_display_name), ''), 'New gift');
  sender_avatar := new.sender_avatar_url;
  gift_label := case new.gift_type
    when 'rose' then 'a rose'
    when 'teddy' then 'a teddy bear'
    when 'ring' then 'a ring'
    else 'a gift'
  end;
  v_inbox_body := sender_name || ' sent you ' || gift_label || ' worth opening.';

  if v_has_inbox_items
     and v_recipient_user_id is not null
     and not exists (
       select 1
       from public.notification_prefs p
       where p.user_id = v_recipient_user_id
         and (p.inapp_enabled = false or p.gifts = false)
     )
     and not exists (
       select 1
       from public.inbox_items inbox
       where inbox.user_id = v_recipient_user_id
         and inbox.entity_type = 'profile_gift'
         and inbox.entity_id = new.id
     )
  then
    insert into public.inbox_items (
      user_id,
      type,
      actor_id,
      entity_id,
      entity_type,
      title,
      body,
      action_required,
      metadata
    )
    values (
      v_recipient_user_id,
      'GIFT_RECEIVED',
      new.sender_profile_id,
      new.id,
      'profile_gift',
      sender_name,
      v_inbox_body,
      true,
      jsonb_build_object(
        'type', 'profile_gift',
        'gift_id', new.id,
        'gift_type', new.gift_type,
        'profile_id', new.sender_profile_id,
        'name', sender_name,
        'avatar_url', sender_avatar,
        'actor_user_id', new.sender_id,
        'route', '/profile-insights',
        'cta_label', 'Say Thanks'
      )
    );
  end if;

  if exists (
    select 1
    from public.notification_prefs p
    where p.user_id = v_recipient_user_id
      and (p.push_enabled = false or p.gifts = false)
  ) then
    return new;
  end if;

  if exists (
    select 1
    from public.profiles recipient
    where recipient.id = new.profile_id
      and public.is_quiet_hours(recipient.user_id)
  ) then
    return new;
  end if;

  if exists (
    select 1
    from public.profiles recipient
    join public.blocks b
      on (b.blocker_id = recipient.user_id and b.blocked_id = new.sender_id)
      or (b.blocker_id = new.sender_id and b.blocked_id = recipient.user_id)
    where recipient.id = new.profile_id
  ) then
    return new;
  end if;

  perform private.send_push_webhook(
    jsonb_build_object(
      'user_id', v_recipient_user_id,
      'title', sender_name,
      'body', v_inbox_body,
      'data', jsonb_build_object(
        'type', 'profile_gift',
        'gift_id', new.id,
        'gift_type', new.gift_type,
        'profile_id', new.sender_profile_id,
        'name', sender_name,
        'avatar_url', sender_avatar,
        'route', '/profile-insights'
      )
    )
  );
  return new;
end;
$$;


ALTER FUNCTION "public"."notify_profile_gift_push"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_profile_gift_sender_moment"("p_gift_id" "uuid", "p_moment" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_catalog'
    AS $$
declare
  v_gift public.profile_gifts%rowtype;
  v_sender_profile public.profiles%rowtype;
  v_recipient_profile public.profiles%rowtype;
  v_has_inbox_items boolean := to_regclass('public.inbox_items') is not null;
  v_gift_label text;
  v_recipient_name text;
  v_recipient_avatar text;
  v_body text;
  v_entity_type text;
  v_push_type text;
  v_cta_label text;
begin
  if coalesce(nullif(btrim(p_moment), ''), '') not in ('revealed', 'archived') then
    raise exception 'invalid_profile_gift_sender_moment' using errcode = '22023';
  end if;

  select g.*
    into v_gift
  from public.profile_gifts g
  where g.id = p_gift_id
  limit 1;

  if v_gift.id is null then
    raise exception 'gift not found' using errcode = 'P0002';
  end if;

  if v_gift.sender_profile_id is not null then
    select p.*
      into v_sender_profile
    from public.profiles p
    where p.id = v_gift.sender_profile_id
    limit 1;
  end if;

  if v_sender_profile.id is null then
    select p.*
      into v_sender_profile
    from public.profiles p
    where p.user_id = v_gift.sender_id
      and p.deleted_at is null
    limit 1;
  end if;

  select p.*
    into v_recipient_profile
  from public.profiles p
  where p.id = v_gift.profile_id
  limit 1;

  v_gift_label := case v_gift.gift_type
    when 'rose' then 'rose'
    when 'teddy' then 'teddy bear'
    when 'ring' then 'ring'
    else 'gift'
  end;
  v_recipient_name := coalesce(
    nullif(btrim(v_recipient_profile.full_name), ''),
    nullif(btrim(v_recipient_profile.username), ''),
    'A Betweener'
  );
  v_recipient_avatar := v_recipient_profile.avatar_url;
  v_entity_type := case
    when p_moment = 'revealed' then 'profile_gift_revealed'
    else 'profile_gift_archived'
  end;
  v_push_type := case
    when p_moment = 'revealed' then 'profile_gift_revealed'
    else 'profile_gift_archived'
  end;
  v_cta_label := case
    when p_moment = 'revealed' then 'Open archive'
    else 'View archive'
  end;
  v_body := case
    when p_moment = 'revealed'
      then v_recipient_name || ' opened your ' || v_gift_label || '.'
    else v_recipient_name || ' saved your ' || v_gift_label || ' in their archive.'
  end;

  if v_has_inbox_items
     and not exists (
       select 1
       from public.notification_prefs p
       where p.user_id = v_gift.sender_id
         and (p.inapp_enabled = false or p.gifts = false)
     )
     and not exists (
       select 1
       from public.inbox_items inbox
       where inbox.user_id = v_gift.sender_id
         and inbox.entity_type = v_entity_type
         and inbox.entity_id = v_gift.id
     )
  then
    insert into public.inbox_items (
      user_id,
      type,
      actor_id,
      entity_id,
      entity_type,
      title,
      body,
      action_required,
      metadata
    )
    values (
      v_gift.sender_id,
      'SYSTEM',
      v_recipient_profile.id,
      v_gift.id,
      v_entity_type,
      v_recipient_name,
      v_body,
      false,
      jsonb_build_object(
        'type', v_push_type,
        'gift_id', v_gift.id,
        'gift_type', v_gift.gift_type,
        'profile_id', v_recipient_profile.id,
        'name', v_recipient_name,
        'avatar_url', v_recipient_avatar,
        'route', '/profile-insights',
        'cta_label', v_cta_label
      )
    );
  end if;

  if p_moment = 'revealed'
     and not exists (
       select 1
       from public.notification_prefs p
       where p.user_id = v_gift.sender_id
         and (p.push_enabled = false or p.gifts = false)
     )
     and not public.is_quiet_hours(v_gift.sender_id)
     and not exists (
       select 1
       from public.blocks b
       where (b.blocker_id = v_gift.sender_id and b.blocked_id = v_recipient_profile.user_id)
          or (b.blocker_id = v_recipient_profile.user_id and b.blocked_id = v_gift.sender_id)
     )
  then
    perform private.send_push_webhook(
      jsonb_build_object(
        'user_id', v_gift.sender_id,
        'title', v_recipient_name,
        'body', v_body,
        'data', jsonb_build_object(
          'type', v_push_type,
          'gift_id', v_gift.id,
          'gift_type', v_gift.gift_type,
          'profile_id', v_recipient_profile.id,
          'name', v_recipient_name,
          'avatar_url', v_recipient_avatar,
          'route', '/profile-insights'
        )
      )
    );
  end if;

  return true;
end;
$$;


ALTER FUNCTION "public"."notify_profile_gift_sender_moment"("p_gift_id" "uuid", "p_moment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_profile_image_reaction_push"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  target_user_id uuid;
  reactor_profile_id uuid;
  reactor_name text;
  reactor_avatar text;
  body_text text;
begin
  if tg_op = 'UPDATE' and old.emoji is not distinct from new.emoji then
    return new;
  end if;

  select p.user_id
  into target_user_id
  from public.profiles p
  where p.id = new.profile_id
  limit 1;

  if target_user_id is null then
    return new;
  end if;

  if exists (
    select 1
    from public.notification_prefs p
    where p.user_id = target_user_id
      and (p.push_enabled = false or p.reactions = false)
  ) then
    return new;
  end if;

  if public.is_quiet_hours(target_user_id) then
    return new;
  end if;

  if exists (
    select 1
    from public.blocks b
    where (b.blocker_id = target_user_id and b.blocked_id = new.reactor_user_id)
       or (b.blocker_id = new.reactor_user_id and b.blocked_id = target_user_id)
  ) then
    return new;
  end if;

  select p.id, p.full_name, p.avatar_url
  into reactor_profile_id, reactor_name, reactor_avatar
  from public.profiles p
  where p.user_id = new.reactor_user_id
  limit 1;

  reactor_name := coalesce(reactor_name, 'Someone');
  body_text := case
    when new.emoji is not null and new.emoji <> '' then 'reacted ' || new.emoji || ' to your photo'
    else 'reacted to your photo'
  end;

  perform private.send_push_webhook(
    jsonb_build_object(
      'user_id', target_user_id,
      'title', reactor_name,
      'body', body_text,
      'data', jsonb_build_object(
        'type', 'profile_reaction',
        'reaction_id', new.id,
        'profile_id', reactor_profile_id,
        'peer_user_id', new.reactor_user_id,
        'name', reactor_name,
        'avatar_url', reactor_avatar,
        'emoji', new.emoji
      )
    )
  );

  return new;
end;
$$;


ALTER FUNCTION "public"."notify_profile_image_reaction_push"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_profile_note_push"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  target_user_id uuid;
  sender_profile_id uuid;
  sender_name text;
  sender_avatar text;
  preview_text boolean;
  body_text text;
begin
  select p.user_id
  into target_user_id
  from public.profiles p
  where p.id = new.profile_id
  limit 1;

  select p.id, coalesce(nullif(btrim(p.full_name), ''), 'Someone'), p.avatar_url
  into sender_profile_id, sender_name, sender_avatar
  from public.profiles p
  where p.user_id = new.sender_id
  limit 1;

  if target_user_id is null or new.sender_id is null then
    return new;
  end if;

  if exists (
    select 1
    from public.notification_prefs p
    where p.user_id = target_user_id
      and (p.push_enabled = false or p.notes = false)
  ) then
    return new;
  end if;

  if public.is_quiet_hours(target_user_id) then
    return new;
  end if;

  if exists (
    select 1
    from public.blocks b
    where (b.blocker_id = target_user_id and b.blocked_id = new.sender_id)
       or (b.blocker_id = new.sender_id and b.blocked_id = target_user_id)
  ) then
    return new;
  end if;

  select coalesce(p.preview_text, true)
  into preview_text
  from public.notification_prefs p
  where p.user_id = target_user_id
  limit 1;

  body_text := case
    when coalesce(preview_text, true) = false then 'Left you a note worth opening.'
    when nullif(btrim(coalesce(new.note, '')), '') is not null then
      'Left you a note: "' || left(regexp_replace(new.note, '\s+', ' ', 'g'), 120) || '"'
    else 'Left you a note worth opening.'
  end;

  perform private.send_push_webhook(
    jsonb_build_object(
      'user_id', target_user_id,
      'title', sender_name,
      'body', body_text,
      'data', jsonb_build_object(
        'type', 'profile_note',
        'note_id', new.id,
        'profile_id', sender_profile_id,
        'peer_user_id', new.sender_id,
        'name', sender_name,
        'avatar_url', sender_avatar
      )
    )
  );

  return new;
end;
$$;


ALTER FUNCTION "public"."notify_profile_note_push"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_swipe_push"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  recipient_user_id uuid;
  liker_user_id uuid;
  liker_name text;
  liker_avatar text;
  body_text text;
begin
  if new.action not in ('LIKE', 'SUPERLIKE') then
    return new;
  end if;

  if exists (
    select 1
    from public.matches m
    where m.status in ('PENDING', 'ACCEPTED')
      and (
        (m.user1_id = new.swiper_id and m.user2_id = new.target_id)
        or (m.user1_id = new.target_id and m.user2_id = new.swiper_id)
      )
  ) then
    return new;
  end if;

  select p.user_id
  into recipient_user_id
  from public.profiles p
  where p.id = new.target_id
  limit 1;

  select p.user_id, coalesce(nullif(btrim(p.full_name), ''), 'Someone'), p.avatar_url
  into liker_user_id, liker_name, liker_avatar
  from public.profiles p
  where p.id = new.swiper_id
  limit 1;

  if recipient_user_id is null or liker_user_id is null then
    return new;
  end if;

  if exists (
    select 1
    from public.notification_prefs p
    where p.user_id = recipient_user_id
      and (
        p.push_enabled = false
        or (new.action = 'LIKE' and p.likes = false)
        or (new.action = 'SUPERLIKE' and p.superlikes = false)
      )
  ) then
    return new;
  end if;

  if public.is_quiet_hours(recipient_user_id) then
    return new;
  end if;

  if exists (
    select 1
    from public.blocks b
    where (b.blocker_id = recipient_user_id and b.blocked_id = liker_user_id)
       or (b.blocker_id = liker_user_id and b.blocked_id = recipient_user_id)
  ) then
    return new;
  end if;

  body_text := case
    when new.action = 'SUPERLIKE' then 'Made a stronger move toward you.'
    else 'Noticed you and wanted you to know.'
  end;

  perform private.send_push_webhook(
    jsonb_build_object(
      'user_id', recipient_user_id,
      'title', liker_name,
      'body', body_text,
      'data', jsonb_build_object(
        'type', lower(new.action::text),
        'swipe_id', new.id,
        'profile_id', new.swiper_id,
        'peer_user_id', liker_user_id,
        'name', liker_name,
        'avatar_url', liker_avatar
      )
    )
  );

  return new;
end;
$$;


ALTER FUNCTION "public"."notify_swipe_push"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_system_message_push"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  peer_name text;
  peer_avatar text;
  peer_profile_id uuid;
  title_text text;
  body_text text;
  v_role text;
  v_date_plan_id text;
  v_text text;
begin
  v_role := coalesce(new.metadata->>'role', '');
  v_date_plan_id := nullif(btrim(coalesce(new.metadata->>'date_plan_id', '')), '');
  v_text := coalesce(nullif(btrim(new.text), ''), '');

  if v_role = 'accepter' then
    return new;
  end if;

  if new.event_type = 'date_plan_concierge_requested' and v_role = 'requester' then
    return new;
  end if;

  if new.event_type = 'date_plan_cancelled' and lower(v_text) like 'you %' then
    return new;
  end if;

  if exists (
    select 1
    from public.notification_prefs p
    where p.user_id = new.user_id
      and p.push_enabled = false
  ) then
    return new;
  end if;

  if public.is_quiet_hours(new.user_id) then
    return new;
  end if;

  select coalesce(nullif(btrim(p.full_name), ''), 'They'), p.avatar_url, p.id
  into peer_name, peer_avatar, peer_profile_id
  from public.profiles p
  where p.user_id = new.peer_user_id
  limit 1;

  if new.event_type = 'admin_queue_item' then
    title_text := 'Admin queue';
    body_text := coalesce(nullif(v_text, ''), 'A new admin item needs review.');
  elsif new.event_type = 'request_accepted' then
    title_text := peer_name;
    body_text := 'Reopened the door. Start with something warm and specific.';
  elsif new.event_type = 'request_expired' then
    title_text := 'A window closed';
    body_text := coalesce(nullif(v_text, ''), 'That opening closed. If it still feels right, come back warmer and more specific.');
  elsif new.event_type = 'date_plan_accepted' then
    title_text := peer_name;
    body_text := 'Said yes to the date plan. Keep the energy warm and specific.';
  elsif new.event_type = 'date_plan_declined' then
    title_text := peer_name;
    body_text := 'Passed on the date plan for now.';
  elsif new.event_type = 'date_plan_cancelled' then
    title_text := peer_name;
    body_text := 'Closed the date plan for now.';
  elsif new.event_type = 'date_plan_concierge_requested' then
    title_text := peer_name;
    body_text := 'Asked Betweener to help shape the details.';
  else
    title_text := 'Betweener';
    body_text := coalesce(nullif(v_text, ''), 'There is something worth checking.');
  end if;

  perform private.send_push_webhook(
    jsonb_build_object(
      'user_id', new.user_id,
      'title', title_text,
      'body', body_text,
      'data', jsonb_build_object(
        'type', 'system_message',
        'event_type', new.event_type,
        'system_message_id', new.id,
        'peer_user_id', new.peer_user_id,
        'profile_id', peer_profile_id,
        'name', peer_name,
        'avatar_url', peer_avatar,
        'intent_request_id', new.intent_request_id,
        'date_plan_id', v_date_plan_id,
        'queue_type', new.metadata->>'queue_type',
        'record_id', new.metadata->>'record_id'
      )
    )
  );

  return new;
end;
$$;


ALTER FUNCTION "public"."notify_system_message_push"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_verification_outcome_push"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_target_level integer;
  v_title text;
  v_body text;
  v_method_label text;
begin
  if new.status not in ('approved', 'rejected')
     or old.status is not distinct from new.status then
    return new;
  end if;

  if new.user_id is null then
    return new;
  end if;

  if exists (
    select 1
    from public.notification_prefs p
    where p.user_id = new.user_id
      and (p.push_enabled = false or p.verification = false)
  ) then
    return new;
  end if;

  if public.is_quiet_hours(new.user_id) then
    return new;
  end if;

  v_target_level := case new.verification_type
    when 'social' then 1
    when 'selfie_liveness' then 2
    when 'passport' then 2
    when 'residence' then 2
    when 'workplace' then 2
    else 1
  end;

  v_method_label := case new.verification_type
    when 'social' then 'social proof'
    when 'selfie_liveness' then 'face check'
    when 'passport' then 'passport proof'
    when 'residence' then 'residence proof'
    when 'workplace' then 'work or study proof'
    else 'verification'
  end;

  if new.status = 'approved' then
    v_title := 'Trust update';
    v_body := 'Your ' || v_method_label || ' moved you to Trust level ' || v_target_level || '.';
  else
    v_title := 'One proof needs another pass';
    v_body := 'One proof needs a cleaner pass. Pick it up privately when you are ready.';
  end if;

  perform private.send_push_webhook(
    jsonb_build_object(
      'user_id', new.user_id,
      'title', v_title,
      'body', v_body,
      'data', jsonb_build_object(
        'type', 'verification_outcome',
        'status', new.status,
        'request_id', new.id,
        'verification_type', new.verification_type,
        'target_level', v_target_level
      )
    )
  );

  return new;
end;
$$;


ALTER FUNCTION "public"."notify_verification_outcome_push"() OWNER TO "postgres";


