CREATE OR REPLACE FUNCTION "public"."profile_interest_level"("p_interest_score" integer) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  select case
    when coalesce(p_interest_score, 0) >= 16 then 'High Interest'
    when coalesce(p_interest_score, 0) >= 7 then 'Medium Interest'
    else 'Low Interest'
  end;
$$;


ALTER FUNCTION "public"."profile_interest_level"("p_interest_score" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."profile_interest_score"("p_profile_open_count" integer DEFAULT 0, "p_full_open_count" integer DEFAULT 0, "p_intro_watch_count" integer DEFAULT 0, "p_profile_save_count" integer DEFAULT 0, "p_repeat_visit_count" integer DEFAULT 0, "p_intent_open_count" integer DEFAULT 0) RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  select least(
    100,
    greatest(
      0,
      coalesce(p_profile_open_count, 0)
      + coalesce(p_full_open_count, 0) * 2
      + coalesce(p_intro_watch_count, 0) * 3
      + coalesce(p_profile_save_count, 0) * 4
      + coalesce(p_repeat_visit_count, 0) * 5
      + coalesce(p_intent_open_count, 0) * 5
    )
  )::integer;
$$;


ALTER FUNCTION "public"."profile_interest_score"("p_profile_open_count" integer, "p_full_open_count" integer, "p_intro_watch_count" integer, "p_profile_save_count" integer, "p_repeat_visit_count" integer, "p_intent_open_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."profiles_compute_profile_completed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  has_core_identity boolean;
  has_completion_marker boolean;
  has_profile_substance boolean;
begin
  has_core_identity :=
    (new.full_name is not null and btrim(new.full_name) <> '')
    and (new.age is not null)
    and (new.gender is not null)
    and (new.phone_verified is true and new.phone_number is not null);

  has_completion_marker :=
    new.onboarding_completed_at is not null
    or new.identity_finalized_at is not null
    or new.identity_status = 'active';

  has_profile_substance :=
    (new.bio is not null and btrim(new.bio) <> '')
    or (new.region is not null and btrim(new.region) <> '')
    or (new.location is not null and btrim(new.location) <> '')
    or (new.current_country is not null and btrim(new.current_country) <> '')
    or (new.avatar_url is not null and btrim(new.avatar_url) <> '');

  new.profile_completed :=
    has_core_identity
    and (
      has_completion_marker
      or has_profile_substance
    );

  return new;
end;
$$;


ALTER FUNCTION "public"."profiles_compute_profile_completed"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."profiles_guard_sensitive_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_country_lock_policy text := coalesce(old.country_lock_policy, 'none');
begin
  if auth.uid() is null
    or coalesce(auth.role(), '') in ('service_role', 'supabase_admin')
    or coalesce(current_setting('app.server_managed_update', true), '') = 'on' then
    return new;
  end if;

  if new.country_lock_policy is distinct from old.country_lock_policy then
    raise exception 'country_lock_policy is server-managed';
  end if;

  if new.verification_level is distinct from old.verification_level then
    raise exception 'verification_level is server-managed';
  end if;

  if new.phone_verified is distinct from old.phone_verified then
    raise exception 'phone_verified is server-managed';
  end if;

  if new.phone_verification_score is distinct from old.phone_verification_score then
    raise exception 'phone_verification_score is server-managed';
  end if;

  if new.superlikes_left is distinct from old.superlikes_left then
    raise exception 'superlikes_left is server-managed';
  end if;

  if new.superlikes_reset_at is distinct from old.superlikes_reset_at then
    raise exception 'superlikes_reset_at is server-managed';
  end if;

  if new.ai_score is distinct from old.ai_score then
    raise exception 'ai_score is server-managed';
  end if;

  if new.ai_score_updated_at is distinct from old.ai_score_updated_at then
    raise exception 'ai_score_updated_at is server-managed';
  end if;

  if v_country_lock_policy = 'ghana_locked' then
    if new.current_country is distinct from 'Ghana'
      or coalesce(new.current_country_code, '') <> 'GH' then
      raise exception 'ghana_onboarding_current_country_locked' using errcode = '42501';
    end if;

    if new.origin_country is distinct from 'Ghana'
      or coalesce(new.origin_country_code, '') <> 'GH' then
      raise exception 'ghana_onboarding_origin_country_locked' using errcode = '42501';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."profiles_guard_sensitive_fields"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_chat_conversation_summary"("p_owner_user_id" "uuid", "p_peer_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  perform public.refresh_chat_conversation_summary_unchecked(
    p_owner_user_id,
    p_peer_user_id
  );

  update public.chat_conversation_summaries summary
  set last_activity_kind = null,
      last_activity_message_id = null,
      last_activity_preview = null,
      last_activity_at = null,
      updated_at = timezone('utc'::text, now())
  where summary.owner_user_id = p_owner_user_id
    and summary.peer_user_id = p_peer_user_id
    and (
      summary.last_activity_at is null
      or summary.last_activity_at <= summary.last_message_created_at
    );
end;
$$;


ALTER FUNCTION "public"."refresh_chat_conversation_summary"("p_owner_user_id" "uuid", "p_peer_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_chat_conversation_summary_unchecked"("p_owner_user_id" "uuid", "p_peer_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_summary record;
begin
  if p_owner_user_id is null or p_peer_user_id is null or p_owner_user_id = p_peer_user_id then
    return;
  end if;

  with visible_messages as (
    select
      m.id,
      m.text,
      m.created_at,
      m.sender_id,
      m.receiver_id,
      m.is_read,
      m.delivered_at,
      coalesce(m.message_type, 'text') as message_type,
      coalesce(m.is_view_once, false) as is_view_once,
      coalesce(m.deleted_for_all, false) as deleted_for_all,
      m.edited_at
    from public.messages m
    left join public.message_hides mh
      on mh.message_id = m.id
     and mh.user_id = p_owner_user_id
    where mh.message_id is null
      and (
        (m.sender_id = p_owner_user_id and m.receiver_id = p_peer_user_id)
        or
        (m.sender_id = p_peer_user_id and m.receiver_id = p_owner_user_id)
      )
  ),
  ranked_messages as (
    select
      vm.*,
      count(*) filter (
        where vm.receiver_id = p_owner_user_id
          and vm.is_read = false
      ) over ()::integer as unread_count,
      row_number() over (
        order by vm.created_at desc, vm.id desc
      ) as row_num
    from visible_messages vm
  ),
  latest_message as (
    select *
    from ranked_messages
    where row_num = 1
  ),
  latest_reaction as (
    select
      mr.emoji,
      mr.user_id,
      mr.created_at,
      lm.message_type as target_type
    from latest_message lm
    join public.message_reactions mr
      on mr.message_id = lm.id
    order by mr.created_at desc, mr.id desc
    limit 1
  ),
  activity_events as (
    select
      'edit'::text as activity_kind,
      vm.id as activity_message_id,
      case vm.message_type
        when 'image' then 'Edited: Photo'
        when 'video' then 'Edited: Video'
        when 'voice' then 'Edited: Voice message'
        when 'document' then 'Edited: Document'
        when 'location' then 'Edited: Location'
        when 'mood_sticker' then 'Edited: Sticker'
        else 'Edited: ' || coalesce(nullif(btrim(vm.text), ''), 'Message')
      end as activity_preview,
      vm.edited_at as activity_at
    from visible_messages vm
    where vm.edited_at is not null

    union all

    select
      'reaction'::text as activity_kind,
      vm.id as activity_message_id,
      case when mr.user_id = p_owner_user_id then 'You' else 'Someone' end ||
        ' reacted ' || mr.emoji || ' to ' ||
        case vm.message_type
          when 'image' then 'photo'
          when 'video' then 'video'
          when 'voice' then 'voice note'
          when 'document' then 'document'
          when 'location' then 'location'
          when 'mood_sticker' then 'sticker'
          else 'message'
        end as activity_preview,
      mr.created_at as activity_at
    from visible_messages vm
    join public.message_reactions mr
      on mr.message_id = vm.id
  ),
  latest_activity as (
    select
      ae.activity_kind,
      ae.activity_message_id,
      ae.activity_preview,
      ae.activity_at
    from activity_events ae
    order by ae.activity_at desc, ae.activity_message_id desc, ae.activity_kind desc
    limit 1
  )
  select
    lm.id as last_message_id,
    lm.text as last_message_text,
    lm.created_at as last_message_created_at,
    lm.sender_id as last_message_sender_id,
    lm.receiver_id as last_message_receiver_id,
    lm.is_read as last_message_is_read,
    lm.delivered_at as last_message_delivered_at,
    lm.message_type as last_message_type,
    lm.is_view_once as last_message_is_view_once,
    lm.deleted_for_all as last_message_deleted_for_all,
    lm.edited_at as last_message_edited_at,
    lr.emoji as last_message_reaction_emoji,
    lr.user_id as last_message_reaction_user_id,
    lr.created_at as last_message_reaction_created_at,
    lr.target_type as last_message_reaction_target_type,
    la.activity_kind as last_activity_kind,
    la.activity_message_id as last_activity_message_id,
    la.activity_preview as last_activity_preview,
    la.activity_at as last_activity_at,
    greatest(coalesce(lm.unread_count, 0), 0) as unread_count
  into v_summary
  from latest_message lm
  left join latest_reaction lr on true
  left join latest_activity la on true;

  if v_summary.last_message_id is null then
    delete from public.chat_conversation_summaries
    where owner_user_id = p_owner_user_id
      and peer_user_id = p_peer_user_id;
    return;
  end if;

  insert into public.chat_conversation_summaries (
    owner_user_id,
    peer_user_id,
    last_message_id,
    last_message_text,
    last_message_created_at,
    last_message_sender_id,
    last_message_receiver_id,
    last_message_is_read,
    last_message_delivered_at,
    last_message_type,
    last_message_is_view_once,
    last_message_deleted_for_all,
    last_message_edited_at,
    last_message_reaction_emoji,
    last_message_reaction_user_id,
    last_message_reaction_created_at,
    last_message_reaction_target_type,
    last_activity_kind,
    last_activity_message_id,
    last_activity_preview,
    last_activity_at,
    unread_count,
    updated_at
  )
  values (
    p_owner_user_id,
    p_peer_user_id,
    v_summary.last_message_id,
    v_summary.last_message_text,
    v_summary.last_message_created_at,
    v_summary.last_message_sender_id,
    v_summary.last_message_receiver_id,
    v_summary.last_message_is_read,
    v_summary.last_message_delivered_at,
    v_summary.last_message_type,
    v_summary.last_message_is_view_once,
    v_summary.last_message_deleted_for_all,
    v_summary.last_message_edited_at,
    v_summary.last_message_reaction_emoji,
    v_summary.last_message_reaction_user_id,
    v_summary.last_message_reaction_created_at,
    v_summary.last_message_reaction_target_type,
    v_summary.last_activity_kind,
    v_summary.last_activity_message_id,
    v_summary.last_activity_preview,
    v_summary.last_activity_at,
    v_summary.unread_count,
    timezone('utc'::text, now())
  )
  on conflict (owner_user_id, peer_user_id) do update
  set last_message_id = excluded.last_message_id,
      last_message_text = excluded.last_message_text,
      last_message_created_at = excluded.last_message_created_at,
      last_message_sender_id = excluded.last_message_sender_id,
      last_message_receiver_id = excluded.last_message_receiver_id,
      last_message_is_read = excluded.last_message_is_read,
      last_message_delivered_at = excluded.last_message_delivered_at,
      last_message_type = excluded.last_message_type,
      last_message_is_view_once = excluded.last_message_is_view_once,
      last_message_deleted_for_all = excluded.last_message_deleted_for_all,
      last_message_edited_at = excluded.last_message_edited_at,
      last_message_reaction_emoji = excluded.last_message_reaction_emoji,
      last_message_reaction_user_id = excluded.last_message_reaction_user_id,
      last_message_reaction_created_at = excluded.last_message_reaction_created_at,
      last_message_reaction_target_type = excluded.last_message_reaction_target_type,
      last_activity_kind = excluded.last_activity_kind,
      last_activity_message_id = excluded.last_activity_message_id,
      last_activity_preview = excluded.last_activity_preview,
      last_activity_at = excluded.last_activity_at,
      unread_count = excluded.unread_count,
      updated_at = excluded.updated_at;
end;
$$;


ALTER FUNCTION "public"."refresh_chat_conversation_summary_unchecked"("p_owner_user_id" "uuid", "p_peer_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_profile_recommendation_quality_metrics"("p_profile_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_rows integer := 0;
begin
  with scoped_profiles as (
    select
      profile.id,
      profile.user_id
    from public.profiles profile
    where profile.deleted_at is null
      and (p_profile_ids is null or profile.id = any(p_profile_ids))
  ),
  scoped_user_ids as (
    select coalesce(array_agg(distinct scoped_profiles.user_id), '{}'::uuid[]) as ids
    from scoped_profiles
  ),
  scoped_event_metrics as (
    select
      event_row.target_profile_id as profile_id,
      count(*) filter (where event_row.event_type = 'card_seen')::integer as impressions_30d,
      count(*) filter (
        where event_row.event_type in (
          'profile_opened', 'signal_opened', 'intent_opened', 'intro_played', 'intro_completed'
        )
      )::integer as opens_30d,
      count(*) filter (
        where event_row.event_type in ('like', 'signal_sent', 'intent_sent')
      )::integer as positives_30d,
      count(*) filter (where coalesce(event_row.dwell_ms, 0) >= 4000)::integer as long_dwells_30d
    from public.vibes_events event_row
    where event_row.created_at >= now() - interval '30 days'
      and (p_profile_ids is null or event_row.target_profile_id = any(p_profile_ids))
    group by event_row.target_profile_id
  ),
  recent_message_pairs as (
    select
      least(message_row.sender_id, message_row.receiver_id) as user_a,
      greatest(message_row.sender_id, message_row.receiver_id) as user_b,
      count(*)::integer as message_count
    from public.messages message_row
    cross join scoped_user_ids
    where message_row.created_at >= now() - interval '60 days'
      and (
        message_row.sender_id = any(scoped_user_ids.ids)
        or message_row.receiver_id = any(scoped_user_ids.ids)
      )
    group by 1, 2
  ),
  scoped_conversations as (
    select
      scoped_profiles.id as profile_id,
      count(*) filter (where recent_message_pairs.message_count >= 2)::integer as conversation_pairs_60d,
      count(*) filter (where recent_message_pairs.message_count >= 6)::integer as deep_conversation_pairs_60d
    from scoped_profiles
    left join recent_message_pairs
      on recent_message_pairs.user_a = scoped_profiles.user_id
      or recent_message_pairs.user_b = scoped_profiles.user_id
    group by scoped_profiles.id
  ),
  scoped_matches as (
    select
      paired.profile_id,
      count(*)::integer as accepted_matches_60d
    from (
      select match_row.user1_id as profile_id
      from public.matches match_row
      where match_row.status = 'ACCEPTED'
        and match_row.updated_at >= now() - interval '60 days'
        and (p_profile_ids is null or match_row.user1_id = any(p_profile_ids))

      union all

      select match_row.user2_id as profile_id
      from public.matches match_row
      where match_row.status = 'ACCEPTED'
        and match_row.updated_at >= now() - interval '60 days'
        and (p_profile_ids is null or match_row.user2_id = any(p_profile_ids))
    ) paired
    group by paired.profile_id
  ),
  source as (
    select
      scoped_profiles.id as profile_id,
      coalesce(scoped_event_metrics.impressions_30d, 0) as impressions_30d,
      coalesce(scoped_event_metrics.opens_30d, 0) as opens_30d,
      coalesce(scoped_event_metrics.positives_30d, 0) as positives_30d,
      coalesce(scoped_event_metrics.long_dwells_30d, 0) as long_dwells_30d,
      coalesce(scoped_conversations.conversation_pairs_60d, 0) as conversation_pairs_60d,
      coalesce(scoped_conversations.deep_conversation_pairs_60d, 0) as deep_conversation_pairs_60d,
      coalesce(scoped_matches.accepted_matches_60d, 0) as accepted_matches_60d,
      least(
        (
          coalesce(scoped_event_metrics.opens_30d, 0) +
          coalesce(scoped_event_metrics.positives_30d, 0) * 1.6 +
          coalesce(scoped_event_metrics.long_dwells_30d, 0) * 0.7 +
          coalesce(scoped_conversations.conversation_pairs_60d, 0) * 1.8 +
          coalesce(scoped_conversations.deep_conversation_pairs_60d, 0) * 2.4 +
          coalesce(scoped_matches.accepted_matches_60d, 0) * 2.1
        ) / greatest(coalesce(scoped_event_metrics.impressions_30d, 0), 12),
        1.25
      )::numeric as market_quality_score,
      timezone('utc'::text, now()) as refreshed_at
    from scoped_profiles
    left join scoped_event_metrics
      on scoped_event_metrics.profile_id = scoped_profiles.id
    left join scoped_conversations
      on scoped_conversations.profile_id = scoped_profiles.id
    left join scoped_matches
      on scoped_matches.profile_id = scoped_profiles.id
  ),
  upserted as (
    insert into public.profile_recommendation_quality_metrics (
      profile_id,
      impressions_30d,
      opens_30d,
      positives_30d,
      long_dwells_30d,
      conversation_pairs_60d,
      deep_conversation_pairs_60d,
      accepted_matches_60d,
      market_quality_score,
      refreshed_at
    )
    select
      source.profile_id,
      source.impressions_30d,
      source.opens_30d,
      source.positives_30d,
      source.long_dwells_30d,
      source.conversation_pairs_60d,
      source.deep_conversation_pairs_60d,
      source.accepted_matches_60d,
      source.market_quality_score,
      source.refreshed_at
    from source
    on conflict (profile_id) do update
      set impressions_30d = excluded.impressions_30d,
          opens_30d = excluded.opens_30d,
          positives_30d = excluded.positives_30d,
          long_dwells_30d = excluded.long_dwells_30d,
          conversation_pairs_60d = excluded.conversation_pairs_60d,
          deep_conversation_pairs_60d = excluded.deep_conversation_pairs_60d,
          accepted_matches_60d = excluded.accepted_matches_60d,
          market_quality_score = excluded.market_quality_score,
          refreshed_at = excluded.refreshed_at
    returning 1
  )
  select count(*) into v_rows
  from upserted;

  if p_profile_ids is null then
    delete from public.profile_recommendation_quality_metrics metrics
    where not exists (
      select 1
      from public.profiles profile
      where profile.id = metrics.profile_id
        and profile.deleted_at is null
    );
  end if;

  return v_rows;
end;
$$;


ALTER FUNCTION "public"."refresh_profile_recommendation_quality_metrics"("p_profile_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_profile_visibility_entitlements"("p_profile_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_rows integer := 0;
begin
  with active_boosts as (
    select distinct on (boost_row.user_id)
      boost_row.user_id as profile_id,
      boost_row.ends_at as boost_ends_at,
      coalesce(boost_row.boost_type, 'manual') as boost_type,
      coalesce(boost_row.audience_mode, 'for_you') as boost_audience_mode,
      coalesce(boost_row.focus_mode, 'profile') as boost_focus_mode
    from public.profile_boosts boost_row
    where boost_row.ends_at > timezone('utc'::text, now())
      and coalesce(boost_row.status, 'active') = 'active'
      and (p_profile_ids is null or boost_row.user_id = any(p_profile_ids))
    order by boost_row.user_id, boost_row.ends_at desc, boost_row.created_at desc
  ),
  source as (
    select
      profile.id as profile_id,
      profile.user_id,
      plan_state.premium_plan,
      case plan_state.premium_plan
        when 'GOLD' then 2
        when 'SILVER' then 1
        else 0
      end as premium_rank,
      active_boosts.boost_ends_at is not null as has_active_boost,
      active_boosts.boost_ends_at,
      active_boosts.boost_type,
      active_boosts.boost_audience_mode,
      active_boosts.boost_focus_mode,
      profile.created_at as profile_created_at,
      timezone('utc'::text, now()) as refreshed_at
    from public.profiles profile
    cross join lateral (
      select public.get_active_subscription_plan(profile.user_id)::text as premium_plan
    ) plan_state
    left join active_boosts
      on active_boosts.profile_id = profile.id
    where profile.deleted_at is null
      and (p_profile_ids is null or profile.id = any(p_profile_ids))
  ),
  upserted as (
    insert into public.profile_visibility_entitlements (
      profile_id,
      user_id,
      premium_plan,
      premium_rank,
      has_active_boost,
      boost_ends_at,
      boost_type,
      boost_audience_mode,
      boost_focus_mode,
      profile_created_at,
      refreshed_at
    )
    select
      source.profile_id,
      source.user_id,
      source.premium_plan,
      source.premium_rank,
      source.has_active_boost,
      source.boost_ends_at,
      source.boost_type,
      source.boost_audience_mode,
      source.boost_focus_mode,
      source.profile_created_at,
      source.refreshed_at
    from source
    on conflict (profile_id) do update
      set user_id = excluded.user_id,
          premium_plan = excluded.premium_plan,
          premium_rank = excluded.premium_rank,
          has_active_boost = excluded.has_active_boost,
          boost_ends_at = excluded.boost_ends_at,
          boost_type = excluded.boost_type,
          boost_audience_mode = excluded.boost_audience_mode,
          boost_focus_mode = excluded.boost_focus_mode,
          profile_created_at = excluded.profile_created_at,
          refreshed_at = excluded.refreshed_at
    returning 1
  )
  select count(*) into v_rows
  from upserted;

  if p_profile_ids is null then
    delete from public.profile_visibility_entitlements ent
    where not exists (
      select 1
      from public.profiles profile
      where profile.id = ent.profile_id
        and profile.deleted_at is null
    );
  end if;

  return v_rows;
end;
$$;


ALTER FUNCTION "public"."refresh_profile_visibility_entitlements"("p_profile_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_viewer_profile_behavior_summary"("p_viewer_profile_id" "uuid", "p_target_profile_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_rows integer := 0;
begin
  if p_viewer_profile_id is null then
    return 0;
  end if;

  if p_target_profile_ids is null then
    delete from public.viewer_profile_behavior_summary summary_row
    where summary_row.viewer_profile_id = p_viewer_profile_id;
  else
    delete from public.viewer_profile_behavior_summary summary_row
    where summary_row.viewer_profile_id = p_viewer_profile_id
      and summary_row.target_profile_id = any(p_target_profile_ids);
  end if;

  with source as (
    select
      event_row.target_profile_id,
      count(*) filter (where event_row.event_type = 'card_seen')::integer as seen_count,
      count(*) filter (where event_row.event_type = 'profile_opened')::integer as profile_open_count,
      count(*) filter (where event_row.event_type = 'full_profile_opened')::integer as full_open_count,
      count(*) filter (
        where event_row.event_type in ('intro_played', 'intro_completed')
      )::integer as intro_count,
      count(*) filter (where event_row.event_type = 'profile_saved')::integer as profile_saved_count,
      count(*) filter (where event_row.event_type = 'signal_opened')::integer as signal_opened_count,
      count(*) filter (where event_row.event_type = 'intent_opened')::integer as intent_opened_count,
      count(*) filter (
        where event_row.event_type in ('like', 'signal_sent', 'intent_sent')
      )::integer as positive_count,
      count(*) filter (where event_row.event_type = 'pass')::integer as pass_count,
      count(*) filter (where event_row.event_type = 'undo')::integer as undo_count,
      coalesce(
        (avg(event_row.dwell_ms) filter (where event_row.dwell_ms is not null))::double precision,
        0
      ) as avg_dwell_ms,
      count(*) filter (where coalesce(event_row.dwell_ms, 0) >= 4000)::integer as long_dwell_count,
      max(event_row.created_at) as last_event_at,
      max(event_row.created_at) filter (
        where event_row.event_type in ('like', 'signal_sent', 'intent_sent')
      ) as last_positive_at,
      max(event_row.created_at) filter (where event_row.event_type = 'pass') as last_pass_at,
      timezone('utc'::text, now()) as refreshed_at
    from public.vibes_events event_row
    where event_row.viewer_profile_id = p_viewer_profile_id
      and event_row.created_at >= now() - interval '60 days'
      and (p_target_profile_ids is null or event_row.target_profile_id = any(p_target_profile_ids))
    group by event_row.target_profile_id
  ),
  inserted as (
    insert into public.viewer_profile_behavior_summary (
      viewer_profile_id,
      target_profile_id,
      seen_count,
      profile_open_count,
      full_open_count,
      intro_count,
      profile_saved_count,
      signal_opened_count,
      intent_opened_count,
      positive_count,
      pass_count,
      undo_count,
      avg_dwell_ms,
      long_dwell_count,
      last_event_at,
      last_positive_at,
      last_pass_at,
      refreshed_at
    )
    select
      p_viewer_profile_id,
      source.target_profile_id,
      source.seen_count,
      source.profile_open_count,
      source.full_open_count,
      source.intro_count,
      source.profile_saved_count,
      source.signal_opened_count,
      source.intent_opened_count,
      source.positive_count,
      source.pass_count,
      source.undo_count,
      source.avg_dwell_ms,
      source.long_dwell_count,
      source.last_event_at,
      source.last_positive_at,
      source.last_pass_at,
      source.refreshed_at
    from source
    returning 1
  )
  select count(*) into v_rows
  from inserted;

  return v_rows;
end;
$$;


ALTER FUNCTION "public"."refresh_viewer_profile_behavior_summary"("p_viewer_profile_id" "uuid", "p_target_profile_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reset_daily_superlikes"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  update public.profiles
  set superlikes_left = 1,
      superlikes_reset_at = now(),
      updated_at = now()
  where (superlikes_left <= 0 or superlikes_reset_at is null or superlikes_reset_at < date_trunc('day', now()));
end;
$$;


ALTER FUNCTION "public"."reset_daily_superlikes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_circle_role_requests_after_promotion"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if new.status = 'active'
    and (
      tg_op = 'INSERT'
      or old.role is distinct from new.role
      or old.status is distinct from new.status
    ) then
    update public.circle_role_requests
    set status = 'approved',
        reviewed_at = coalesce(reviewed_at, timezone('utc'::text, now())),
        updated_at = timezone('utc'::text, now())
    where circle_id = new.circle_id
      and requester_profile_id = new.profile_id
      and status = 'pending'
      and (
        (requested_role = 'moderator' and lower(coalesce(new.role, 'member')) in ('moderator', 'host', 'admin', 'leader'))
        or (requested_role = 'host' and lower(coalesce(new.role, 'member')) in ('host', 'admin', 'leader'))
      );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."resolve_circle_role_requests_after_promotion"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_accept_date_plan"("p_plan_id" "uuid") RETURNS TABLE("plan_id" "uuid", "status" "text", "concierge_requested" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_plan public.date_plans%rowtype;
  v_parent_plan public.date_plans%rowtype;
  v_actor_profile public.profiles%rowtype;
  v_creator_name text;
  v_recipient_name text;
begin
  select *
  into v_actor_profile
  from public.profiles
  where user_id = auth.uid()
  limit 1;

  if v_actor_profile.id is null then
    raise exception 'actor_profile_not_found';
  end if;

  select *
  into v_plan
  from public.date_plans
  where id = p_plan_id
  limit 1;

  if v_plan.id is null then
    raise exception 'date_plan_not_found';
  end if;

  if v_plan.recipient_user_id <> auth.uid() then
    raise exception 'Only the other person can accept this date suggestion.';
  end if;

  if v_plan.status = 'accepted' then
    return query
    select v_plan.id, v_plan.status, v_plan.concierge_requested;
    return;
  end if;

  if v_plan.status <> 'pending' then
    raise exception 'This date suggestion can no longer be accepted.';
  end if;

  update public.date_plans
  set status = 'accepted',
      accepted_at = now(),
      accepted_by_profile_id = v_actor_profile.id,
      declined_at = null,
      declined_by_profile_id = null,
      updated_at = now()
  where id = p_plan_id;

  if v_plan.parent_plan_id is not null then
    select *
    into v_parent_plan
    from public.date_plans
    where id = v_plan.parent_plan_id
    limit 1;

    if v_parent_plan.id is not null and v_parent_plan.status = 'accepted' then
      update public.date_plans
      set status = 'cancelled',
          accepted_at = null,
          accepted_by_profile_id = null,
          concierge_requested = false,
          concierge_requested_at = null,
          concierge_requested_by_profile_id = null,
          updated_at = now()
      where id = v_parent_plan.id;

      update public.date_plan_concierge_requests
      set status = 'cancelled',
          resolved_at = coalesce(resolved_at, now()),
          updated_at = now()
      where date_plan_id = v_parent_plan.id
        and public.date_plan_concierge_requests.status in ('pending', 'claimed');
    end if;
  end if;

  select full_name into v_creator_name from public.profiles where id = v_plan.creator_profile_id;
  select full_name into v_recipient_name from public.profiles where id = v_plan.recipient_profile_id;

  insert into public.system_messages (
    user_id,
    peer_user_id,
    event_type,
    text,
    metadata
  )
  values (
    v_plan.creator_user_id,
    v_plan.recipient_user_id,
    'date_plan_accepted',
    coalesce(v_recipient_name, 'They') || ' accepted your date suggestion. Betweener can help with the plan.',
    jsonb_build_object('date_plan_id', p_plan_id, 'role', 'requester')
  );

  insert into public.system_messages (
    user_id,
    peer_user_id,
    event_type,
    text,
    metadata
  )
  values (
    v_plan.recipient_user_id,
    v_plan.creator_user_id,
    'date_plan_accepted',
    'You accepted ' || coalesce(v_creator_name, 'their') || '''s date suggestion. Betweener can help if you want.',
    jsonb_build_object('date_plan_id', p_plan_id, 'role', 'accepter')
  );

  return query
  select p_plan_id, 'accepted', false;
end;
$$;


ALTER FUNCTION "public"."rpc_accept_date_plan"("p_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_ack_verification_refresh"("p_profile_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  update public.profiles
     set verification_refresh_user_notified = true,
         updated_at = timezone('utc'::text, now())
   where id = p_profile_id
     and user_id = auth.uid()
     and coalesce(verification_refresh_required, false) = true;

  return found;
end;
$$;


