CREATE OR REPLACE FUNCTION "public"."rpc_acknowledge_messages_delivered"("p_peer_user_id" "uuid" DEFAULT NULL::"uuid", "p_message_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_count integer := 0;
begin
  if v_user_id is null then
    raise exception 'unauthenticated';
  end if;

  update public.messages
  set delivered_at = coalesce(delivered_at, now())
  where receiver_id = v_user_id
    and sender_id <> v_user_id
    and delivered_at is null
    and (p_message_id is null or id = p_message_id)
    and (p_peer_user_id is null or sender_id = p_peer_user_id);

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


ALTER FUNCTION "public"."rpc_acknowledge_messages_delivered"("p_peer_user_id" "uuid", "p_message_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_admin_clear_verification_refresh"("p_profile_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.is_internal_admin() then
    raise exception 'admin access required';
  end if;

  update public.profiles
     set verification_refresh_required = false,
         verification_refresh_reason = null,
         verification_refresh_target_level = null,
         verification_refresh_resolved_at = timezone('utc'::text, now()),
         updated_at = timezone('utc'::text, now())
   where id = p_profile_id;

  return found;
end;
$$;


ALTER FUNCTION "public"."rpc_admin_clear_verification_refresh"("p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_admin_create_account_merge_case"("p_source_user_id" "uuid", "p_target_user_id" "uuid", "p_source_profile_id" "uuid" DEFAULT NULL::"uuid", "p_target_profile_id" "uuid" DEFAULT NULL::"uuid", "p_request_channel" "text" DEFAULT 'support'::"text", "p_candidate_reason" "text" DEFAULT NULL::"text", "p_evidence" "jsonb" DEFAULT '{}'::"jsonb", "p_requester_user_id" "uuid" DEFAULT NULL::"uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_existing_id uuid;
  v_source_profile_id uuid := p_source_profile_id;
  v_target_profile_id uuid := p_target_profile_id;
  v_case_id uuid;
  v_channel text := lower(trim(coalesce(p_request_channel, 'support')));
begin
  if not public.is_internal_admin() then
    raise exception 'admin access required';
  end if;

  if p_source_user_id is null or p_target_user_id is null then
    raise exception 'source and target user ids are required';
  end if;

  if p_source_user_id = p_target_user_id then
    raise exception 'source and target users must be different';
  end if;

  if v_channel not in ('support', 'user_report', 'ops', 'system') then
    raise exception 'invalid request channel';
  end if;

  if v_source_profile_id is null then
    select p.id
      into v_source_profile_id
    from public.profiles p
    where p.user_id = p_source_user_id
    limit 1;
  end if;

  if v_target_profile_id is null then
    select p.id
      into v_target_profile_id
    from public.profiles p
    where p.user_id = p_target_user_id
    limit 1;
  end if;

  select amc.id
    into v_existing_id
  from public.account_merge_cases amc
  where amc.source_user_id = p_source_user_id
    and amc.target_user_id = p_target_user_id
    and amc.status in ('pending', 'reviewing', 'approved', 'scheduled')
  limit 1;

  if v_existing_id is not null then
    return v_existing_id;
  end if;

  insert into public.account_merge_cases (
    source_user_id,
    source_profile_id,
    target_user_id,
    target_profile_id,
    request_channel,
    candidate_reason,
    evidence,
    requester_user_id,
    created_by,
    notes
  )
  values (
    p_source_user_id,
    v_source_profile_id,
    p_target_user_id,
    v_target_profile_id,
    v_channel,
    nullif(trim(coalesce(p_candidate_reason, '')), ''),
    coalesce(p_evidence, '{}'::jsonb),
    p_requester_user_id,
    auth.uid(),
    nullif(trim(coalesce(p_notes, '')), '')
  )
  returning id into v_case_id;

  insert into public.account_merge_events (
    merge_case_id,
    event_type,
    actor_user_id,
    metadata
  )
  values (
    v_case_id,
    'case_created',
    auth.uid(),
    jsonb_build_object(
      'source_user_id', p_source_user_id,
      'source_profile_id', v_source_profile_id,
      'target_user_id', p_target_user_id,
      'target_profile_id', v_target_profile_id,
      'request_channel', v_channel
    )
  );

  return v_case_id;
end;
$$;


ALTER FUNCTION "public"."rpc_admin_create_account_merge_case"("p_source_user_id" "uuid", "p_target_user_id" "uuid", "p_source_profile_id" "uuid", "p_target_profile_id" "uuid", "p_request_channel" "text", "p_candidate_reason" "text", "p_evidence" "jsonb", "p_requester_user_id" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_admin_dashboard_overview"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  result jsonb;
begin
  if not public.is_internal_admin() then
    raise exception 'admin access required';
  end if;

  select jsonb_build_object(
    'pending_verifications', (
      select count(*)::int from public.verification_requests
      where status = 'pending'
    ),
    'rejected_unread', (
      select count(*)::int from public.verification_requests
      where status = 'rejected' and coalesce(user_notified, false) = false
    ),
    'open_reports', (
      select count(*)::int from public.reports
      where upper(coalesce(status, 'PENDING')) in ('PENDING', 'REVIEWING')
    ),
    'active_subscriptions', (
      select count(*)::int from public.subscriptions
      where is_active = true
    ),
    'silver_active', (
      select count(*)::int from public.subscriptions
      where is_active = true and type = 'SILVER'
    ),
    'gold_active', (
      select count(*)::int from public.subscriptions
      where is_active = true and type = 'GOLD'
    ),
    'members_total', (
      select count(*)::int from public.profiles
      where deleted_at is null
    ),
    'members_last_7d', (
      select count(*)::int from public.profiles
      where deleted_at is null
        and created_at >= timezone('utc'::text, now()) - interval '7 days'
    )
  )
  into result;

  return coalesce(result, '{}'::jsonb);
end;
$$;


ALTER FUNCTION "public"."rpc_admin_dashboard_overview"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_admin_execute_account_merge_case"("p_case_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_case public.account_merge_cases%rowtype;
  v_source_profile public.profiles%rowtype;
  v_target_profile public.profiles%rowtype;
  v_now timestamptz := timezone('utc'::text, now());
  v_count bigint := 0;
  v_counts jsonb := '{}'::jsonb;
  v_execution_summary jsonb;
  v_last_step text := 'initialize';
  v_sqlstate text;
  v_error_message text;
  v_error_detail text;
  v_error_hint text;
  v_error_context text;
begin
  if not public.is_internal_admin() then
    raise exception 'admin access required';
  end if;

  v_last_step := 'load_merge_case';
  select *
    into v_case
  from public.account_merge_cases
  where id = p_case_id
  for update;

  if not found then
    raise exception 'merge case not found';
  end if;

  if coalesce(lower(v_case.status), '') not in ('approved', 'scheduled') then
    raise exception 'merge case must be approved before execution';
  end if;

  if exists (
    select 1
    from public.merged_accounts ma
    where ma.merge_case_id = v_case.id
       or ma.source_user_id = v_case.source_user_id
  ) then
    raise exception 'merge case already executed';
  end if;

  v_last_step := 'load_source_profile';
  select *
    into v_source_profile
  from public.profiles
  where id = coalesce(
    v_case.source_profile_id,
    (select p.id from public.profiles p where p.user_id = v_case.source_user_id limit 1)
  )
  limit 1;

  v_last_step := 'load_target_profile';
  select *
    into v_target_profile
  from public.profiles
  where id = coalesce(
    v_case.target_profile_id,
    (select p.id from public.profiles p where p.user_id = v_case.target_user_id limit 1)
  )
  limit 1;

  if v_source_profile.id is null or v_target_profile.id is null then
    raise exception 'source and target profiles are required';
  end if;

  if v_source_profile.id = v_target_profile.id or v_case.source_user_id = v_case.target_user_id then
    raise exception 'source and target accounts must be different';
  end if;

  create temporary table tmp_merge_counts (
    label text primary key,
    moved_count bigint not null default 0
  ) on commit drop;

  create temporary table tmp_swipe_pairs (
    swiper_id uuid not null,
    target_id uuid not null,
    action text not null,
    created_at timestamptz not null
  ) on commit drop;

  create temporary table tmp_match_pairs (
    user1_id uuid not null,
    user2_id uuid not null,
    status text not null,
    created_at timestamptz not null,
    updated_at timestamptz not null
  ) on commit drop;

  create temporary table tmp_intent_requests (
    id uuid not null,
    actor_id uuid not null,
    recipient_id uuid not null,
    type text not null,
    message text null,
    suggested_time timestamptz null,
    suggested_place text null,
    status text not null,
    created_at timestamptz not null,
    expires_at timestamptz not null,
    metadata jsonb not null
  ) on commit drop;

  create temporary table tmp_date_plans (
    id uuid not null,
    accepted_at timestamptz null,
    accepted_by_profile_id uuid null,
    city text null,
    concierge_requested boolean not null,
    concierge_requested_at timestamptz null,
    concierge_requested_by_profile_id uuid null,
    created_at timestamptz not null,
    creator_profile_id uuid not null,
    creator_user_id uuid not null,
    declined_at timestamptz null,
    declined_by_profile_id uuid null,
    lat double precision null,
    lng double precision null,
    message_id uuid null,
    note text null,
    parent_plan_id uuid null,
    place_address text null,
    place_badges jsonb not null,
    place_name text not null,
    place_source text not null,
    place_summary text null,
    recipient_profile_id uuid not null,
    recipient_user_id uuid not null,
    response_kind text not null,
    scheduled_for timestamptz not null,
    status text not null,
    updated_at timestamptz not null,
    venue_id uuid null
  ) on commit drop;

  create temporary table tmp_concierge_requests (
    id uuid not null,
    date_plan_id uuid not null,
    requested_by_profile_id uuid not null,
    requested_by_user_id uuid not null,
    assigned_admin_user_id uuid null,
    status text not null,
    note text null,
    resolved_at timestamptz null,
    created_at timestamptz not null,
    updated_at timestamptz not null
  ) on commit drop;

  v_last_step := 'merge_verification_requests';
  if exists (select 1 from information_schema.tables where table_schema = 'public' and table_name = 'verification_requests') then
    update public.verification_requests
       set user_id = v_case.target_user_id
     where user_id = v_case.source_user_id;
    get diagnostics v_count = row_count;
    insert into tmp_merge_counts (label, moved_count) values ('verification_requests_user_id', v_count);

    update public.verification_requests
       set profile_id = v_target_profile.id
     where profile_id = v_source_profile.id;
    get diagnostics v_count = row_count;
    insert into tmp_merge_counts (label, moved_count) values ('verification_requests_profile_id', v_count);
  end if;

  v_last_step := 'merge_push_tokens';
  if exists (select 1 from information_schema.tables where table_schema = 'public' and table_name = 'push_tokens') then
    update public.push_tokens
       set user_id = v_case.target_user_id,
           updated_at = v_now
     where user_id = v_case.source_user_id;
    get diagnostics v_count = row_count;
    insert into tmp_merge_counts (label, moved_count) values ('push_tokens', v_count);
  end if;

  v_last_step := 'merge_notification_prefs';
  if exists (select 1 from information_schema.tables where table_schema = 'public' and table_name = 'notification_prefs') then
    select count(*)
      into v_count
    from public.notification_prefs
    where user_id = v_case.source_user_id;
    insert into tmp_merge_counts (label, moved_count) values ('notification_prefs', v_count);

    create temporary table tmp_notification_pref_rows on commit drop as
    select
      np.id,
      v_case.target_user_id as user_id,
      np.push_enabled,
      np.inapp_enabled,
      np.messages,
      np.reactions,
      np.likes,
      np.superlikes,
      np.matches,
      np.moments,
      np.verification,
      np.announcements,
      np.preview_text,
      np.message_reactions,
      np.notes,
      np.gifts,
      np.boosts,
      np.quiet_hours_enabled,
      np.quiet_hours_start,
      np.quiet_hours_end,
      np.quiet_hours_tz,
      np.updated_at,
      case when np.user_id = v_case.target_user_id then 0 else 1 end as source_rank
    from public.notification_prefs np
    where np.user_id in (v_case.source_user_id, v_case.target_user_id);

    if exists (select 1 from tmp_notification_pref_rows) then
      delete from public.notification_prefs
      where user_id in (v_case.source_user_id, v_case.target_user_id);

      insert into public.notification_prefs (
        id,
        user_id,
        push_enabled,
        inapp_enabled,
        messages,
        reactions,
        likes,
        superlikes,
        matches,
        moments,
        verification,
        announcements,
        preview_text,
        updated_at,
        message_reactions,
        notes,
        gifts,
        boosts,
        quiet_hours_enabled,
        quiet_hours_start,
        quiet_hours_end,
        quiet_hours_tz
      )
      select
        chosen.id,
        chosen.user_id,
        chosen.push_enabled,
        chosen.inapp_enabled,
        chosen.messages,
        chosen.reactions,
        chosen.likes,
        chosen.superlikes,
        chosen.matches,
        chosen.moments,
        chosen.verification,
        chosen.announcements,
        chosen.preview_text,
        chosen.updated_at,
        chosen.message_reactions,
        chosen.notes,
        chosen.gifts,
        chosen.boosts,
        chosen.quiet_hours_enabled,
        chosen.quiet_hours_start,
        chosen.quiet_hours_end,
        chosen.quiet_hours_tz
      from (
        select distinct on (user_id)
          id,
          user_id,
          push_enabled,
          inapp_enabled,
          messages,
          reactions,
          likes,
          superlikes,
          matches,
          moments,
          verification,
          announcements,
          preview_text,
          updated_at,
          message_reactions,
          notes,
          gifts,
          boosts,
          quiet_hours_enabled,
          quiet_hours_start,
          quiet_hours_end,
          quiet_hours_tz
        from tmp_notification_pref_rows
        order by user_id, source_rank asc, updated_at desc, id desc
      ) chosen;
    end if;
  end if;

  v_last_step := 'merge_settings';
  if exists (select 1 from information_schema.tables where table_schema = 'public' and table_name = 'settings') then
    select count(*)
      into v_count
    from public.settings
    where user_id = v_case.source_user_id;
    insert into tmp_merge_counts (label, moved_count) values ('settings', v_count);

    create temporary table tmp_settings_rows on commit drop as
    select
      s.id,
      v_case.target_user_id as user_id,
      s.notifications,
      s.show_online,
      s.dark_mode,
      s.show_age,
      s.show_distance,
      s.created_at,
      s.updated_at,
      case when s.user_id = v_case.target_user_id then 0 else 1 end as source_rank
    from public.settings s
    where s.user_id in (v_case.source_user_id, v_case.target_user_id);

    if exists (select 1 from tmp_settings_rows) then
      delete from public.settings
      where user_id in (v_case.source_user_id, v_case.target_user_id);

      insert into public.settings (
        id,
        user_id,
        notifications,
        show_online,
        dark_mode,
        show_age,
        show_distance,
        created_at,
        updated_at
      )
      select
        chosen.id,
        chosen.user_id,
        chosen.notifications,
        chosen.show_online,
        chosen.dark_mode,
        chosen.show_age,
        chosen.show_distance,
        chosen.created_at,
        chosen.updated_at
      from (
        select distinct on (user_id)
          id,
          user_id,
          notifications,
          show_online,
          dark_mode,
          show_age,
          show_distance,
          created_at,
          updated_at
        from tmp_settings_rows
        order by user_id, source_rank asc, updated_at desc, created_at desc, id desc
      ) chosen;
    end if;
  end if;

  v_last_step := 'merge_subscriptions';
  if exists (select 1 from information_schema.tables where table_schema = 'public' and table_name = 'subscriptions') then
    select count(*)
      into v_count
    from public.subscriptions
    where user_id = v_case.source_user_id;
    insert into tmp_merge_counts (label, moved_count) values ('subscriptions', v_count);

    create temporary table tmp_subscription_rows on commit drop as
    select
      s.id,
      v_case.target_user_id as user_id,
      s.type,
      s.started_at,
      s.ends_at,
      s.is_active,
      s.source,
      s.external_customer_id,
      s.external_product_id,
      s.external_entitlement,
      s.external_environment,
      s.updated_at,
      case when s.user_id = v_case.target_user_id then 0 else 1 end as source_rank
    from public.subscriptions s
    where s.user_id in (v_case.source_user_id, v_case.target_user_id);

    delete from public.subscriptions
    where user_id in (v_case.source_user_id, v_case.target_user_id);

    insert into public.subscriptions (
      id,
      user_id,
      type,
      started_at,
      ends_at,
      is_active,
      source,
      external_customer_id,
      external_product_id,
      external_entitlement,
      external_environment,
      updated_at
    )
    select
      ranked.id,
      ranked.user_id,
      ranked.type,
      ranked.started_at,
      ranked.ends_at,
      ranked.is_active,
      ranked.source,
      ranked.external_customer_id,
      ranked.external_product_id,
      ranked.external_entitlement,
      ranked.external_environment,
      ranked.updated_at
    from (
      select
        id,
        user_id,
        type,
        started_at,
        ends_at,
        is_active,
        source,
        external_customer_id,
        external_product_id,
        external_entitlement,
        external_environment,
        updated_at
      from tmp_subscription_rows
      where external_product_id is null

      union all

      select
        deduped.id,
        deduped.user_id,
        deduped.type,
        deduped.started_at,
        deduped.ends_at,
        deduped.is_active,
        deduped.source,
        deduped.external_customer_id,
        deduped.external_product_id,
        deduped.external_entitlement,
        deduped.external_environment,
        deduped.updated_at
      from (
        select distinct on (source, external_product_id, ends_at)
          id,
          user_id,
          type,
          started_at,
          ends_at,
          is_active,
          source,
          external_customer_id,
          external_product_id,
          external_entitlement,
          external_environment,
          updated_at,
          source_rank
        from tmp_subscription_rows
        where external_product_id is not null
        order by
          source,
          external_product_id,
          ends_at,
          is_active desc,
          updated_at desc,
          started_at desc,
          source_rank asc,
          id desc
      ) deduped
    ) ranked;
  end if;

  v_last_step := 'merge_photos';
  if exists (select 1 from information_schema.tables where table_schema = 'public' and table_name = 'photos') then
    select count(*)
      into v_count
    from public.photos
    where user_id = v_case.source_user_id;
    insert into tmp_merge_counts (label, moved_count) values ('photos', v_count);

    create temporary table tmp_photo_candidates on commit drop as
    select
      p.id,
      p.url,
      v_case.target_user_id as user_id,
      p.is_primary,
      p.ordering,
      p.created_at,
      case when p.user_id = v_case.target_user_id then 0 else 1 end as source_rank
    from public.photos p
    where p.user_id in (v_case.source_user_id, v_case.target_user_id);

    delete from public.photos
    where user_id in (v_case.source_user_id, v_case.target_user_id);

    create temporary table tmp_photo_rows on commit drop as
    select
      deduped.id,
      deduped.url,
      deduped.user_id,
      case
        when row_number() over (
          order by
            deduped.is_primary desc,
            deduped.source_rank asc,
            deduped.ordering asc,
            deduped.created_at asc,
            deduped.id asc
        ) = 1 then true
        else false
      end as is_primary,
      row_number() over (
        order by
          deduped.is_primary desc,
          deduped.source_rank asc,
          deduped.ordering asc,
          deduped.created_at asc,
          deduped.id asc
      ) - 1 as ordering,
      deduped.created_at
    from (
      select distinct on (url)
        id,
        url,
        user_id,
        is_primary,
        ordering,
        created_at,
        source_rank
      from tmp_photo_candidates
      order by
        url,
        source_rank asc,
        is_primary desc,
        ordering asc,
        created_at asc,
        id asc
    ) deduped;

    insert into public.photos (
      id,
      url,
      user_id,
      is_primary,
      ordering,
      created_at
    )
    select
      id,
      url,
      user_id,
      is_primary,
      ordering,
      created_at
    from tmp_photo_rows;
  end if;

  v_last_step := 'merge_inbox_items';
  if exists (select 1 from information_schema.tables where table_schema = 'public' and table_name = 'inbox_items') then
    update public.inbox_items
       set user_id = v_case.target_user_id
     where user_id = v_case.source_user_id;
    get diagnostics v_count = row_count;
    insert into tmp_merge_counts (label, moved_count) values ('inbox_items', v_count);
  end if;

  v_last_step := 'merge_phone_verifications';
  if exists (select 1 from information_schema.tables where table_schema = 'public' and table_name = 'phone_verifications') then
    update public.phone_verifications
       set user_id = v_case.target_user_id,
           updated_at = v_now
     where user_id = v_case.source_user_id;
    get diagnostics v_count = row_count;
    insert into tmp_merge_counts (label, moved_count) values ('phone_verifications', v_count);
  end if;

  v_last_step := 'merge_signup_events';
  if exists (select 1 from information_schema.tables where table_schema = 'public' and table_name = 'signup_events') then
    update public.signup_events
       set user_id = v_case.target_user_id,
           updated_at = v_now
     where user_id = v_case.source_user_id;
    get diagnostics v_count = row_count;
    insert into tmp_merge_counts (label, moved_count) values ('signup_events', v_count);
  end if;

  v_last_step := 'merge_travel_history';
  if exists (select 1 from information_schema.tables where table_schema = 'public' and table_name = 'travel_history') then
    update public.travel_history
       set user_id = v_case.target_user_id
     where user_id = v_case.source_user_id;
    get diagnostics v_count = row_count;
    insert into tmp_merge_counts (label, moved_count) values ('travel_history', v_count);
  end if;

  v_last_step := 'merge_user_location_profiles';
  if exists (select 1 from information_schema.tables where table_schema = 'public' and table_name = 'user_location_profiles') then
    select count(*)
      into v_count
    from public.user_location_profiles
    where user_id = v_case.source_user_id;
    insert into tmp_merge_counts (label, moved_count) values ('user_location_profiles', v_count);

    create temporary table tmp_user_location_profile_rows on commit drop as
    select
      ulp.id,
      ulp.created_at,
      ulp.current_address,
      ulp.current_location,
      ulp.current_travel_mode,
      ulp.diaspora_status,
      ulp.ghana_region,
      ulp.home_address,
      ulp.home_location,
      ulp.hometown,
      ulp.is_traveling,
      ulp.location_sharing,
      ulp.location_updated_at,
      ulp.privacy_level,
      ulp.traditional_area,
      ulp.travel_confidence,
      ulp.tribe,
      ulp.updated_at,
      v_case.target_user_id as user_id,
      ulp.work_address,
      ulp.work_location,
      ulp.years_in_diaspora,
      case when ulp.user_id = v_case.target_user_id then 0 else 1 end as source_rank
    from public.user_location_profiles ulp
    where ulp.user_id in (v_case.source_user_id, v_case.target_user_id);

    if exists (select 1 from tmp_user_location_profile_rows) then
      delete from public.user_location_profiles
      where user_id in (v_case.source_user_id, v_case.target_user_id);

      insert into public.user_location_profiles (
        id,
        created_at,
        current_address,
        current_location,
        current_travel_mode,
        diaspora_status,
        ghana_region,
        home_address,
        home_location,
        hometown,
        is_traveling,
        location_sharing,
        location_updated_at,
        privacy_level,
        traditional_area,
        travel_confidence,
        tribe,
        updated_at,
        user_id,
        work_address,
        work_location,
        years_in_diaspora
      )
      select
        chosen.id,
        chosen.created_at,
        chosen.current_address,
        chosen.current_location,
        chosen.current_travel_mode,
        chosen.diaspora_status,
        chosen.ghana_region,
        chosen.home_address,
        chosen.home_location,
        chosen.hometown,
        chosen.is_traveling,
        chosen.location_sharing,
        chosen.location_updated_at,
        chosen.privacy_level,
        chosen.traditional_area,
        chosen.travel_confidence,
        chosen.tribe,
        chosen.updated_at,
        chosen.user_id,
        chosen.work_address,
        chosen.work_location,
        chosen.years_in_diaspora
      from (
        select distinct on (user_id)
          id,
          created_at,
          current_address,
          current_location,
          current_travel_mode,
          diaspora_status,
          ghana_region,
          home_address,
          home_location,
          hometown,
          is_traveling,
          location_sharing,
          location_updated_at,
          privacy_level,
          traditional_area,
          travel_confidence,
          tribe,
          updated_at,
          user_id,
          work_address,
          work_location,
          years_in_diaspora
        from tmp_user_location_profile_rows
        order by
          user_id,
          source_rank asc,
          updated_at desc nulls last,
          created_at desc nulls last,
          id desc
      ) chosen;
    end if;
  end if;

