CREATE OR REPLACE FUNCTION "public"."rpc_admin_get_account_merge_case"("p_case_id" "uuid") RETURNS TABLE("id" "uuid", "status" "text", "request_channel" "text", "candidate_reason" "text", "source_user_id" "uuid", "source_profile_id" "uuid", "source_name" "text", "source_avatar_url" "text", "target_user_id" "uuid", "target_profile_id" "uuid", "target_name" "text", "target_avatar_url" "text", "requester_user_id" "uuid", "created_by" "uuid", "reviewed_by" "uuid", "executed_by" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "reviewed_at" timestamp with time zone, "executed_at" timestamp with time zone, "resolved_at" timestamp with time zone, "preflight_summary" "jsonb", "execution_summary" "jsonb", "evidence" "jsonb", "notes" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.is_internal_admin() then
    raise exception 'admin access required';
  end if;

  return query
  select
    amc.id,
    amc.status,
    amc.request_channel,
    amc.candidate_reason,
    amc.source_user_id,
    amc.source_profile_id,
    source_profile.full_name,
    source_profile.avatar_url,
    amc.target_user_id,
    amc.target_profile_id,
    target_profile.full_name,
    target_profile.avatar_url,
    amc.requester_user_id,
    amc.created_by,
    amc.reviewed_by,
    amc.executed_by,
    amc.created_at,
    amc.updated_at,
    amc.reviewed_at,
    amc.executed_at,
    amc.resolved_at,
    amc.preflight_summary,
    amc.execution_summary,
    amc.evidence,
    amc.notes
  from public.account_merge_cases amc
  left join public.profiles source_profile on source_profile.id = amc.source_profile_id
  left join public.profiles target_profile on target_profile.id = amc.target_profile_id
  where amc.id = p_case_id
  limit 1;
end;
$$;


