CREATE TABLE IF NOT EXISTS "public"."circles" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "visibility" "text" DEFAULT 'public'::"text" NOT NULL,
    "category" "text",
    "created_by_profile_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "image_path" "text",
    "image_updated_at" timestamp with time zone,
    "slug" "text",
    "short_description" "text",
    "cover_image_url" "text",
    "icon_url" "text",
    "circle_type" "text" DEFAULT 'community'::"text" NOT NULL,
    "status" "text" DEFAULT 'pending_review'::"text" NOT NULL,
    "visibility_scope" "text" DEFAULT 'country'::"text" NOT NULL,
    "country_code" "text",
    "country_name" "text",
    "region" "text",
    "city" "text",
    "latitude" double precision,
    "longitude" double precision,
    "diaspora_tags" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "culture_tags" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "faith_tags" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "interest_tags" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "audience_tags" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "is_official" boolean DEFAULT false NOT NULL,
    "is_partner" boolean DEFAULT false NOT NULL,
    "is_featured" boolean DEFAULT false NOT NULL,
    "requires_join_approval" boolean DEFAULT false NOT NULL,
    "created_by_user_id" "uuid",
    "approved_by_admin_id" "uuid",
    "approved_at" timestamp with time zone,
    "rejected_reason" "text",
    "rules" "text",
    "safety_note" "text",
    "report_count" integer DEFAULT 0 NOT NULL,
    "member_count" integer DEFAULT 0 NOT NULL,
    "active_this_week_count" integer DEFAULT 0 NOT NULL,
    "gathering_count" integer DEFAULT 0 NOT NULL,
    "archived_at" timestamp with time zone,
    "host_note" "text",
    "host_note_updated_at" timestamp with time zone,
    "host_note_updated_by_profile_id" "uuid",
    CONSTRAINT "circles_visibility_check" CHECK (("visibility" = ANY (ARRAY['public'::"text", 'private'::"text"])))
);


