CREATE OR REPLACE FUNCTION "public"."rpc_admin_get_reports_queue"() RETURNS TABLE("id" "uuid", "reason" "text", "status" "text", "created_at" timestamp with time zone, "reporter_user_id" "uuid", "reported_user_id" "uuid", "reporter_name" "text", "reporter_avatar" "text", "reporter_verification_level" integer, "reported_name" "text", "reported_avatar" "text", "reported_verification_level" integer, "evidence_message_id" "uuid", "evidence_message_text" "text", "evidence_message_type" "text", "evidence_message_sender_id" "uuid", "evidence_message_created_at" timestamp with time zone, "evidence" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.is_internal_admin() then
    raise exception 'admin access required';
  end if;

  return query
  select
    r.id,
    r.reason,
    coalesce(r.status, 'PENDING') as status,
    r.created_at,
    r.reporter_id,
    r.reported_id,
    reporter_profile.full_name,
    reporter_profile.avatar_url,
    reporter_profile.verification_level,
    reported_profile.full_name,
    reported_profile.avatar_url,
    reported_profile.verification_level,
    r.evidence_message_id,
    r.evidence_message_text,
    r.evidence_message_type,
    r.evidence_message_sender_id,
    r.evidence_message_created_at,
    r.evidence
  from public.reports r
  left join public.profiles reporter_profile on reporter_profile.user_id = r.reporter_id
  left join public.profiles reported_profile on reported_profile.user_id = r.reported_id
  order by
    case when upper(coalesce(r.status, 'PENDING')) in ('PENDING', 'REVIEWING') then 0 else 1 end,
    r.created_at desc;
end;
$$;


ALTER FUNCTION "public"."rpc_admin_get_reports_queue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_admin_get_verification_queue"() RETURNS TABLE("id" "uuid", "user_id" "uuid", "profile_id" "uuid", "verification_type" "text", "status" "text", "submitted_at" timestamp with time zone, "reviewed_at" timestamp with time zone, "reviewer_notes" "text", "auto_verification_score" numeric, "auto_verification_data" "jsonb", "document_url" "text", "full_name" "text", "current_country" "text", "avatar_url" "text", "verification_level" integer, "verification_refresh_required" boolean, "verification_refresh_reason" "text", "verification_refresh_target_level" integer, "verification_refresh_requested_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.is_internal_admin() then
    raise exception 'admin access required';
  end if;

  return query
  select
    vr.id,
    vr.user_id,
    vr.profile_id,
    vr.verification_type,
    coalesce(vr.status, 'pending') as status,
    vr.submitted_at,
    vr.reviewed_at,
    vr.reviewer_notes,
    vr.auto_verification_score,
    vr.auto_verification_data,
    vr.document_url,
    p.full_name,
    p.current_country,
    p.avatar_url,
    p.verification_level,
    coalesce(p.verification_refresh_required, false) as verification_refresh_required,
    p.verification_refresh_reason,
    p.verification_refresh_target_level,
    p.verification_refresh_requested_at
  from public.verification_requests vr
  left join public.profiles p on p.id = vr.profile_id
  where coalesce(vr.status, 'pending') <> 'cancelled'
  order by
    case when coalesce(vr.status, 'pending') = 'pending' then 0 else 1 end,
    vr.submitted_at asc nulls last;
end;
$$;


ALTER FUNCTION "public"."rpc_admin_get_verification_queue"() OWNER TO "postgres";


