CREATE OR REPLACE FUNCTION "public"."rpc_admin_preview_account_merge_case"("p_case_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_case public.account_merge_cases%rowtype;
  v_user_columns text[] := array[
    'user_id',
    'peer_user_id',
    'creator_user_id',
    'recipient_user_id',
    'requested_by_user_id',
    'requester_user_id',
    'reporter_id',
    'reported_id',
    'sender_id',
    'receiver_id',
    'reactor_user_id',
    'assigned_admin_user_id',
    'created_by',
    'reviewed_by',
    'executed_by'
  ];
  v_profile_columns text[] := array[
    'profile_id',
    'target_profile_id',
    'viewer_profile_id',
    'created_by_profile_id',
    'requested_by_profile_id',
    'creator_profile_id',
    'recipient_profile_id',
    'accepted_by_profile_id',
    'declined_by_profile_id',
    'concierge_requested_by_profile_id'
  ];
  v_row record;
  v_refs jsonb := '[]'::jsonb;
  v_count bigint;
  v_user_total bigint := 0;
  v_profile_total bigint := 0;
  v_result jsonb;
begin
  if not public.is_internal_admin() then
    raise exception 'admin access required';
  end if;

  select *
    into v_case
  from public.account_merge_cases
  where id = p_case_id
  for update;

  if not found then
    raise exception 'merge case not found';
  end if;

  for v_row in
    select c.table_name, c.column_name
    from information_schema.columns c
    where c.table_schema = 'public'
      and c.data_type = 'uuid'
      and c.table_name not in ('account_merge_cases', 'account_merge_events')
      and (
        c.column_name = any(v_user_columns)
        or c.column_name = any(v_profile_columns)
      )
    order by c.table_name, c.column_name
  loop
    if v_row.column_name = any(v_user_columns) then
      if v_case.source_user_id is null then
        continue;
      end if;
      execute format(
        'select count(*) from public.%I where %I = $1',
        v_row.table_name,
        v_row.column_name
      )
      into v_count
      using v_case.source_user_id;

      if v_count > 0 then
        v_user_total := v_user_total + v_count;
        v_refs := v_refs || jsonb_build_array(
          jsonb_build_object(
            'scope', 'user',
            'table', v_row.table_name,
            'column', v_row.column_name,
            'count', v_count
          )
        );
      end if;
    else
      if v_case.source_profile_id is null then
        continue;
      end if;
      execute format(
        'select count(*) from public.%I where %I = $1',
        v_row.table_name,
        v_row.column_name
      )
      into v_count
      using v_case.source_profile_id;

      if v_count > 0 then
        v_profile_total := v_profile_total + v_count;
        v_refs := v_refs || jsonb_build_array(
          jsonb_build_object(
            'scope', 'profile',
            'table', v_row.table_name,
            'column', v_row.column_name,
            'count', v_count
          )
        );
      end if;
    end if;
  end loop;

  v_result := jsonb_build_object(
    'case_id', v_case.id,
    'status', v_case.status,
    'source', jsonb_build_object(
      'user_id', v_case.source_user_id,
      'profile_id', v_case.source_profile_id
    ),
    'target', jsonb_build_object(
      'user_id', v_case.target_user_id,
      'profile_id', v_case.target_profile_id
    ),
    'totals', jsonb_build_object(
      'user_reference_rows', v_user_total,
      'profile_reference_rows', v_profile_total,
      'combined_rows', v_user_total + v_profile_total
    ),
    'references', v_refs,
    'recommendation', 'manual review required before any merge execution'
  );

  update public.account_merge_cases
     set preflight_summary = v_result,
         updated_at = timezone('utc'::text, now())
   where id = v_case.id;

  insert into public.account_merge_events (
    merge_case_id,
    event_type,
    actor_user_id,
    metadata
  )
  values (
    v_case.id,
    'case_preflighted',
    auth.uid(),
    jsonb_build_object(
      'user_reference_rows', v_user_total,
      'profile_reference_rows', v_profile_total
    )
  );

  return v_result;
end;
$_$;


ALTER FUNCTION "public"."rpc_admin_preview_account_merge_case"("p_case_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_admin_request_verification_refresh"("p_profile_id" "uuid", "p_target_level" integer DEFAULT NULL::integer, "p_reason" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_user_id uuid;
  v_current_level integer;
  v_refresh_required boolean;
  v_target_level integer;
  v_reason text;
begin
  if not public.is_internal_admin() then
    raise exception 'admin access required';
  end if;

  select
    p.user_id,
    coalesce(p.verification_level, 0),
    coalesce(p.verification_refresh_required, false)
    into v_user_id, v_current_level, v_refresh_required
  from public.profiles p
  where p.id = p_profile_id
  for update;

  if v_user_id is null then
    return false;
  end if;

  if v_current_level <= 0 then
    raise exception 'profile is not verified yet';
  end if;

  if coalesce(v_refresh_required, false) then
    raise exception 'fresh review already requested';
  end if;

  v_target_level := least(greatest(coalesce(p_target_level, v_current_level, 1), 1), 2);
  v_reason := nullif(btrim(coalesce(p_reason, '')), '');

  update public.profiles
     set verification_refresh_required = true,
         verification_refresh_reason = coalesce(
           v_reason,
           'Betweener needs a quick fresh check to keep your trust signal current.'
         ),
         verification_refresh_target_level = v_target_level,
         verification_refresh_requested_at = timezone('utc'::text, now()),
         verification_refresh_requested_by = auth.uid(),
         verification_refresh_resolved_at = null,
         verification_refresh_user_notified = false,
         updated_at = timezone('utc'::text, now())
   where id = p_profile_id;

  if not exists (
    select 1
    from public.notification_prefs p
    where p.user_id = v_user_id
      and (
        p.push_enabled = false
        or p.verification = false
      )
  )
     and not public.is_quiet_hours(v_user_id) then
    perform private.send_push_webhook(
      jsonb_build_object(
        'user_id', v_user_id,
        'title', 'A quick Betweener trust refresh is needed',
        'body', 'Open Betweener to complete a private fresh check.',
        'data', jsonb_build_object(
          'type', 'verification_refresh_requested',
          'profile_id', p_profile_id,
          'target_level', v_target_level
        )
      )
    );
  end if;

  return true;
end;
$$;


ALTER FUNCTION "public"."rpc_admin_request_verification_refresh"("p_profile_id" "uuid", "p_target_level" integer, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_admin_review_verification_request"("p_request_id" "uuid", "p_decision" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  request_row public.verification_requests%rowtype;
  next_level integer;
  refresh_target_level integer;
begin
  if not public.is_internal_admin() then
    raise exception 'admin access required';
  end if;

  if p_decision not in ('approved', 'rejected') then
    raise exception 'invalid decision';
  end if;

  select *
    into request_row
  from public.verification_requests
  where id = p_request_id
  for update;

  if not found then
    return false;
  end if;

  update public.verification_requests
     set status = p_decision,
         reviewed_at = timezone('utc'::text, now()),
         reviewer_notes = nullif(trim(coalesce(p_notes, '')), ''),
         user_notified = false,
         updated_at = timezone('utc'::text, now())
   where id = p_request_id;

  if p_decision = 'approved' and request_row.profile_id is not null then
    next_level := case request_row.verification_type
      when 'social' then 1
      when 'selfie_liveness' then 2
      when 'passport' then 2
      when 'residence' then 2
      when 'workplace' then 2
      else 1
    end;

    select least(greatest(coalesce(p.verification_refresh_target_level, p.verification_level, 1), 1), 2)
      into refresh_target_level
    from public.profiles p
    where p.id = request_row.profile_id;

    perform set_config('app.server_managed_update', 'on', true);

    update public.profiles
       set verification_level = greatest(coalesce(verification_level, 0), next_level),
           verification_refresh_required = case
             when coalesce(verification_refresh_required, false)
                  and next_level >= coalesce(refresh_target_level, 1)
               then false
             else verification_refresh_required
           end,
           verification_refresh_reason = case
             when coalesce(verification_refresh_required, false)
                  and next_level >= coalesce(refresh_target_level, 1)
               then null
             else verification_refresh_reason
           end,
           verification_refresh_target_level = case
             when coalesce(verification_refresh_required, false)
                  and next_level >= coalesce(refresh_target_level, 1)
               then null
             else verification_refresh_target_level
           end,
           verification_refresh_resolved_at = case
             when coalesce(verification_refresh_required, false)
                  and next_level >= coalesce(refresh_target_level, 1)
               then timezone('utc'::text, now())
             else verification_refresh_resolved_at
           end,
           updated_at = timezone('utc'::text, now())
     where id = request_row.profile_id;
  end if;

  return true;
end;
$$;


ALTER FUNCTION "public"."rpc_admin_review_verification_request"("p_request_id" "uuid", "p_decision" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_admin_update_account_merge_case"("p_case_id" "uuid", "p_status" "text", "p_notes" "text" DEFAULT NULL::"text", "p_execution_summary" "jsonb" DEFAULT NULL::"jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_status text := lower(trim(coalesce(p_status, '')));
begin
  if not public.is_internal_admin() then
    raise exception 'admin access required';
  end if;

  if v_status not in ('pending', 'reviewing', 'approved', 'scheduled', 'completed', 'rejected', 'failed', 'cancelled') then
    raise exception 'invalid merge status';
  end if;

  update public.account_merge_cases
     set status = v_status,
         notes = coalesce(nullif(trim(coalesce(p_notes, '')), ''), notes),
         execution_summary = coalesce(p_execution_summary, execution_summary),
         reviewed_by = case
           when v_status in ('reviewing', 'approved', 'rejected', 'failed', 'cancelled') then auth.uid()
           else reviewed_by
         end,
         reviewed_at = case
           when v_status in ('reviewing', 'approved', 'rejected', 'failed', 'cancelled') then timezone('utc'::text, now())
           else reviewed_at
         end,
         executed_by = case
           when v_status = 'completed' then auth.uid()
           else executed_by
         end,
         executed_at = case
           when v_status = 'completed' then timezone('utc'::text, now())
           else executed_at
         end,
         resolved_at = case
           when v_status in ('completed', 'rejected', 'failed', 'cancelled') then timezone('utc'::text, now())
           else null
         end,
         updated_at = timezone('utc'::text, now())
   where id = p_case_id;

  if not found then
    return false;
  end if;

  insert into public.account_merge_events (
    merge_case_id,
    event_type,
    actor_user_id,
    metadata
  )
  values (
    p_case_id,
    'case_status_updated',
    auth.uid(),
    jsonb_build_object(
      'status', v_status,
      'notes', nullif(trim(coalesce(p_notes, '')), ''),
      'execution_summary', coalesce(p_execution_summary, '{}'::jsonb)
    )
  );

  return true;
end;
$$;


ALTER FUNCTION "public"."rpc_admin_update_account_merge_case"("p_case_id" "uuid", "p_status" "text", "p_notes" "text", "p_execution_summary" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_admin_update_account_recovery_request"("p_request_id" "uuid", "p_status" "text", "p_review_notes" "text" DEFAULT NULL::"text", "p_linked_merge_case_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_status text := lower(trim(coalesce(p_status, '')));
  v_existing public.account_recovery_requests%rowtype;
  v_next_review_notes text;
  v_next_linked_merge_case_id uuid;
begin
  if not public.is_internal_admin() then
    raise exception 'admin access required';
  end if;

  if v_status not in ('pending', 'reviewing', 'resolved', 'closed') then
    raise exception 'invalid recovery request status';
  end if;

  select *
    into v_existing
  from public.account_recovery_requests
  where id = p_request_id
  for update;

  if not found then
    return false;
  end if;

  v_next_review_notes := coalesce(nullif(trim(coalesce(p_review_notes, '')), ''), v_existing.review_notes);
  v_next_linked_merge_case_id := coalesce(p_linked_merge_case_id, v_existing.linked_merge_case_id);

  update public.account_recovery_requests
     set status = v_status,
         linked_merge_case_id = v_next_linked_merge_case_id,
         review_notes = v_next_review_notes,
         reviewed_by = case
           when v_status in ('reviewing', 'resolved', 'closed') then auth.uid()
           else v_existing.reviewed_by
         end,
         reviewed_at = case
           when v_status in ('reviewing', 'resolved', 'closed') then timezone('utc'::text, now())
           else v_existing.reviewed_at
         end
   where id = p_request_id;

  insert into public.account_recovery_request_events (
    request_id,
    event_type,
    actor_user_id,
    metadata
  )
  values (
    p_request_id,
    'request_updated',
    auth.uid(),
    jsonb_build_object(
      'from_status', v_existing.status,
      'to_status', v_status,
      'linked_merge_case_id', v_next_linked_merge_case_id,
      'review_notes', v_next_review_notes
    )
  );

  return true;
end;
$$;


ALTER FUNCTION "public"."rpc_admin_update_account_recovery_request"("p_request_id" "uuid", "p_status" "text", "p_review_notes" "text", "p_linked_merge_case_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_admin_update_report_status"("p_report_id" "uuid", "p_status" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  normalized_status text;
begin
  if not public.is_internal_admin() then
    raise exception 'admin access required';
  end if;

  normalized_status := upper(trim(coalesce(p_status, '')));
  if normalized_status not in ('PENDING', 'REVIEWING', 'RESOLVED', 'DISMISSED') then
    raise exception 'invalid report status';
  end if;

  update public.reports
     set status = normalized_status
   where id = p_report_id;

  return found;
end;
$$;


ALTER FUNCTION "public"."rpc_admin_update_report_status"("p_report_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."circle_prompt_responses" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prompt_id" "uuid" NOT NULL,
    "circle_id" "uuid",
    "profile_id" "uuid" NOT NULL,
    "user_id" "uuid",
    "response" "text" NOT NULL,
    "reaction_count" integer DEFAULT 0 NOT NULL,
    "is_deleted" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    CONSTRAINT "circle_prompt_responses_length" CHECK ((("char_length"("btrim"("response")) >= 1) AND ("char_length"("btrim"("response")) <= 500)))
);


ALTER TABLE "public"."circle_prompt_responses" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_answer_circle_prompt"("p_prompt_id" "uuid", "p_response" "text") RETURNS "public"."circle_prompt_responses"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_profile_id uuid;
  v_circle_id uuid;
  v_body text := nullif(btrim(coalesce(p_response, '')), '');
  v_response public.circle_prompt_responses;
begin
  if v_user_id is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if v_body is null or char_length(v_body) > 500 then
    raise exception 'invalid_response';
  end if;

  select p.id
    into v_profile_id
  from public.profiles p
  where p.user_id = v_user_id
    and p.deleted_at is null
  limit 1;

  select cp.circle_id
    into v_circle_id
  from public.circle_prompts cp
  where cp.id = p_prompt_id
    and cp.status = 'published'
    and (cp.starts_at is null or cp.starts_at <= timezone('utc'::text, now()))
    and (cp.expires_at is null or cp.expires_at > timezone('utc'::text, now()))
  limit 1;

  if v_profile_id is null or v_circle_id is null then
    raise exception 'prompt_unavailable';
  end if;

  if v_circle_id is not null and not public.is_circle_member(v_circle_id, v_user_id) then
    raise exception 'circle_membership_required' using errcode = '42501';
  end if;

  insert into public.circle_prompt_responses (prompt_id, circle_id, profile_id, user_id, response)
  values (p_prompt_id, v_circle_id, v_profile_id, v_user_id, v_body)
  on conflict (prompt_id, profile_id) do update
    set response = excluded.response,
        is_deleted = false,
        updated_at = timezone('utc'::text, now())
  returning * into v_response;

  return v_response;
end;
$$;


ALTER FUNCTION "public"."rpc_answer_circle_prompt"("p_prompt_id" "uuid", "p_response" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_approve_circle"("p_circle_id" "uuid") RETURNS "public"."circles"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_circle public.circles;
begin
  if not public.is_admin_user(auth.uid()) then
    raise exception 'admin access required' using errcode = '42501';
  end if;

  update public.circles
  set status = 'approved',
      approved_by_admin_id = auth.uid(),
      approved_at = timezone('utc'::text, now()),
      rejected_reason = null,
      archived_at = null,
      updated_at = timezone('utc'::text, now())
  where id = p_circle_id
    and status <> 'archived'
  returning * into v_circle;

  return v_circle;
end;
$$;


ALTER FUNCTION "public"."rpc_approve_circle"("p_circle_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_approve_circle_member"("p_circle_id" "uuid", "p_member_id" "uuid", "p_profile_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_owner uuid;
  v_actor_role text;
  v_is_admin boolean := public.is_admin_user(auth.uid());
  v_is_circle_owner boolean := false;
  v_updated boolean := false;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  select user_id into v_owner
  from public.profiles
  where id = p_profile_id
  limit 1;

  if v_owner is null or v_owner <> auth.uid() then
    raise exception 'Not authorized';
  end if;

  v_is_circle_owner := public.is_circle_owner(p_circle_id, auth.uid());

  if not v_is_admin and not v_is_circle_owner then
    select lower(role) into v_actor_role
    from public.circle_members
    where circle_id = p_circle_id
      and profile_id = p_profile_id
      and status = 'active'
    limit 1;

    if coalesce(v_actor_role, '') not in ('leader', 'host', 'admin', 'moderator') then
      raise exception 'Only hosts or moderators can approve';
    end if;
  end if;

  update public.circle_members
  set status = 'active',
      left_at = null,
      updated_at = timezone('utc'::text, now())
  where circle_id = p_circle_id
    and profile_id = p_member_id
    and status = 'pending';
  v_updated := found;

  update public.circles c
  set member_count = (
    select count(*)::int
    from public.circle_members cm
    where cm.circle_id = c.id
      and cm.status = 'active'
  )
  where c.id = p_circle_id;

  return v_updated;
end;
$$;


ALTER FUNCTION "public"."rpc_approve_circle_member"("p_circle_id" "uuid", "p_member_id" "uuid", "p_profile_id" "uuid") OWNER TO "postgres";


