ALTER FUNCTION "public"."rpc_approve_gathering"("p_gathering_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_archive_circle_pulse_item"("p_item_id" "uuid", "p_actor_profile_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_circle_id uuid;
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_actor_profile_id
      and p.user_id = auth.uid()
      and p.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  select cpi.circle_id
    into v_circle_id
  from public.circle_pulse_items cpi
  where cpi.id = p_item_id
  for update;

  if v_circle_id is null then
    raise exception 'pulse_item_not_found';
  end if;

  if not public.can_manage_circle_pulse(v_circle_id, auth.uid()) then
    raise exception 'host_required' using errcode = '42501';
  end if;

  update public.circle_pulse_items
  set status = 'archived'
  where id = p_item_id;

  return found;
end;
$$;


ALTER FUNCTION "public"."rpc_archive_circle_pulse_item"("p_item_id" "uuid", "p_actor_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_archive_owned_circle"("p_circle_id" "uuid", "p_actor_profile_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_circle public.circles%rowtype;
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles actor
    where actor.id = p_actor_profile_id
      and actor.user_id = auth.uid()
      and actor.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  select *
    into v_circle
  from public.circles c
  where c.id = p_circle_id
  for update;

  if v_circle.id is null then
    raise exception 'circle_not_found';
  end if;

  if v_circle.created_by_profile_id <> p_actor_profile_id then
    raise exception 'circle_creator_required' using errcode = '42501';
  end if;

  if coalesce(v_circle.is_official, false) then
    raise exception 'official_circle_requires_admin' using errcode = '42501';
  end if;

  update public.circles
  set status = 'archived',
      archived_at = timezone('utc'::text, now()),
      updated_at = timezone('utc'::text, now())
  where id = p_circle_id;

  return true;
end;
$$;


ALTER FUNCTION "public"."rpc_archive_owned_circle"("p_circle_id" "uuid", "p_actor_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_archive_profile_gift"("p_gift_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_row public.profile_gifts%rowtype;
  v_was_archived_at timestamptz;
begin
  if auth.uid() is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  select g.archived_at
    into v_was_archived_at
  from public.profile_gifts g
  where g.id = p_gift_id
    and exists (
      select 1
      from public.profiles recipient
      where recipient.id = g.profile_id
        and recipient.user_id = auth.uid()
        and recipient.deleted_at is null
    )
  limit 1;

  update public.profile_gifts g
  set opened_at = coalesce(g.opened_at, timezone('utc'::text, now())),
      revealed_at = coalesce(g.revealed_at, timezone('utc'::text, now())),
      archived_at = coalesce(g.archived_at, timezone('utc'::text, now()))
  where g.id = p_gift_id
    and exists (
      select 1
      from public.profiles recipient
      where recipient.id = g.profile_id
        and recipient.user_id = auth.uid()
        and recipient.deleted_at is null
    )
  returning g.* into v_row;

  if v_row.id is null then
    raise exception 'gift not found' using errcode = 'P0002';
  end if;

  if v_was_archived_at is null then
    perform public.rpc_log_profile_gift_event(
      v_row.id,
      'archived',
      jsonb_build_object('gift_type', v_row.gift_type)
    );

    perform public.notify_profile_gift_sender_moment(v_row.id, 'archived');
  end if;

  return jsonb_build_object(
    'gift_id', v_row.id,
    'opened_at', v_row.opened_at,
    'revealed_at', v_row.revealed_at,
    'archived_at', v_row.archived_at
  );
end;
$$;


ALTER FUNCTION "public"."rpc_archive_profile_gift"("p_gift_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_archive_relationship_gist_editorial"("p_gist_id" "uuid", "p_actor_profile_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not public.is_admin_user(auth.uid()) then
    raise exception 'admin access required' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles actor
    where actor.id = p_actor_profile_id
      and actor.user_id = auth.uid()
      and actor.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  update public.relationship_gists
  set status = 'archived',
      scheduled_for = null,
      updated_at = timezone('utc'::text, now())
  where id = p_gist_id
    and status <> 'archived';

  if not found then
    raise exception 'gist_not_found';
  end if;

  return true;
end;
$$;


ALTER FUNCTION "public"."rpc_archive_relationship_gist_editorial"("p_gist_id" "uuid", "p_actor_profile_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."gathering_attendees" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "gathering_id" "uuid" NOT NULL,
    "profile_id" "uuid" NOT NULL,
    "user_id" "uuid",
    "status" "text" DEFAULT 'attending'::"text" NOT NULL,
    "visible_to_others" boolean DEFAULT false NOT NULL,
    "checked_in_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    CONSTRAINT "gathering_attendees_status_valid" CHECK (("status" = ANY (ARRAY['interested'::"text", 'attending'::"text", 'cancelled'::"text", 'checked_in'::"text"])))
);


ALTER TABLE "public"."gathering_attendees" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_attend_gathering"("p_gathering_id" "uuid", "p_status" "text" DEFAULT 'attending'::"text", "p_visible_to_others" boolean DEFAULT false) RETURNS "public"."gathering_attendees"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_profile_id uuid;
  v_attendee public.gathering_attendees;
begin
  if v_user_id is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if p_status not in ('interested', 'attending', 'cancelled', 'checked_in') then
    raise exception 'invalid_status';
  end if;

  select p.id
    into v_profile_id
  from public.profiles p
  where p.user_id = v_user_id
    and p.deleted_at is null
  limit 1;

  if v_profile_id is null then
    raise exception 'profile_not_found';
  end if;

  if not exists (
    select 1
    from public.gatherings g
    where g.id = p_gathering_id
      and g.status = 'approved'
      and g.cancelled_at is null
      and (g.max_attendees is null or g.attendee_count < g.max_attendees or p_status = 'cancelled')
  ) then
    raise exception 'gathering_unavailable';
  end if;

  insert into public.gathering_attendees (gathering_id, profile_id, user_id, status, visible_to_others)
  values (p_gathering_id, v_profile_id, v_user_id, p_status, coalesce(p_visible_to_others, false))
  on conflict (gathering_id, profile_id) do update
    set status = excluded.status,
        visible_to_others = excluded.visible_to_others,
        updated_at = timezone('utc'::text, now())
  returning * into v_attendee;

  update public.gatherings g
  set attendee_count = (
    select count(*)::int
    from public.gathering_attendees ga
    where ga.gathering_id = g.id
      and ga.status in ('interested', 'attending', 'checked_in')
  )
  where g.id = p_gathering_id;

  return v_attendee;
end;
$$;


ALTER FUNCTION "public"."rpc_attend_gathering"("p_gathering_id" "uuid", "p_status" "text", "p_visible_to_others" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_backfill_swipe_likes_into_intent_requests"("p_days" integer DEFAULT 30, "p_limit" integer DEFAULT 5000) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_inserted integer := 0;
BEGIN
  -- Guardrails.
  IF p_days IS NULL OR p_days < 1 THEN
    RAISE EXCEPTION 'p_days must be >= 1';
  END IF;
  IF p_limit IS NULL OR p_limit < 1 THEN
    RAISE EXCEPTION 'p_limit must be >= 1';
  END IF;

  WITH candidates AS (
    SELECT
      s.id AS swipe_id,
      s.swiper_id AS actor_profile_id,
      s.target_id AS recipient_profile_id,
      s.action AS swipe_action,
      s.created_at AS swipe_created_at
    FROM public.swipes s
    WHERE s.action IN ('LIKE','SUPERLIKE')
      AND s.created_at >= (now() - make_interval(days => p_days))
    ORDER BY s.created_at DESC
    LIMIT p_limit
  ),
  resolved AS (
    SELECT
      c.*,
      pa.user_id AS actor_user_id,
      pr.user_id AS recipient_user_id
    FROM candidates c
    JOIN public.profiles pa ON pa.id = c.actor_profile_id
    JOIN public.profiles pr ON pr.id = c.recipient_profile_id
    WHERE pa.user_id IS NOT NULL
      AND pr.user_id IS NOT NULL
  ),
  filtered AS (
    SELECT r.*
    FROM resolved r
    WHERE NOT EXISTS (
      -- Skip if any like_with_note already exists for this pair (any status).
      SELECT 1
      FROM public.intent_requests ir
      WHERE ir.recipient_id = r.recipient_profile_id
        AND ir.actor_id = r.actor_profile_id
        AND ir.type = 'like_with_note'
    )
    AND NOT EXISTS (
      -- Skip if blocked either way (blocks are stored by user_id).
      SELECT 1
      FROM public.blocks b
      WHERE (b.blocker_id = r.actor_user_id AND b.blocked_id = r.recipient_user_id)
         OR (b.blocker_id = r.recipient_user_id AND b.blocked_id = r.actor_user_id)
    )
  ),
  inserted AS (
    INSERT INTO public.intent_requests (
      recipient_id,
      actor_id,
      type,
      message,
      suggested_time,
      suggested_place,
      status,
      created_at,
      expires_at,
      metadata
    )
    SELECT
      f.recipient_profile_id,
      f.actor_profile_id,
      'like_with_note',
      NULL,
      NULL,
      NULL,
      CASE
        WHEN (f.swipe_created_at + interval '72 hours') < now() THEN 'expired'
        ELSE 'pending'
      END,
      f.swipe_created_at,
      (f.swipe_created_at + interval '72 hours'),
      jsonb_build_object(
        'source', 'swipe_backfill',
        'swipe_id', f.swipe_id,
        'swipe_action', f.swipe_action,
        'backfill_days', p_days
      )
    FROM filtered f
    RETURNING 1
  )
  SELECT count(*) INTO v_inserted FROM inserted;

  RETURN v_inserted;
END;
$$;


ALTER FUNCTION "public"."rpc_backfill_swipe_likes_into_intent_requests"("p_days" integer, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_cancel_circle_invitation"("p_invitation_id" "uuid", "p_actor_profile_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_catalog'
    AS $$
declare
  v_invitation public.circle_invitations%rowtype;
  v_target_user_id uuid;
  v_circle_name text;
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles actor
    where actor.id = p_actor_profile_id
      and actor.user_id = auth.uid()
      and actor.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  select *
    into v_invitation
  from public.circle_invitations ci
  where ci.id = p_invitation_id
    and ci.status = 'pending'
  for update;

  if v_invitation.id is null then
    raise exception 'circle_invitation_not_found';
  end if;

  if v_invitation.inviter_profile_id <> p_actor_profile_id
    and not public.can_manage_circle_pulse(v_invitation.circle_id, auth.uid()) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  update public.circle_invitations
  set status = 'revoked',
      responded_at = timezone('utc'::text, now())
  where id = p_invitation_id;

  update public.circle_members
  set status = 'removed',
      left_at = timezone('utc'::text, now())
  where circle_id = v_invitation.circle_id
    and profile_id = v_invitation.invited_profile_id
    and status = 'invited';

  select invited.user_id, c.name
    into v_target_user_id, v_circle_name
  from public.profiles invited
  join public.circles c on c.id = v_invitation.circle_id
  where invited.id = v_invitation.invited_profile_id
  limit 1;

  if v_target_user_id is not null
    and not exists (
      select 1
      from public.notification_prefs np
      where np.user_id = v_target_user_id
        and np.push_enabled = false
    )
    and not public.is_quiet_hours(v_target_user_id) then
    perform private.send_push_webhook(
      jsonb_build_object(
        'user_id', v_target_user_id,
        'title', 'Circle invitation updated',
        'body', 'The invitation from ' || coalesce(v_circle_name, 'a Betweener Circle') || ' is no longer active.',
        'data', jsonb_build_object(
          'type', 'circle_invitation',
          'event_type', 'withdrawn',
          'circle_id', v_invitation.circle_id,
          'invitation_id', v_invitation.id
        )
      )
    );
  end if;

  return true;
end;
$$;


ALTER FUNCTION "public"."rpc_cancel_circle_invitation"("p_invitation_id" "uuid", "p_actor_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_cancel_circle_love_seat_nomination"("p_love_seat_id" "uuid", "p_actor_profile_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_love_seat public.circle_love_seats%rowtype;
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_actor_profile_id
      and p.user_id = auth.uid()
      and p.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  select *
    into v_love_seat
  from public.circle_love_seats cls
  where cls.id = p_love_seat_id
  for update;

  if v_love_seat.id is null then
    raise exception 'love_seat_not_found';
  end if;

  if v_love_seat.status <> 'pending_user_approval' then
    raise exception 'pending_love_seat_not_found';
  end if;

  if not public.can_manage_circle_pulse(v_love_seat.circle_id, auth.uid()) then
    raise exception 'host_required' using errcode = '42501';
  end if;

  update public.circle_love_seats
  set status = 'archived',
      responded_at = timezone('utc'::text, now())
  where id = p_love_seat_id;

  return true;
end;
$$;


ALTER FUNCTION "public"."rpc_cancel_circle_love_seat_nomination"("p_love_seat_id" "uuid", "p_actor_profile_id" "uuid") OWNER TO "postgres";


