CREATE OR REPLACE FUNCTION "public"."rpc_cancel_circle_role_request"("p_request_id" "uuid", "p_profile_id" "uuid") RETURNS "public"."circle_role_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_owner uuid;
  v_request public.circle_role_requests%rowtype;
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  select user_id into v_owner
  from public.profiles
  where id = p_profile_id
  limit 1;

  if v_owner is null or v_owner <> auth.uid() then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  update public.circle_role_requests
  set status = 'cancelled',
      updated_at = timezone('utc'::text, now())
  where id = p_request_id
    and requester_profile_id = p_profile_id
    and status = 'pending'
  returning * into v_request;

  if v_request.id is null then
    raise exception 'request_not_found';
  end if;

  return v_request;
end;
$$;


ALTER FUNCTION "public"."rpc_cancel_circle_role_request"("p_request_id" "uuid", "p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_cancel_date_plan"("p_plan_id" "uuid") RETURNS TABLE("plan_id" "uuid", "status" "text", "concierge_requested" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_plan public.date_plans%rowtype;
  v_actor_profile public.profiles%rowtype;
  v_cancelled_by_name text;
  v_requester_text text;
  v_actor_text text;
begin
  select *
  into v_actor_profile
  from public.profiles
  where user_id = auth.uid()
  limit 1;

  if v_actor_profile.id is null then
    raise exception 'actor_profile_not_found';
  end if;

  select *
  into v_plan
  from public.date_plans
  where id = p_plan_id
  limit 1;

  if v_plan.id is null then
    raise exception 'date_plan_not_found';
  end if;

  if auth.uid() not in (v_plan.creator_user_id, v_plan.recipient_user_id) then
    raise exception 'Only participants can cancel this date plan.';
  end if;

  if v_plan.status = 'cancelled' then
    return query
    select v_plan.id, v_plan.status, false;
    return;
  end if;

  if v_plan.status not in ('pending', 'accepted') then
    raise exception 'This date plan can no longer be cancelled.';
  end if;

  if v_plan.status = 'pending' and auth.uid() <> v_plan.creator_user_id then
    raise exception 'Only the person who suggested the plan can cancel it while it is waiting.';
  end if;

  update public.date_plans
  set status = 'cancelled',
      accepted_at = null,
      accepted_by_profile_id = null,
      declined_at = null,
      declined_by_profile_id = null,
      concierge_requested = false,
      concierge_requested_at = null,
      concierge_requested_by_profile_id = null,
      updated_at = now()
  where id = p_plan_id;

  update public.date_plan_concierge_requests
  set status = 'cancelled',
      resolved_at = coalesce(resolved_at, now()),
      updated_at = now()
  where date_plan_id = p_plan_id
    and public.date_plan_concierge_requests.status in ('pending', 'claimed');

  v_cancelled_by_name := coalesce(v_actor_profile.full_name, 'Someone');

  if v_plan.status = 'pending' then
    v_requester_text := v_cancelled_by_name || ' cancelled the date suggestion.';
    v_actor_text := 'You cancelled the date suggestion.';
  else
    v_requester_text := v_cancelled_by_name || ' cancelled the date plan.';
    v_actor_text := 'You cancelled the date plan.';
  end if;

  insert into public.system_messages (
    user_id,
    peer_user_id,
    event_type,
    text,
    metadata
  )
  values (
    v_plan.creator_user_id,
    v_plan.recipient_user_id,
    'date_plan_cancelled',
    case
      when auth.uid() = v_plan.creator_user_id then v_actor_text
      else v_requester_text
    end,
    jsonb_build_object('date_plan_id', p_plan_id, 'role', case when auth.uid() = v_plan.creator_user_id then 'requester' else 'participant' end)
  );

  insert into public.system_messages (
    user_id,
    peer_user_id,
    event_type,
    text,
    metadata
  )
  values (
    v_plan.recipient_user_id,
    v_plan.creator_user_id,
    'date_plan_cancelled',
    case
      when auth.uid() = v_plan.recipient_user_id then v_actor_text
      else v_requester_text
    end,
    jsonb_build_object('date_plan_id', p_plan_id, 'role', case when auth.uid() = v_plan.recipient_user_id then 'requester' else 'participant' end)
  );

  return query
  select p_plan_id, 'cancelled', false;
end;
$$;


ALTER FUNCTION "public"."rpc_cancel_date_plan"("p_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_cancel_intent_request"("p_request_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid;
  v_profile_id uuid;
  v_id uuid;
begin
  v_user_id := auth.uid();
  if v_user_id is null then
    raise exception 'Not authenticated';
  end if;

  select p.id
    into v_profile_id
  from public.profiles p
  where p.user_id = v_user_id
  limit 1;

  if v_profile_id is null then
    raise exception 'Profile not found';
  end if;

  update public.intent_requests
  set status = 'cancelled'
  where id = p_request_id
    and actor_id = v_profile_id
    and status = 'pending'
  returning id into v_id;

  if v_id is null then
    raise exception 'Request not found or not cancellable';
  end if;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."rpc_cancel_intent_request"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_cancel_my_verification_request"("p_request_id" "uuid", "p_cancel_reason" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  request_row public.verification_requests%rowtype;
  v_reason text;
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  select *
    into request_row
  from public.verification_requests
  where id = p_request_id
    and user_id = auth.uid()
  for update;

  if not found then
    raise exception 'verification request not found';
  end if;

  if coalesce(request_row.status, 'pending') <> 'pending' then
    raise exception 'only pending verification requests can be withdrawn';
  end if;

  v_reason := nullif(left(trim(coalesce(p_cancel_reason, '')), 240), '');

  update public.verification_requests
     set status = 'cancelled',
         cancelled_at = timezone('utc'::text, now()),
         cancelled_by = auth.uid(),
         cancel_reason = coalesce(v_reason, 'Withdrawn by user'),
         reviewer_notes = case
           when nullif(trim(coalesce(reviewer_notes, '')), '') is null
             then 'Withdrawn by user'
           else reviewer_notes
         end,
         user_notified = true,
         updated_at = timezone('utc'::text, now())
   where id = request_row.id;

  return true;
end;
$$;


ALTER FUNCTION "public"."rpc_cancel_my_verification_request"("p_request_id" "uuid", "p_cancel_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_cancel_signal"("p_signal_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_id uuid;
begin
  if auth.uid() is null then
    raise exception 'unauthenticated';
  end if;

  update public.profile_signal_gestures
  set status = 'dismissed',
      dismissed_at = now()
  where id = p_signal_id
    and sender_user_id = auth.uid()
    and status in ('sent', 'seen')
  returning id into v_id;

  if v_id is null then
    raise exception 'signal_not_cancellable';
  end if;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."rpc_cancel_signal"("p_signal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_clear_signin_provider_disconnected"("p_provider" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_provider text := lower(trim(coalesce(p_provider, '')));
begin
  if v_user_id is null then
    raise exception 'authentication required';
  end if;

  if v_provider not in ('google', 'apple') then
    raise exception 'unsupported provider';
  end if;

  update public.account_disconnected_signin_providers
  set
    active = false,
    reconnected_at = timezone('utc'::text, now()),
    updated_at = timezone('utc'::text, now())
  where user_id = v_user_id
    and provider = v_provider
    and active = true;

  return true;
end;
$$;


ALTER FUNCTION "public"."rpc_clear_signin_provider_disconnected"("p_provider" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_create_circle"("p_profile_id" "uuid", "p_name" "text", "p_description" "text", "p_visibility" "text" DEFAULT 'public'::"text", "p_category" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_owner uuid;
  v_circle_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  select user_id into v_owner
  from public.profiles
  where id = p_profile_id
  limit 1;

  if v_owner is null or v_owner <> auth.uid() then
    raise exception 'Not authorized';
  end if;

  insert into public.circles (name, description, visibility, category, created_by_profile_id)
  values (p_name, p_description, coalesce(p_visibility, 'public'), p_category, p_profile_id)
  returning id into v_circle_id;

  insert into public.circle_members (circle_id, profile_id, role, status, is_visible)
  values (v_circle_id, p_profile_id, 'leader', 'active', true)
  on conflict (circle_id, profile_id) do nothing;

  return v_circle_id;
end;
$$;


ALTER FUNCTION "public"."rpc_create_circle"("p_profile_id" "uuid", "p_name" "text", "p_description" "text", "p_visibility" "text", "p_category" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."circle_prompts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "circle_id" "uuid",
    "title" "text" NOT NULL,
    "prompt" "text" NOT NULL,
    "prompt_type" "text" DEFAULT 'weekly'::"text" NOT NULL,
    "status" "text" DEFAULT 'published'::"text" NOT NULL,
    "created_by_profile_id" "uuid",
    "created_by_admin_id" "uuid",
    "starts_at" timestamp with time zone,
    "expires_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    CONSTRAINT "circle_prompts_prompt_length" CHECK ((("char_length"("btrim"("prompt")) >= 3) AND ("char_length"("btrim"("prompt")) <= 500))),
    CONSTRAINT "circle_prompts_status_valid" CHECK (("status" = ANY (ARRAY['draft'::"text", 'published'::"text", 'archived'::"text"]))),
    CONSTRAINT "circle_prompts_title_length" CHECK ((("char_length"("btrim"("title")) >= 3) AND ("char_length"("btrim"("title")) <= 120))),
    CONSTRAINT "circle_prompts_type_valid" CHECK (("prompt_type" = ANY (ARRAY['daily'::"text", 'weekly'::"text", 'featured'::"text", 'host'::"text"])))
);


ALTER TABLE "public"."circle_prompts" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_create_circle_prompt"("p_circle_id" "uuid", "p_title" "text", "p_prompt" "text", "p_prompt_type" "text" DEFAULT 'host'::"text", "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "public"."circle_prompts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_profile public.profiles%rowtype;
  v_prompt public.circle_prompts%rowtype;
  v_circle public.circles%rowtype;
  v_title text := nullif(btrim(coalesce(p_title, '')), '');
  v_body text := nullif(btrim(coalesce(p_prompt, '')), '');
  v_is_admin boolean := false;
  v_can_publish boolean := false;
begin
  if v_user_id is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if p_circle_id is null then
    raise exception 'circle_not_found';
  end if;

  if v_title is null or char_length(v_title) < 3 or char_length(v_title) > 120 then
    raise exception 'invalid_title';
  end if;

  if v_body is null or char_length(v_body) < 3 or char_length(v_body) > 500 then
    raise exception 'invalid_prompt';
  end if;

  if coalesce(p_prompt_type, 'host') not in ('daily', 'weekly', 'featured', 'host') then
    raise exception 'invalid_prompt_type';
  end if;

  select *
    into v_profile
  from public.profiles p
  where p.user_id = v_user_id
    and p.deleted_at is null
  limit 1;

  if v_profile.id is null then
    raise exception 'profile_not_found';
  end if;

  select *
    into v_circle
  from public.circles c
  where c.id = p_circle_id
    and c.archived_at is null
  limit 1;

  if v_circle.id is null or v_circle.status <> 'approved' then
    raise exception 'circle_not_found';
  end if;

  v_is_admin := public.is_admin_user(v_user_id);
  v_can_publish := v_is_admin
    or public.is_circle_owner(p_circle_id, v_user_id)
    or public.is_circle_host(p_circle_id, v_profile.id);

  if not v_can_publish then
    raise exception 'host_required' using errcode = '42501';
  end if;

  if p_expires_at is not null and p_expires_at <= timezone('utc'::text, now()) then
    raise exception 'invalid_expiry';
  end if;

  insert into public.circle_prompts (
    circle_id,
    title,
    prompt,
    prompt_type,
    status,
    created_by_profile_id,
    created_by_admin_id,
    starts_at,
    expires_at
  )
  values (
    p_circle_id,
    v_title,
    v_body,
    coalesce(p_prompt_type, 'host'),
    'published',
    v_profile.id,
    case when v_is_admin then v_user_id else null end,
    timezone('utc'::text, now()),
    p_expires_at
  )
  returning * into v_prompt;

  return v_prompt;
end;
$$;


ALTER FUNCTION "public"."rpc_create_circle_prompt"("p_circle_id" "uuid", "p_title" "text", "p_prompt" "text", "p_prompt_type" "text", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_create_circle_pulse_comment"("p_pulse_item_id" "uuid", "p_profile_id" "uuid", "p_body" "text", "p_parent_comment_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "pulse_item_id" "uuid", "circle_id" "uuid", "profile_id" "uuid", "display_name" "text", "avatar_url" "text", "body" "text", "parent_comment_id" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "edited_at" timestamp with time zone, "is_own" boolean, "can_remove" boolean, "can_edit" boolean, "can_pin" boolean, "pinned_at" timestamp with time zone, "report_count" integer, "reaction_count" integer, "my_reaction" "text", "reply_preview_profile_id" "uuid", "reply_preview_display_name" "text", "reply_preview_body" "text", "reaction_summary" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_circle_id uuid;
  v_comment public.circle_pulse_comments%rowtype;
  v_body text := nullif(btrim(coalesce(p_body, '')), '');
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_profile_id
      and p.user_id = auth.uid()
      and p.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  if v_body is null or char_length(v_body) > 500 then
    raise exception 'invalid_comment';
  end if;

  select cpi.circle_id
    into v_circle_id
  from public.circle_pulse_items cpi
  where cpi.id = p_pulse_item_id
    and cpi.status = 'active'
    and (cpi.starts_at is null or cpi.starts_at <= timezone('utc'::text, now()))
    and (cpi.expires_at is null or cpi.expires_at > timezone('utc'::text, now()))
  limit 1;

  if v_circle_id is null then
    raise exception 'pulse_item_not_found';
  end if;

  if not public.is_circle_member(v_circle_id, auth.uid())
    and not public.is_circle_owner(v_circle_id, auth.uid()) then
    raise exception 'circle_membership_required' using errcode = '42501';
  end if;

  if p_parent_comment_id is not null and not exists (
    select 1
    from public.circle_pulse_comments cpc
    where cpc.id = p_parent_comment_id
      and cpc.pulse_item_id = p_pulse_item_id
      and cpc.status = 'active'
  ) then
    raise exception 'parent_comment_not_found';
  end if;

  insert into public.circle_pulse_comments (
    circle_id,
    pulse_item_id,
    profile_id,
    user_id,
    body,
    parent_comment_id
  )
  values (
    v_circle_id,
    p_pulse_item_id,
    p_profile_id,
    auth.uid(),
    v_body,
    p_parent_comment_id
  )
  returning * into v_comment;

  return query
  select *
  from public.rpc_get_circle_pulse_comment_snapshot(v_comment.id);
end;
$$;


ALTER FUNCTION "public"."rpc_create_circle_pulse_comment"("p_pulse_item_id" "uuid", "p_profile_id" "uuid", "p_body" "text", "p_parent_comment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_create_circle_relationship_gist"("p_circle_id" "uuid", "p_actor_profile_id" "uuid", "p_title" "text", "p_short_body" "text", "p_body" "text", "p_perspective" "text" DEFAULT 'general'::"text") RETURNS "public"."relationship_gists"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_gist public.relationship_gists%rowtype;
  v_title text := nullif(btrim(coalesce(p_title, '')), '');
  v_short_body text := nullif(btrim(coalesce(p_short_body, '')), '');
  v_body text := nullif(btrim(coalesce(p_body, '')), '');
  v_perspective text := lower(nullif(btrim(coalesce(p_perspective, '')), ''));
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not public.is_admin_user(auth.uid()) then
    raise exception 'admin access required' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles actor
    where actor.id = p_actor_profile_id
      and actor.user_id = auth.uid()
      and actor.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  if v_title is null or char_length(v_title) not between 3 and 140 then
    raise exception 'gist_title_invalid';
  end if;

  if v_body is null or char_length(v_body) not between 20 and 5000 then
    raise exception 'gist_body_invalid';
  end if;

  if v_perspective not in ('general', 'christian', 'muslim', 'culture', 'safety', 'communication') then
    raise exception 'gist_perspective_invalid';
  end if;

  insert into public.relationship_gists (
    circle_id,
    title,
    short_body,
    body,
    perspective,
    status,
    created_by_profile_id,
    created_by_admin_id,
    published_at
  )
  values (
    p_circle_id,
    v_title,
    v_short_body,
    v_body,
    v_perspective,
    'published',
    p_actor_profile_id,
    auth.uid(),
    timezone('utc'::text, now())
  )
  returning * into v_gist;

  return v_gist;
end;
$$;


ALTER FUNCTION "public"."rpc_create_circle_relationship_gist"("p_circle_id" "uuid", "p_actor_profile_id" "uuid", "p_title" "text", "p_short_body" "text", "p_body" "text", "p_perspective" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_create_circle_request"("p_name" "text", "p_description" "text" DEFAULT NULL::"text", "p_short_description" "text" DEFAULT NULL::"text", "p_circle_type" "text" DEFAULT 'gold_community'::"text", "p_visibility_scope" "text" DEFAULT 'country'::"text", "p_country_code" "text" DEFAULT NULL::"text", "p_country_name" "text" DEFAULT NULL::"text", "p_region" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_diaspora_tags" "text"[] DEFAULT '{}'::"text"[], "p_culture_tags" "text"[] DEFAULT '{}'::"text"[], "p_faith_tags" "text"[] DEFAULT '{}'::"text"[], "p_interest_tags" "text"[] DEFAULT '{}'::"text"[], "p_audience_tags" "text"[] DEFAULT '{}'::"text"[], "p_requires_join_approval" boolean DEFAULT false, "p_rules" "text" DEFAULT NULL::"text") RETURNS "public"."circles"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_profile public.profiles%rowtype;
  v_is_admin boolean;
  v_name text := nullif(btrim(coalesce(p_name, '')), '');
  v_slug_base text;
  v_slug text;
  v_status text;
  v_circle public.circles;
begin
  if v_user_id is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if v_name is null or char_length(v_name) < 3 or char_length(v_name) > 80 then
    raise exception 'invalid_name';
  end if;

  if p_visibility_scope not in ('local', 'country', 'diaspora', 'global', 'invite_only') then
    raise exception 'invalid_visibility';
  end if;

  select *
    into v_profile
  from public.profiles p
  where p.user_id = v_user_id
    and p.deleted_at is null
  limit 1;

  if v_profile.id is null then
    raise exception 'profile_not_found';
  end if;

  v_is_admin := public.is_admin_user(v_user_id);

  if not v_is_admin and not public.has_gold_entitlement(v_user_id, v_profile.id) then
    raise exception 'gold_required' using errcode = '42501';
  end if;

  if not v_is_admin and coalesce(p_circle_type, 'gold_community') not in ('gold_community', 'community', 'private') then
    raise exception 'invalid_circle_type';
  end if;

  v_slug_base := public.slugify(v_name);
  v_slug := v_slug_base;

  if exists (
    select 1
    from public.circles c
    where c.status = 'approved'
      and public.slugify(c.name) = v_slug_base
      and coalesce(upper(c.country_code), '') = coalesce(upper(p_country_code), '')
      and coalesce(lower(c.city), '') = coalesce(lower(p_city), '')
      and c.archived_at is null
  ) then
    raise exception 'duplicate_circle';
  end if;

  while exists (select 1 from public.circles c where c.slug = v_slug) loop
    v_slug := v_slug_base || '-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 6);
  end loop;

  v_status := case when v_is_admin then 'approved' else 'pending_review' end;

  insert into public.circles (
    name,
    slug,
    description,
    short_description,
    visibility,
    circle_type,
    status,
    visibility_scope,
    country_code,
    country_name,
    region,
    city,
    diaspora_tags,
    culture_tags,
    faith_tags,
    interest_tags,
    audience_tags,
    is_official,
    is_partner,
    requires_join_approval,
    created_by_profile_id,
    created_by_user_id,
    approved_by_admin_id,
    approved_at,
    rules
  )
  values (
    v_name,
    v_slug,
    nullif(btrim(coalesce(p_description, '')), ''),
    nullif(btrim(coalesce(p_short_description, '')), ''),
    case when p_visibility_scope = 'invite_only' or p_circle_type = 'private' then 'private' else 'public' end,
    case
      when v_is_admin then coalesce(nullif(p_circle_type, ''), 'official')
      when p_circle_type = 'private' then 'private'
      else 'gold_community'
    end,
    v_status,
    p_visibility_scope,
    upper(nullif(btrim(coalesce(p_country_code, '')), '')),
    nullif(btrim(coalesce(p_country_name, '')), ''),
    nullif(btrim(coalesce(p_region, '')), ''),
    nullif(btrim(coalesce(p_city, '')), ''),
    coalesce(p_diaspora_tags, '{}'),
    coalesce(p_culture_tags, '{}'),
    coalesce(p_faith_tags, '{}'),
    coalesce(p_interest_tags, '{}'),
    coalesce(p_audience_tags, '{}'),
    v_is_admin and coalesce(p_circle_type, 'official') = 'official',
    v_is_admin and coalesce(p_circle_type, '') = 'partner',
    coalesce(p_requires_join_approval, false),
    v_profile.id,
    v_user_id,
    case when v_is_admin then v_user_id else null end,
    case when v_is_admin then timezone('utc'::text, now()) else null end,
    nullif(btrim(coalesce(p_rules, '')), '')
  )
  returning * into v_circle;

  insert into public.circle_members (circle_id, profile_id, user_id, role, status, is_visible, joined_at)
  values (
    v_circle.id,
    v_profile.id,
    v_user_id,
    case when v_is_admin then 'admin' else 'host' end,
    'active',
    true,
    timezone('utc'::text, now())
  )
  on conflict (circle_id, profile_id) do update
    set role = excluded.role,
        status = 'active',
        user_id = excluded.user_id,
        joined_at = coalesce(public.circle_members.joined_at, excluded.joined_at);

  return v_circle;
end;
$$;


ALTER FUNCTION "public"."rpc_create_circle_request"("p_name" "text", "p_description" "text", "p_short_description" "text", "p_circle_type" "text", "p_visibility_scope" "text", "p_country_code" "text", "p_country_name" "text", "p_region" "text", "p_city" "text", "p_diaspora_tags" "text"[], "p_culture_tags" "text"[], "p_faith_tags" "text"[], "p_interest_tags" "text"[], "p_audience_tags" "text"[], "p_requires_join_approval" boolean, "p_rules" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_create_gathering_request"("p_circle_id" "uuid" DEFAULT NULL::"uuid", "p_title" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_gathering_type" "text" DEFAULT 'physical'::"text", "p_country_code" "text" DEFAULT NULL::"text", "p_country_name" "text" DEFAULT NULL::"text", "p_region" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_venue_name" "text" DEFAULT NULL::"text", "p_venue_address" "text" DEFAULT NULL::"text", "p_address_visibility" "text" DEFAULT 'attendees_only'::"text", "p_online_url" "text" DEFAULT NULL::"text", "p_platform" "text" DEFAULT NULL::"text", "p_starts_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_ends_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_timezone" "text" DEFAULT NULL::"text", "p_max_attendees" integer DEFAULT NULL::integer, "p_tags" "text"[] DEFAULT '{}'::"text"[], "p_safety_note" "text" DEFAULT NULL::"text", "p_poster_url" "text" DEFAULT NULL::"text", "p_presentation_mode" "text" DEFAULT 'general'::"text", "p_featured_profile_id" "uuid" DEFAULT NULL::"uuid", "p_seat_context" "text" DEFAULT NULL::"text", "p_host_created_for_member" boolean DEFAULT false) RETURNS "public"."gatherings"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_profile public.profiles%rowtype;
  v_is_admin boolean;
  v_can_manage_circle boolean := false;
  v_title text := nullif(btrim(coalesce(p_title, '')), '');
  v_slug_base text;
  v_slug text;
  v_gathering public.gatherings;
  v_presentation_mode text := lower(coalesce(nullif(btrim(coalesce(p_presentation_mode, '')), ''), 'general'));
  v_featured_profile_id uuid := null;
  v_seat_context text := lower(nullif(btrim(coalesce(p_seat_context, '')), ''));
begin
  if v_user_id is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if v_title is null or char_length(v_title) < 3 or char_length(v_title) > 120 then
    raise exception 'invalid_title';
  end if;

  if p_gathering_type not in ('online', 'physical', 'hybrid', 'partner_venue', 'livestream') then
    raise exception 'invalid_gathering_type';
  end if;

  if p_starts_at is null or p_starts_at <= timezone('utc'::text, now()) then
    raise exception 'invalid_start_time';
  end if;

  if p_ends_at is not null and p_ends_at <= p_starts_at then
    raise exception 'invalid_end_time';
  end if;

  if v_presentation_mode not in ('general', 'seat_linked') then
    raise exception 'invalid_presentation_mode';
  end if;

  if v_seat_context is not null and v_seat_context not in ('welcome', 'love') then
    raise exception 'invalid_seat_context';
  end if;

  select *
    into v_profile
  from public.profiles p
  where p.user_id = v_user_id
    and p.deleted_at is null
  limit 1;

  if v_profile.id is null then
    raise exception 'profile_not_found';
  end if;

  v_is_admin := public.is_admin_user(v_user_id);
  v_can_manage_circle := p_circle_id is not null and public.can_manage_circle_pulse(p_circle_id, v_user_id);

  if not v_is_admin and not v_can_manage_circle and not public.has_gold_entitlement(v_user_id, v_profile.id) then
    raise exception 'gold_required' using errcode = '42501';
  end if;

  if p_circle_id is not null and not exists (
    select 1
    from public.circles c
    where c.id = p_circle_id
      and (c.status = 'approved' or c.created_by_user_id = v_user_id or v_is_admin)
  ) then
    raise exception 'circle_not_found';
  end if;

  if v_presentation_mode = 'seat_linked' then
    if p_circle_id is null or p_featured_profile_id is null then
      raise exception 'invalid_seat_link';
    end if;

    select p.id
      into v_featured_profile_id
    from public.circle_members cm
    join public.profiles p
      on p.id = cm.profile_id
     and p.deleted_at is null
    where cm.circle_id = p_circle_id
      and cm.profile_id = p_featured_profile_id
      and cm.status = 'active'
      and cm.is_visible is not false
    limit 1;

    if v_featured_profile_id is null then
      raise exception 'featured_profile_unavailable';
    end if;
  else
    v_featured_profile_id := null;
    v_seat_context := null;
  end if;

  v_slug_base := public.slugify(v_title);
  v_slug := v_slug_base;
  while exists (select 1 from public.gatherings g where g.slug = v_slug) loop
    v_slug := v_slug_base || '-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 6);
  end loop;

  insert into public.gatherings (
    circle_id,
    title,
    slug,
    description,
    poster_url,
    presentation_mode,
    featured_profile_id,
    seat_context,
    host_created_for_member,
    gathering_type,
    status,
    country_code,
    country_name,
    region,
    city,
    venue_name,
    venue_address,
    address_visibility,
    online_url,
    platform,
    starts_at,
    ends_at,
    timezone,
    is_official,
    is_partner_venue,
    safe_first_date_space,
    max_attendees,
    created_by_profile_id,
    created_by_user_id,
    approved_by_admin_id,
    approved_at,
    tags,
    safety_note
  )
  values (
    p_circle_id,
    v_title,
    v_slug,
    nullif(btrim(coalesce(p_description, '')), ''),
    nullif(btrim(coalesce(p_poster_url, '')), ''),
    v_presentation_mode,
    v_featured_profile_id,
    v_seat_context,
    case when v_presentation_mode = 'seat_linked' then true else false end,
    p_gathering_type,
    case when v_is_admin then 'approved' else 'pending_review' end,
    upper(nullif(btrim(coalesce(p_country_code, '')), '')),
    nullif(btrim(coalesce(p_country_name, '')), ''),
    nullif(btrim(coalesce(p_region, '')), ''),
    nullif(btrim(coalesce(p_city, '')), ''),
    nullif(btrim(coalesce(p_venue_name, '')), ''),
    nullif(btrim(coalesce(p_venue_address, '')), ''),
    case
      when v_is_admin then coalesce(nullif(p_address_visibility, ''), 'attendees_only')
      when p_gathering_type in ('physical', 'hybrid', 'partner_venue') then 'attendees_only'
      else coalesce(nullif(p_address_visibility, ''), 'hidden')
    end,
    nullif(btrim(coalesce(p_online_url, '')), ''),
    nullif(btrim(coalesce(p_platform, '')), ''),
    p_starts_at,
    p_ends_at,
    p_timezone,
    v_is_admin,
    v_is_admin and p_gathering_type = 'partner_venue',
    false,
    p_max_attendees,
    v_profile.id,
    v_user_id,
    case when v_is_admin then v_user_id else null end,
    case when v_is_admin then timezone('utc'::text, now()) else null end,
    coalesce(p_tags, '{}'),
    nullif(btrim(coalesce(p_safety_note, '')), '')
  )
  returning * into v_gathering;

  return v_gathering;
end;
$$;


ALTER FUNCTION "public"."rpc_create_gathering_request"("p_circle_id" "uuid", "p_title" "text", "p_description" "text", "p_gathering_type" "text", "p_country_code" "text", "p_country_name" "text", "p_region" "text", "p_city" "text", "p_venue_name" "text", "p_venue_address" "text", "p_address_visibility" "text", "p_online_url" "text", "p_platform" "text", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_timezone" "text", "p_max_attendees" integer, "p_tags" "text"[], "p_safety_note" "text", "p_poster_url" "text", "p_presentation_mode" "text", "p_featured_profile_id" "uuid", "p_seat_context" "text", "p_host_created_for_member" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_create_intent_request"("p_recipient_id" "uuid", "p_type" "text", "p_message" "text" DEFAULT NULL::"text", "p_suggested_time" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_suggested_place" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_actor_user_id uuid;
  v_actor_profile_id uuid;
  v_recipient_user_id uuid;
  v_existing_id uuid;
  v_incoming_id uuid;
  v_expires_at timestamptz;
  v_today_count integer;
BEGIN
  v_actor_user_id := auth.uid();
  IF v_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT p.id
    INTO v_actor_profile_id
  FROM public.profiles p
  WHERE p.user_id = v_actor_user_id
  LIMIT 1;

  IF v_actor_profile_id IS NULL THEN
    RAISE EXCEPTION 'Profile not found';
  END IF;

  IF p_recipient_id = v_actor_profile_id THEN
    RAISE EXCEPTION 'Cannot request yourself';
  END IF;

  SELECT p.user_id
    INTO v_recipient_user_id
  FROM public.profiles p
  WHERE p.id = p_recipient_id
  LIMIT 1;

  IF v_recipient_user_id IS NULL THEN
    RAISE EXCEPTION 'Recipient not found';
  END IF;

  -- Blocks are stored by user_id, not profile_id.
  IF EXISTS (
    SELECT 1
    FROM public.blocks b
    WHERE (b.blocker_id = v_recipient_user_id AND b.blocked_id = v_actor_user_id)
       OR (b.blocker_id = v_actor_user_id AND b.blocked_id = v_recipient_user_id)
  ) THEN
    RAISE EXCEPTION 'Blocked';
  END IF;

  -- If users are already matched (mutual-like match or accepted), don't allow new intents/requests between them.
  IF EXISTS (
    SELECT 1
    FROM public.matches m
    WHERE m.status IN ('PENDING', 'ACCEPTED')
      AND (
        (m.user1_id = v_actor_profile_id AND m.user2_id = p_recipient_id)
        OR (m.user1_id = p_recipient_id AND m.user2_id = v_actor_profile_id)
      )
  ) THEN
    RAISE EXCEPTION 'Already matched';
  END IF;

  -- Expire any stale pending requests between these profiles (either direction).
  UPDATE public.intent_requests
  SET status = 'expired'
  WHERE status = 'pending'
    AND expires_at < now()
    AND (
      (recipient_id = p_recipient_id AND actor_id = v_actor_profile_id)
      OR (recipient_id = v_actor_profile_id AND actor_id = p_recipient_id)
    );

  -- If there's already an outgoing pending request to this profile (any type), block creating another.
  SELECT id
    INTO v_existing_id
  FROM public.intent_requests
  WHERE recipient_id = p_recipient_id
    AND actor_id = v_actor_profile_id
    AND status = 'pending'
    AND expires_at > now()
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE EXCEPTION 'You''ve already placed a request. Please wait for their response.';
  END IF;

  -- If there's an incoming pending request from this profile, user should accept/pass it (no cross-requests).
  SELECT id
    INTO v_incoming_id
  FROM public.intent_requests
  WHERE recipient_id = v_actor_profile_id
    AND actor_id = p_recipient_id
    AND status = 'pending'
    AND expires_at > now()
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_incoming_id IS NOT NULL THEN
    RAISE EXCEPTION 'You already have a request from them. Open Intent to respond.';
  END IF;

  SELECT COUNT(*)
    INTO v_today_count
  FROM public.intent_requests
  WHERE actor_id = v_actor_profile_id
    AND type = p_type
    AND created_at >= date_trunc('day', now());

  IF p_type = 'connect' AND v_today_count >= 20 THEN
    RAISE EXCEPTION 'Connect quota exceeded';
  END IF;
  IF p_type = 'date_request' AND v_today_count >= 5 THEN
    RAISE EXCEPTION 'Date request quota exceeded';
  END IF;

  v_expires_at := CASE p_type
    WHEN 'date_request' THEN now() + interval '24 hours'
    WHEN 'like_with_note' THEN now() + interval '72 hours'
    ELSE now() + interval '48 hours'
  END;

  INSERT INTO public.intent_requests (
    recipient_id,
    actor_id,
    type,
    message,
    suggested_time,
    suggested_place,
    status,
    created_at,
    expires_at,
    metadata
  )
  VALUES (
    p_recipient_id,
    v_actor_profile_id,
    p_type,
    p_message,
    p_suggested_time,
    p_suggested_place,
    'pending',
    now(),
    v_expires_at,
    COALESCE(p_metadata, '{}'::jsonb)
  )
  RETURNING id INTO v_existing_id;

  RETURN v_existing_id;
END;
$$;


ALTER FUNCTION "public"."rpc_create_intent_request"("p_recipient_id" "uuid", "p_type" "text", "p_message" "text", "p_suggested_time" timestamp with time zone, "p_suggested_place" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_create_media_moment"("p_moment_id" "uuid", "p_type" "text", "p_media_url" "text", "p_caption" "text" DEFAULT NULL::"text", "p_visibility" "text" DEFAULT 'matches'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_type text := lower(coalesce(trim(p_type), ''));
  v_media_url text := nullif(btrim(coalesce(p_media_url, '')), '');
  v_visibility text := lower(coalesce(trim(p_visibility), 'matches'));
  v_caption text := nullif(btrim(coalesce(p_caption, '')), '');
  v_moment_id uuid := coalesce(p_moment_id, gen_random_uuid());
begin
  if v_user_id is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not public.can_post_moment(v_user_id) then
    raise exception 'moment_signal_required' using errcode = '42501';
  end if;

  if v_type not in ('video', 'photo') then
    raise exception 'invalid_moment_type';
  end if;

  if v_media_url is null then
    raise exception 'invalid_media_url';
  end if;

  if v_visibility not in ('public', 'matches', 'vibe_check_approved', 'private') then
    raise exception 'invalid_moment_visibility';
  end if;

  insert into public.moments (
    id,
    user_id,
    type,
    media_url,
    caption,
    visibility,
    metadata
  )
  values (
    v_moment_id,
    v_user_id,
    v_type,
    v_media_url,
    v_caption,
    v_visibility,
    coalesce(p_metadata, '{}'::jsonb)
  );

  return v_moment_id;
end;
$$;


ALTER FUNCTION "public"."rpc_create_media_moment"("p_moment_id" "uuid", "p_type" "text", "p_media_url" "text", "p_caption" "text", "p_visibility" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_create_moment"("p_type" "text", "p_text_body" "text" DEFAULT NULL::"text", "p_caption" "text" DEFAULT NULL::"text", "p_visibility" "text" DEFAULT 'matches'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_type text := lower(coalesce(trim(p_type), ''));
  v_visibility text := lower(coalesce(trim(p_visibility), 'matches'));
  v_text_body text := nullif(btrim(coalesce(p_text_body, '')), '');
  v_caption text := nullif(btrim(coalesce(p_caption, '')), '');
  v_moment_id uuid;
begin
  if v_user_id is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not public.can_post_moment(v_user_id) then
    raise exception 'moment_signal_required' using errcode = '42501';
  end if;

  if v_type not in ('video', 'photo', 'text') then
    raise exception 'invalid_moment_type';
  end if;

  if v_visibility not in ('public', 'matches', 'vibe_check_approved', 'private') then
    raise exception 'invalid_moment_visibility';
  end if;

  if v_type = 'text' and v_text_body is null then
    raise exception 'invalid_text_body';
  end if;

  insert into public.moments (
    user_id,
    type,
    text_body,
    caption,
    visibility,
    metadata
  )
  values (
    v_user_id,
    v_type,
    case when v_type = 'text' then v_text_body else null end,
    v_caption,
    v_visibility,
    coalesce(p_metadata, '{}'::jsonb)
  )
  returning id into v_moment_id;

  return v_moment_id;
end;
$$;


ALTER FUNCTION "public"."rpc_create_moment"("p_type" "text", "p_text_body" "text", "p_caption" "text", "p_visibility" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."moment_comments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "moment_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "body" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "is_deleted" boolean DEFAULT false NOT NULL,
    "parent_comment_id" "uuid",
    CONSTRAINT "moment_comments_parent_comment_self_check" CHECK ((("parent_comment_id" IS NULL) OR ("parent_comment_id" <> "id")))
);

ALTER TABLE ONLY "public"."moment_comments" REPLICA IDENTITY FULL;


ALTER TABLE "public"."moment_comments" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_create_moment_comment"("p_moment_id" "uuid", "p_body" "text") RETURNS "public"."moment_comments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  return public.rpc_create_moment_comment(
    p_moment_id,
    p_body,
    null
  );
end;
$$;


ALTER FUNCTION "public"."rpc_create_moment_comment"("p_moment_id" "uuid", "p_body" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_create_moment_comment"("p_moment_id" "uuid", "p_body" "text", "p_parent_comment_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."moment_comments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_body text := nullif(btrim(coalesce(p_body, '')), '');
  v_comment public.moment_comments;
  v_parent_comment public.moment_comments;
begin
  if v_user_id is null then
    raise exception 'not_authenticated' using errcode = '42501';
  end if;

  if p_moment_id is null or v_body is null then
    return null;
  end if;

  if not public.can_view_moment(p_moment_id) then
    return null;
  end if;

  if p_parent_comment_id is not null then
    select *
      into v_parent_comment
    from public.moment_comments
    where id = p_parent_comment_id
      and moment_id = p_moment_id
      and is_deleted = false;

    if not found then
      raise exception 'invalid_parent_comment' using errcode = 'P0001';
    end if;

    if v_parent_comment.parent_comment_id is not null then
      raise exception 'nested_replies_not_allowed' using errcode = 'P0001';
    end if;
  end if;

  insert into public.moment_comments (
    moment_id,
    user_id,
    body,
    parent_comment_id
  )
  values (
    p_moment_id,
    v_user_id,
    v_body,
    p_parent_comment_id
  )
  returning * into v_comment;

  return v_comment;
end;
$$;


ALTER FUNCTION "public"."rpc_create_moment_comment"("p_moment_id" "uuid", "p_body" "text", "p_parent_comment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_create_profile_boost"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  return public.rpc_create_profile_boost_v2(
    'manual',
    'for_you',
    'profile',
    '{}'::jsonb
  );
end;
$$;


ALTER FUNCTION "public"."rpc_create_profile_boost"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_create_profile_boost_v2"("p_boost_type" "text" DEFAULT 'manual'::"text", "p_audience_mode" "text" DEFAULT 'for_you'::"text", "p_focus_mode" "text" DEFAULT 'profile'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_plan public.subscription_type := 'FREE';
  viewer_profile_id uuid;
  active_boost_ends_at timestamptz;
  boost_type_norm text := coalesce(nullif(lower(btrim(coalesce(p_boost_type, ''))), ''), 'manual');
  audience_mode_norm text := coalesce(nullif(lower(btrim(coalesce(p_audience_mode, ''))), ''), 'for_you');
  focus_mode_norm text := coalesce(nullif(lower(btrim(coalesce(p_focus_mode, ''))), ''), 'profile');
  include_sandbox_preview boolean := false;
  cleaned_metadata jsonb := coalesce(p_metadata, '{}'::jsonb);
  created_boost record;
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  begin
    include_sandbox_preview := coalesce((coalesce(p_metadata, '{}'::jsonb) ->> 'include_sandbox_preview')::boolean, false);
  exception
    when others then
      include_sandbox_preview := false;
  end;

  include_sandbox_preview := include_sandbox_preview and public.is_admin_user(auth.uid());
  cleaned_metadata := cleaned_metadata - 'include_sandbox_preview';

  resolved_plan := public.get_subscription_badge_plan(
    auth.uid(),
    include_sandbox_preview
  );
  if resolved_plan not in ('SILVER', 'GOLD') then
    raise exception 'premium subscription required';
  end if;

  if boost_type_norm not in ('manual', 'smart') then
    raise exception 'invalid boost type';
  end if;

  if audience_mode_norm not in ('for_you', 'nearby', 'active_now', 'intent_match', 'second_look') then
    raise exception 'invalid audience mode';
  end if;

  if focus_mode_norm not in ('profile', 'intro', 'intent') then
    raise exception 'invalid focus mode';
  end if;

  if resolved_plan = 'SILVER' then
    boost_type_norm := 'manual';
    if audience_mode_norm not in ('for_you', 'nearby') then
      audience_mode_norm := 'for_you';
    end if;
    focus_mode_norm := 'profile';
  end if;

  select p.id
    into viewer_profile_id
  from public.profiles p
  where p.user_id = auth.uid()
    and p.deleted_at is null
  limit 1;

  if viewer_profile_id is null then
    raise exception 'profile required';
  end if;

  select max(pb.ends_at)
    into active_boost_ends_at
  from public.profile_boosts pb
  where pb.user_id = viewer_profile_id
    and pb.starts_at <= timezone('utc'::text, now())
    and pb.ends_at > timezone('utc'::text, now());

  if active_boost_ends_at is not null then
    raise exception 'boost already active';
  end if;

  insert into public.profile_boosts (
    user_id,
    starts_at,
    ends_at,
    boost_type,
    audience_mode,
    focus_mode,
    status,
    metadata
  )
  values (
    viewer_profile_id,
    timezone('utc'::text, now()),
    timezone('utc'::text, now()) + interval '30 minutes',
    boost_type_norm,
    audience_mode_norm,
    focus_mode_norm,
    'active',
    jsonb_strip_nulls(cleaned_metadata || jsonb_build_object(
      'creator_plan', resolved_plan,
      'source', 'app_v2',
      'sandbox_preview', include_sandbox_preview
    ))
  )
  returning
    id,
    starts_at,
    ends_at,
    boost_type,
    audience_mode,
    focus_mode,
    status
    into created_boost;

  return jsonb_build_object(
    'plan', resolved_plan,
    'profile_id', viewer_profile_id,
    'id', created_boost.id,
    'starts_at', created_boost.starts_at,
    'ends_at', created_boost.ends_at,
    'boost_type', created_boost.boost_type,
    'audience_mode', created_boost.audience_mode,
    'focus_mode', created_boost.focus_mode,
    'status', created_boost.status
  );
end;
$$;


ALTER FUNCTION "public"."rpc_create_profile_boost_v2"("p_boost_type" "text", "p_audience_mode" "text", "p_focus_mode" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_create_warm_introduction"("p_circle_id" "uuid", "p_profile_a_id" "uuid", "p_profile_b_id" "uuid", "p_reason" "text", "p_shared_context" "text"[] DEFAULT '{}'::"text"[], "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "public"."warm_introductions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_initiator_profile_id uuid;
  v_intro public.warm_introductions;
begin
  if v_user_id is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if p_profile_a_id = p_profile_b_id then
    raise exception 'profiles_must_differ';
  end if;

  select p.id
    into v_initiator_profile_id
  from public.profiles p
  where p.user_id = v_user_id
    and p.deleted_at is null
  limit 1;

  if not public.is_admin_user(v_user_id)
     and (p_circle_id is null or not public.is_circle_host(p_circle_id, v_initiator_profile_id)) then
    raise exception 'host_required' using errcode = '42501';
  end if;

  insert into public.warm_introductions (
    circle_id,
    initiator_profile_id,
    initiator_role,
    profile_a_id,
    profile_b_id,
    reason,
    shared_context,
    expires_at
  )
  values (
    p_circle_id,
    v_initiator_profile_id,
    case when public.is_admin_user(v_user_id) then 'admin' else 'host' end,
    p_profile_a_id,
    p_profile_b_id,
    nullif(btrim(coalesce(p_reason, '')), ''),
    coalesce(p_shared_context, '{}'),
    coalesce(p_expires_at, timezone('utc'::text, now()) + interval '72 hours')
  )
  returning * into v_intro;

  return v_intro;
end;
$$;


ALTER FUNCTION "public"."rpc_create_warm_introduction"("p_circle_id" "uuid", "p_profile_a_id" "uuid", "p_profile_b_id" "uuid", "p_reason" "text", "p_shared_context" "text"[], "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_debug_circle_member_moments"("p_circle_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not public.can_manage_circle_pulse(p_circle_id, auth.uid())
    and not public.is_circle_owner(p_circle_id, auth.uid()) then
    raise exception 'host_required' using errcode = '42501';
  end if;

  with eligible_profiles as (
    select
      member.profile_id,
      coalesce(nullif(btrim(profile.full_name), ''), 'Circle member') as profile_name,
      member.role,
      member.status,
      member.is_visible,
      member.user_id as membership_user_id,
      profile.user_id as profile_user_id
    from public.circle_members member
    left join public.profiles profile on profile.id = member.profile_id
    where member.circle_id = p_circle_id

    union all

    select
      owner.id,
      coalesce(nullif(btrim(owner.full_name), ''), 'Circle creator'),
      'creator'::text,
      'active'::text,
      true,
      circle_row.created_by_user_id,
      owner.user_id
    from public.circles circle_row
    left join public.profiles owner on owner.id = circle_row.created_by_profile_id
    where circle_row.id = p_circle_id
      and not exists (
        select 1
        from public.circle_members member
        where member.circle_id = circle_row.id
          and member.profile_id = owner.id
      )
  )
  select jsonb_build_object(
    'circle_id', p_circle_id,
    'viewer_user_id', auth.uid(),
    'profiles', coalesce(jsonb_agg(
      jsonb_build_object(
        'profile_id', eligible.profile_id,
        'profile_name', eligible.profile_name,
        'role', eligible.role,
        'membership_status', eligible.status,
        'is_visible', eligible.is_visible,
        'membership_user_id', eligible.membership_user_id,
        'profile_user_id', eligible.profile_user_id,
        'identity_mismatch', eligible.membership_user_id is distinct from eligible.profile_user_id,
        'active_moment_count', (
          select count(*)::integer
          from public.moments moment
          where (
              moment.user_id = eligible.membership_user_id
              or moment.user_id = eligible.profile_user_id
            )
            and moment.is_deleted = false
            and moment.expires_at > timezone('utc'::text, now())
        ),
        'circle_visible_moment_count', (
          select count(*)::integer
          from public.moments moment
          where (
              moment.user_id = eligible.membership_user_id
              or moment.user_id = eligible.profile_user_id
            )
            and moment.is_deleted = false
            and moment.expires_at > timezone('utc'::text, now())
            and moment.visibility <> 'private'
            and (
              moment.type = 'text'
              or nullif(btrim(coalesce(moment.media_url, '')), '') is not null
            )
        )
      )
      order by eligible.profile_name, eligible.profile_id
    ), '[]'::jsonb)
  )
    into v_result
  from eligible_profiles eligible;

  return coalesce(v_result, jsonb_build_object(
    'circle_id', p_circle_id,
    'viewer_user_id', auth.uid(),
    'profiles', '[]'::jsonb
  ));
end;
$$;


ALTER FUNCTION "public"."rpc_debug_circle_member_moments"("p_circle_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_debug_closure_to_clarity_pool"("p_intent_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_viewer_profile public.profiles%rowtype;
  v_target_profile public.profiles%rowtype;
  v_request public.intent_requests%rowtype;
  v_target_profile_id uuid;
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  select profile.*
    into v_viewer_profile
  from public.profiles profile
  where profile.user_id = auth.uid()
    and profile.deleted_at is null
  limit 1;

  if v_viewer_profile.id is null then
    raise exception 'profile required';
  end if;

  select request_row.*
    into v_request
  from public.intent_requests request_row
  where request_row.id = p_intent_request_id
    and (
      request_row.actor_id = v_viewer_profile.id
      or request_row.recipient_id = v_viewer_profile.id
    )
  limit 1;

  if v_request.id is null then
    raise exception 'intent request not found';
  end if;

  v_target_profile_id := case
    when v_request.actor_id = v_viewer_profile.id then v_request.recipient_id
    else v_request.actor_id
  end;

  select profile.*
    into v_target_profile
  from public.profiles profile
  where profile.id = v_target_profile_id
    and profile.deleted_at is null
  limit 1;

  if v_target_profile.id is null then
    raise exception 'target profile not found';
  end if;

  with candidates as (
    select
      profile.id,
      profile.user_id,
      profile.gender,
      profile.age,
      profile.profile_completed,
      profile.discoverable_in_vibes,
      profile.deleted_at,
      profile.full_name,
      exists (
        select 1
        from public.intent_requests request_row
        where (
          (request_row.actor_id = v_viewer_profile.id and request_row.recipient_id = profile.id)
          or (request_row.actor_id = profile.id and request_row.recipient_id = v_viewer_profile.id)
        )
          and (
            request_row.status in ('pending', 'accepted', 'matched')
            or (
              request_row.status = 'passed'
              and request_row.created_at > now() - interval '21 days'
            )
          )
      ) as blocked_by_existing_intent,
      exists (
        select 1
        from public.matches match_row
        where (match_row.user1_id = v_viewer_profile.id and match_row.user2_id = profile.id)
           or (match_row.user1_id = profile.id and match_row.user2_id = v_viewer_profile.id)
      ) as blocked_by_match,
      exists (
        select 1
        from public.blocks block_row
        where (block_row.blocker_id = v_viewer_profile.user_id and block_row.blocked_id = profile.user_id)
           or (block_row.blocker_id = profile.user_id and block_row.blocked_id = v_viewer_profile.user_id)
      ) as blocked_by_block,
      coalesce((
        select swipe_row.action::text
        from public.swipes swipe_row
        where swipe_row.swiper_id = v_viewer_profile.id
          and swipe_row.target_id = profile.id
        order by swipe_row.created_at desc, swipe_row.id desc
        limit 1
      ), '') = 'PASS' as blocked_by_swipe_pass,
      (
        v_viewer_profile.gender is null
        or v_viewer_profile.gender not in ('MALE', 'FEMALE')
        or profile.gender is null
        or profile.gender not in ('MALE', 'FEMALE')
        or (v_viewer_profile.gender = 'MALE' and profile.gender = 'FEMALE')
        or (v_viewer_profile.gender = 'FEMALE' and profile.gender = 'MALE')
      ) as viewer_gender_ok,
      (
        v_viewer_profile.min_age_interest is null
        or v_viewer_profile.max_age_interest is null
        or profile.age between v_viewer_profile.min_age_interest and v_viewer_profile.max_age_interest
      ) as viewer_age_ok,
      (
        v_target_profile.min_age_interest is null
        or v_target_profile.max_age_interest is null
        or profile.age between v_target_profile.min_age_interest and v_target_profile.max_age_interest
      ) as target_age_ok
    from public.profiles profile
    where profile.id <> v_viewer_profile.id
      and profile.id <> v_target_profile.id
      and profile.user_id is not null
      and profile.user_id <> v_viewer_profile.user_id
  ),
  base_pool as (
    select *
    from candidates
    where deleted_at is null
      and profile_completed is true
      and coalesce(discoverable_in_vibes, true) = true
      and full_name is not null
      and age is not null
  ),
  annotated as (
    select
      base_candidate.*,
      not (
        base_candidate.blocked_by_existing_intent
        or base_candidate.blocked_by_match
        or base_candidate.blocked_by_block
        or base_candidate.blocked_by_swipe_pass
      ) as passes_safety,
      base_candidate.viewer_gender_ok as passes_gender,
      (base_candidate.viewer_age_ok and base_candidate.target_age_ok) as passes_age
    from base_pool base_candidate
  ),
  counted as (
    select
      count(*)::integer as discoverable_pool_count,
      count(*) filter (where blocked_by_existing_intent)::integer as blocked_by_existing_intent_count,
      count(*) filter (where blocked_by_match)::integer as blocked_by_match_count,
      count(*) filter (where blocked_by_block)::integer as blocked_by_block_count,
      count(*) filter (where blocked_by_swipe_pass)::integer as blocked_by_swipe_pass_count,
      count(*) filter (where passes_safety)::integer as post_safety_pool_count,
      count(*) filter (where not viewer_gender_ok)::integer as blocked_by_viewer_gender_count,
      count(*) filter (where passes_safety and not passes_gender)::integer as blocked_by_gender_after_safety_count,
      count(*) filter (where passes_safety and passes_gender)::integer as post_gender_pool_count,
      count(*) filter (where passes_safety and passes_gender and not viewer_age_ok)::integer as blocked_by_viewer_age_count,
      count(*) filter (where passes_safety and passes_gender and not target_age_ok)::integer as blocked_by_target_age_count,
      count(*) filter (where passes_safety and passes_gender and passes_age)::integer as final_eligible_count,
      count(*) filter (where passes_safety and passes_gender and passes_age and viewer_age_ok and target_age_ok)::integer as tier_0_count,
      count(*) filter (where passes_safety and passes_gender and viewer_age_ok and not target_age_ok)::integer as tier_1_count,
      count(*) filter (where passes_safety and passes_gender and target_age_ok and not viewer_age_ok)::integer as tier_2_count,
      count(*) filter (where passes_safety and passes_gender and (not viewer_age_ok or not target_age_ok))::integer as tier_3_count
    from annotated
  ),
  samples as (
    select jsonb_build_object(
      'final_candidate_ids', coalesce(
        (
          select jsonb_agg(sample.id order by sample.id)
          from (
            select annotated.id
            from annotated
            where annotated.passes_safety
              and annotated.passes_gender
              and annotated.passes_age
            order by annotated.id
            limit 8
          ) sample
        ),
        '[]'::jsonb
      )
    ) as value
  )
  select jsonb_build_object(
    'request_id', p_intent_request_id,
    'request_status', v_request.status,
    'viewer_profile_id', v_viewer_profile.id,
    'viewer_gender', v_viewer_profile.gender,
    'target_profile_id', v_target_profile.id,
    'target_gender', v_target_profile.gender,
    'counts', to_jsonb(counted),
    'samples', samples.value
  )
    into v_result
  from counted
  cross join samples;

  return coalesce(v_result, '{}'::jsonb);
end;
$$;


ALTER FUNCTION "public"."rpc_debug_closure_to_clarity_pool"("p_intent_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_debug_message_delivery_receipt"("p_message_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_result jsonb;
begin
  if v_user_id is null then
    raise exception 'authentication required';
  end if;

  select jsonb_build_object(
    'id', m.id,
    'sender_id', m.sender_id,
    'receiver_id', m.receiver_id,
    'is_read', m.is_read,
    'delivered_at', m.delivered_at,
    'created_at', m.created_at,
    'message_type', m.message_type
  )
    into v_result
  from public.messages m
  where m.id = p_message_id
    and (m.sender_id = v_user_id or m.receiver_id = v_user_id)
  limit 1;

  return coalesce(v_result, '{}'::jsonb);
end;
$$;


ALTER FUNCTION "public"."rpc_debug_message_delivery_receipt"("p_message_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_debug_vibes_recommendation_pool"("p_profile_id" "uuid", "p_active_window_minutes" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_profile public.profiles%rowtype;
  v_cutoff timestamptz := now() - (greatest(5, least(coalesce(p_active_window_minutes, 30), 240)) || ' minutes')::interval;
  v_result jsonb;
begin
  if v_user_id is null then
    raise exception 'authentication required';
  end if;

  select *
    into v_profile
  from public.profiles p
  where p.id = p_profile_id
    and p.user_id = v_user_id
  limit 1;

  if v_profile.id is null then
    raise exception 'profile not found';
  end if;

  with candidates as (
    select
      p.id,
      p.user_id,
      p.profile_completed,
      p.discoverable_in_vibes,
      p.matchmaking_mode,
      p.deleted_at,
      p.gender,
      p.age,
      p.last_active,
      p.online,
      exists (
        select 1
        from public.blocks b
        where (b.blocker_id = v_user_id and b.blocked_id = p.user_id)
           or (b.blocker_id = p.user_id and b.blocked_id = v_user_id)
      ) as blocked,
      exists (
        select 1
        from public.matches mt
        where mt.status in ('PENDING', 'ACCEPTED')
          and (
            (mt.user1_id = p_profile_id and mt.user2_id = p.id)
            or (mt.user1_id = p.id and mt.user2_id = p_profile_id)
          )
      ) as matched_or_pending,
      exists (
        select 1
        from public.intent_requests ir
        where ir.status = 'pending'
          and ir.expires_at > now()
          and (
            (ir.actor_id = p_profile_id and ir.recipient_id = p.id)
            or (ir.actor_id = p.id and ir.recipient_id = p_profile_id)
          )
      ) as pending_intent,
      exists (
        select 1
        from public.profile_signal_gestures psg
        where psg.status in ('sent', 'seen')
          and psg.expires_at > now()
          and (
            (psg.sender_profile_id = p_profile_id and psg.receiver_profile_id = p.id)
            or (psg.sender_profile_id = p.id and psg.receiver_profile_id = p_profile_id)
          )
      ) as active_signal,
      exists (
        select 1
        from public.swipes s
        where s.swiper_id = p_profile_id
          and s.target_id = p.id
          and s.action::text in ('LIKE', 'SUPERLIKE')
      ) as already_liked,
      exists (
        select 1
        from public.swipes s
        where s.swiper_id = p_profile_id
          and s.target_id = p.id
          and s.action::text = 'PASS'
          and s.created_at >= now() - interval '21 days'
      ) as recent_pass,
      (
        v_profile.gender is null
        or v_profile.gender not in ('MALE', 'FEMALE')
        or p.gender is null
        or (v_profile.gender = 'MALE' and p.gender = 'FEMALE')
        or (v_profile.gender = 'FEMALE' and p.gender = 'MALE')
      ) as gender_ok,
      (v_profile.min_age_interest is null or p.age >= v_profile.min_age_interest) as min_age_ok,
      (v_profile.max_age_interest is null or p.age <= v_profile.max_age_interest) as max_age_ok,
      (p.last_active is not null and p.last_active >= v_cutoff) as active_window_ok
    from public.profiles p
    where p.id <> p_profile_id
      and p.user_id is not null
      and p.user_id <> v_user_id
  ),
  counted as (
    select
      count(*) as total_profiles,
      count(*) filter (where profile_completed is true) as completed,
      count(*) filter (where deleted_at is null and profile_completed is true and coalesce(discoverable_in_vibes, true) = true and coalesce(matchmaking_mode, false) = false) as base_visible,
      count(*) filter (where blocked) as blocked,
      count(*) filter (where matched_or_pending) as matched_or_pending,
      count(*) filter (where pending_intent) as pending_intent,
      count(*) filter (where active_signal) as active_signal,
      count(*) filter (where already_liked) as already_liked,
      count(*) filter (where recent_pass) as recent_pass_21d,
      count(*) filter (where not gender_ok) as gender_filtered,
      count(*) filter (where not min_age_ok or not max_age_ok) as age_filtered,
      count(*) filter (where active_window_ok) as active_window_candidates,
      count(*) filter (
        where deleted_at is null
          and profile_completed is true
          and coalesce(discoverable_in_vibes, true) = true
          and coalesce(matchmaking_mode, false) = false
          and not blocked
          and not matched_or_pending
          and not pending_intent
          and not active_signal
          and not already_liked
          and not recent_pass
          and gender_ok
          and min_age_ok
          and max_age_ok
      ) as for_you_eligible,
      count(*) filter (
        where deleted_at is null
          and profile_completed is true
          and coalesce(discoverable_in_vibes, true) = true
          and coalesce(matchmaking_mode, false) = false
          and not blocked
          and not matched_or_pending
          and not pending_intent
          and not active_signal
          and not already_liked
          and not recent_pass
          and gender_ok
          and min_age_ok
          and max_age_ok
          and active_window_ok
      ) as active_now_eligible
    from candidates
  )
  select jsonb_build_object(
    'profile_id', p_profile_id,
    'active_window_minutes', greatest(5, least(coalesce(p_active_window_minutes, 30), 240)),
    'counts', to_jsonb(counted)
  )
  into v_result
  from counted;

  return coalesce(v_result, '{}'::jsonb);
end;
$$;


ALTER FUNCTION "public"."rpc_debug_vibes_recommendation_pool"("p_profile_id" "uuid", "p_active_window_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_decide_intent_request"("p_request_id" "uuid", "p_decision" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid;
  v_profile_id uuid;
  v_id uuid;
  v_actor_profile_id uuid;
  v_recipient_profile_id uuid;
  v_match_id uuid;
  v_user1_profile_id uuid;
  v_user2_profile_id uuid;
begin
  if p_decision not in ('accept','pass') then
    raise exception 'Invalid decision';
  end if;

  v_user_id := auth.uid();
  if v_user_id is null then
    raise exception 'Not authenticated';
  end if;

  select p.id
    into v_profile_id
  from public.profiles p
  where p.user_id = v_user_id
  limit 1;

  if v_profile_id is null then
    raise exception 'Profile not found';
  end if;

  update public.intent_requests
  set status = case when p_decision = 'accept' then 'accepted' else 'passed' end
  where id = p_request_id
    and recipient_id = v_profile_id
    and status = 'pending'
    and expires_at > now()
  returning id, actor_id, recipient_id
    into v_id, v_actor_profile_id, v_recipient_profile_id;

  if v_id is null then
    raise exception 'Request not found or expired';
  end if;

  if p_decision = 'accept' then
    if v_actor_profile_id::text < v_recipient_profile_id::text then
      v_user1_profile_id := v_actor_profile_id;
      v_user2_profile_id := v_recipient_profile_id;
    else
      v_user1_profile_id := v_recipient_profile_id;
      v_user2_profile_id := v_actor_profile_id;
    end if;

    select m.id
      into v_match_id
    from public.matches m
    where (m.user1_id = v_actor_profile_id and m.user2_id = v_recipient_profile_id)
       or (m.user1_id = v_recipient_profile_id and m.user2_id = v_actor_profile_id)
    limit 1
    for update;

    if v_match_id is null then
      begin
        insert into public.matches (user1_id, user2_id, status, created_at, updated_at)
        values (v_user1_profile_id, v_user2_profile_id, 'ACCEPTED'::match_status, now(), now())
        returning id into v_match_id;
      exception when unique_violation then
        select m.id
          into v_match_id
        from public.matches m
        where (m.user1_id = v_actor_profile_id and m.user2_id = v_recipient_profile_id)
           or (m.user1_id = v_recipient_profile_id and m.user2_id = v_actor_profile_id)
        limit 1
        for update;
      end;
    end if;

    if v_match_id is not null then
      update public.matches
      set status = 'ACCEPTED'::match_status,
          updated_at = now()
      where id = v_match_id
        and status::text <> 'ACCEPTED';
    end if;

    update public.intent_requests
    set status = 'passed'
    where status = 'pending'
      and expires_at > now()
      and id <> p_request_id
      and (
        (actor_id = v_actor_profile_id and recipient_id = v_recipient_profile_id)
        or (actor_id = v_recipient_profile_id and recipient_id = v_actor_profile_id)
      );
  end if;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."rpc_decide_intent_request"("p_request_id" "uuid", "p_decision" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_decline_date_plan"("p_plan_id" "uuid") RETURNS TABLE("plan_id" "uuid", "status" "text", "concierge_requested" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_plan public.date_plans%rowtype;
  v_actor_profile public.profiles%rowtype;
  v_creator_name text;
  v_recipient_name text;
begin
  select *
  into v_actor_profile
  from public.profiles
  where user_id = auth.uid()
  limit 1;

  if v_actor_profile.id is null then
    raise exception 'actor_profile_not_found';
  end if;

  select *
  into v_plan
  from public.date_plans
  where id = p_plan_id
  limit 1;

  if v_plan.id is null then
    raise exception 'date_plan_not_found';
  end if;

  if v_plan.recipient_user_id <> auth.uid() then
    raise exception 'Only the other person can respond to this date suggestion.';
  end if;

  if v_plan.status = 'declined' then
    return query
    select v_plan.id, v_plan.status, v_plan.concierge_requested;
    return;
  end if;

  if v_plan.status <> 'pending' then
    raise exception 'This date suggestion can no longer be changed.';
  end if;

  update public.date_plans
  set status = 'declined',
      declined_at = now(),
      declined_by_profile_id = v_actor_profile.id,
      accepted_at = null,
      accepted_by_profile_id = null,
      updated_at = now()
  where id = p_plan_id;

  select full_name into v_creator_name from public.profiles where id = v_plan.creator_profile_id;
  select full_name into v_recipient_name from public.profiles where id = v_plan.recipient_profile_id;

  insert into public.system_messages (
    user_id,
    peer_user_id,
    event_type,
    text,
    metadata
  )
  values (
    v_plan.creator_user_id,
    v_plan.recipient_user_id,
    'date_plan_declined',
    coalesce(v_recipient_name, 'They') || ' passed on your date suggestion for now.',
    jsonb_build_object('date_plan_id', p_plan_id, 'role', 'requester')
  );

  insert into public.system_messages (
    user_id,
    peer_user_id,
    event_type,
    text,
    metadata
  )
  values (
    v_plan.recipient_user_id,
    v_plan.creator_user_id,
    'date_plan_declined',
    'You passed on ' || coalesce(v_creator_name, 'their') || '''s date suggestion.',
    jsonb_build_object('date_plan_id', p_plan_id, 'role', 'accepter')
  );

  return query
  select p_plan_id, 'declined', false;
end;
$$;


ALTER FUNCTION "public"."rpc_decline_date_plan"("p_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_delete_circle_prompt"("p_prompt_id" "uuid", "p_circle_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_profile public.profiles%rowtype;
begin
  if v_user_id is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  select *
    into v_profile
  from public.profiles p
  where p.user_id = v_user_id
    and p.deleted_at is null
  limit 1;

  if v_profile.id is null then
    raise exception 'profile_not_found';
  end if;

  if not (
    public.is_admin_user(v_user_id)
    or public.is_circle_owner(p_circle_id, v_user_id)
    or public.is_circle_host(p_circle_id, v_profile.id)
  ) then
    raise exception 'host_required' using errcode = '42501';
  end if;

  update public.circle_prompts
  set status = 'archived',
      expires_at = coalesce(expires_at, timezone('utc'::text, now())),
      updated_at = timezone('utc'::text, now())
  where id = p_prompt_id
    and circle_id = p_circle_id
    and status <> 'archived';

  update public.circle_pulse_items
  set status = 'archived'
  where circle_id = p_circle_id
    and prompt_id = p_prompt_id
    and status <> 'archived';

  return found;
end;
$$;


ALTER FUNCTION "public"."rpc_delete_circle_prompt"("p_prompt_id" "uuid", "p_circle_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_delete_circle_pulse_comment"("p_comment_id" "uuid", "p_profile_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_comment public.circle_pulse_comments%rowtype;
  v_status text;
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_profile_id
      and p.user_id = auth.uid()
      and p.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  select *
    into v_comment
  from public.circle_pulse_comments cpc
  where cpc.id = p_comment_id
    and cpc.status = 'active'
  for update;

  if v_comment.id is null then
    raise exception 'comment_not_found';
  end if;

  if v_comment.user_id <> auth.uid()
    and not public.can_manage_circle_pulse(v_comment.circle_id, auth.uid()) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  v_status := case when v_comment.user_id = auth.uid() then 'deleted' else 'removed' end;

  update public.circle_pulse_comments
  set status = v_status,
      deleted_at = timezone('utc'::text, now())
  where id = p_comment_id;

  return found;
end;
$$;


ALTER FUNCTION "public"."rpc_delete_circle_pulse_comment"("p_comment_id" "uuid", "p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_delete_circle_pulse_item"("p_item_id" "uuid", "p_actor_profile_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_circle_id uuid;
  v_status text;
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_actor_profile_id
      and p.user_id = auth.uid()
      and p.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  select cpi.circle_id, cpi.status
    into v_circle_id, v_status
  from public.circle_pulse_items cpi
  where cpi.id = p_item_id
  for update;

  if v_circle_id is null then
    raise exception 'pulse_item_not_found';
  end if;

  if not public.can_manage_circle_pulse(v_circle_id, auth.uid()) then
    raise exception 'host_required' using errcode = '42501';
  end if;

  if v_status = 'active' then
    raise exception 'archive_active_pulse_item_first';
  end if;

  delete from public.circle_pulse_items
  where id = p_item_id;

  return found;
end;
$$;


ALTER FUNCTION "public"."rpc_delete_circle_pulse_item"("p_item_id" "uuid", "p_actor_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_delete_circle_relationship_gist"("p_gist_id" "uuid", "p_circle_id" "uuid", "p_actor_profile_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles actor
    where actor.id = p_actor_profile_id
      and actor.user_id = auth.uid()
      and actor.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  if not public.can_manage_circle_pulse(p_circle_id, auth.uid()) then
    raise exception 'host_required' using errcode = '42501';
  end if;

  update public.relationship_gists
  set status = 'archived',
      updated_at = timezone('utc'::text, now())
  where id = p_gist_id
    and circle_id = p_circle_id
    and status <> 'archived';

  return found;
end;
$$;


ALTER FUNCTION "public"."rpc_delete_circle_relationship_gist"("p_gist_id" "uuid", "p_circle_id" "uuid", "p_actor_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_delete_gathering_request"("p_gathering_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_profile public.profiles%rowtype;
  v_circle_id uuid;
begin
  if v_user_id is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  select *
    into v_profile
  from public.profiles p
  where p.user_id = v_user_id
    and p.deleted_at is null
  limit 1;

  if v_profile.id is null then
    raise exception 'profile_not_found';
  end if;

  select g.circle_id
    into v_circle_id
  from public.gatherings g
  where g.id = p_gathering_id
    and (
      public.is_admin_user(v_user_id)
      or g.created_by_user_id = v_user_id
      or g.created_by_profile_id = v_profile.id
      or (g.circle_id is not null and public.can_manage_circle_pulse(g.circle_id, v_user_id))
    )
  limit 1;

  if v_circle_id is null then
    raise exception 'gathering_not_found';
  end if;

  update public.gatherings
  set status = 'archived',
      cancelled_at = coalesce(cancelled_at, timezone('utc'::text, now())),
      updated_at = timezone('utc'::text, now())
  where id = p_gathering_id
    and status <> 'archived';

  update public.circle_pulse_items
  set status = 'archived'
  where gathering_id = p_gathering_id
    and status <> 'archived';

  return found;
end;
$$;


ALTER FUNCTION "public"."rpc_delete_gathering_request"("p_gathering_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_delete_moment_comment"("p_comment_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_comment public.moment_comments;
begin
  if v_user_id is null then
    raise exception 'not_authenticated' using errcode = '42501';
  end if;

  if p_comment_id is null then
    return false;
  end if;

  update public.moment_comments
  set is_deleted = true
  where id = p_comment_id
    and user_id = v_user_id
    and is_deleted = false
  returning * into v_comment;

  if not found then
    return false;
  end if;

  update public.moment_comments
  set is_deleted = true
  where parent_comment_id = v_comment.id
    and is_deleted = false;

  return true;
end;
$$;


ALTER FUNCTION "public"."rpc_delete_moment_comment"("p_comment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_delete_owned_circle"("p_circle_id" "uuid", "p_actor_profile_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_circle public.circles%rowtype;
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles actor
    where actor.id = p_actor_profile_id
      and actor.user_id = auth.uid()
      and actor.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  select *
    into v_circle
  from public.circles c
  where c.id = p_circle_id
  for update;

  if v_circle.id is null then
    raise exception 'circle_not_found';
  end if;

  if v_circle.created_by_profile_id <> p_actor_profile_id then
    raise exception 'circle_creator_required' using errcode = '42501';
  end if;

  if coalesce(v_circle.is_official, false) then
    raise exception 'official_circle_requires_admin' using errcode = '42501';
  end if;

  if v_circle.status = 'approved' and v_circle.archived_at is null then
    raise exception 'archive_live_circle_first';
  end if;

  delete from public.circles
  where id = p_circle_id;

  return found;
end;
$$;


ALTER FUNCTION "public"."rpc_delete_owned_circle"("p_circle_id" "uuid", "p_actor_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_end_circle_love_seat"("p_love_seat_id" "uuid", "p_actor_profile_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_love_seat public.circle_love_seats%rowtype;
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_actor_profile_id
      and p.user_id = auth.uid()
      and p.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  select *
    into v_love_seat
  from public.circle_love_seats cls
  where cls.id = p_love_seat_id
    and cls.status = 'active'
  for update;

  if v_love_seat.id is null then
    raise exception 'active_love_seat_not_found';
  end if;

  if v_love_seat.featured_profile_id <> p_actor_profile_id
    and not public.can_manage_circle_pulse(v_love_seat.circle_id, auth.uid()) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  update public.circle_love_seats
  set status = 'ended',
      ends_at = timezone('utc'::text, now())
  where id = p_love_seat_id;

  update public.circle_pulse_items
  set status = 'archived',
      expires_at = timezone('utc'::text, now())
  where love_seat_id = p_love_seat_id
    and status = 'active';

  return true;
end;
$$;


ALTER FUNCTION "public"."rpc_end_circle_love_seat"("p_love_seat_id" "uuid", "p_actor_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_account_recovery_options"("p_recovery_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_catalog'
    AS $$
declare
  v_session public.account_recovery_sessions%rowtype;
  v_owner_user_id uuid;
  v_owner_profile_id uuid;
  v_owner_name text;
  v_owner_email text;
  v_email_hint text;
  v_email_local text;
  v_email_domain text;
  v_methods text[] := array[]::text[];
  v_primary_method text;
  v_merge public.merged_accounts%rowtype;
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  if p_recovery_token is null then
    raise exception 'recovery token is required';
  end if;

  select *
    into v_session
  from public.account_recovery_sessions ars
  where ars.recovery_token = p_recovery_token
    and ars.requester_user_id = auth.uid()
    and ars.expires_at > timezone('utc'::text, now())
  order by ars.created_at desc
  limit 1;

  if v_session.id is null then
    return jsonb_build_object(
      'found', false,
      'message', 'Recovery session expired or was not found.',
      'sign_in_methods', '[]'::jsonb
    );
  end if;

  v_owner_user_id := v_session.owner_user_id;
  v_owner_profile_id := v_session.owner_profile_id;

  select nullif(btrim(coalesce(p.full_name, '')), '')
    into v_owner_name
  from public.profiles p
  where p.id = v_owner_profile_id
  limit 1;

  select *
    into v_merge
  from public.merged_accounts ma
  where ma.source_user_id = v_owner_user_id
    and ma.status = 'active'
  limit 1;

  if v_merge.source_user_id is not null then
    v_owner_user_id := v_merge.target_user_id;
    v_owner_profile_id := v_merge.target_profile_id;

    select nullif(btrim(coalesce(p.full_name, '')), '')
      into v_owner_name
    from public.profiles p
    where p.id = v_owner_profile_id
    limit 1;
  end if;

  select u.email
    into v_owner_email
  from auth.users u
  where u.id = v_owner_user_id
  limit 1;

  if v_owner_email is not null and position('@' in v_owner_email) > 1 then
    v_email_local := split_part(v_owner_email, '@', 1);
    v_email_domain := split_part(v_owner_email, '@', 2);
    v_email_hint :=
      left(v_email_local, 1)
      || repeat('*', greatest(char_length(v_email_local) - 1, 2))
      || '@'
      || left(v_email_domain, 1)
      || repeat('*', greatest(char_length(v_email_domain) - 3, 2))
      || right(v_email_domain, 2);
  end if;

  select coalesce(
    array_agg(distinct normalized.provider order by normalized.provider),
    array[]::text[]
  )
    into v_methods
  from (
    select
      case lower(coalesce(i.provider, ''))
        when 'google' then 'google'
        when 'apple' then 'apple'
        when 'email' then 'email'
        else null
      end as provider
    from auth.identities i
    where i.user_id = v_owner_user_id
  ) normalized
  where normalized.provider is not null;

  if v_owner_email is not null and not ('email' = any(v_methods)) then
    v_methods := array_append(v_methods, 'email');
  end if;

  v_primary_method := case
    when 'google' = any(v_methods) then 'google'
    when 'apple' = any(v_methods) then 'apple'
    when 'email' = any(v_methods) then 'email'
    else null
  end;

  return jsonb_build_object(
    'found', true,
    'phone_number', v_session.conflicting_phone_number,
    'display_name', split_part(coalesce(v_owner_name, ''), ' ', 1),
    'email_hint', v_email_hint,
    'sign_in_methods', to_jsonb(coalesce(v_methods, array[]::text[])),
    'primary_method', v_primary_method,
    'is_merged', (v_merge.source_user_id is not null),
    'merge_case_id', v_merge.merge_case_id,
    'recovery_token', v_session.recovery_token,
    'message',
      case
        when v_merge.source_user_id is not null then
          'We verified your phone. That number now routes to the kept Betweener account.'
        else
          'We verified your phone. You can now restore the older Betweener account safely.'
      end
  );
end;
$$;


ALTER FUNCTION "public"."rpc_get_account_recovery_options"("p_recovery_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_account_recovery_provider_link_plan"("p_recovery_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_session public.account_recovery_sessions%rowtype;
  v_effective_owner_user_id uuid := auth.uid();
  v_shell_profile public.profiles%rowtype;
  v_shell_provider text;
  v_shell_identities text[] := array[]::text[];
  v_restored_identities text[] := array[]::text[];
  v_action text := 'none';
  v_reason text := 'no_candidate_provider';
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  if p_recovery_token is null then
    raise exception 'recovery token is required';
  end if;

  select *
    into v_session
  from public.account_recovery_sessions
  where recovery_token = p_recovery_token
  order by created_at desc
  limit 1;

  if v_session.id is null then
    return jsonb_build_object(
      'found', false,
      'action', 'none',
      'reason', 'recovery_session_not_found'
    );
  end if;

  select ma.target_user_id
    into v_effective_owner_user_id
  from public.merged_accounts ma
  where ma.source_user_id = v_session.owner_user_id
    and ma.status = 'active'
  limit 1;

  v_effective_owner_user_id := coalesce(v_effective_owner_user_id, v_session.owner_user_id);

  if auth.uid() <> v_effective_owner_user_id then
    return jsonb_build_object(
      'found', false,
      'action', 'none',
      'reason', 'wrong_restored_account'
    );
  end if;

  select *
    into v_shell_profile
  from public.profiles
  where user_id = v_session.requester_user_id
  limit 1;

  select coalesce(
    array_agg(distinct lower(i.provider) order by lower(i.provider)),
    array[]::text[]
  )
    into v_shell_identities
  from auth.identities i
  where i.user_id = v_session.requester_user_id
    and lower(coalesce(i.provider, '')) in ('google', 'apple', 'email');

  select coalesce(
    array_agg(distinct lower(i.provider) order by lower(i.provider)),
    array[]::text[]
  )
    into v_restored_identities
  from auth.identities i
  where i.user_id = v_effective_owner_user_id
    and lower(coalesce(i.provider, '')) in ('google', 'apple', 'email');

  v_shell_provider := lower(
    coalesce(
      nullif(v_shell_profile.last_successful_auth_provider, ''),
      nullif(v_shell_profile.created_via_provider, ''),
      case
        when cardinality(v_shell_identities) > 0 then v_shell_identities[1]
        else null
      end
    )
  );

  if v_shell_provider is null then
    v_action := 'none';
    v_reason := 'no_candidate_provider';
  elsif v_shell_provider = any(v_restored_identities) then
    v_action := 'already_linked';
    v_reason := 'provider_already_on_restored_account';
  elsif v_shell_provider = 'email' then
    v_action := 'manual_email_backup';
    v_reason := 'email_provider_needs_manual_backup_setup';
  elsif v_shell_provider = any(v_shell_identities) then
    v_action := 'blocked_by_duplicate_shell_identity';
    v_reason := 'provider_still_attached_to_duplicate_shell';
  elsif v_shell_provider in ('google', 'apple') then
    v_action := 'offer_native_link';
    v_reason := 'provider_available_for_native_link';
  else
    v_action := 'none';
    v_reason := 'unsupported_candidate_provider';
  end if;

  return jsonb_build_object(
    'found', true,
    'recovery_token', p_recovery_token,
    'shell_user_id', v_session.requester_user_id,
    'restored_user_id', v_effective_owner_user_id,
    'candidate_provider', v_shell_provider,
    'shell_identity_status', coalesce(v_shell_profile.identity_status, 'unknown'),
    'shell_identities', to_jsonb(v_shell_identities),
    'restored_identities', to_jsonb(v_restored_identities),
    'action', v_action,
    'reason', v_reason
  );
end;
$$;


ALTER FUNCTION "public"."rpc_get_account_recovery_provider_link_plan"("p_recovery_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_app_version_rule"("p_platform" "text", "p_environment" "text" DEFAULT 'production'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_rule public.app_version_rules%rowtype;
  v_platform text := lower(nullif(btrim(coalesce(p_platform, '')), ''));
  v_environment text := lower(nullif(btrim(coalesce(p_environment, '')), ''));
begin
  if v_platform not in ('ios', 'android') then
    return null;
  end if;

  if v_environment not in ('production', 'staging', 'development') then
    v_environment := 'production';
  end if;

  select *
    into v_rule
  from public.app_version_rules
  where enabled = true
    and platform = v_platform
    and environment = v_environment
  order by updated_at desc, created_at desc
  limit 1;

  if not found then
    return null;
  end if;

  return jsonb_build_object(
    'platform', v_rule.platform,
    'environment', v_rule.environment,
    'latestVersion', v_rule.latest_version,
    'latestBuildNumber', v_rule.latest_build_number,
    'minimumSupportedVersion', v_rule.minimum_supported_version,
    'minimumSupportedBuildNumber', v_rule.minimum_supported_build_number,
    'updateMode', v_rule.update_mode,
    'updateTitle', v_rule.update_title,
    'updateMessage', v_rule.update_message,
    'whatsNewTitle', v_rule.whats_new_title,
    'whatsNewItems', coalesce(v_rule.whats_new_items, '[]'::jsonb),
    'storeUrl', v_rule.store_url,
    'softPromptCooldownHours', v_rule.soft_prompt_cooldown_hours
  );
end;
$$;


ALTER FUNCTION "public"."rpc_get_app_version_rule"("p_platform" "text", "p_environment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_chat_conversation_summaries"("p_limit" integer DEFAULT 200, "p_offset" integer DEFAULT 0) RETURNS TABLE("other_user_id" "uuid", "last_message_id" "uuid", "last_message_text" "text", "last_message_created_at" timestamp with time zone, "last_message_sender_id" "uuid", "last_message_receiver_id" "uuid", "last_message_is_read" boolean, "last_message_delivered_at" timestamp with time zone, "last_message_type" "text", "last_message_is_view_once" boolean, "last_message_deleted_for_all" boolean, "last_message_edited_at" timestamp with time zone, "last_message_reaction_emoji" "text", "last_message_reaction_user_id" "uuid", "last_message_reaction_created_at" timestamp with time zone, "last_message_reaction_target_type" "text", "last_activity_kind" "text", "last_activity_message_id" "uuid", "last_activity_preview" "text", "last_activity_at" timestamp with time zone, "unread_count" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  select
    s.peer_user_id as other_user_id,
    s.last_message_id,
    s.last_message_text,
    s.last_message_created_at,
    s.last_message_sender_id,
    s.last_message_receiver_id,
    s.last_message_is_read,
    s.last_message_delivered_at,
    s.last_message_type,
    s.last_message_is_view_once,
    s.last_message_deleted_for_all,
    s.last_message_edited_at,
    s.last_message_reaction_emoji,
    s.last_message_reaction_user_id,
    s.last_message_reaction_created_at,
    s.last_message_reaction_target_type,
    s.last_activity_kind,
    s.last_activity_message_id,
    s.last_activity_preview,
    s.last_activity_at,
    s.unread_count
  from public.chat_conversation_summaries s
  where auth.uid() is not null
    and s.owner_user_id = auth.uid()
  order by s.last_message_created_at desc nulls last, s.last_message_id desc nulls last
  limit greatest(1, least(coalesce(p_limit, 200), 500))
  offset greatest(coalesce(p_offset, 0), 0);
$$;


