CREATE OR REPLACE FUNCTION "public"."rpc_get_circle_member_moments"("p_circle_id" "uuid", "p_limit" integer DEFAULT 18) RETURNS TABLE("id" "uuid", "user_id" "uuid", "type" "text", "media_url" "text", "thumbnail_url" "text", "text_body" "text", "caption" "text", "created_at" timestamp with time zone, "expires_at" timestamp with time zone, "visibility" "text", "is_deleted" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
begin
  return query
  select recovery.*
  from public.rpc_get_circle_member_moments_recovery(p_circle_id, p_limit) recovery;
end;
$$;


ALTER FUNCTION "public"."rpc_get_circle_member_moments"("p_circle_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_circle_member_moments_recovery"("p_circle_id" "uuid", "p_limit" integer DEFAULT 18) RETURNS TABLE("id" "uuid", "user_id" "uuid", "type" "text", "media_url" "text", "thumbnail_url" "text", "text_body" "text", "caption" "text", "created_at" timestamp with time zone, "expires_at" timestamp with time zone, "visibility" "text", "is_deleted" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not public.is_circle_member(p_circle_id, auth.uid())
    and not public.is_circle_owner(p_circle_id, auth.uid()) then
    raise exception 'circle_membership_required' using errcode = '42501';
  end if;

  return query
  with eligible_users as (
    select member.user_id
    from public.circle_members member
    where member.circle_id = p_circle_id
      and member.status = 'active'
      and member.is_visible is not false
      and member.user_id is not null

    union

    select profile.user_id
    from public.circle_members member
    join public.profiles profile on profile.id = member.profile_id
    where member.circle_id = p_circle_id
      and member.status = 'active'
      and member.is_visible is not false
      and profile.user_id is not null

    union

    select circle_row.created_by_user_id
    from public.circles circle_row
    where circle_row.id = p_circle_id
      and circle_row.created_by_user_id is not null

    union

    select owner.user_id
    from public.circles circle_row
    join public.profiles owner on owner.id = circle_row.created_by_profile_id
    where circle_row.id = p_circle_id
      and owner.user_id is not null
  )
  select
    moment.id,
    moment.user_id,
    moment.type,
    moment.media_url,
    moment.thumbnail_url,
    moment.text_body,
    moment.caption,
    moment.created_at,
    moment.expires_at,
    moment.visibility,
    moment.is_deleted
  from public.moments moment
  join eligible_users eligible on eligible.user_id = moment.user_id
  where moment.is_deleted = false
    and moment.expires_at > timezone('utc'::text, now())
    and (
      moment.user_id = auth.uid()
      or moment.visibility in ('public', 'matches')
    )
    and (
      moment.type = 'text'
      or nullif(btrim(coalesce(moment.media_url, '')), '') is not null
    )
  order by moment.created_at desc, moment.id desc
  limit greatest(1, least(coalesce(p_limit, 18), 48));
end;
$$;


ALTER FUNCTION "public"."rpc_get_circle_member_moments_recovery"("p_circle_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_circle_profile_suggestions"("p_profile_id" "uuid", "p_limit" integer DEFAULT 8) RETURNS TABLE("profile_id" "uuid", "full_name" "text", "age" integer, "avatar_url" "text", "circle_id" "uuid", "circle_name" "text", "reason" "text", "score" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles viewer_profile
    where viewer_profile.id = p_profile_id
      and viewer_profile.user_id = auth.uid()
      and viewer_profile.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  return query
  with viewer as (
    select viewer_profile.*
    from public.profiles viewer_profile
    where viewer_profile.id = p_profile_id
  ),
  viewer_circles as (
    select distinct member.circle_id
    from public.circle_members member
    where member.profile_id = p_profile_id
      and member.status = 'active'
      and member.is_visible is not false
  ),
  viewer_signal_taste as (
    select distinct candidate_interest.interest_id
    from public.profile_signals signal
    join public.profile_interests candidate_interest
      on candidate_interest.profile_id = signal.target_profile_id
    where signal.profile_id = p_profile_id
      and (
        signal.liked is true
        or coalesce(signal.opened_profile_count, 0) > 0
        or coalesce(signal.dwell_score, 0) > 0
        or signal.intro_video_started is true
        or signal.intro_video_completed is true
      )
  ),
  raw_candidates as (
    select
      candidate.id as profile_id,
      candidate.full_name,
      candidate.age,
      candidate.avatar_url,
      candidate.user_id,
      candidate.city,
      candidate.region,
      candidate.current_country,
      candidate.current_country_code,
      candidate.religion,
      candidate.looking_for,
      candidate.min_age_interest,
      candidate.max_age_interest,
      candidate.bio,
      candidate.photos,
      candidate.profile_video,
      candidate.verification_level,
      candidate.last_active,
      candidate.profile_completed,
      circle_row.id as circle_id,
      circle_row.name as circle_name,
      member.joined_at
    from viewer
    join viewer_circles viewer_circle on true
    join public.circle_members member
      on member.circle_id = viewer_circle.circle_id
     and member.status = 'active'
     and member.is_visible is not false
     and member.profile_id <> p_profile_id
    join public.profiles candidate
      on candidate.id = member.profile_id
     and candidate.deleted_at is null
     and coalesce(candidate.is_active, true)
     and coalesce(candidate.discoverable_in_vibes, true)
     and coalesce(candidate.matchmaking_mode, false) = false
     and candidate.user_id is not null
    join public.circles circle_row
      on circle_row.id = member.circle_id
     and circle_row.archived_at is null
    where not exists (
        select 1
        from public.blocks block_row
        where (block_row.blocker_id = viewer.user_id and block_row.blocked_id = candidate.user_id)
           or (block_row.blocker_id = candidate.user_id and block_row.blocked_id = viewer.user_id)
      )
      and not exists (
        select 1
        from public.matches match_row
        where lower(coalesce(match_row.status::text, '')) in ('pending', 'accepted')
          and (
            (match_row.user1_id = viewer.id and match_row.user2_id = candidate.id)
            or (match_row.user1_id = candidate.id and match_row.user2_id = viewer.id)
          )
      )
      and (
        viewer.gender is null
        or viewer.gender not in ('MALE', 'FEMALE')
        or candidate.gender is null
        or candidate.gender not in ('MALE', 'FEMALE')
        or (viewer.gender = 'MALE' and candidate.gender = 'FEMALE')
        or (viewer.gender = 'FEMALE' and candidate.gender = 'MALE')
      )
  ),
  candidate_rollup as (
    select
      raw.profile_id,
      raw.full_name,
      raw.age,
      raw.avatar_url,
      raw.user_id,
      raw.city,
      raw.region,
      raw.current_country,
      raw.current_country_code,
      raw.religion,
      raw.looking_for,
      raw.min_age_interest,
      raw.max_age_interest,
      raw.bio,
      raw.photos,
      raw.profile_video,
      raw.verification_level,
      raw.last_active,
      raw.profile_completed,
      (array_agg(raw.circle_id order by raw.joined_at desc nulls last, raw.circle_name))[1] as circle_id,
      (array_agg(raw.circle_name order by raw.joined_at desc nulls last, raw.circle_name))[1] as circle_name,
      count(distinct raw.circle_id)::integer as shared_circle_count
    from raw_candidates raw
    group by
      raw.profile_id,
      raw.full_name,
      raw.age,
      raw.avatar_url,
      raw.user_id,
      raw.city,
      raw.region,
      raw.current_country,
      raw.current_country_code,
      raw.religion,
      raw.looking_for,
      raw.min_age_interest,
      raw.max_age_interest,
      raw.bio,
      raw.photos,
      raw.profile_video,
      raw.verification_level,
      raw.last_active,
      raw.profile_completed
  ),
  scored as (
    select
      candidate.profile_id,
      candidate.full_name,
      candidate.age,
      candidate.avatar_url,
      candidate.circle_id,
      candidate.circle_name,
      candidate.shared_circle_count,
      coalesce(shared.shared_interest_count, 0) as shared_interest_count,
      coalesce(taste.taste_interest_count, 0) as taste_interest_count,
      coalesce(signal.signal_score, 0) as signal_score,
      coalesce(vibes.vibes_score, 0) as vibes_score,
      coalesce(suggested.suggested_score, 0) as suggested_score,
      coalesce(intent.intent_score, 0) as intent_score,
      coalesce(vibes.recent_pass, false) as recent_pass,
      (
        100
        + least(candidate.shared_circle_count * 12, 30)
        + least(coalesce(shared.shared_interest_count, 0) * 10, 30)
        + least(coalesce(taste.taste_interest_count, 0) * 8, 24)
        + case
            when nullif(btrim(coalesce(candidate.looking_for, '')), '') is not null
             and lower(candidate.looking_for) = lower(viewer.looking_for) then 18
            else 0
          end
        + case
            when candidate.age between coalesce(viewer.min_age_interest, 18) and coalesce(viewer.max_age_interest, 99) then 14
            else 0
          end
        + case
            when viewer.age between coalesce(candidate.min_age_interest, 18) and coalesce(candidate.max_age_interest, 99) then 10
            else 0
          end
        + case
            when nullif(btrim(coalesce(candidate.city, '')), '') is not null
             and lower(candidate.city) = lower(viewer.city) then 16
            when nullif(btrim(coalesce(candidate.current_country_code, '')), '') is not null
             and upper(candidate.current_country_code) = upper(viewer.current_country_code) then 11
            when nullif(btrim(coalesce(candidate.current_country, '')), '') is not null
             and lower(candidate.current_country) = lower(viewer.current_country) then 9
            when nullif(btrim(coalesce(candidate.region, '')), '') is not null
             and lower(candidate.region) = lower(viewer.region) then 6
            else 0
          end
        + case
            when candidate.religion is not null and candidate.religion = viewer.religion then 10
            else 0
          end
        + case
            when coalesce(candidate.verification_level, 0) > 0 then 8
            else 0
          end
        + case
            when candidate.last_active >= timezone('utc'::text, now()) - interval '30 minutes' then 12
            when candidate.last_active >= timezone('utc'::text, now()) - interval '24 hours' then 8
            when candidate.last_active >= timezone('utc'::text, now()) - interval '7 days' then 4
            else 0
          end
        + case when coalesce(candidate.profile_completed, false) then 6 else 0 end
        + case when nullif(btrim(coalesce(candidate.bio, '')), '') is not null then 4 else 0 end
        + case when cardinality(coalesce(candidate.photos, array[]::text[])) > 0 then 4 else 0 end
        + case when nullif(btrim(coalesce(candidate.profile_video, '')), '') is not null then 6 else 0 end
        + coalesce(signal.signal_score, 0)
        + coalesce(vibes.vibes_score, 0)
        + coalesce(suggested.suggested_score, 0)
        + coalesce(intent.intent_score, 0)
        - case when coalesce(vibes.recent_pass, false) then 45 else 0 end
      )::integer as score,
      concat_ws(
        ' - ',
        'Shared Circle',
        case when coalesce(shared.shared_interest_count, 0) > 0 then 'Shared interests' end,
        case
          when nullif(btrim(coalesce(candidate.looking_for, '')), '') is not null
           and lower(candidate.looking_for) = lower(viewer.looking_for) then 'Intent aligned'
        end,
        case
          when nullif(btrim(coalesce(candidate.city, '')), '') is not null
           and lower(candidate.city) = lower(viewer.city) then 'Nearby context'
          when nullif(btrim(coalesce(candidate.current_country_code, '')), '') is not null
           and upper(candidate.current_country_code) = upper(viewer.current_country_code) then 'Country context'
        end,
        case when coalesce(vibes.vibes_score, 0) > 0 or coalesce(signal.signal_score, 0) > 0 then 'Warm signal' end,
        case when candidate.last_active >= timezone('utc'::text, now()) - interval '24 hours' then 'Active recently' end
      ) as reason
    from candidate_rollup candidate
    cross join viewer
    left join lateral (
      select count(*)::integer as shared_interest_count
      from public.profile_interests candidate_interest
      join public.profile_interests viewer_interest
        on viewer_interest.interest_id = candidate_interest.interest_id
       and viewer_interest.profile_id = viewer.id
      where candidate_interest.profile_id = candidate.profile_id
    ) shared on true
    left join lateral (
      select count(*)::integer as taste_interest_count
      from public.profile_interests candidate_interest
      join viewer_signal_taste taste_interest
        on taste_interest.interest_id = candidate_interest.interest_id
      where candidate_interest.profile_id = candidate.profile_id
    ) taste on true
    left join lateral (
      select coalesce(sum(
        case
          when signal.liked is true then 18 else 0
        end
        + least(coalesce(signal.opened_profile_count, 0) * 4, 12)
        + least(coalesce(signal.dwell_score, 0), 12)
        + case when signal.intro_video_completed is true then 10 when signal.intro_video_started is true then 5 else 0 end
      ), 0)::integer as signal_score
      from public.profile_signals signal
      where signal.profile_id = viewer.id
        and signal.target_profile_id = candidate.profile_id
        and signal.last_interacted_at >= timezone('utc'::text, now()) - interval '180 days'
    ) signal on true
    left join lateral (
      select
        coalesce(sum(
          case event.event_type
            when 'like' then 18
            when 'signal_sent' then 18
            when 'intent_sent' then 18
            when 'profile_opened' then 8
            when 'intro_completed' then 8
            when 'intro_played' then 5
            when 'signal_opened' then 5
            when 'intent_opened' then 5
            when 'pass' then -18
            else 0
          end
          + case when coalesce(event.dwell_ms, 0) >= 8000 then 4 else 0 end
        ), 0)::integer as vibes_score,
        bool_or(event.event_type = 'pass' and event.created_at >= timezone('utc'::text, now()) - interval '14 days') as recent_pass
      from public.vibes_events event
      where event.viewer_profile_id = viewer.id
        and event.target_profile_id = candidate.profile_id
        and event.created_at >= timezone('utc'::text, now()) - interval '180 days'
    ) vibes on true
    left join lateral (
      select coalesce(sum(
        case event.event_type
          when 'intent_sent' then 18
          when 'intent_opened' then 8
          when 'opener_revealed' then 6
          when 'preview_profile' then 5
          when 'impression' then 1
          else 0
        end
      ), 0)::integer as suggested_score
      from public.suggested_move_events event
      where event.viewer_profile_id = viewer.id
        and event.candidate_profile_id = candidate.profile_id
        and event.created_at >= timezone('utc'::text, now()) - interval '180 days'
    ) suggested on true
    left join lateral (
      select coalesce(sum(
        case request.status
          when 'accepted' then 22
          when 'pending' then 8
          when 'passed' then -25
          when 'cancelled' then -8
          else 0
        end
      ), 0)::integer as intent_score
      from public.intent_requests request
      where (
          (request.actor_id = viewer.id and request.recipient_id = candidate.profile_id)
          or (request.actor_id = candidate.profile_id and request.recipient_id = viewer.id)
        )
        and request.created_at >= timezone('utc'::text, now()) - interval '180 days'
    ) intent on true
  )
  select
    scored.profile_id,
    coalesce(nullif(btrim(scored.full_name), ''), 'Circle member') as full_name,
    scored.age,
    scored.avatar_url,
    scored.circle_id,
    coalesce(nullif(btrim(scored.circle_name), ''), 'Shared Circle') as circle_name,
    coalesce(nullif(btrim(scored.reason), ''), 'Shared Circle') as reason,
    scored.score
  from scored
  order by
    scored.score desc,
    scored.shared_interest_count desc,
    scored.shared_circle_count desc,
    scored.full_name nulls last,
    scored.profile_id
  limit greatest(1, least(coalesce(p_limit, 8), 24));
end;
$$;


ALTER FUNCTION "public"."rpc_get_circle_profile_suggestions"("p_profile_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_circle_pulse_comment_reactions"("p_pulse_item_id" "uuid") RETURNS TABLE("comment_id" "uuid", "reaction_count" integer, "my_reaction" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_circle_id uuid;
  v_profile_id uuid;
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  select cpi.circle_id
    into v_circle_id
  from public.circle_pulse_items cpi
  where cpi.id = p_pulse_item_id
    and cpi.status = 'active'
    and (cpi.starts_at is null or cpi.starts_at <= timezone('utc'::text, now()))
    and (cpi.expires_at is null or cpi.expires_at > timezone('utc'::text, now()))
  limit 1;

  if v_circle_id is null then
    raise exception 'pulse_item_not_found';
  end if;

  if not public.can_manage_circle_pulse(v_circle_id, auth.uid())
    and not public.is_circle_member(v_circle_id, auth.uid())
    and not public.is_circle_owner(v_circle_id, auth.uid()) then
    raise exception 'circle_membership_required' using errcode = '42501';
  end if;

  select p.id
    into v_profile_id
  from public.profiles p
  where p.user_id = auth.uid()
    and p.deleted_at is null
  limit 1;

  return query
  select
    cpc.id,
    count(cpcr.id)::integer as reaction_count,
    max(cpcr.reaction) filter (where cpcr.profile_id = v_profile_id) as my_reaction
  from public.circle_pulse_comments cpc
  left join public.circle_pulse_comment_reactions cpcr
    on cpcr.comment_id = cpc.id
  where cpc.pulse_item_id = p_pulse_item_id
    and cpc.status = 'active'
  group by cpc.id;
end;
$$;


ALTER FUNCTION "public"."rpc_get_circle_pulse_comment_reactions"("p_pulse_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_circle_pulse_comment_snapshot"("p_comment_id" "uuid") RETURNS TABLE("id" "uuid", "pulse_item_id" "uuid", "circle_id" "uuid", "profile_id" "uuid", "display_name" "text", "avatar_url" "text", "body" "text", "parent_comment_id" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "edited_at" timestamp with time zone, "is_own" boolean, "can_remove" boolean, "can_edit" boolean, "can_pin" boolean, "pinned_at" timestamp with time zone, "report_count" integer, "reaction_count" integer, "my_reaction" "text", "reply_preview_profile_id" "uuid", "reply_preview_display_name" "text", "reply_preview_body" "text", "reaction_summary" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_comment public.circle_pulse_comments%rowtype;
  v_profile_id uuid;
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  select *
    into v_comment
  from public.circle_pulse_comments cpc
  where cpc.id = p_comment_id
  limit 1;

  if v_comment.id is null or v_comment.status <> 'active' then
    raise exception 'comment_not_found';
  end if;

  if not public.can_manage_circle_pulse(v_comment.circle_id, auth.uid())
    and not public.is_circle_member(v_comment.circle_id, auth.uid())
    and not public.is_circle_owner(v_comment.circle_id, auth.uid()) then
    raise exception 'circle_membership_required' using errcode = '42501';
  end if;

  select p.id
    into v_profile_id
  from public.profiles p
  where p.user_id = auth.uid()
    and p.deleted_at is null
  limit 1;

  return query
  select
    projection.id,
    projection.pulse_item_id,
    projection.circle_id,
    projection.profile_id,
    projection.display_name,
    projection.avatar_url,
    projection.body,
    projection.parent_comment_id,
    projection.created_at,
    projection.updated_at,
    projection.edited_at,
    projection.is_own,
    projection.can_remove,
    projection.can_edit,
    projection.can_pin,
    projection.pinned_at,
    projection.report_count,
    projection.reaction_count,
    projection.my_reaction,
    projection.reply_preview_profile_id,
    projection.reply_preview_display_name,
    projection.reply_preview_body,
    projection.reaction_summary
  from public.get_circle_pulse_comment_projection(p_comment_id, auth.uid(), v_profile_id) projection;
end;
$$;


ALTER FUNCTION "public"."rpc_get_circle_pulse_comment_snapshot"("p_comment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_circle_pulse_comments"("p_pulse_item_id" "uuid", "p_limit" integer DEFAULT 100) RETURNS TABLE("id" "uuid", "pulse_item_id" "uuid", "circle_id" "uuid", "profile_id" "uuid", "display_name" "text", "avatar_url" "text", "body" "text", "parent_comment_id" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "is_own" boolean, "can_remove" boolean, "report_count" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_circle_id uuid;
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  select cpi.circle_id
    into v_circle_id
  from public.circle_pulse_items cpi
  where cpi.id = p_pulse_item_id
    and cpi.status = 'active'
    and (cpi.starts_at is null or cpi.starts_at <= timezone('utc'::text, now()))
    and (cpi.expires_at is null or cpi.expires_at > timezone('utc'::text, now()))
  limit 1;

  if v_circle_id is null then
    raise exception 'pulse_item_not_found';
  end if;

  if not public.can_manage_circle_pulse(v_circle_id, auth.uid())
    and not public.is_circle_member(v_circle_id, auth.uid())
    and not public.is_circle_owner(v_circle_id, auth.uid()) then
    raise exception 'circle_membership_required' using errcode = '42501';
  end if;

  return query
  select
    cpc.id,
    cpc.pulse_item_id,
    cpc.circle_id,
    cpc.profile_id,
    coalesce(nullif(btrim(p.full_name), ''), 'Member') as display_name,
    p.avatar_url,
    cpc.body,
    cpc.parent_comment_id,
    cpc.created_at,
    cpc.updated_at,
    cpc.user_id = auth.uid() as is_own,
    (
      cpc.user_id = auth.uid()
      or public.can_manage_circle_pulse(cpc.circle_id, auth.uid())
    ) as can_remove,
    cpc.report_count
  from public.circle_pulse_comments cpc
  join public.profiles p on p.id = cpc.profile_id
  where cpc.pulse_item_id = p_pulse_item_id
    and cpc.status = 'active'
  order by cpc.created_at asc, cpc.id asc
  limit greatest(1, least(coalesce(p_limit, 100), 200));
end;
$$;


ALTER FUNCTION "public"."rpc_get_circle_pulse_comments"("p_pulse_item_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_circle_pulse_comments_page"("p_pulse_item_id" "uuid", "p_limit" integer DEFAULT 30, "p_before_created_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_before_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "pulse_item_id" "uuid", "circle_id" "uuid", "profile_id" "uuid", "display_name" "text", "avatar_url" "text", "body" "text", "parent_comment_id" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "edited_at" timestamp with time zone, "is_own" boolean, "can_remove" boolean, "can_edit" boolean, "can_pin" boolean, "pinned_at" timestamp with time zone, "report_count" integer, "reaction_count" integer, "my_reaction" "text", "reply_preview_profile_id" "uuid", "reply_preview_display_name" "text", "reply_preview_body" "text", "reaction_summary" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_circle_id uuid;
  v_profile_id uuid;
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  select cpi.circle_id
    into v_circle_id
  from public.circle_pulse_items cpi
  where cpi.id = p_pulse_item_id
    and cpi.status = 'active'
    and (cpi.starts_at is null or cpi.starts_at <= timezone('utc'::text, now()))
    and (cpi.expires_at is null or cpi.expires_at > timezone('utc'::text, now()))
  limit 1;

  if v_circle_id is null then
    raise exception 'pulse_item_not_found';
  end if;

  if not public.can_manage_circle_pulse(v_circle_id, auth.uid())
    and not public.is_circle_member(v_circle_id, auth.uid())
    and not public.is_circle_owner(v_circle_id, auth.uid()) then
    raise exception 'circle_membership_required' using errcode = '42501';
  end if;

  select p.id
    into v_profile_id
  from public.profiles p
  where p.user_id = auth.uid()
    and p.deleted_at is null
  limit 1;

  return query
  with windowed as (
    select
      cpc.id,
      cpc.created_at
    from public.circle_pulse_comments cpc
    where cpc.pulse_item_id = p_pulse_item_id
      and cpc.status = 'active'
      and (
        p_before_created_at is null
        or cpc.created_at < p_before_created_at
        or (
          p_before_id is not null
          and cpc.created_at = p_before_created_at
          and cpc.id < p_before_id
        )
      )
    order by cpc.created_at desc, cpc.id desc
    limit greatest(1, least(coalesce(p_limit, 30), 100))
  )
  select
    projection.id,
    projection.pulse_item_id,
    projection.circle_id,
    projection.profile_id,
    projection.display_name,
    projection.avatar_url,
    projection.body,
    projection.parent_comment_id,
    projection.created_at,
    projection.updated_at,
    projection.edited_at,
    projection.is_own,
    projection.can_remove,
    projection.can_edit,
    projection.can_pin,
    projection.pinned_at,
    projection.report_count,
    projection.reaction_count,
    projection.my_reaction,
    projection.reply_preview_profile_id,
    projection.reply_preview_display_name,
    projection.reply_preview_body,
    projection.reaction_summary
  from windowed
  join lateral public.get_circle_pulse_comment_projection(windowed.id, auth.uid(), v_profile_id) projection
    on true
  order by projection.created_at asc, projection.id asc;
end;
$$;


ALTER FUNCTION "public"."rpc_get_circle_pulse_comments_page"("p_pulse_item_id" "uuid", "p_limit" integer, "p_before_created_at" timestamp with time zone, "p_before_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_circle_pulse_discussion_read_state"("p_pulse_item_id" "uuid", "p_profile_id" "uuid") RETURNS TABLE("pulse_item_id" "uuid", "last_seen_comment_id" "uuid", "last_seen_at" timestamp with time zone, "unread_count" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_circle_id uuid;
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_profile_id
      and p.user_id = auth.uid()
      and p.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  select cpi.circle_id
    into v_circle_id
  from public.circle_pulse_items cpi
  where cpi.id = p_pulse_item_id
  limit 1;

  if v_circle_id is null then
    raise exception 'pulse_item_not_found';
  end if;

  if not public.can_manage_circle_pulse(v_circle_id, auth.uid())
    and not public.is_circle_member(v_circle_id, auth.uid())
    and not public.is_circle_owner(v_circle_id, auth.uid()) then
    raise exception 'circle_membership_required' using errcode = '42501';
  end if;

  return query
  with read_state as (
    select dr.last_seen_comment_id, dr.last_seen_at
    from public.circle_pulse_discussion_reads dr
    where dr.pulse_item_id = p_pulse_item_id
      and dr.profile_id = p_profile_id
    limit 1
  )
  select
    p_pulse_item_id,
    rs.last_seen_comment_id,
    rs.last_seen_at,
    coalesce((
      select count(*)::integer
      from public.circle_pulse_comments cpc
      where cpc.pulse_item_id = p_pulse_item_id
        and cpc.status = 'active'
        and cpc.user_id <> auth.uid()
        and cpc.created_at > coalesce(rs.last_seen_at, '-infinity'::timestamptz)
    ), 0) as unread_count
  from read_state rs
  union all
  select
    p_pulse_item_id,
    null::uuid,
    null::timestamptz,
    coalesce((
      select count(*)::integer
      from public.circle_pulse_comments cpc
      where cpc.pulse_item_id = p_pulse_item_id
        and cpc.status = 'active'
        and cpc.user_id <> auth.uid()
    ), 0) as unread_count
  where not exists (select 1 from read_state);
end;
$$;


ALTER FUNCTION "public"."rpc_get_circle_pulse_discussion_read_state"("p_pulse_item_id" "uuid", "p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_circle_pulse_discussion_reads"("p_circle_id" "uuid", "p_profile_id" "uuid") RETURNS TABLE("pulse_item_id" "uuid", "last_seen_comment_id" "uuid", "last_seen_at" timestamp with time zone, "unread_count" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_profile_id
      and p.user_id = auth.uid()
      and p.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  if not public.can_manage_circle_pulse(p_circle_id, auth.uid())
    and not public.is_circle_member(p_circle_id, auth.uid())
    and not public.is_circle_owner(p_circle_id, auth.uid()) then
    raise exception 'circle_membership_required' using errcode = '42501';
  end if;

  return query
  select
    cpi.id as pulse_item_id,
    dr.last_seen_comment_id,
    dr.last_seen_at,
    coalesce((
      select count(*)::integer
      from public.circle_pulse_comments cpc
      where cpc.pulse_item_id = cpi.id
        and cpc.status = 'active'
        and cpc.user_id <> auth.uid()
        and cpc.created_at > coalesce(dr.last_seen_at, '-infinity'::timestamptz)
    ), 0) as unread_count
  from public.circle_pulse_items cpi
  left join public.circle_pulse_discussion_reads dr
    on dr.pulse_item_id = cpi.id
   and dr.profile_id = p_profile_id
  where cpi.circle_id = p_circle_id
    and (
      public.can_manage_circle_pulse(p_circle_id, auth.uid())
      or (
        cpi.status = 'active'
        and (cpi.starts_at is null or cpi.starts_at <= timezone('utc'::text, now()))
        and (cpi.expires_at is null or cpi.expires_at > timezone('utc'::text, now()))
      )
    );
end;
$$;


ALTER FUNCTION "public"."rpc_get_circle_pulse_discussion_reads"("p_circle_id" "uuid", "p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_circle_pulse_items"("p_circle_id" "uuid", "p_include_inactive" boolean DEFAULT false) RETURNS TABLE("id" "uuid", "circle_id" "uuid", "item_type" "text", "title" "text", "subtitle" "text", "body" "text", "image_url" "text", "media_url" "text", "media_type" "text", "prompt_id" "uuid", "gathering_id" "uuid", "moment_id" "uuid", "love_seat_id" "uuid", "featured_profile_id" "uuid", "featured_profile_name" "text", "featured_profile_age" integer, "featured_profile_avatar_url" "text", "featured_profile_location" "text", "featured_profile_badge" "text", "love_seat_quote" "text", "welcome_profiles" "jsonb", "status" "text", "priority" integer, "starts_at" timestamp with time zone, "expires_at" timestamp with time zone, "comment_count" integer, "discussion_cta" "text", "discussion_summary" "text", "gathering_starts_at" timestamp with time zone, "gathering_city" "text", "gathering_type" "text", "gathering_presentation_mode" "text", "gathering_seat_context" "text", "gathering_host_created_for_member" boolean, "gathering_is_partner_venue" boolean, "gathering_safe_first_date_space" boolean, "gathering_attendee_count" integer, "source_available" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_can_manage boolean := public.can_manage_circle_pulse(p_circle_id, auth.uid());
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if p_circle_id is null then
    raise exception 'circle_not_found';
  end if;

  if not v_can_manage
    and not public.is_circle_member(p_circle_id, auth.uid())
    and not public.is_circle_owner(p_circle_id, auth.uid()) then
    raise exception 'circle_membership_required' using errcode = '42501';
  end if;

  if coalesce(p_include_inactive, false) and not v_can_manage then
    raise exception 'host_required' using errcode = '42501';
  end if;

  return query
  with resolved as (
    select
      cpi.id,
      cpi.circle_id,
      cpi.item_type,
      case
        when cpi.item_type = 'prompt' then cp.title
        when cpi.item_type = 'gathering' then g.title
        when cpi.item_type = 'love_seat' then 'Love Seat'::text
        when cpi.item_type = 'welcome' then 'Welcome new member'::text
        else cpi.title
      end as title,
      cpi.subtitle,
      case
        when cpi.item_type = 'prompt' then cp.prompt
        when cpi.item_type = 'gathering' then g.description
        when cpi.item_type = 'love_seat' then cls.quote
        else cpi.body
      end as body,
      coalesce(
        nullif(btrim(coalesce(cpi.image_url, '')), ''),
        nullif(btrim(coalesce(g.poster_url, '')), ''),
        nullif(btrim(coalesce(m.thumbnail_url, '')), ''),
        nullif(btrim(coalesce(featured.avatar_url, '')), ''),
        nullif(btrim(coalesce(welcome.featured_avatar_url, '')), '')
      ) as image_url,
      coalesce(
        nullif(btrim(coalesce(cpi.media_url, '')), ''),
        nullif(btrim(coalesce(m.media_url, '')), '')
      ) as media_url,
      coalesce(
        cpi.media_type,
        case m.type
          when 'photo' then 'image'
          when 'video' then 'video'
          else null
        end
      ) as media_type,
      cpi.prompt_id,
      cpi.gathering_id,
      cpi.moment_id,
      cpi.love_seat_id,
      case
        when cpi.item_type = 'gathering'
          and coalesce(g.presentation_mode, 'general') = 'seat_linked'
          and gathering_featured.id is not null
          and gathering_featured_member.id is not null
        then gathering_featured.id
        else featured.id
      end as featured_profile_id,
      case
        when cpi.item_type = 'gathering'
          and coalesce(g.presentation_mode, 'general') = 'seat_linked'
          and gathering_featured.id is not null
          and gathering_featured_member.id is not null
        then gathering_featured.full_name
        else featured.full_name
      end as featured_profile_name,
      case
        when cpi.item_type = 'gathering'
          and coalesce(g.presentation_mode, 'general') = 'seat_linked'
          and gathering_featured.id is not null
          and gathering_featured_member.id is not null
        then gathering_featured.age
        else featured.age
      end as featured_profile_age,
      case
        when cpi.item_type = 'gathering'
          and coalesce(g.presentation_mode, 'general') = 'seat_linked'
          and gathering_featured.id is not null
          and gathering_featured_member.id is not null
        then gathering_featured.avatar_url
        else featured.avatar_url
      end as featured_profile_avatar_url,
      case
        when cpi.item_type = 'gathering'
          and coalesce(g.presentation_mode, 'general') = 'seat_linked'
          and gathering_featured.id is not null
          and gathering_featured_member.id is not null
        then coalesce(gathering_featured.city, gathering_featured.region)
        else coalesce(featured.city, featured.region)
      end as featured_profile_location,
      case
        when cpi.item_type = 'gathering'
          and coalesce(g.presentation_mode, 'general') = 'seat_linked'
          and gathering_featured.id is not null
          and gathering_featured_member.id is not null
          and coalesce(gathering_featured.verification_level, 0) > 0
        then 'Verified'::text
        when coalesce(featured.verification_level, 0) > 0
        then 'Verified'::text
        else null
      end as featured_profile_badge,
      cls.quote as love_seat_quote,
      coalesce(welcome.profiles, '[]'::jsonb) as welcome_profiles,
      cpi.status,
      cpi.priority,
      coalesce(cpi.starts_at, cp.starts_at, g.starts_at, cls.starts_at) as starts_at,
      coalesce(cpi.expires_at, cp.expires_at, cls.ends_at, welcome.expires_at) as expires_at,
      cpi.starts_at as editorial_starts_at,
      cpi.expires_at as editorial_expires_at,
      coalesce(cpi.comment_count, 0)::integer as comment_count,
      cpi.discussion_cta,
      cpi.discussion_summary,
      g.starts_at as gathering_starts_at,
      g.city as gathering_city,
      g.gathering_type,
      coalesce(g.presentation_mode, 'general') as gathering_presentation_mode,
      g.seat_context as gathering_seat_context,
      coalesce(g.host_created_for_member, false) as gathering_host_created_for_member,
      coalesce(g.is_partner_venue, false) as gathering_is_partner_venue,
      coalesce(g.safe_first_date_space, false) as gathering_safe_first_date_space,
      coalesce(g.attendee_count, 0)::integer as gathering_attendee_count,
      case cpi.item_type
        when 'prompt' then (
          cp.id is not null
          and cp.status = 'published'
          and (cp.starts_at is null or cp.starts_at <= timezone('utc'::text, now()))
          and (cp.expires_at is null or cp.expires_at > timezone('utc'::text, now()))
        )
        when 'gathering' then (
          g.id is not null
          and g.status = 'approved'
          and g.cancelled_at is null
          and g.starts_at > timezone('utc'::text, now())
        )
        when 'host_note' then nullif(btrim(coalesce(cpi.body, '')), '') is not null
        when 'media' then (
          (
            nullif(btrim(coalesce(cpi.media_url, '')), '') is not null
            and cpi.media_type in ('image', 'video', 'audio')
          )
          or (
            m.id is not null
            and m.is_deleted = false
            and m.expires_at > timezone('utc'::text, now())
            and nullif(btrim(coalesce(m.media_url, '')), '') is not null
            and public.can_view_moment(m.id)
          )
        )
        when 'love_seat' then (
          cls.id is not null
          and cls.status = 'active'
          and cls.approved_by_profile_id = cls.featured_profile_id
          and featured.id is not null
          and featured.deleted_at is null
          and featured_member.id is not null
          and (cls.starts_at is null or cls.starts_at <= timezone('utc'::text, now()))
          and (cls.ends_at is null or cls.ends_at > timezone('utc'::text, now()))
        )
        when 'welcome' then jsonb_array_length(coalesce(welcome.profiles, '[]'::jsonb)) > 0
        else false
      end as source_available
    from public.circle_pulse_items cpi
    left join public.circle_prompts cp on cp.id = cpi.prompt_id and cp.circle_id = cpi.circle_id
    left join public.gatherings g on g.id = cpi.gathering_id and g.circle_id = cpi.circle_id
    left join public.moments m on m.id = cpi.moment_id
    left join public.circle_love_seats cls on cls.id = cpi.love_seat_id and cls.circle_id = cpi.circle_id
    left join public.profiles featured on featured.id = cls.featured_profile_id
    left join public.circle_members featured_member
      on featured_member.circle_id = cpi.circle_id
     and featured_member.profile_id = featured.id
     and featured_member.status = 'active'
     and featured_member.is_visible is not false
    left join public.profiles gathering_featured
      on gathering_featured.id = g.featured_profile_id
     and gathering_featured.deleted_at is null
    left join public.circle_members gathering_featured_member
      on gathering_featured_member.circle_id = cpi.circle_id
     and gathering_featured_member.profile_id = gathering_featured.id
     and gathering_featured_member.status = 'active'
     and gathering_featured_member.is_visible is not false
    left join lateral (
      select
        jsonb_agg(
          jsonb_build_object(
            'profile_id', profile.id,
            'name', coalesce(nullif(btrim(profile.full_name), ''), 'New member'),
            'avatar_url', profile.avatar_url,
            'location', coalesce(profile.city, profile.region),
            'joined_at', cpwm.joined_at
          )
          order by cpwm.joined_at desc, cpwm.id desc
        ) as profiles,
        max(cpwm.expires_at) as expires_at,
        max(profile.avatar_url) as featured_avatar_url
      from public.circle_pulse_welcome_members cpwm
      join public.circle_members member on member.id = cpwm.membership_id
      join public.profiles profile on profile.id = cpwm.profile_id
      where cpwm.pulse_item_id = cpi.id
        and cpwm.status = 'active'
        and cpwm.expires_at > timezone('utc'::text, now())
        and member.status = 'active'
        and member.is_visible is not false
        and profile.deleted_at is null
    ) welcome on cpi.item_type = 'welcome'
    where cpi.circle_id = p_circle_id
  )
  select
    r.id,
    r.circle_id,
    r.item_type,
    r.title,
    r.subtitle,
    r.body,
    r.image_url,
    r.media_url,
    r.media_type,
    r.prompt_id,
    r.gathering_id,
    r.moment_id,
    r.love_seat_id,
    r.featured_profile_id,
    r.featured_profile_name,
    r.featured_profile_age,
    r.featured_profile_avatar_url,
    r.featured_profile_location,
    r.featured_profile_badge,
    r.love_seat_quote,
    r.welcome_profiles,
    r.status,
    r.priority,
    r.starts_at,
    r.expires_at,
    r.comment_count,
    r.discussion_cta,
    r.discussion_summary,
    r.gathering_starts_at,
    r.gathering_city,
    r.gathering_type,
    r.gathering_presentation_mode,
    r.gathering_seat_context,
    r.gathering_host_created_for_member,
    r.gathering_is_partner_venue,
    r.gathering_safe_first_date_space,
    r.gathering_attendee_count,
    r.source_available
  from resolved r
  where (
      coalesce(p_include_inactive, false)
      or (
        r.status = 'active'
        and (r.editorial_starts_at is null or r.editorial_starts_at <= timezone('utc'::text, now()))
        and (r.editorial_expires_at is null or r.editorial_expires_at > timezone('utc'::text, now()))
        and r.source_available
      )
    )
  order by
    case r.item_type
      when 'prompt' then 1
      when 'gathering' then 2
      when 'welcome' then 3
      when 'love_seat' then 4
      when 'media' then 5
      when 'host_note' then 6
      else 7
    end,
    r.priority desc,
    r.starts_at desc nulls last,
    r.id desc;
end;
$$;


ALTER FUNCTION "public"."rpc_get_circle_pulse_items"("p_circle_id" "uuid", "p_include_inactive" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_closure_to_clarity_candidates"("p_intent_request_id" "uuid", "p_limit" integer DEFAULT 28) RETURNS TABLE("id" "uuid", "full_name" "text", "age" integer, "avatar_url" "text", "city" "text", "region" "text", "current_country" "text", "current_country_code" "text", "religion" "text", "looking_for" "text", "wants_children" "text", "love_language" "text", "personality_type" "text", "verification_level" integer, "phone_verified" boolean, "interests" "text"[], "short_tags" "text"[], "has_intro_video" boolean, "distance_km" double precision, "shared_interest_names" "text"[], "shared_interest_count" integer, "prompt_title" "text", "prompt_answer" "text", "bio_snippet" "text", "same_region" boolean, "same_religion" boolean, "same_looking_for" boolean, "active_now" boolean, "recently_active" boolean, "candidate_tier" integer, "quality_band" integer, "closure_similarity_score" double precision, "closure_timing_score" double precision, "closure_freshness_score" double precision, "closure_rank_score" double precision)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_viewer_profile public.profiles%rowtype;
  v_target_profile public.profiles%rowtype;
  v_request public.intent_requests%rowtype;
  v_target_profile_id uuid;
  v_selected_reasons text[] := '{}'::text[];
begin
  if auth.uid() is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  select profile.*
    into v_viewer_profile
  from public.profiles profile
  where profile.user_id = auth.uid()
    and profile.deleted_at is null
  limit 1;

  if v_viewer_profile.id is null then
    raise exception 'profile required' using errcode = '42501';
  end if;

  select request_row.*
    into v_request
  from public.intent_requests request_row
  where request_row.id = p_intent_request_id
    and (
      request_row.actor_id = v_viewer_profile.id
      or request_row.recipient_id = v_viewer_profile.id
    )
  limit 1;

  if v_request.id is null then
    raise exception 'intent request not found' using errcode = '42501';
  end if;

  if not (
    v_request.status in ('expired', 'passed', 'cancelled')
    or (
      v_request.status = 'pending'
      and v_request.expires_at <= timezone('utc'::text, now())
    )
  ) then
    raise exception 'intent request is not closed';
  end if;

  v_target_profile_id := case
    when v_request.actor_id = v_viewer_profile.id then v_request.recipient_id
    else v_request.actor_id
  end;

  select profile.*
    into v_target_profile
  from public.profiles profile
  where profile.id = v_target_profile_id
    and profile.deleted_at is null
  limit 1;

  if v_target_profile.id is null then
    raise exception 'target profile not found' using errcode = '42501';
  end if;

  select coalesce(reflection.selected_reasons, '{}'::text[])
    into v_selected_reasons
  from public.intent_reflections reflection
  where reflection.intent_request_id = p_intent_request_id
    and reflection.owner_profile_id = v_viewer_profile.id
  limit 1;

  return query
  with viewer_interests as (
    select coalesce(array_agg(distinct interest.name order by interest.name), '{}'::text[]) as names
    from public.profile_interests profile_interest
    join public.interests interest on interest.id = profile_interest.interest_id
    where profile_interest.profile_id = v_viewer_profile.id
  ),
  target_interests as (
    select coalesce(array_agg(distinct interest.name order by interest.name), '{}'::text[]) as names
    from public.profile_interests profile_interest
    join public.interests interest on interest.id = profile_interest.interest_id
    where profile_interest.profile_id = v_target_profile.id
  ),
  base_candidates as (
    select
      profile.id,
      profile.full_name,
      profile.age,
      profile.avatar_url,
      profile.city,
      profile.region,
      profile.current_country,
      profile.current_country_code,
      profile.religion::text as religion,
      profile.looking_for,
      profile.wants_children,
      profile.love_language,
      profile.personality_type,
      profile.verification_level,
      profile.phone_verified,
      profile.profile_video,
      profile.latitude,
      profile.longitude,
      profile.online,
      profile.last_active,
      profile.created_at,
      left(regexp_replace(coalesce(profile.bio, ''), '\s+', ' ', 'g'), 160) as bio_snippet,
      greatest(
        coalesce(array_length(profile.photos, 1), 0),
        case
          when profile.avatar_url is not null and btrim(profile.avatar_url) <> '' then 1
          else 0
        end
      ) as photo_count,
      (
        v_viewer_profile.min_age_interest is null
        or v_viewer_profile.max_age_interest is null
        or profile.age between v_viewer_profile.min_age_interest and v_viewer_profile.max_age_interest
      ) as within_viewer_age_pref,
      (
        v_target_profile.min_age_interest is null
        or v_target_profile.max_age_interest is null
        or profile.age between v_target_profile.min_age_interest and v_target_profile.max_age_interest
      ) as within_target_age_pref,
      (
        v_viewer_profile.gender is null
        or v_viewer_profile.gender not in ('MALE', 'FEMALE')
        or profile.gender is null
        or profile.gender not in ('MALE', 'FEMALE')
        or (v_viewer_profile.gender = 'MALE' and profile.gender = 'FEMALE')
        or (v_viewer_profile.gender = 'FEMALE' and profile.gender = 'MALE')
      ) as viewer_binary_gender_match
    from public.profiles profile
    where profile.id <> v_viewer_profile.id
      and profile.id <> v_target_profile.id
      and profile.deleted_at is null
      and profile.profile_completed is true
      and coalesce(profile.discoverable_in_vibes, true) = true
      and profile.user_id is not null
      and profile.user_id <> v_viewer_profile.user_id
      and profile.full_name is not null
      and profile.age is not null
      and not exists (
        select 1
        from public.intent_requests request_row
        where (
          (request_row.actor_id = v_viewer_profile.id and request_row.recipient_id = profile.id)
          or (request_row.actor_id = profile.id and request_row.recipient_id = v_viewer_profile.id)
        )
          and (
            request_row.status in ('pending', 'accepted', 'matched')
            or (
              request_row.status = 'passed'
              and request_row.created_at > now() - interval '21 days'
            )
          )
      )
      and not exists (
        select 1
        from public.matches match_row
        where (match_row.user1_id = v_viewer_profile.id and match_row.user2_id = profile.id)
           or (match_row.user1_id = profile.id and match_row.user2_id = v_viewer_profile.id)
      )
      and not exists (
        select 1
        from public.blocks block_row
        where (block_row.blocker_id = v_viewer_profile.user_id and block_row.blocked_id = profile.user_id)
           or (block_row.blocker_id = profile.user_id and block_row.blocked_id = v_viewer_profile.user_id)
      )
      and coalesce((
        select swipe_row.action::text
        from public.swipes swipe_row
        where swipe_row.swiper_id = v_viewer_profile.id
          and swipe_row.target_id = profile.id
        order by swipe_row.created_at desc, swipe_row.id desc
        limit 1
      ), '') <> 'PASS'
  ),
  tiered_candidates as (
    select base_candidate.*, 0::integer as candidate_tier
    from base_candidates base_candidate
    where base_candidate.within_viewer_age_pref
      and base_candidate.within_target_age_pref
      and base_candidate.viewer_binary_gender_match

    union all

    select base_candidate.*, 1::integer as candidate_tier
    from base_candidates base_candidate
    where base_candidate.within_viewer_age_pref
      and base_candidate.viewer_binary_gender_match

    union all

    select base_candidate.*, 2::integer as candidate_tier
    from base_candidates base_candidate
    where base_candidate.within_target_age_pref
      and base_candidate.viewer_binary_gender_match

    union all

    select base_candidate.*, 3::integer as candidate_tier
    from base_candidates base_candidate
    where base_candidate.viewer_binary_gender_match
  ),
  candidate_selection as (
    select selected.*
    from (
      select
        tiered_candidate.*,
        row_number() over (
          partition by tiered_candidate.id
          order by tiered_candidate.candidate_tier asc
        ) as tier_rank
      from tiered_candidates tiered_candidate
    ) selected
    where selected.tier_rank = 1
  ),
  enriched as (
    select
      candidate.id,
      candidate.full_name,
      candidate.age,
      candidate.avatar_url,
      candidate.city,
      candidate.region,
      candidate.current_country,
      candidate.current_country_code,
      candidate.religion,
      candidate.looking_for,
      candidate.wants_children,
      candidate.love_language,
      candidate.personality_type,
      candidate.verification_level,
      candidate.phone_verified,
      coalesce(candidate_interest_names.names, '{}'::text[]) as interests,
      coalesce(shared_target.shared_interest_names, '{}'::text[]) as shared_interest_names,
      coalesce(shared_target.shared_interest_count, 0) as shared_interest_count,
      coalesce(shared_viewer.shared_interest_count, 0) as viewer_shared_interest_count,
      prompt.prompt_title,
      prompt.prompt_answer,
      nullif(candidate.bio_snippet, '') as bio_snippet,
      candidate.profile_video,
      candidate.latitude,
      candidate.longitude,
      candidate.online,
      candidate.last_active,
      candidate.photo_count,
      candidate.candidate_tier,
      (
        nullif(lower(btrim(coalesce(candidate.region, ''))), '') is not null
        and nullif(lower(btrim(coalesce(v_target_profile.region, ''))), '') is not null
        and lower(btrim(candidate.region)) = lower(btrim(v_target_profile.region))
      ) as same_region,
      (
        nullif(lower(btrim(coalesce(candidate.religion, ''))), '') is not null
        and nullif(lower(btrim(coalesce(v_target_profile.religion::text, ''))), '') is not null
        and lower(btrim(candidate.religion)) = lower(btrim(v_target_profile.religion::text))
      ) as same_religion,
      (
        nullif(lower(btrim(coalesce(candidate.looking_for, ''))), '') is not null
        and nullif(lower(btrim(coalesce(v_target_profile.looking_for, ''))), '') is not null
        and lower(btrim(candidate.looking_for)) = lower(btrim(v_target_profile.looking_for))
      ) as same_looking_for
    from candidate_selection candidate
    left join lateral (
      select coalesce(array_agg(distinct interest.name order by interest.name), '{}'::text[]) as names
      from public.profile_interests profile_interest
      join public.interests interest on interest.id = profile_interest.interest_id
      where profile_interest.profile_id = candidate.id
    ) candidate_interest_names on true
    cross join target_interests
    cross join viewer_interests
    left join lateral (
      select
        count(*)::integer as shared_interest_count,
        (coalesce(array_agg(interest.name order by interest.name), '{}'::text[]))[1:4] as shared_interest_names
      from public.profile_interests profile_interest
      join public.interests interest on interest.id = profile_interest.interest_id
      where profile_interest.profile_id = candidate.id
        and interest.name = any(target_interests.names)
    ) shared_target on true
    left join lateral (
      select count(*)::integer as shared_interest_count
      from public.profile_interests profile_interest
      join public.interests interest on interest.id = profile_interest.interest_id
      where profile_interest.profile_id = candidate.id
        and interest.name = any(viewer_interests.names)
    ) shared_viewer on true
    left join lateral (
      select
        profile_prompt.prompt_title,
        profile_prompt.answer as prompt_answer
      from public.profile_prompts profile_prompt
      where profile_prompt.profile_id = candidate.id
        and profile_prompt.answer is not null
        and btrim(profile_prompt.answer) <> ''
      order by profile_prompt.updated_at desc nulls last, profile_prompt.created_at desc, profile_prompt.id desc
      limit 1
    ) prompt on true
  ),
  scored as (
    select
      enriched.*,
      (
        enriched.profile_video is not null
        and btrim(enriched.profile_video) <> ''
      ) as has_intro_video,
      case
        when v_viewer_profile.latitude is null
          or v_viewer_profile.longitude is null
          or enriched.latitude is null
          or enriched.longitude is null
          then null::double precision
        else (
          6371 * 2 * asin(
            sqrt(
              power(sin(radians((enriched.latitude - v_viewer_profile.latitude) / 2)), 2)
              + cos(radians(v_viewer_profile.latitude))
              * cos(radians(enriched.latitude))
              * power(sin(radians((enriched.longitude - v_viewer_profile.longitude) / 2)), 2)
            )
          )
        )
      end as distance_km,
      coalesce((enriched.online = true or enriched.last_active > now() - interval '20 minutes'), false) as active_now,
      coalesce((enriched.last_active > now() - interval '3 days'), false) as recently_active,
      (
        least(enriched.shared_interest_count, 4) * (
          case
            when 'interests_lifestyle' = any(v_selected_reasons) then 3.4
            else 2.5
          end
        )
        + case
            when enriched.same_looking_for then
              case
                when 'relationship_intent' = any(v_selected_reasons) then 4.8
                else 3.2
              end
            else 0
          end
        + case
            when enriched.same_religion then
              case
                when 'shared_values' = any(v_selected_reasons)
                  or 'faith_family' = any(v_selected_reasons)
                  then 3.6
                else 1.3
              end
            else 0
          end
        + case
            when 'faith_family' = any(v_selected_reasons)
              and nullif(lower(btrim(coalesce(enriched.wants_children, ''))), '') is not null
              and nullif(lower(btrim(coalesce(v_target_profile.wants_children, ''))), '') is not null
              and lower(btrim(enriched.wants_children)) = lower(btrim(v_target_profile.wants_children))
              then 2.8
            else 0
          end
        + case
            when 'personality' = any(v_selected_reasons)
              and nullif(lower(btrim(coalesce(enriched.personality_type, ''))), '') is not null
              and nullif(lower(btrim(coalesce(v_target_profile.personality_type, ''))), '') is not null
              and lower(btrim(enriched.personality_type)) = lower(btrim(v_target_profile.personality_type))
              then 2.1
            else 0
          end
        + case
            when 'personality' = any(v_selected_reasons)
              and nullif(lower(btrim(coalesce(enriched.love_language, ''))), '') is not null
              and nullif(lower(btrim(coalesce(v_target_profile.love_language, ''))), '') is not null
              and lower(btrim(enriched.love_language)) = lower(btrim(v_target_profile.love_language))
              then 1.9
            else 0
          end
        + case
            when 'culture_location' = any(v_selected_reasons) and enriched.same_region then 1.7
            when 'culture_location' = any(v_selected_reasons)
              and nullif(lower(btrim(coalesce(enriched.current_country, ''))), '') is not null
              and nullif(lower(btrim(coalesce(v_target_profile.current_country, ''))), '') is not null
              and lower(btrim(enriched.current_country)) = lower(btrim(v_target_profile.current_country))
              then 1.2
            else 0
          end
        + least(enriched.viewer_shared_interest_count, 2) * 0.7
      )::double precision as closure_similarity_score,
      (
        case when enriched.online = true or enriched.last_active > now() - interval '20 minutes' then 4.0 else 0 end
        + case when enriched.last_active > now() - interval '24 hours' then 1.7 when enriched.last_active > now() - interval '3 days' then 0.8 else 0 end
        + case when enriched.profile_video is not null and btrim(enriched.profile_video) <> '' then 2.2 else 0 end
        + case when coalesce(enriched.phone_verified, false) or coalesce(enriched.verification_level, 0) > 0 then 1.8 else 0 end
        + case when enriched.prompt_title is not null then 1.1 else 0 end
        + case
            when char_length(coalesce(enriched.bio_snippet, '')) >= 120 then 0.8
            when char_length(coalesce(enriched.bio_snippet, '')) >= 50 then 0.35
            else 0
          end
        + case
            when enriched.photo_count >= 3 then 0.6
            when enriched.photo_count = 2 then 0.25
            else 0
          end
      )::double precision as closure_timing_score,
      (
        least(
          (
            case
              when nullif(lower(btrim(coalesce(enriched.region, ''))), '') is not null
                and nullif(lower(btrim(coalesce(v_target_profile.region, ''))), '') is not null
                and lower(btrim(enriched.region)) <> lower(btrim(v_target_profile.region))
                then 1
              else 0
            end
            + case
                when nullif(lower(btrim(coalesce(enriched.current_country, ''))), '') is not null
                  and nullif(lower(btrim(coalesce(v_target_profile.current_country, ''))), '') is not null
                  and lower(btrim(enriched.current_country)) <> lower(btrim(v_target_profile.current_country))
                  then 1
                else 0
              end
            + case
                when nullif(lower(btrim(coalesce(enriched.personality_type, ''))), '') is not null
                  and nullif(lower(btrim(coalesce(v_target_profile.personality_type, ''))), '') is not null
                  and lower(btrim(enriched.personality_type)) <> lower(btrim(v_target_profile.personality_type))
                  then 1
                else 0
              end
            + case
                when nullif(lower(btrim(coalesce(enriched.religion, ''))), '') is not null
                  and nullif(lower(btrim(coalesce(v_target_profile.religion::text, ''))), '') is not null
                  and lower(btrim(enriched.religion)) <> lower(btrim(v_target_profile.religion::text))
                  then 1
                else 0
              end
          )::double precision,
          3
        ) * 1.35
        + case when enriched.same_looking_for then 1.4 else 0 end
        + case when enriched.shared_interest_count > 0 then 0.9 else 0 end
      )::double precision as closure_freshness_score
    from enriched
  ),
  ranked as (
    select
      scored.*,
      (
        case
          when scored.shared_interest_count >= 2 and scored.same_looking_for then 3
          when scored.shared_interest_count >= 1 or scored.same_looking_for or scored.same_religion then 2
          when scored.has_intro_video or scored.active_now or scored.prompt_title is not null then 1
          else 0
        end
      )::integer as quality_band,
      (
        scored.closure_similarity_score * 1.18
        + scored.closure_timing_score * 0.78
        + scored.closure_freshness_score * 0.56
        + case when scored.distance_km is null then 0 when scored.distance_km <= 25 then 1.4 when scored.distance_km <= 100 then 0.6 when scored.distance_km <= 500 then 0 else -0.6 end
        - case
            when scored.candidate_tier = 1 then 0.85
            when scored.candidate_tier = 2 then 1.1
            when scored.candidate_tier = 3 then 1.45
            else 0
          end
      )::double precision as closure_rank_score
    from scored
  ),
  diversified as (
    select
      ranked.*,
      row_number() over (
        partition by coalesce(nullif(lower(btrim(coalesce(ranked.region, ''))), ''), '<<none>>')
        order by ranked.quality_band desc, ranked.closure_rank_score desc, ranked.distance_km asc nulls last, ranked.last_active desc nulls last, ranked.id desc
      ) as region_rank,
      row_number() over (
        partition by
          case
            when ranked.shared_interest_count >= 2 then 'deep_overlap'
            when ranked.same_looking_for then 'intent'
            when ranked.has_intro_video then 'intro'
            when ranked.active_now then 'active'
            else 'general'
          end
        order by ranked.quality_band desc, ranked.closure_rank_score desc, ranked.distance_km asc nulls last, ranked.last_active desc nulls last, ranked.id desc
      ) as archetype_rank
    from ranked
  )
  select
    diversified.id,
    diversified.full_name,
    diversified.age,
    diversified.avatar_url,
    diversified.city,
    diversified.region,
    diversified.current_country,
    diversified.current_country_code,
    diversified.religion,
    diversified.looking_for,
    diversified.wants_children,
    diversified.love_language,
    diversified.personality_type,
    diversified.verification_level,
    diversified.phone_verified,
    diversified.interests,
    (array_remove(array[
      case when diversified.shared_interest_count > 0 then 'Shared spark' end,
      case when diversified.same_looking_for then 'Same intent' end,
      case when diversified.same_religion then 'Shared values' end,
      case when diversified.has_intro_video then 'Intro video' end,
      case when diversified.active_now then 'Active now' end,
      case when diversified.prompt_title is not null then 'Strong prompt' end
    ], null))[1:4] as short_tags,
    diversified.has_intro_video,
    diversified.distance_km,
    diversified.shared_interest_names,
    diversified.shared_interest_count,
    diversified.prompt_title,
    diversified.prompt_answer,
    diversified.bio_snippet,
    diversified.same_region,
    diversified.same_religion,
    diversified.same_looking_for,
    diversified.active_now,
    diversified.recently_active,
    diversified.candidate_tier,
    diversified.quality_band,
    diversified.closure_similarity_score,
    diversified.closure_timing_score,
    diversified.closure_freshness_score,
    diversified.closure_rank_score
  from diversified
  order by
    diversified.quality_band desc,
    (
      diversified.closure_rank_score
      - greatest(diversified.region_rank - 2, 0) * 0.55
      - greatest(diversified.archetype_rank - 2, 0) * 0.35
    ) desc,
    diversified.distance_km asc nulls last,
    diversified.last_active desc nulls last,
    diversified.id desc
  limit greatest(1, least(coalesce(p_limit, 28), 40));
end;
$$;


ALTER FUNCTION "public"."rpc_get_closure_to_clarity_candidates"("p_intent_request_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_disconnected_signin_providers"() RETURNS "text"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception 'authentication required';
  end if;

  return coalesce(
    (
      select array_agg(provider order by provider)
      from public.account_disconnected_signin_providers
      where user_id = v_user_id
        and active = true
    ),
    array[]::text[]
  );
end;
$$;


ALTER FUNCTION "public"."rpc_get_disconnected_signin_providers"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_intent_reflection"("p_intent_request_id" "uuid") RETURNS "text"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_owner_profile_id uuid;
  v_selected_reasons text[];
begin
  if auth.uid() is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  select profile.id
    into v_owner_profile_id
  from public.profiles profile
  where profile.user_id = auth.uid()
    and profile.deleted_at is null
  limit 1;

  if v_owner_profile_id is null then
    raise exception 'profile required' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.intent_requests request_row
    where request_row.id = p_intent_request_id
      and (
        request_row.actor_id = v_owner_profile_id
        or request_row.recipient_id = v_owner_profile_id
      )
  ) then
    raise exception 'intent request not found' using errcode = '42501';
  end if;

  select reflection.selected_reasons
    into v_selected_reasons
  from public.intent_reflections reflection
  where reflection.intent_request_id = p_intent_request_id
    and reflection.owner_profile_id = v_owner_profile_id;

  return coalesce(v_selected_reasons, '{}'::text[]);
end;
$$;


ALTER FUNCTION "public"."rpc_get_intent_reflection"("p_intent_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_merged_account_redirect"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_record public.merged_accounts%rowtype;
  v_target_email text;
  v_target_email_hint text;
  v_target_email_local text;
  v_target_email_domain text;
  v_target_methods text[];
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  select *
    into v_record
  from public.merged_accounts
  where source_user_id = auth.uid()
    and status = 'active'
  limit 1;

  if v_record.source_user_id is null then
    return jsonb_build_object('is_merged', false);
  end if;

  select u.email
    into v_target_email
  from auth.users u
  where u.id = v_record.target_user_id
  limit 1;

  if v_target_email is not null and position('@' in v_target_email) > 1 then
    v_target_email_local := split_part(v_target_email, '@', 1);
    v_target_email_domain := split_part(v_target_email, '@', 2);
    v_target_email_hint :=
      left(v_target_email_local, 1)
      || repeat('*', greatest(char_length(v_target_email_local) - 1, 2))
      || '@'
      || left(v_target_email_domain, 1)
      || repeat('*', greatest(char_length(v_target_email_domain) - 3, 2))
      || right(v_target_email_domain, 2);
  end if;

  select coalesce(array_agg(distinct lower(i.provider) order by lower(i.provider)), array[]::text[])
    into v_target_methods
  from auth.identities i
  where i.user_id = v_record.target_user_id;

  return jsonb_build_object(
    'is_merged', true,
    'target_user_id', v_record.target_user_id,
    'target_profile_id', v_record.target_profile_id,
    'merge_case_id', v_record.merge_case_id,
    'kept_email_hint', v_target_email_hint,
    'kept_sign_in_methods', to_jsonb(coalesce(v_target_methods, array[]::text[])),
    'message', 'This sign-in method is attached to an older Betweener account that has already been merged.'
  );
end;
$$;


ALTER FUNCTION "public"."rpc_get_merged_account_redirect"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_my_circle_invitation_count"("p_profile_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_count integer := 0;
begin
  if auth.uid() is null then
    return 0;
  end if;

  if not exists (
    select 1
    from public.profiles recipient
    where recipient.id = p_profile_id
      and recipient.user_id = auth.uid()
      and recipient.deleted_at is null
  ) then
    return 0;
  end if;

  select count(*)::integer
    into v_count
  from public.circle_invitations ci
  where ci.invited_profile_id = p_profile_id
    and ci.status = 'pending'
    and ci.expires_at > timezone('utc'::text, now());

  return coalesce(v_count, 0);
end;
$$;


ALTER FUNCTION "public"."rpc_get_my_circle_invitation_count"("p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_my_circle_love_seat_nominations"("p_profile_id" "uuid", "p_circle_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "circle_id" "uuid", "circle_name" "text", "featured_profile_id" "uuid", "nominated_by_profile_id" "uuid", "nominator_name" "text", "quote" "text", "reason" "text", "status" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_profile_id
      and p.user_id = auth.uid()
      and p.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  return query
  select
    cls.id,
    cls.circle_id,
    c.name as circle_name,
    cls.featured_profile_id,
    cls.nominated_by_profile_id,
    coalesce(nullif(btrim(nominator.full_name), ''), 'Circle host') as nominator_name,
    cls.quote,
    cls.reason,
    cls.status,
    cls.created_at
  from public.circle_love_seats cls
  join public.circles c on c.id = cls.circle_id
  left join public.profiles nominator on nominator.id = cls.nominated_by_profile_id
  where cls.featured_profile_id = p_profile_id
    and cls.status = 'pending_user_approval'
    and (p_circle_id is null or cls.circle_id = p_circle_id)
  order by cls.created_at desc;
end;
$$;


ALTER FUNCTION "public"."rpc_get_my_circle_love_seat_nominations"("p_profile_id" "uuid", "p_circle_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_my_moment_recent_viewers"("p_moment_id" "uuid", "p_limit" integer DEFAULT 40) RETURNS TABLE("viewer_user_id" "uuid", "viewed_at" timestamp with time zone, "profile_id" "uuid", "full_name" "text", "avatar_url" "text", "current_country_code" "text", "is_match" boolean, "viewed_moment_count" integer, "is_repeat_viewer" boolean)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  with owner_moments as (
    select id
    from public.moments
    where user_id = auth.uid()
  ),
  viewer_totals as (
    select
      mv.viewer_user_id,
      count(*)::integer as viewed_moment_count
    from public.moment_views mv
    join owner_moments om
      on om.id = mv.moment_id
    group by mv.viewer_user_id
  )
  select
    mv.viewer_user_id,
    mv.viewed_at,
    pr.id as profile_id,
    pr.full_name,
    pr.avatar_url,
    pr.current_country_code,
    public.is_match(auth.uid(), mv.viewer_user_id) as is_match,
    coalesce(vt.viewed_moment_count, 0) as viewed_moment_count,
    coalesce(vt.viewed_moment_count, 0) > 1 as is_repeat_viewer
  from public.moment_views mv
  join public.moments m
    on m.id = mv.moment_id
  left join public.profiles pr
    on pr.user_id = mv.viewer_user_id
  left join viewer_totals vt
    on vt.viewer_user_id = mv.viewer_user_id
  where mv.moment_id = p_moment_id
    and m.user_id = auth.uid()
  order by mv.viewed_at desc
  limit greatest(1, least(coalesce(p_limit, 40), 100));
$$;


ALTER FUNCTION "public"."rpc_get_my_moment_recent_viewers"("p_moment_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_my_moment_view_stats"("p_moment_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("moment_id" "uuid", "unique_viewers" integer)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  select
    m.id as moment_id,
    count(mv.viewer_user_id)::integer as unique_viewers
  from public.moments m
  left join public.moment_views mv
    on mv.moment_id = m.id
  where m.user_id = auth.uid()
    and (
      p_moment_ids is null
      or cardinality(p_moment_ids) = 0
      or m.id = any(p_moment_ids)
    )
  group by m.id;
$$;


ALTER FUNCTION "public"."rpc_get_my_moment_view_stats"("p_moment_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_my_moment_view_time_insights"("p_days" integer DEFAULT 21, "p_utc_offset_minutes" integer DEFAULT 0) RETURNS TABLE("local_hour" integer, "weekday_bucket" integer, "view_count" integer)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  with scoped_views as (
    select
      mv.viewed_at
      + make_interval(mins => greatest(-720, least(coalesce(p_utc_offset_minutes, 0), 840))) as local_viewed_at
    from public.moment_views mv
    join public.moments m
      on m.id = mv.moment_id
    where m.user_id = auth.uid()
      and mv.viewed_at >= now() - (greatest(3, least(coalesce(p_days, 21), 90)) || ' days')::interval
  )
  select
    extract(hour from local_viewed_at)::integer as local_hour,
    extract(dow from local_viewed_at)::integer as weekday_bucket,
    count(*)::integer as view_count
  from scoped_views
  group by 1, 2
  order by view_count desc, weekday_bucket asc, local_hour asc;
$$;


ALTER FUNCTION "public"."rpc_get_my_moment_view_time_insights"("p_days" integer, "p_utc_offset_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_my_moment_viewer_segments"("p_days" integer DEFAULT 30) RETURNS TABLE("total_viewers" integer, "matched_viewers" integer, "non_match_viewers" integer, "ghana_viewers" integer, "abroad_viewers" integer, "repeat_viewers" integer, "first_time_viewers" integer)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  with owner_moments as (
    select id
    from public.moments
    where user_id = auth.uid()
  ),
  scoped as (
    select
      mv.viewer_user_id,
      max(mv.viewed_at) as last_viewed_at,
      count(*)::integer as viewed_moment_count
    from public.moment_views mv
    join owner_moments om
      on om.id = mv.moment_id
    where mv.viewed_at >= now() - (greatest(3, least(coalesce(p_days, 30), 120)) || ' days')::interval
    group by mv.viewer_user_id
  )
  select
    count(*)::integer as total_viewers,
    count(*) filter (where public.is_match(auth.uid(), scoped.viewer_user_id))::integer as matched_viewers,
    count(*) filter (where not public.is_match(auth.uid(), scoped.viewer_user_id))::integer as non_match_viewers,
    count(*) filter (where coalesce(pr.current_country_code, '') = 'GH')::integer as ghana_viewers,
    count(*) filter (where coalesce(pr.current_country_code, '') <> '' and coalesce(pr.current_country_code, '') <> 'GH')::integer as abroad_viewers,
    count(*) filter (where scoped.viewed_moment_count > 1)::integer as repeat_viewers,
    count(*) filter (where scoped.viewed_moment_count <= 1)::integer as first_time_viewers
  from scoped
  left join public.profiles pr
    on pr.user_id = scoped.viewer_user_id;
$$;


ALTER FUNCTION "public"."rpc_get_my_moment_viewer_segments"("p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_my_premium_state"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_plan public.subscription_type := 'FREE';
  resolved_started_at timestamptz;
  resolved_ends_at timestamptz;
  resolved_is_active boolean := false;
  viewer_profile_id uuid;
  active_boost record;
begin
  if auth.uid() is null then
    return jsonb_build_object(
      'plan', 'FREE',
      'is_active', false,
      'started_at', null,
      'ends_at', null,
      'has_active_boost', false,
      'active_boost_ends_at', null
    );
  end if;

  select
    s.type,
    s.started_at,
    s.ends_at,
    s.is_active
    into
      resolved_plan,
      resolved_started_at,
      resolved_ends_at,
      resolved_is_active
  from public.subscriptions s
  where s.user_id = auth.uid()
    and s.is_active = true
    and s.ends_at > timezone('utc'::text, now())
  order by
    case s.type
      when 'GOLD' then 2
      when 'SILVER' then 1
      else 0
    end desc,
    s.ends_at desc
  limit 1;

  select p.id
    into viewer_profile_id
  from public.profiles p
  where p.user_id = auth.uid()
    and p.deleted_at is null
  limit 1;

  if viewer_profile_id is not null then
    select
      pb.id,
      pb.ends_at,
      pb.boost_type,
      pb.audience_mode,
      pb.focus_mode
      into active_boost
    from public.profile_boosts pb
    where pb.user_id = viewer_profile_id
      and pb.starts_at <= timezone('utc'::text, now())
      and pb.ends_at > timezone('utc'::text, now())
    order by pb.ends_at desc
    limit 1;
  end if;

  return jsonb_strip_nulls(jsonb_build_object(
    'plan', coalesce(resolved_plan, 'FREE'),
    'is_active', coalesce(resolved_is_active, false),
    'started_at', resolved_started_at,
    'ends_at', resolved_ends_at,
    'has_active_boost', active_boost.id is not null,
    'active_boost_ends_at', active_boost.ends_at,
    'active_boost_id', active_boost.id,
    'active_boost_type', active_boost.boost_type,
    'active_boost_audience_mode', active_boost.audience_mode,
    'active_boost_focus_mode', active_boost.focus_mode
  ));
end;
$$;


ALTER FUNCTION "public"."rpc_get_my_premium_state"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_my_profile_interest"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_profile_id uuid;
  v_plan text;
  v_metrics jsonb;
  v_people jsonb := '[]'::jsonb;
  v_timeline jsonb := '[]'::jsonb;
  v_window interval;
begin
  if auth.uid() is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  select profile.id
    into v_profile_id
  from public.profiles profile
  where profile.user_id = auth.uid()
    and profile.deleted_at is null
  limit 1;

  if v_profile_id is null then
    raise exception 'profile required';
  end if;

  v_plan := public.get_active_subscription_plan(auth.uid())::text;
  v_window := case when v_plan = 'GOLD' then interval '30 days' else interval '7 days' end;

  with recent as (
    select event_row.*
    from public.vibes_events event_row
    join public.profiles actor
      on actor.id = event_row.viewer_profile_id
     and actor.deleted_at is null
    where event_row.target_profile_id = v_profile_id
      and event_row.created_at > timezone('utc'::text, now()) - interval '7 days'
      and event_row.viewer_profile_id is not null
  ),
  recent_visit_counts as (
    select
      recent.viewer_profile_id,
      count(*) filter (where recent.event_type = 'profile_opened')::integer as profile_open_count,
      count(*) filter (where recent.event_type = 'full_profile_opened')::integer as full_open_count,
      count(*) filter (where recent.event_type in ('profile_opened', 'full_profile_opened'))::integer as total_open_count
    from recent
    group by recent.viewer_profile_id
  ),
  recent_saves as (
    select
      save_row.viewer_profile_id,
      max(save_row.created_at) as saved_at
    from public.profile_saves save_row
    join public.profiles actor
      on actor.id = save_row.viewer_profile_id
     and actor.deleted_at is null
    where save_row.target_profile_id = v_profile_id
      and save_row.created_at > timezone('utc'::text, now()) - interval '7 days'
    group by save_row.viewer_profile_id
  )
  select jsonb_build_object(
    'profile_visits', (
      select count(*)
      from recent_visit_counts
      where total_open_count > 0
    ),
    'unique_visitors', (
      select count(*)
      from recent_visit_counts
      where total_open_count > 0
    ),
    'profile_visit_events', (
      select coalesce(sum(total_open_count), 0)
      from recent_visit_counts
    ),
    'intro_watches', (
      select count(distinct recent.viewer_profile_id)
      from recent
      where recent.event_type in ('intro_played', 'intro_completed')
    ),
    'intro_watch_events', (
      select count(*)
      from recent
      where recent.event_type in ('intro_played', 'intro_completed')
    ),
    'profile_saves', (
      select count(*)
      from recent_saves
    ),
    'full_opens', (
      select count(distinct recent.viewer_profile_id)
      from recent
      where recent.event_type = 'full_profile_opened'
    ),
    'full_open_events', (
      select count(*)
      from recent
      where recent.event_type = 'full_profile_opened'
    ),
    'repeat_visits', (
      select count(*)
      from recent_visit_counts
      where total_open_count > 1
    ),
    'repeat_visit_events', (
      select coalesce(sum(greatest(total_open_count - 1, 0)), 0)
      from recent_visit_counts
    ),
    'intent_opens', (
      select count(distinct recent.viewer_profile_id)
      from recent
      where recent.event_type = 'intent_opened'
    ),
    'intent_open_events', (
      select count(*)
      from recent
      where recent.event_type = 'intent_opened'
    )
  ) into v_metrics;

  with scoped as (
    select event_row.*
    from public.vibes_events event_row
    join public.profiles actor
      on actor.id = event_row.viewer_profile_id
     and actor.deleted_at is null
    where event_row.target_profile_id = v_profile_id
      and event_row.viewer_profile_id is not null
      and event_row.event_type in (
        'profile_opened', 'full_profile_opened', 'intro_played',
        'intro_completed', 'profile_saved', 'profile_unsaved', 'intent_opened'
      )
      and event_row.created_at > timezone('utc'::text, now()) - v_window
  ),
  current_saves as (
    select
      save_row.viewer_profile_id,
      max(save_row.created_at) as saved_at
    from public.profile_saves save_row
    join public.profiles actor
      on actor.id = save_row.viewer_profile_id
     and actor.deleted_at is null
    where save_row.target_profile_id = v_profile_id
      and save_row.created_at > timezone('utc'::text, now()) - v_window
    group by save_row.viewer_profile_id
  ),
  signal_people as (
    select scoped.viewer_profile_id
    from scoped
    union
    select current_saves.viewer_profile_id
    from current_saves
  ),
  grouped as (
    select
      signal_people.viewer_profile_id,
      max(scoped.created_at) as last_event_at,
      count(*) filter (where scoped.event_type = 'profile_opened')::integer as profile_open_count,
      count(*) filter (where scoped.event_type = 'full_profile_opened')::integer as full_open_count,
      count(*) filter (where scoped.event_type in ('profile_opened', 'full_profile_opened'))::integer as visit_count,
      count(*) filter (where scoped.event_type = 'intro_played')::integer as intro_play_count,
      count(*) filter (where scoped.event_type = 'intro_completed')::integer as intro_complete_count,
      count(*) filter (where scoped.event_type in ('intro_played', 'intro_completed'))::integer as intro_watch_count,
      count(*) filter (where scoped.event_type = 'profile_saved')::integer as save_event_count,
      count(*) filter (where scoped.event_type = 'profile_unsaved')::integer as unsave_event_count,
      count(*) filter (where scoped.event_type = 'intent_opened')::integer as intent_open_count,
      greatest(count(*) filter (where scoped.event_type in ('profile_opened', 'full_profile_opened')) - 1, 0)::integer as repeat_visit_count
    from signal_people
    left join scoped
      on scoped.viewer_profile_id = signal_people.viewer_profile_id
    group by signal_people.viewer_profile_id
  ),
  latest_signal as (
    select distinct on (scoped.viewer_profile_id)
      scoped.viewer_profile_id,
      scoped.event_type,
      scoped.created_at
    from scoped
    order by scoped.viewer_profile_id, scoped.created_at desc, scoped.id desc
  ),
  enriched as (
    select
      grouped.viewer_profile_id,
      case
        when grouped.last_event_at is null then current_saves.saved_at
        when current_saves.saved_at is null then grouped.last_event_at
        else greatest(grouped.last_event_at, current_saves.saved_at)
      end as last_signal_at,
      grouped.profile_open_count,
      grouped.full_open_count,
      grouped.visit_count,
      grouped.intro_play_count,
      grouped.intro_complete_count,
      grouped.intro_watch_count,
      case
        when current_saves.viewer_profile_id is not null then greatest(grouped.save_event_count, 1)
        else 0
      end::integer as profile_save_count,
      grouped.unsave_event_count,
      current_saves.viewer_profile_id is not null as saved_profile,
      grouped.intent_open_count,
      grouped.repeat_visit_count,
      grouped.intro_watch_count > 0 as watched_intro,
      grouped.intent_open_count > 0 as opened_intent,
      latest_signal.event_type as last_signal_type,
      public.profile_interest_score(
        grouped.profile_open_count,
        grouped.full_open_count,
        grouped.intro_watch_count,
        case
          when current_saves.viewer_profile_id is not null then greatest(grouped.save_event_count, 1)
          else 0
        end::integer,
        grouped.repeat_visit_count,
        grouped.intent_open_count
      ) as interest_score,
      case
        when coalesce(
          case
            when grouped.last_event_at is null then current_saves.saved_at
            when current_saves.saved_at is null then grouped.last_event_at
            else greatest(grouped.last_event_at, current_saves.saved_at)
          end,
          timezone('utc'::text, now()) - interval '365 days'
        ) > timezone('utc'::text, now()) - interval '24 hours' then 4
        when coalesce(
          case
            when grouped.last_event_at is null then current_saves.saved_at
            when current_saves.saved_at is null then grouped.last_event_at
            else greatest(grouped.last_event_at, current_saves.saved_at)
          end,
          timezone('utc'::text, now()) - interval '365 days'
        ) > timezone('utc'::text, now()) - interval '3 days' then 2
        when coalesce(
          case
            when grouped.last_event_at is null then current_saves.saved_at
            when current_saves.saved_at is null then grouped.last_event_at
            else greatest(grouped.last_event_at, current_saves.saved_at)
          end,
          timezone('utc'::text, now()) - interval '365 days'
        ) > timezone('utc'::text, now()) - interval '7 days' then 1
        else 0
      end as recency_bonus
    from grouped
    left join current_saves
      on current_saves.viewer_profile_id = grouped.viewer_profile_id
    left join latest_signal
      on latest_signal.viewer_profile_id = grouped.viewer_profile_id
  ),
  ranked_people as (
    select
      enriched.*,
      actor.id,
      actor.full_name,
      actor.username,
      actor.avatar_url,
      case
        when enriched.saved_profile and enriched.profile_save_count > 0 then 'profile_saved'
        when not enriched.saved_profile and enriched.last_signal_type = 'profile_unsaved' then 'profile_unsaved'
        when enriched.intent_open_count > 0 then 'intent_opened'
        when enriched.intro_complete_count > 0 then 'intro_completed'
        when enriched.intro_play_count > 1 then 'intro_replayed'
        when enriched.intro_play_count > 0 then 'intro_played'
        when enriched.repeat_visit_count > 0 then 'repeat_visit'
        when enriched.full_open_count > 0 then 'full_profile_opened'
        else 'profile_opened'
      end as dominant_signal,
      enriched.interest_score + enriched.recency_bonus as ranking_score
    from enriched
    join public.profiles actor
      on actor.id = enriched.viewer_profile_id
    where actor.deleted_at is null
    order by ranking_score desc, enriched.last_signal_at desc nulls last
    limit case
      when v_plan = 'GOLD' then 40
      when v_plan = 'SILVER' then 12
      else 8
    end
  )
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'profile_id', ranked_people.id,
    'name', case
      when v_plan = 'FREE' then 'Private member'
      else coalesce(nullif(btrim(ranked_people.full_name), ''), nullif(btrim(ranked_people.username), ''), 'Someone')
    end,
    'avatar_url', ranked_people.avatar_url,
    'last_signal_at', ranked_people.last_signal_at,
    'last_signal_type', ranked_people.last_signal_type,
    'visit_count', ranked_people.visit_count,
    'profile_open_count', ranked_people.profile_open_count,
    'full_open_count', ranked_people.full_open_count,
    'intro_play_count', ranked_people.intro_play_count,
    'intro_complete_count', ranked_people.intro_complete_count,
    'intro_watch_count', ranked_people.intro_watch_count,
    'profile_save_count', ranked_people.profile_save_count,
    'profile_unsave_count', ranked_people.unsave_event_count,
    'intent_open_count', ranked_people.intent_open_count,
    'repeat_visit_count', ranked_people.repeat_visit_count,
    'watched_intro', ranked_people.watched_intro,
    'saved_profile', ranked_people.saved_profile,
    'opened_intent', ranked_people.opened_intent,
    'dominant_signal', ranked_people.dominant_signal,
    'interest_score', ranked_people.interest_score,
    'ranking_score', ranked_people.ranking_score,
    'interest_level', public.profile_interest_level(ranked_people.interest_score),
    'shared_values', case when v_plan = 'GOLD' then (
      select coalesce(jsonb_agg(value_name order by value_name), '[]'::jsonb)
      from (
        select distinct interest.name as value_name
        from public.profile_interests actor_interest
        join public.profile_interests owner_interest
          on owner_interest.interest_id = actor_interest.interest_id
        join public.interests interest on interest.id = actor_interest.interest_id
        where actor_interest.profile_id = ranked_people.id
          and owner_interest.profile_id = v_profile_id
        limit 5
      ) shared
    ) end
  )) order by ranked_people.ranking_score desc, ranked_people.last_signal_at desc nulls last), '[]'::jsonb)
    into v_people
  from ranked_people;

  if v_plan = 'GOLD' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', timeline.id,
      'profile_id', timeline.profile_id,
      'name', timeline.name,
      'avatar_url', timeline.avatar_url,
      'signal', timeline.signal,
      'occurred_at', timeline.occurred_at
    ) order by timeline.occurred_at desc), '[]'::jsonb)
      into v_timeline
    from (
      select
        event_row.id,
        actor.id as profile_id,
        coalesce(
          nullif(btrim(actor.full_name), ''),
          nullif(btrim(actor.username), ''),
          'Someone'
        ) as name,
        actor.avatar_url,
        case
          when event_row.event_type = 'profile_unsaved' then 'profile_unsaved'
          when event_row.event_type = 'intro_played'
            and exists (
              select 1
              from public.vibes_events earlier_intro
              where earlier_intro.viewer_profile_id = event_row.viewer_profile_id
                and earlier_intro.target_profile_id = event_row.target_profile_id
                and earlier_intro.event_type in ('intro_played', 'intro_completed')
                and earlier_intro.created_at < event_row.created_at
                and earlier_intro.created_at > event_row.created_at - interval '30 days'
            ) then 'intro_replayed'
          when event_row.event_type = 'profile_opened'
            and exists (
              select 1
              from public.vibes_events earlier_open
              where earlier_open.viewer_profile_id = event_row.viewer_profile_id
                and earlier_open.target_profile_id = event_row.target_profile_id
                and earlier_open.event_type in ('profile_opened', 'full_profile_opened')
                and earlier_open.created_at < event_row.created_at
                and earlier_open.created_at > event_row.created_at - interval '30 days'
            ) then 'repeat_visit'
          else event_row.event_type
        end as signal,
        event_row.created_at as occurred_at
      from public.vibes_events event_row
      join public.profiles actor
        on actor.id = event_row.viewer_profile_id
       and actor.deleted_at is null
      where event_row.target_profile_id = v_profile_id
        and event_row.event_type in (
          'profile_opened', 'full_profile_opened', 'intro_played',
          'intro_completed', 'profile_saved', 'profile_unsaved', 'intent_opened'
        )
        and event_row.created_at > timezone('utc'::text, now()) - interval '30 days'
      order by event_row.created_at desc
      limit 60
    ) timeline;
  end if;

  return jsonb_build_object(
    'plan', v_plan,
    'window_days', case when v_plan = 'GOLD' then 30 else 7 end,
    'metrics', coalesce(v_metrics, '{}'::jsonb),
    'people', coalesce(v_people, '[]'::jsonb),
    'timeline', coalesce(v_timeline, '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."rpc_get_my_profile_interest"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_my_recent_boost_analytics"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_viewer_profile_id uuid;
  boost_row record;
  unique_viewer_count integer := 0;
  view_count integer := 0;
  unique_intro_viewer_count integer := 0;
  intro_count integer := 0;
  unique_saver_count integer := 0;
  save_count integer := 0;
  unique_intent_viewer_count integer := 0;
  intent_count integer := 0;
  like_count integer := 0;
  accepted_match_count integer := 0;
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  select p.id
    into v_viewer_profile_id
  from public.profiles p
  where p.user_id = auth.uid()
    and p.deleted_at is null
  limit 1;

  if v_viewer_profile_id is null then
    raise exception 'profile required';
  end if;

  select
    pb.id,
    pb.starts_at,
    pb.ends_at,
    pb.created_at,
    pb.boost_type,
    pb.audience_mode,
    pb.focus_mode,
    pb.status
    into boost_row
  from public.profile_boosts pb
  where pb.user_id = v_viewer_profile_id
    and pb.created_at > timezone('utc'::text, now()) - interval '30 days'
  order by pb.ends_at desc, pb.created_at desc
  limit 1;

  if boost_row.id is null then
    return jsonb_build_object(
      'has_boost', false,
      'analytics_meta', jsonb_build_object(
        'trust_filter', 'trusted_viewers_only',
        'is_trust_filtered', true
      ),
      'metrics', jsonb_build_object(
        'unique_viewers', 0,
        'views', 0,
        'unique_intro_viewers', 0,
        'intro_opens', 0,
        'unique_savers', 0,
        'saves', 0,
        'unique_intent_viewers', 0,
        'intent_opens', 0,
        'likes', 0,
        'accepted_matches', 0
      )
    );
  end if;

  select
    count(distinct event_row.viewer_profile_id) filter (
      where event_row.event_type in ('profile_opened', 'full_profile_opened')
        and event_row.viewer_profile_id is not null
    )::integer,
    count(*) filter (where event_row.event_type in ('profile_opened', 'full_profile_opened'))::integer,
    count(distinct event_row.viewer_profile_id) filter (
      where event_row.event_type in ('intro_played', 'intro_completed')
        and event_row.viewer_profile_id is not null
    )::integer,
    count(*) filter (where event_row.event_type in ('intro_played', 'intro_completed'))::integer,
    count(distinct event_row.viewer_profile_id) filter (
      where event_row.event_type = 'profile_saved'
        and event_row.viewer_profile_id is not null
    )::integer,
    count(*) filter (where event_row.event_type = 'profile_saved')::integer,
    count(distinct event_row.viewer_profile_id) filter (
      where event_row.event_type = 'intent_opened'
        and event_row.viewer_profile_id is not null
    )::integer,
    count(*) filter (where event_row.event_type = 'intent_opened')::integer,
    count(*) filter (where event_row.event_type = 'like')::integer
    into unique_viewer_count,
      view_count,
      unique_intro_viewer_count,
      intro_count,
      unique_saver_count,
      save_count,
      unique_intent_viewer_count,
      intent_count,
      like_count
  from public.vibes_events event_row
  where event_row.target_profile_id = v_viewer_profile_id
    and event_row.created_at >= boost_row.starts_at
    and event_row.created_at <= least(boost_row.ends_at, timezone('utc'::text, now()))
    and public.is_trusted_boost_viewer(event_row.viewer_profile_id, v_viewer_profile_id);

  select count(*)::integer
    into accepted_match_count
  from public.matches match_row
  cross join lateral (
    select case
      when match_row.user1_id = v_viewer_profile_id then match_row.user2_id
      else match_row.user1_id
    end as counterpart_profile_id
  ) counterpart
  where match_row.status = 'ACCEPTED'
    and match_row.updated_at >= boost_row.starts_at
    and match_row.updated_at <= least(boost_row.ends_at + interval '24 hours', timezone('utc'::text, now()))
    and (
      match_row.user1_id = v_viewer_profile_id
      or match_row.user2_id = v_viewer_profile_id
    )
    and public.is_trusted_boost_viewer(counterpart.counterpart_profile_id, v_viewer_profile_id);

  return jsonb_build_object(
    'has_boost', true,
    'analytics_meta', jsonb_build_object(
      'trust_filter', 'trusted_viewers_only',
      'is_trust_filtered', true
    ),
    'boost', jsonb_build_object(
      'id', boost_row.id,
      'starts_at', boost_row.starts_at,
      'ends_at', boost_row.ends_at,
      'created_at', boost_row.created_at,
      'boost_type', boost_row.boost_type,
      'audience_mode', boost_row.audience_mode,
      'focus_mode', boost_row.focus_mode,
      'status', boost_row.status,
      'is_active', boost_row.starts_at <= timezone('utc'::text, now()) and boost_row.ends_at > timezone('utc'::text, now())
    ),
    'metrics', jsonb_build_object(
      'unique_viewers', unique_viewer_count,
      'views', view_count,
      'unique_intro_viewers', unique_intro_viewer_count,
      'intro_opens', intro_count,
      'unique_savers', unique_saver_count,
      'saves', save_count,
      'unique_intent_viewers', unique_intent_viewer_count,
      'intent_opens', intent_count,
      'likes', like_count,
      'accepted_matches', accepted_match_count
    )
  );
end;
$$;


ALTER FUNCTION "public"."rpc_get_my_recent_boost_analytics"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_my_saved_profiles"() RETURNS TABLE("profile_id" "uuid", "saved_at" timestamp with time zone, "full_name" "text", "age" integer, "avatar_url" "text", "city" "text", "region" "text", "current_country" "text", "current_country_code" "text", "premium_plan" "text", "is_new_here" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_viewer_profile_id uuid;
begin
  if auth.uid() is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  select profile.id
    into v_viewer_profile_id
  from public.profiles profile
  where profile.user_id = auth.uid()
    and profile.deleted_at is null
  limit 1;

  if v_viewer_profile_id is null then
    raise exception 'profile required' using errcode = '42501';
  end if;

  return query
  select
    target.id as profile_id,
    save_row.created_at as saved_at,
    target.full_name,
    target.age,
    target.avatar_url,
    target.city,
    target.region,
    target.current_country,
    target.current_country_code,
    public.get_active_subscription_plan(target.user_id)::text as premium_plan,
    target.created_at > timezone('utc'::text, now()) - interval '14 days' as is_new_here
  from public.profile_saves save_row
  join public.profiles target
    on target.id = save_row.target_profile_id
  where save_row.viewer_profile_id = v_viewer_profile_id
    and target.deleted_at is null
  order by save_row.created_at desc;
end;
$$;


ALTER FUNCTION "public"."rpc_get_my_saved_profiles"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_my_saved_profiles"("p_include_sandbox_preview" boolean DEFAULT false) RETURNS TABLE("profile_id" "uuid", "saved_at" timestamp with time zone, "full_name" "text", "age" integer, "avatar_url" "text", "city" "text", "region" "text", "current_country" "text", "current_country_code" "text", "premium_plan" "text", "is_new_here" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_viewer_profile_id uuid;
begin
  if auth.uid() is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  select profile.id
    into v_viewer_profile_id
  from public.profiles profile
  where profile.user_id = auth.uid()
    and profile.deleted_at is null
  limit 1;

  if v_viewer_profile_id is null then
    raise exception 'profile required' using errcode = '42501';
  end if;

  return query
  select
    target.id as profile_id,
    save_row.created_at as saved_at,
    target.full_name,
    target.age,
    target.avatar_url,
    target.city,
    target.region,
