CREATE OR REPLACE FUNCTION "public"."rpc_get_phone_verification_status"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
declare
  v_user_id uuid;
  v_phone text;
begin
  -- Avoid lock hangs
  set local statement_timeout = '2s';
  set local lock_timeout = '2s';

  v_user_id := auth.uid();
  if v_user_id is null then
    return jsonb_build_object('verified', false);
  end if;

  -- Find latest verified phone for this user
  select pv.phone_number
    into v_phone
  from public.phone_verifications pv
  where pv.user_id = v_user_id
    and (pv.status = 'verified' or pv.is_verified = true)
  order by pv.verified_at desc nulls last, pv.updated_at desc nulls last
  limit 1;

  if v_phone is null then
    return jsonb_build_object('verified', false);
  end if;

  -- Ensure profile exists (Phase-2 nullable schema allows minimal row)
  insert into public.profiles (user_id)
  values (v_user_id)
  on conflict (user_id) do nothing;

  -- Persist verification on profile (non-blocking)
  update public.profiles
  set phone_verified = true,
      phone_number = coalesce(phone_number, v_phone),
      updated_at = now()
  where user_id = v_user_id
    and user_id in (
      select user_id
      from public.profiles
      where user_id = v_user_id
      for update skip locked
    );

  return jsonb_build_object('verified', true, 'phone_number', v_phone);
end;
$$;


ALTER FUNCTION "public"."rpc_get_phone_verification_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_profile_boost_recommendations"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_plan public.subscription_type := 'FREE';
  v_viewer_profile_id uuid;
  active_boost record;
  best_hour integer := null;
  best_score numeric := 0;
  recent_unique_viewers integer := 0;
  recent_views integer := 0;
  recent_intro_opens integer := 0;
  recent_saves integer := 0;
  recent_intent_opens integer := 0;
  recommended_start_at timestamptz;
  recommendation_reason text;
  audience_options jsonb;
  focus_options jsonb;
  best_recent_recipe jsonb := null;
  last_used_recipe jsonb := null;
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  resolved_plan := public.get_active_subscription_plan(auth.uid());

  select p.id
    into v_viewer_profile_id
  from public.profiles p
  where p.user_id = auth.uid()
    and p.deleted_at is null
  limit 1;

  if v_viewer_profile_id is null then
    raise exception 'profile required';
  end if;

  select
    pb.id,
    pb.ends_at,
    pb.boost_type,
    pb.audience_mode,
    pb.focus_mode
    into active_boost
  from public.profile_boosts pb
  where pb.user_id = v_viewer_profile_id
    and pb.starts_at <= timezone('utc'::text, now())
    and pb.ends_at > timezone('utc'::text, now())
  order by pb.ends_at desc
  limit 1;

  with recent_events as (
    select event_row.event_type, extract(hour from event_row.created_at)::integer as hour_bucket
    from public.vibes_events event_row
    where event_row.target_profile_id = v_viewer_profile_id
      and event_row.created_at > timezone('utc'::text, now()) - interval '21 days'
      and public.is_trusted_boost_viewer(event_row.viewer_profile_id, v_viewer_profile_id)
      and event_row.event_type in (
        'profile_opened', 'full_profile_opened', 'intro_played',
        'intro_completed', 'profile_saved', 'intent_opened'
      )
  ),
  hour_scores as (
    select
      recent_events.hour_bucket,
      count(*)::integer as raw_events,
      sum(
        case recent_events.event_type
          when 'profile_saved' then 4.0
          when 'intent_opened' then 3.3
          when 'intro_completed' then 3.0
          when 'intro_played' then 2.0
          when 'full_profile_opened' then 1.8
          else 1.0
        end
      ) as weighted_score
    from recent_events
    group by recent_events.hour_bucket
  )
  select
    hour_scores.hour_bucket,
    hour_scores.weighted_score
    into best_hour,
      best_score
  from hour_scores
  order by hour_scores.weighted_score desc, hour_scores.raw_events desc, hour_scores.hour_bucket asc
  limit 1;

  select
    count(distinct event_row.viewer_profile_id) filter (
      where event_row.event_type in ('profile_opened', 'full_profile_opened')
        and event_row.viewer_profile_id is not null
    )::integer,
    count(*) filter (where event_row.event_type in ('profile_opened', 'full_profile_opened'))::integer,
    count(*) filter (where event_row.event_type in ('intro_played', 'intro_completed'))::integer,
    count(*) filter (where event_row.event_type = 'profile_saved')::integer,
    count(*) filter (where event_row.event_type = 'intent_opened')::integer
    into recent_unique_viewers,
      recent_views,
      recent_intro_opens,
      recent_saves,
      recent_intent_opens
  from public.vibes_events event_row
  where event_row.target_profile_id = v_viewer_profile_id
    and event_row.created_at > timezone('utc'::text, now()) - interval '7 days'
    and public.is_trusted_boost_viewer(event_row.viewer_profile_id, v_viewer_profile_id);

  with recent_boosts as (
    select
      pb.id,
      pb.created_at,
      pb.starts_at,
      pb.ends_at,
      coalesce(pb.boost_type, 'manual') as boost_type,
      coalesce(pb.audience_mode, 'for_you') as audience_mode,
      coalesce(pb.focus_mode, 'profile') as focus_mode
    from public.profile_boosts pb
    where pb.user_id = v_viewer_profile_id
      and pb.created_at > timezone('utc'::text, now()) - interval '45 days'
      and pb.ends_at <= timezone('utc'::text, now())
  ),
  boost_event_metrics as (
    select
      rb.id,
      count(distinct event_row.viewer_profile_id) filter (
        where event_row.event_type in ('profile_opened', 'full_profile_opened')
          and event_row.viewer_profile_id is not null
      )::integer as unique_viewers,
      count(*) filter (
        where event_row.event_type in ('profile_opened', 'full_profile_opened')
      )::integer as views,
      count(*) filter (
        where event_row.event_type in ('intro_played', 'intro_completed')
      )::integer as intro_opens,
      count(distinct event_row.viewer_profile_id) filter (
        where event_row.event_type = 'profile_saved'
          and event_row.viewer_profile_id is not null
      )::integer as unique_savers,
      count(distinct event_row.viewer_profile_id) filter (
        where event_row.event_type = 'intent_opened'
          and event_row.viewer_profile_id is not null
      )::integer as unique_intent_viewers
    from recent_boosts rb
    left join public.vibes_events event_row
      on event_row.target_profile_id = v_viewer_profile_id
     and event_row.created_at >= rb.starts_at
     and event_row.created_at <= rb.ends_at
     and public.is_trusted_boost_viewer(event_row.viewer_profile_id, v_viewer_profile_id)
    group by rb.id
  ),
  boost_match_metrics as (
    select
      rb.id,
      count(*)::integer as accepted_matches
    from recent_boosts rb
    left join public.matches match_row
      on match_row.status = 'ACCEPTED'
     and match_row.updated_at >= rb.starts_at
     and match_row.updated_at <= least(rb.ends_at + interval '24 hours', timezone('utc'::text, now()))
     and (
       match_row.user1_id = v_viewer_profile_id
       or match_row.user2_id = v_viewer_profile_id
     )
    left join public.profiles counterpart
      on counterpart.id = case
        when match_row.user1_id = v_viewer_profile_id then match_row.user2_id
        else match_row.user1_id
      end
    where match_row.id is null
       or public.is_trusted_boost_viewer(counterpart.id, v_viewer_profile_id)
    group by rb.id
  ),
  ranked_recipes as (
    select
      rb.*,
      coalesce(bem.unique_viewers, 0) as unique_viewers,
      coalesce(bem.views, 0) as views,
      coalesce(bem.intro_opens, 0) as intro_opens,
      coalesce(bem.unique_savers, 0) as unique_savers,
      coalesce(bem.unique_intent_viewers, 0) as unique_intent_viewers,
      coalesce(bmm.accepted_matches, 0) as accepted_matches,
      (
        coalesce(bem.unique_viewers, 0) * 0.4 +
        coalesce(bem.intro_opens, 0) * 1.3 +
        coalesce(bem.unique_savers, 0) * 4.2 +
        coalesce(bem.unique_intent_viewers, 0) * 5.0 +
        coalesce(bmm.accepted_matches, 0) * 8.0
      ) as recipe_score,
      case
        when coalesce(bem.unique_viewers, 0) >= 12
          and (
            coalesce(bem.unique_savers, 0) >= 2
            or coalesce(bem.unique_intent_viewers, 0) >= 1
            or coalesce(bmm.accepted_matches, 0) >= 1
          ) then 'proven'
        when coalesce(bem.unique_viewers, 0) >= 6
          and (
            coalesce(bem.unique_savers, 0) >= 1
            or coalesce(bem.unique_intent_viewers, 0) >= 1
            or coalesce(bmm.accepted_matches, 0) >= 1
            or coalesce(bem.intro_opens, 0) >= 2
          ) then 'emerging'
        else 'thin_sample'
      end as confidence,
      case
        when coalesce(bem.unique_viewers, 0) >= 12
          and (
            coalesce(bem.unique_savers, 0) >= 2
            or coalesce(bem.unique_intent_viewers, 0) >= 1
            or coalesce(bmm.accepted_matches, 0) >= 1
          ) then 2
        when coalesce(bem.unique_viewers, 0) >= 6
          and (
            coalesce(bem.unique_savers, 0) >= 1
            or coalesce(bem.unique_intent_viewers, 0) >= 1
            or coalesce(bmm.accepted_matches, 0) >= 1
            or coalesce(bem.intro_opens, 0) >= 2
          ) then 1
        else 0
      end as confidence_rank
    from recent_boosts rb
    left join boost_event_metrics bem
      on bem.id = rb.id
    left join boost_match_metrics bmm
      on bmm.id = rb.id
    where
      coalesce(bem.unique_viewers, 0) >= 3
      or coalesce(bem.unique_savers, 0) > 0
      or coalesce(bem.unique_intent_viewers, 0) > 0
      or coalesce(bmm.accepted_matches, 0) > 0
  )
  select jsonb_build_object(
    'boost_type', recipe.boost_type,
    'audience_mode', recipe.audience_mode,
    'focus_mode', recipe.focus_mode,
    'headline',
      case
        when recipe.accepted_matches > 0 then 'Best recent converter'
        when recipe.unique_intent_viewers > 0 then 'Best recent intent recipe'
        when recipe.unique_savers > 0 then 'Best recent quality recipe'
        else 'Best recent reach recipe'
      end,
    'summary',
      case
        when recipe.accepted_matches > 0 then
          format(
            '%s brought %s and %s from trusted viewers.',
            case when recipe.boost_type = 'smart' then 'This precision recipe' else 'This boost recipe' end,
            case when recipe.accepted_matches = 1 then '1 match' else recipe.accepted_matches::text || ' matches' end,
            case when recipe.unique_intent_viewers = 1 then '1 intent viewer' else recipe.unique_intent_viewers::text || ' intent viewers' end
          )
        when recipe.unique_intent_viewers > 0 then
          format(
            'This combo drove %s and %s.',
            case when recipe.unique_intent_viewers = 1 then '1 intent viewer' else recipe.unique_intent_viewers::text || ' intent viewers' end,
            case when recipe.unique_savers = 1 then '1 save' else recipe.unique_savers::text || ' saves' end
          )
        when recipe.unique_savers > 0 then
          format(
            'This combo drove %s from a trusted audience.',
            case when recipe.unique_savers = 1 then '1 save' else recipe.unique_savers::text || ' saves' end
          )
        else
          format(
            'This combo reached %s with %s total opens.',
            case when recipe.unique_viewers = 1 then '1 trusted viewer' else recipe.unique_viewers::text || ' trusted viewers' end,
            recipe.views::text
          )
      end,
    'confidence', recipe.confidence,
    'confidence_label',
      case recipe.confidence
        when 'proven' then 'Proven'
        when 'emerging' then 'Emerging'
        else 'Thin sample'
      end,
    'confidence_note',
      case recipe.confidence
        when 'proven' then 'Enough trusted reach and downstream quality to reuse with confidence.'
        when 'emerging' then 'Promising signal, but still building toward a stronger sample.'
        else 'Useful as a hint, not yet strong enough to treat as fully proven.'
      end,
    'trusted_reach', recipe.unique_viewers,
    'views', recipe.views,
    'intro_opens', recipe.intro_opens,
    'unique_savers', recipe.unique_savers,
    'unique_intent_viewers', recipe.unique_intent_viewers,
    'accepted_matches', recipe.accepted_matches,
    'recipe_score', round(recipe.recipe_score::numeric, 2),
    'created_at', recipe.created_at
  )
    into best_recent_recipe
  from ranked_recipes recipe
  order by recipe.confidence_rank desc, recipe.recipe_score desc, recipe.created_at desc
  limit 1;

  with last_completed_boost as (
    select
      pb.id,
      pb.created_at,
      coalesce(pb.boost_type, 'manual') as boost_type,
      coalesce(pb.audience_mode, 'for_you') as audience_mode,
      coalesce(pb.focus_mode, 'profile') as focus_mode
    from public.profile_boosts pb
    where pb.user_id = v_viewer_profile_id
      and pb.created_at > timezone('utc'::text, now()) - interval '45 days'
      and pb.ends_at <= timezone('utc'::text, now())
    order by pb.created_at desc
    limit 1
  )
  select jsonb_build_object(
    'boost_type', last_completed_boost.boost_type,
    'audience_mode', last_completed_boost.audience_mode,
    'focus_mode', last_completed_boost.focus_mode,
    'headline', 'Last used recipe',
    'summary', 'Your most recent completed boost setup. Reuse it when you want continuity before testing a variation.',
    'created_at', last_completed_boost.created_at
  )
    into last_used_recipe
  from last_completed_boost;

  if best_hour is null then
    best_hour := 20;
  end if;

  recommended_start_at := date_trunc('day', timezone('utc'::text, now()))
    + (best_hour || ' hours')::interval;
  if recommended_start_at <= timezone('utc'::text, now()) + interval '15 minutes' then
    recommended_start_at := recommended_start_at + interval '1 day';
  end if;

  recommendation_reason := case
    when recent_unique_viewers <= 1 and recent_views >= 10 then
      'Most of this traffic is coming from a very small number of viewers. Use the totals as directional, not broad-market demand yet.'
    when best_recent_recipe is not null
      and coalesce(best_recent_recipe ->> 'confidence', '') = 'proven' then
      'You already have a proven recent boost recipe with credible trusted outcomes. Start there before experimenting.'
    when best_recent_recipe is not null
      and coalesce(best_recent_recipe ->> 'confidence', '') = 'emerging' then
      'You already have a promising recent boost recipe. Start there, but keep reading the live quality before treating it as proven.'
    when best_recent_recipe is not null then
      'You have a recent recipe hint, but the sample is still thin. Use it as a starting point, not a guarantee.'
    when recent_saves >= 4 or recent_intent_opens >= 4 then
      'Your strongest signals are already converting. A precision boost can turn that momentum into deeper actions.'
    when recent_intro_opens >= 6 then
      'People are spending time with your intro. Lead with an intro-focused boost while attention is warm.'
    when recent_views >= 8 then
      'You are getting profile traffic. A boost now is best used to convert opens into saves and intent.'
    when best_score >= 6 then
      'Your profile historically performs best around this time window.'
    else
      'Use a boost when people nearby are active and your profile is fresh.'
  end;

  audience_options := case
    when resolved_plan = 'GOLD' then
      jsonb_build_array(
        jsonb_build_object('id', 'for_you', 'label', 'For you', 'description', 'Balanced discovery boost across your strongest fit lane.'),
        jsonb_build_object('id', 'nearby', 'label', 'Nearby', 'description', 'Lean into local visibility and short-distance discovery.'),
        jsonb_build_object('id', 'active_now', 'label', 'Active now', 'description', 'Bias the lift toward currently active members.'),
        jsonb_build_object('id', 'intent_match', 'label', 'Intent match', 'description', 'Favor people whose intent looks aligned with yours.'),
        jsonb_build_object('id', 'second_look', 'label', 'Second look', 'description', 'Quietly resurface you where there were earlier opens or curiosity.')
      )
    else
      jsonb_build_array(
        jsonb_build_object('id', 'for_you', 'label', 'For you', 'description', 'Balanced discovery boost across your strongest fit lane.'),
        jsonb_build_object('id', 'nearby', 'label', 'Nearby', 'description', 'Lean into local visibility and short-distance discovery.')
      )
  end;

  focus_options := case
    when resolved_plan = 'GOLD' then
      jsonb_build_array(
        jsonb_build_object('id', 'profile', 'label', 'Profile', 'description', 'Promote your overall profile story.'),
        jsonb_build_object('id', 'intro', 'label', 'Intro', 'description', 'Bias toward people likely to open your intro video.'),
        jsonb_build_object('id', 'intent', 'label', 'Intent', 'description', 'Bias toward deeper intent and fit evaluation.')
      )
    else
      jsonb_build_array(
        jsonb_build_object('id', 'profile', 'label', 'Profile', 'description', 'Promote your overall profile story.')
      )
  end;

  return jsonb_strip_nulls(jsonb_build_object(
    'plan', resolved_plan,
    'has_active_boost', active_boost.id is not null,
    'active_boost_ends_at', active_boost.ends_at,
    'recommended_start_at', recommended_start_at,
    'recommended_audience_mode', case when resolved_plan = 'GOLD' then 'intent_match' else 'for_you' end,
    'recommended_focus_mode', case when resolved_plan = 'GOLD' and recent_intro_opens >= recent_views then 'intro' else 'profile' end,
    'recommendation_reason', recommendation_reason,
    'best_recent_recipe', best_recent_recipe,
    'last_used_recipe', last_used_recipe,
    'audience_options', audience_options,
    'focus_options', focus_options,
    'recent_metrics', jsonb_build_object(
      'unique_viewers_7d', recent_unique_viewers,
      'views_7d', recent_views,
      'intro_opens_7d', recent_intro_opens,
      'saves_7d', recent_saves,
      'intent_opens_7d', recent_intent_opens
    )
  ));
end;
$$;


ALTER FUNCTION "public"."rpc_get_profile_boost_recommendations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_profile_card_context"("p_profile_ids" "uuid"[], "p_include_sandbox_preview" boolean DEFAULT false) RETURNS TABLE("profile_id" "uuid", "premium_plan" "text", "is_new_here" boolean, "interest_relevance_score" integer, "has_active_boost" boolean, "boost_ends_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_profile_ids uuid[] := '{}'::uuid[];
  v_viewer_profile_id uuid;
begin
  if auth.uid() is null then
    return;
  end if;

  select coalesce(array_agg(limited.profile_id), '{}'::uuid[])
    into v_profile_ids
  from (
    select distinct requested.profile_id
    from unnest(coalesce(p_profile_ids, '{}'::uuid[])) as requested(profile_id)
    where requested.profile_id is not null
    limit 80
  ) limited;

  if coalesce(array_length(v_profile_ids, 1), 0) = 0 then
    return;
  end if;

  select profile.id
    into v_viewer_profile_id
  from public.profiles profile
  where profile.user_id = auth.uid()
    and profile.deleted_at is null
  limit 1;

  if v_viewer_profile_id is null then
    return;
  end if;

  return query
  select
    profile.id as profile_id,
    case
      when coalesce(p_include_sandbox_preview, false)
        and public.is_admin_user(auth.uid())
        then public.get_subscription_badge_plan(profile.user_id, true)::text
      else coalesce(ent.premium_plan, 'FREE')
    end as premium_plan,
    coalesce(ent.profile_created_at, profile.created_at) > timezone('utc'::text, now()) - interval '14 days' as is_new_here,
    coalesce(
      public.profile_interest_score(
        coalesce(state.profile_open_count, 0),
        coalesce(state.full_open_count, 0),
        coalesce(state.intro_count, 0),
        coalesce(state.profile_saved_count, 0),
        greatest(coalesce(state.profile_open_count, 0) + coalesce(state.full_open_count, 0) - 1, 0),
        coalesce(state.intent_opened_count, 0)
      ),
      0
    ) as interest_relevance_score,
    coalesce(ent.has_active_boost, false) as has_active_boost,
    ent.boost_ends_at
  from public.profiles profile
  left join public.profile_visibility_entitlements ent
    on ent.profile_id = profile.id
  left join public.viewer_profile_behavior_summary state
    on state.viewer_profile_id = v_viewer_profile_id
   and state.target_profile_id = profile.id
  where profile.id = any(v_profile_ids)
    and profile.deleted_at is null
    and profile.id <> v_viewer_profile_id
    and profile.profile_completed is true
    and coalesce(profile.discoverable_in_vibes, true) = true
    and coalesce(profile.matchmaking_mode, false) = false
    and not exists (
      select 1
      from public.blocks block_row
      where (block_row.blocker_id = auth.uid() and block_row.blocked_id = profile.user_id)
         or (block_row.blocker_id = profile.user_id and block_row.blocked_id = auth.uid())
    );
end;
$$;


ALTER FUNCTION "public"."rpc_get_profile_card_context"("p_profile_ids" "uuid"[], "p_include_sandbox_preview" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_signal_access"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_profile_id uuid;
  v_plan public.subscription_type := 'FREE';
  v_limit integer := 0;
  v_used integer := 0;
  v_period_start timestamptz := date_trunc('week', timezone('utc', now())) at time zone 'utc';
begin
  if v_user_id is null then
    return jsonb_build_object('plan', 'FREE', 'limit', 0, 'used', 0, 'remaining', 0, 'can_send', false);
  end if;

  select id into v_profile_id
  from public.profiles
  where user_id = v_user_id
  limit 1;

  v_plan := public.get_active_subscription_plan(v_user_id);
  v_limit := public.signal_limit_for_plan(v_plan);

  if v_profile_id is not null and v_plan = 'FREE' then
    select count(*)::integer into v_used
    from public.profile_signal_gestures
    where sender_profile_id = v_profile_id;
  elsif v_profile_id is not null then
    select count(*)::integer into v_used
    from public.profile_signal_gestures
    where sender_profile_id = v_profile_id
      and created_at >= v_period_start;
  end if;

  return jsonb_build_object(
    'plan', v_plan,
    'limit', v_limit,
    'used', coalesce(v_used, 0),
    'remaining', greatest(v_limit - coalesce(v_used, 0), 0),
    'can_send', v_limit > coalesce(v_used, 0)
  );
end;
$$;


ALTER FUNCTION "public"."rpc_get_signal_access"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_suggested_moves"("p_profile_id" "uuid", "p_limit" integer DEFAULT 6) RETURNS TABLE("id" "uuid", "full_name" "text", "age" integer, "avatar_url" "text", "short_tags" "text"[], "has_intro_video" boolean, "distance_km" double precision, "shared_interest_names" "text"[], "shared_interest_count" integer, "prompt_title" "text", "prompt_answer" "text", "bio_snippet" "text", "same_region" boolean, "same_religion" boolean, "same_looking_for" boolean, "active_now" boolean, "recently_active" boolean, "candidate_tier" integer, "quality_band" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  my_user_id uuid;
  my_lat double precision;
  my_lon double precision;
  my_gender gender;
  my_age integer;
  my_min_age_interest integer;
  my_max_age_interest integer;
  my_region text;
  my_religion religion;
  my_looking_for text;
begin
  if auth.uid() is null then
    return;
  end if;

  select
    p.user_id,
    p.latitude,
    p.longitude,
    p.gender,
    p.age,
    p.min_age_interest,
    p.max_age_interest,
    p.region,
    p.religion,
    p.looking_for
    into
      my_user_id,
      my_lat,
      my_lon,
      my_gender,
      my_age,
      my_min_age_interest,
      my_max_age_interest,
      my_region,
      my_religion,
      my_looking_for
  from public.profiles p
  where p.id = p_profile_id
    and p.user_id = auth.uid()
  limit 1;

  if my_user_id is null then
    return;
  end if;

  return query
  with viewer_interests as (
    select coalesce(array_agg(distinct i.name order by i.name), '{}'::text[]) as names
    from public.profile_interests pi
    join public.interests i on i.id = pi.interest_id
    where pi.profile_id = p_profile_id
  ),
  top_targets as (
    select ps.target_profile_id
    from public.profile_signals ps
    where ps.profile_id = p_profile_id
    order by
      ps.liked desc,
      ps.intro_video_completed desc,
      ps.dwell_score desc,
      ps.last_interacted_at desc
    limit 20
  ),
  taste_interests as (
    select i.name
    from public.profile_interests pi
    join public.interests i on i.id = pi.interest_id
    join top_targets t on t.target_profile_id = pi.profile_id
    group by i.name
    order by count(*) desc, i.name asc
    limit 5
  ),
  taste as (
    select
      (select names from viewer_interests) as viewer_interest_names,
      case
        when exists (select 1 from taste_interests) then
          coalesce((select array_agg(name order by name) from taste_interests), '{}'::text[])
        else
          (select names from viewer_interests)
      end as top_interest_names
  ),
  candidate_market_feedback as (
    select
      sme.candidate_profile_id,
      count(*) filter (where sme.event_type = 'impression')::integer as impression_count,
      count(*) filter (where sme.event_type = 'preview_profile')::integer as preview_count,
      count(*) filter (where sme.event_type = 'opener_revealed')::integer as opener_reveal_count,
      count(*) filter (where sme.event_type = 'intent_opened')::integer as intent_open_count,
      count(*) filter (where sme.event_type = 'intent_sent')::integer as intent_sent_count
    from public.suggested_move_events sme
    group by sme.candidate_profile_id
  ),
  viewer_candidate_feedback as (
    select
      sme.candidate_profile_id,
      count(*) filter (where sme.event_type = 'impression')::integer as viewer_impression_count,
      count(*) filter (where sme.event_type = 'preview_profile')::integer as viewer_preview_count,
      count(*) filter (where sme.event_type = 'opener_revealed')::integer as viewer_opener_count,
      count(*) filter (where sme.event_type = 'intent_opened')::integer as viewer_intent_open_count,
      count(*) filter (where sme.event_type = 'intent_sent')::integer as viewer_intent_sent_count,
      max(sme.created_at) as viewer_last_event_at
    from public.suggested_move_events sme
    where sme.viewer_profile_id = p_profile_id
    group by sme.candidate_profile_id
  ),
  candidate_response_history as (
    select
      ir.recipient_id as candidate_profile_id,
      count(*) filter (where ir.status in ('accepted', 'passed', 'matched'))::integer as decision_count,
      count(*) filter (where ir.status in ('accepted', 'matched'))::integer as positive_decision_count
    from public.intent_requests ir
    where ir.recipient_id <> p_profile_id
    group by ir.recipient_id
  ),
  base_candidates as (
    select
      p.id,
      p.full_name,
      p.age,
      p.avatar_url,
      p.profile_video,
      p.region,
      p.religion,
      p.looking_for,
      p.min_age_interest,
      p.max_age_interest,
      p.verification_level,
      p.latitude,
      p.longitude,
      p.online,
      p.last_active,
      left(regexp_replace(coalesce(p.bio, ''), '\s+', ' ', 'g'), 160) as bio_snippet,
      greatest(
        coalesce(array_length(p.photos, 1), 0),
        case when p.avatar_url is not null and btrim(p.avatar_url) <> '' then 1 else 0 end
      ) as photo_count,
      (my_region is not null and p.region is not null and my_region = p.region) as same_region,
      (my_religion is not null and p.religion is not null and my_religion = p.religion) as same_religion,
      (
        my_looking_for is not null
        and p.looking_for is not null
        and lower(trim(my_looking_for)) = lower(trim(p.looking_for))
      ) as same_looking_for,
      (
        my_min_age_interest is null
        or my_max_age_interest is null
        or p.age between my_min_age_interest and my_max_age_interest
      ) as within_viewer_age_pref,
      (
        my_age is null
        or p.min_age_interest is null
        or p.max_age_interest is null
        or my_age between p.min_age_interest and p.max_age_interest
      ) as within_mutual_age_pref,
      (
        my_gender is null
        or my_gender not in ('MALE', 'FEMALE')
        or p.gender is null
        or p.gender not in ('MALE', 'FEMALE')
        or (my_gender = 'MALE' and p.gender = 'FEMALE')
        or (my_gender = 'FEMALE' and p.gender = 'MALE')
      ) as binary_gender_match
    from public.profiles p
    where p.id <> p_profile_id
      and p.deleted_at is null
      and p.is_active = true
      and p.profile_completed is true
      and coalesce(p.discoverable_in_vibes, true) = true
      and p.user_id is not null
      and p.user_id <> my_user_id
      and p.full_name is not null
      and p.age is not null
      and not exists (
        select 1
        from public.intent_requests ir
        where (
            (ir.actor_id = p_profile_id and ir.recipient_id = p.id)
            or (ir.actor_id = p.id and ir.recipient_id = p_profile_id)
          )
          and (
            ir.status in ('pending', 'accepted', 'matched')
            or (
              ir.status = 'passed'
              and ir.created_at > now() - interval '21 days'
            )
          )
      )
      and not exists (
        select 1
        from public.matches m
        where (m.user1_id = p_profile_id and m.user2_id = p.id)
           or (m.user1_id = p.id and m.user2_id = p_profile_id)
      )
      and not exists (
        select 1
        from public.blocks b
        where (b.blocker_id = my_user_id and b.blocked_id = p.user_id)
           or (b.blocker_id = p.user_id and b.blocked_id = my_user_id)
      )
      and coalesce((
        select sw.action::text
        from public.swipes sw
        where sw.swiper_id = p_profile_id
          and sw.target_id = p.id
        order by sw.created_at desc, sw.id desc
        limit 1
      ), '') <> 'PASS'
  ),
  primary_candidates as (
    select bc.*, 0::integer as candidate_tier
    from base_candidates bc
    where bc.within_viewer_age_pref
      and bc.within_mutual_age_pref
      and bc.binary_gender_match
  ),
  high_quality_primary_count as (
    select count(*)::integer as total
    from primary_candidates pc
    cross join taste
    where pc.same_looking_for
      or pc.profile_video is not null
      or exists (
        select 1
        from public.profile_interests pi
        join public.interests i on i.id = pi.interest_id
        where pi.profile_id = pc.id
          and i.name = any(taste.viewer_interest_names)
      )
      or exists (
        select 1
        from public.profile_prompts pp
        where pp.profile_id = pc.id
          and pp.answer is not null
          and btrim(pp.answer) <> ''
      )
      or (
        (pc.online = true or pc.last_active > now() - interval '20 minutes')
        and my_lat is not null
        and my_lon is not null
        and pc.latitude is not null
        and pc.longitude is not null
        and (6371 * 2 * asin(sqrt(
          power(sin(radians(pc.latitude - my_lat) / 2), 2) +
          cos(radians(my_lat)) * cos(radians(pc.latitude)) *
          power(sin(radians(pc.longitude - my_lon) / 2), 2)
        ))) <= 25
      )
  ),
  fallback_candidates as (
    select bc.*, 1::integer as candidate_tier
    from base_candidates bc
    cross join high_quality_primary_count hq
    where hq.total < 3
      and bc.within_viewer_age_pref
      and not bc.within_mutual_age_pref
      and bc.binary_gender_match
  ),
  candidate_selection as (
    select * from primary_candidates
    union all
    select * from fallback_candidates
  ),
  candidates as (
    select
      c.id,
      c.full_name,
      c.age,
      c.avatar_url,
      c.profile_video,
      c.region,
      c.religion,
      c.looking_for,
      c.min_age_interest,
      c.max_age_interest,
      c.verification_level,
      c.latitude,
      c.longitude,
      c.online,
      c.last_active,
      c.bio_snippet,
      c.photo_count,
      coalesce(shared.shared_interest_count, 0) as shared_interest_count,
      coalesce(shared.shared_interest_names, '{}'::text[]) as shared_interest_names,
      coalesce(taste_overlap.taste_interest_count, 0) as taste_interest_count,
      prompt.prompt_title,
      prompt.answer as prompt_answer,
      coalesce(signal.opened_profile_count, 0) as opened_profile_count,
      coalesce(signal.dwell_score, 0) as dwell_score,
      coalesce(signal.intro_video_completed, false) as signal_intro_video_completed,
      coalesce(signal.liked, false) as signal_liked,
      signal.last_interacted_at as signal_last_interacted_at,
      swipe.action as latest_swipe_action,
      c.same_region,
      c.same_religion,
      c.same_looking_for,
      coalesce(market.impression_count, 0) as market_impression_count,
      coalesce(market.preview_count, 0) as market_preview_count,
      coalesce(market.opener_reveal_count, 0) as market_opener_reveal_count,
      coalesce(market.intent_open_count, 0) as market_intent_open_count,
      coalesce(market.intent_sent_count, 0) as market_intent_sent_count,
      coalesce(viewer.viewer_impression_count, 0) as viewer_impression_count,
      coalesce(viewer.viewer_preview_count, 0) as viewer_preview_count,
      coalesce(viewer.viewer_opener_count, 0) as viewer_opener_count,
      coalesce(viewer.viewer_intent_open_count, 0) as viewer_intent_open_count,
      coalesce(viewer.viewer_intent_sent_count, 0) as viewer_intent_sent_count,
      viewer.viewer_last_event_at,
      coalesce(response_history.decision_count, 0) as recipient_decision_count,
      coalesce(response_history.positive_decision_count, 0) as recipient_positive_decision_count,
      c.candidate_tier
    from candidate_selection c
    cross join taste
    left join lateral (
      select
        count(*)::integer as shared_interest_count,
        (coalesce(array_agg(i.name order by i.name), '{}'::text[]))[1:3] as shared_interest_names
      from public.profile_interests pi
      join public.interests i on i.id = pi.interest_id
      where pi.profile_id = c.id
        and i.name = any(taste.viewer_interest_names)
    ) shared on true
    left join lateral (
      select count(*)::integer as taste_interest_count
      from public.profile_interests pi
      join public.interests i on i.id = pi.interest_id
      where pi.profile_id = c.id
        and i.name = any(taste.top_interest_names)
    ) taste_overlap on true
    left join lateral (
      select pp.prompt_title, pp.answer
      from public.profile_prompts pp
      where pp.profile_id = c.id
        and pp.answer is not null
        and btrim(pp.answer) <> ''
      order by pp.updated_at desc nulls last, pp.created_at desc, pp.id desc
      limit 1
    ) prompt on true
    left join public.profile_signals signal
      on signal.profile_id = p_profile_id
     and signal.target_profile_id = c.id
    left join lateral (
      select sw.action
      from public.swipes sw
      where sw.swiper_id = p_profile_id
        and sw.target_id = c.id
      order by sw.created_at desc, sw.id desc
      limit 1
    ) swipe on true
    left join candidate_market_feedback market
      on market.candidate_profile_id = c.id
    left join viewer_candidate_feedback viewer
      on viewer.candidate_profile_id = c.id
    left join candidate_response_history response_history
      on response_history.candidate_profile_id = c.id
  ),
  scored as (
    select
      c.*,
      (
        case
          when my_lat is null or my_lon is null or c.latitude is null or c.longitude is null
            then null::double precision
          else (6371 * 2 * asin(sqrt(
            power(sin(radians(c.latitude - my_lat) / 2), 2) +
            cos(radians(my_lat)) * cos(radians(c.latitude)) *
            power(sin(radians(c.longitude - my_lon) / 2), 2)
          )))
        end
      ) as distance_km,
      (c.online = true or c.last_active > now() - interval '20 minutes') as active_now,
      (c.last_active > now() - interval '3 days') as recently_active,
      case
        when c.market_impression_count >= 8 then c.market_preview_count::double precision / greatest(c.market_impression_count, 1)
        else null::double precision
      end as market_preview_rate,
      case
        when c.market_impression_count >= 8 then c.market_intent_open_count::double precision / greatest(c.market_impression_count, 1)
        else null::double precision
      end as market_open_rate,
      case
        when c.market_impression_count >= 8 then c.market_intent_sent_count::double precision / greatest(c.market_impression_count, 1)
        else null::double precision
      end as market_send_rate,
      case
        when c.recipient_decision_count >= 5 then c.recipient_positive_decision_count::double precision / greatest(c.recipient_decision_count, 1)
        else null::double precision
      end as recipient_positive_rate
    from candidates c
  ),
  ranked as (
    select
      s.*,
      (
        case
          when s.same_looking_for or s.shared_interest_count > 0 then 3
          when s.prompt_title is not null then 2
          when s.active_now and s.distance_km is not null and s.distance_km <= 25 then 2
          when s.profile_video is not null or s.active_now then 1
          else 0
        end
      )::integer as quality_band,
      (
        least(s.shared_interest_count, 3) * 3.0
        + least(s.taste_interest_count, 3) * 1.25
        + case when s.profile_video is not null then 2.5 else 0 end
        + case when s.active_now then 1.5 else 0 end
        + case when s.recently_active then 0.75 else -0.75 end
        + case when s.same_region then 0.6 else 0 end
        + case when s.same_religion then 0.3 else 0 end
        + case when s.same_looking_for then 2.2 else 0 end
        + case when coalesce(s.verification_level, 0) > 0 then 0.8 else 0 end
        + case
            when s.photo_count >= 3 then 1.0
            when s.photo_count = 2 then 0.45
            when s.photo_count = 1 then 0.1
            else -1.5
          end
        + case when s.prompt_title is not null then 0.8 else 0 end
        + case
            when char_length(coalesce(s.bio_snippet, '')) >= 120 then 0.6
            when char_length(coalesce(s.bio_snippet, '')) >= 40 then 0.2
            else -0.6
          end
        + case
            when s.latest_swipe_action = 'SUPERLIKE' then 2.5
            when s.latest_swipe_action = 'LIKE' then 1.5
            else 0
          end
        + case when s.signal_liked then 1.25 else 0 end
        + case when s.signal_intro_video_completed then 0.75 else 0 end
        + case
            when s.market_preview_rate is null then 0
            when s.market_preview_rate >= 0.30 then 1.0
            when s.market_preview_rate >= 0.18 then 0.5
            when s.market_preview_rate < 0.08 then -0.5
            else 0
          end
        + case
            when s.market_open_rate is null then 0
            when s.market_open_rate >= 0.14 then 1.1
            when s.market_open_rate >= 0.08 then 0.5
            when s.market_open_rate < 0.03 then -0.45
            else 0
          end
        + case
            when s.market_send_rate is null then 0
            when s.market_send_rate >= 0.08 then 1.3
            when s.market_send_rate >= 0.04 then 0.55
            when s.market_send_rate < 0.015 then -0.75
            else 0
          end
        + case
            when s.recipient_positive_rate is null then 0
            when s.recipient_positive_rate >= 0.45 then 1.4
            when s.recipient_positive_rate >= 0.28 then 0.6
            when s.recipient_positive_rate < 0.10 then -0.8
            else 0
          end
        - case
            when s.shared_interest_count = 0 and not s.same_looking_for then 1.1
            else 0
          end
        - case
            when s.shared_interest_count = 0
              and not s.same_looking_for
              and s.prompt_title is null
              and s.profile_video is null
            then 0.65
            else 0
          end
        - case
            when s.shared_interest_count = 0
              and not s.same_looking_for
              and not s.active_now
              and s.distance_km is null
            then 0.5
            else 0
          end
        - case
            when s.viewer_impression_count >= 2 and s.viewer_intent_sent_count = 0 and s.viewer_preview_count = 0 then least(s.viewer_impression_count, 4) * 0.75
            else 0
          end
        - case
            when s.viewer_impression_count >= 3 and s.viewer_intent_sent_count = 0 and s.viewer_preview_count > 0 then least(s.viewer_impression_count, 4) * 0.55
            else 0
          end
        - case
            when s.viewer_last_event_at > now() - interval '36 hours' and s.viewer_intent_sent_count = 0 then 0.85
            else 0
          end
        - case
            when s.opened_profile_count >= 2 and not s.signal_liked then least(s.opened_profile_count, 4) * 0.9
            else 0
          end
        - case
            when s.signal_last_interacted_at > now() - interval '2 days' and not s.signal_liked then 1.25
            else 0
          end
        - case
            when s.opened_profile_count >= 3 and s.dwell_score < 12 and not s.signal_liked then 1.0
            else 0
          end
        - case when s.candidate_tier = 1 then 2.4 else 0 end
        + case
            when s.distance_km is null then 0
            when s.distance_km <= 25 then 2
            when s.distance_km <= 100 then 1
            when s.distance_km <= 500 then 0
            when s.distance_km <= 2000 then -1
            else -3
          end
      )::double precision as base_score
    from scored s
  ),
  diversified as (
    select
      r.*,
      row_number() over (
        partition by coalesce(r.region, '<<none>>')
        order by r.quality_band desc, r.base_score desc, r.distance_km asc nulls last, r.last_active desc nulls last, r.id desc
      ) as region_rank,
      row_number() over (
        partition by coalesce(r.looking_for, '<<none>>')
        order by r.quality_band desc, r.base_score desc, r.distance_km asc nulls last, r.last_active desc nulls last, r.id desc
      ) as goal_rank,
      row_number() over (
        partition by
          case
            when r.shared_interest_count > 0 then 'shared'
            when r.profile_video is not null then 'video'
            when r.active_now then 'active'
            when r.same_looking_for then 'goals'
            else 'general'
          end
        order by r.quality_band desc, r.base_score desc, r.distance_km asc nulls last, r.last_active desc nulls last, r.id desc
      ) as archetype_rank
    from ranked r
  ),
  hero_pool as (
    select exists(
      select 1
      from diversified d
      where d.quality_band >= 2
    ) as has_hero_quality
  )
  select
    d.id,
    d.full_name,
    d.age,
    d.avatar_url,
    (array_remove(array[
      case when d.shared_interest_count > 0 then 'Shared interests' end,
      case when d.same_looking_for then 'Same goals' end,
      case when d.same_religion then 'Shared values' end,
      case when d.same_region then 'Same region' end,
      case when d.profile_video is not null then 'Intro video' end,
      case when d.active_now then 'Active now' end,
      case when d.prompt_title is not null then 'Strong prompt' end
    ], null))[1:3] as short_tags,
    (d.profile_video is not null) as has_intro_video,
    d.distance_km,
    d.shared_interest_names,
    d.shared_interest_count,
    d.prompt_title,
    d.prompt_answer,
    nullif(d.bio_snippet, '') as bio_snippet,
    d.same_region,
    d.same_religion,
    d.same_looking_for,
    d.active_now,
    d.recently_active,
    d.candidate_tier,
    d.quality_band
  from diversified d
  cross join hero_pool hp
  order by
    case
      when hp.has_hero_quality and d.quality_band >= 2 then 1
      when hp.has_hero_quality then 0
      else 1
    end desc,
    d.quality_band desc,
    (
      d.base_score
      - greatest(d.region_rank - 1, 0) * 0.70
      - greatest(d.goal_rank - 1, 0) * 0.45
      - greatest(d.archetype_rank - 1, 0) * 0.35
    ) desc,
    d.distance_km asc nulls last,
    d.last_active desc nulls last,
    d.id desc
  limit p_limit;
end;
$$;


ALTER FUNCTION "public"."rpc_get_suggested_moves"("p_profile_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_user_taste"("p_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_owner uuid;
  v_taste jsonb;
begin
  if auth.uid() is null then
    return null;
  end if;

  select user_id into v_owner
  from public.profiles
  where id = p_profile_id
  limit 1;

  if v_owner is null or v_owner <> auth.uid() then
    return null;
  end if;

  with top_targets as (
    select ps.target_profile_id
    from public.profile_signals ps
    where ps.profile_id = p_profile_id
    order by ps.liked desc,
             ps.intro_video_completed desc,
             ps.dwell_score desc,
             ps.last_interacted_at desc
    limit 20
  ),
  target_profiles as (
    select p.*
    from public.profiles p
    join top_targets t on t.target_profile_id = p.id
  ),
  interest_counts as (
    select i.name, count(*) as cnt
    from public.profile_interests pi
    join public.interests i on i.id = pi.interest_id
    join top_targets t on t.target_profile_id = pi.profile_id
    group by i.name
    order by cnt desc, i.name asc
    limit 5
  ),
  interest_list as (
    select coalesce(array_agg(name), '{}'::text[]) as top_interests
    from interest_counts
  ),
  stats as (
    select
      min(age) as age_min,
      max(age) as age_max,
      count(*) as total_count,
      count(*) filter (where profile_video is not null) as video_count,
      bool_or(last_active > now() - interval '3 days') as active_recently
    from target_profiles
  )
  select jsonb_build_object(
    'preferred_age_min', (select age_min from stats),
    'preferred_age_max', (select age_max from stats),
    'top_interests', (select top_interests from interest_list),
    'prefers_intro_video', (
      case
        when (select total_count from stats) > 0
          then ((select video_count from stats)::double precision / (select total_count from stats)) >= 0.5
        else false
      end
    ),
    'active_recently', coalesce((select active_recently from stats), false)
  ) into v_taste;

  return v_taste;
end;
$$;


ALTER FUNCTION "public"."rpc_get_user_taste"("p_profile_id" "uuid") OWNER TO "postgres";


