CREATE OR REPLACE FUNCTION "public"."rpc_insert_request_acceptance_system_messages"("p_request_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_request record;
  v_actor_user uuid;
  v_actor_name text;
  v_recipient_user uuid;
  v_recipient_name text;
BEGIN
  SELECT *
  INTO v_request
  FROM public.intent_requests
  WHERE id = p_request_id;

  IF v_request.id IS NULL THEN
    RAISE EXCEPTION 'Request not found';
  END IF;

  SELECT user_id, full_name
  INTO v_actor_user, v_actor_name
  FROM public.profiles
  WHERE id = v_request.actor_id
  LIMIT 1;

  SELECT user_id, full_name
  INTO v_recipient_user, v_recipient_name
  FROM public.profiles
  WHERE id = v_request.recipient_id
  LIMIT 1;

  IF v_actor_user IS NULL OR v_recipient_user IS NULL THEN
    RAISE EXCEPTION 'User not found';
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Support apps that use profile.id as auth uid as well as profile.user_id.
  IF v_recipient_user <> auth.uid() AND v_request.recipient_id <> auth.uid() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  INSERT INTO public.system_messages (
    user_id,
    peer_user_id,
    intent_request_id,
    event_type,
    text,
    metadata
  )
  VALUES (
    v_actor_user,
    v_recipient_user,
    p_request_id,
    'request_accepted',
    COALESCE(v_recipient_name, 'They') || ' accepted your request. Start with a thoughtful hello.',
    jsonb_build_object('role', 'requester')
  )
  ON CONFLICT (intent_request_id, user_id) DO NOTHING;

  INSERT INTO public.system_messages (
    user_id,
    peer_user_id,
    intent_request_id,
    event_type,
    text,
    metadata
  )
  VALUES (
    v_recipient_user,
    v_actor_user,
    p_request_id,
    'request_accepted',
    'You accepted ' || COALESCE(v_actor_name, 'their') || '''s request. It''s time to shine.',
    jsonb_build_object('role', 'accepter')
  )
  ON CONFLICT (intent_request_id, user_id) DO NOTHING;
END;
$$;


ALTER FUNCTION "public"."rpc_insert_request_acceptance_system_messages"("p_request_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."circle_invitations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "circle_id" "uuid" NOT NULL,
    "inviter_profile_id" "uuid" NOT NULL,
    "invited_profile_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "message" "text",
    "expires_at" timestamp with time zone DEFAULT ("timezone"('utc'::"text", "now"()) + '14 days'::interval) NOT NULL,
    "responded_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    CONSTRAINT "circle_invitations_message_length" CHECK ((("message" IS NULL) OR (("char_length"("btrim"("message")) >= 1) AND ("char_length"("btrim"("message")) <= 320)))),
    CONSTRAINT "circle_invitations_status_valid" CHECK (("status" = ANY (ARRAY['pending'::"text", 'accepted'::"text", 'declined'::"text", 'revoked'::"text", 'expired'::"text"])))
);


ALTER TABLE "public"."circle_invitations" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_invite_profile_to_circle"("p_circle_id" "uuid", "p_actor_profile_id" "uuid", "p_invited_profile_id" "uuid", "p_message" "text" DEFAULT NULL::"text") RETURNS "public"."circle_invitations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_catalog'
    AS $$
declare
  v_invitation public.circle_invitations%rowtype;
  v_message text := nullif(btrim(coalesce(p_message, '')), '');
  v_target_user_id uuid;
  v_circle_name text;
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles actor
    where actor.id = p_actor_profile_id
      and actor.user_id = auth.uid()
      and actor.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  if not public.can_invite_to_circle(p_circle_id, auth.uid()) then
    raise exception 'circle_membership_required' using errcode = '42501';
  end if;

  if v_message is not null and char_length(v_message) > 320 then
    raise exception 'invitation_message_too_long';
  end if;

  select candidate.user_id
    into v_target_user_id
  from public.profiles candidate
  where candidate.id = p_invited_profile_id
    and candidate.deleted_at is null
    and coalesce(candidate.is_active, true)
  limit 1;

  if v_target_user_id is null then
    raise exception 'invitee_not_available';
  end if;

  if exists (
    select 1
    from public.circle_members cm
    where cm.circle_id = p_circle_id
      and cm.profile_id = p_invited_profile_id
      and cm.status in ('active', 'pending')
  ) then
    raise exception 'invitee_already_in_circle';
  end if;

  insert into public.circle_invitations (
    circle_id,
    inviter_profile_id,
    invited_profile_id,
    message,
    expires_at
  )
  values (
    p_circle_id,
    p_actor_profile_id,
    p_invited_profile_id,
    v_message,
    timezone('utc'::text, now()) + interval '14 days'
  )
  on conflict (circle_id, invited_profile_id)
    where status = 'pending'
  do update set inviter_profile_id = excluded.inviter_profile_id,
                message = excluded.message,
                expires_at = excluded.expires_at,
                updated_at = timezone('utc'::text, now())
  returning * into v_invitation;

  insert into public.circle_members (
    circle_id,
    profile_id,
    user_id,
    role,
    status,
    is_visible,
    joined_at,
    left_at
  )
  values (
    p_circle_id,
    p_invited_profile_id,
    v_target_user_id,
    'member',
    'invited',
    true,
    timezone('utc'::text, now()),
    null
  )
  on conflict (circle_id, profile_id)
  do update set status = 'invited',
                user_id = excluded.user_id,
                left_at = null,
                updated_at = timezone('utc'::text, now())
  where circle_members.status not in ('active', 'pending');

  select c.name
    into v_circle_name
  from public.circles c
  where c.id = p_circle_id
  limit 1;

  if not exists (
    select 1
    from public.notification_prefs np
    where np.user_id = v_target_user_id
      and np.push_enabled = false
  ) and not public.is_quiet_hours(v_target_user_id) then
    perform private.send_push_webhook(
      jsonb_build_object(
        'user_id', v_target_user_id,
        'title', 'A Circle invited you in',
        'body', coalesce(v_circle_name, 'A Betweener Circle') || ' sent you a private invitation.',
        'data', jsonb_build_object(
          'type', 'circle_invitation',
          'circle_id', p_circle_id,
          'invitation_id', v_invitation.id
        )
      )
    );
  end if;

  return v_invitation;
end;
$$;


ALTER FUNCTION "public"."rpc_invite_profile_to_circle"("p_circle_id" "uuid", "p_actor_profile_id" "uuid", "p_invited_profile_id" "uuid", "p_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_is_profile_saved"("p_viewer_profile_id" "uuid", "p_target_profile_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  select exists (
    select 1
    from public.profile_saves save_row
    join public.profiles viewer on viewer.id = save_row.viewer_profile_id
    where save_row.viewer_profile_id = p_viewer_profile_id
      and save_row.target_profile_id = p_target_profile_id
      and viewer.user_id = auth.uid()
  );
$$;


ALTER FUNCTION "public"."rpc_is_profile_saved"("p_viewer_profile_id" "uuid", "p_target_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_is_signin_provider_disconnected"("p_provider" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_provider text := lower(trim(coalesce(p_provider, '')));
begin
  if v_user_id is null then
    raise exception 'authentication required';
  end if;

  if v_provider not in ('google', 'apple') then
    return false;
  end if;

  return exists (
    select 1
    from public.account_disconnected_signin_providers
    where user_id = v_user_id
      and provider = v_provider
      and active = true
  );
end;
$$;


ALTER FUNCTION "public"."rpc_is_signin_provider_disconnected"("p_provider" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_join_circle"("p_circle_id" "uuid", "p_profile_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_owner uuid;
  v_profile public.profiles%rowtype;
  v_circle public.circles%rowtype;
  v_status text;
  v_has_invitation boolean := false;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  select *
    into v_profile
  from public.profiles
  where id = p_profile_id
    and deleted_at is null
  limit 1;

  v_owner := v_profile.user_id;
  if v_owner is null or v_owner <> auth.uid() then
    raise exception 'Not authorized';
  end if;

  select *
    into v_circle
  from public.circles
  where id = p_circle_id
  limit 1;

  if v_circle.id is null or v_circle.status <> 'approved' or v_circle.archived_at is not null then
    raise exception 'Circle not found';
  end if;

  select exists (
    select 1
    from public.circle_invitations invitation
    where invitation.circle_id = p_circle_id
      and invitation.invited_profile_id = p_profile_id
      and invitation.status = 'pending'
      and invitation.expires_at > timezone('utc'::text, now())
  ) into v_has_invitation;

  if not v_has_invitation
    and v_circle.visibility_scope in ('country', 'local')
    and (
      (
        nullif(btrim(coalesce(v_circle.country_code, '')), '') is not null
        and upper(btrim(coalesce(v_circle.country_code, ''))) <> upper(btrim(coalesce(v_profile.current_country_code, '')))
      )
      or (
        nullif(btrim(coalesce(v_circle.country_code, '')), '') is null
        and nullif(btrim(coalesce(v_circle.country_name, '')), '') is not null
        and lower(btrim(coalesce(v_circle.country_name, ''))) <> lower(btrim(coalesce(v_profile.current_country, '')))
      )
      or (
        v_circle.visibility_scope = 'local'
        and nullif(btrim(coalesce(v_circle.city, '')), '') is not null
        and lower(btrim(coalesce(v_circle.city, ''))) <> lower(btrim(coalesce(v_profile.city, '')))
      )
    ) then
    raise exception 'circle_scope_mismatch' using errcode = '42501';
  end if;

  v_status := case
    when v_circle.visibility = 'private'
      or v_circle.visibility_scope = 'invite_only'
      or coalesce(v_circle.requires_join_approval, false)
      then 'pending'
    else 'active'
  end;

  insert into public.circle_members (circle_id, profile_id, user_id, role, status, is_visible, joined_at, left_at)
  values (p_circle_id, p_profile_id, auth.uid(), 'member', v_status, true, timezone('utc'::text, now()), null)
  on conflict (circle_id, profile_id) do update
    set status = excluded.status,
        user_id = excluded.user_id,
        left_at = null,
        updated_at = timezone('utc'::text, now());

  update public.circles circle_row
  set member_count = (
    select count(*)::int
    from public.circle_members member
    where member.circle_id = circle_row.id
      and member.status = 'active'
  )
  where circle_row.id = p_circle_id;

  return v_status;
end;
$$;


ALTER FUNCTION "public"."rpc_join_circle"("p_circle_id" "uuid", "p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_leave_circle"("p_circle_id" "uuid", "p_profile_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_owner uuid;
  v_role text;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  select user_id into v_owner
  from public.profiles
  where id = p_profile_id
  limit 1;

  if v_owner is null or v_owner <> auth.uid() then
    raise exception 'Not authorized';
  end if;

  select role into v_role
  from public.circle_members
  where circle_id = p_circle_id and profile_id = p_profile_id
  limit 1;

  if v_role in ('leader', 'host', 'admin') then
    raise exception 'Host cannot leave circle';
  end if;

  update public.circle_members
  set status = 'left',
      left_at = timezone('utc'::text, now()),
      updated_at = timezone('utc'::text, now())
  where circle_id = p_circle_id
    and profile_id = p_profile_id;

  update public.circles c
  set member_count = (
    select count(*)::int
    from public.circle_members cm
    where cm.circle_id = c.id
      and cm.status = 'active'
  )
  where c.id = p_circle_id;

  return found;
end;
$$;


ALTER FUNCTION "public"."rpc_leave_circle"("p_circle_id" "uuid", "p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_link_phone_verification"("p_signup_session_id" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
declare
  v_user_id uuid;
begin
  v_user_id := auth.uid();
  if v_user_id is null then
    return false;
  end if;

  if p_signup_session_id is null or length(p_signup_session_id) = 0 then
    return false;
  end if;

  update public.phone_verifications
  set user_id = v_user_id
  where signup_session_id = p_signup_session_id
    and status = 'verified';

  return true;
end;
$$;


ALTER FUNCTION "public"."rpc_link_phone_verification"("p_signup_session_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_list_circle_love_seats_for_host"("p_circle_id" "uuid", "p_actor_profile_id" "uuid") RETURNS TABLE("id" "uuid", "circle_id" "uuid", "featured_profile_id" "uuid", "featured_profile_name" "text", "featured_profile_avatar_url" "text", "quote" "text", "status" "text", "created_at" timestamp with time zone, "responded_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_actor_profile_id
      and p.user_id = auth.uid()
      and p.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  if not public.can_manage_circle_pulse(p_circle_id, auth.uid()) then
    raise exception 'host_required' using errcode = '42501';
  end if;

  return query
  select
    cls.id,
    cls.circle_id,
    cls.featured_profile_id,
    coalesce(nullif(btrim(featured.full_name), ''), 'Circle member') as featured_profile_name,
    featured.avatar_url as featured_profile_avatar_url,
    cls.quote,
    cls.status,
    cls.created_at,
    cls.responded_at
  from public.circle_love_seats cls
  join public.profiles featured on featured.id = cls.featured_profile_id
  where cls.circle_id = p_circle_id
    and cls.status in ('pending_user_approval', 'active')
  order by
    case cls.status when 'active' then 0 else 1 end,
    cls.created_at desc;
end;
$$;


ALTER FUNCTION "public"."rpc_list_circle_love_seats_for_host"("p_circle_id" "uuid", "p_actor_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_list_circle_pulse_comment_reports"("p_circle_id" "uuid", "p_actor_profile_id" "uuid") RETURNS TABLE("comment_id" "uuid", "circle_id" "uuid", "pulse_item_id" "uuid", "pulse_item_type" "text", "pulse_item_title" "text", "comment_profile_id" "uuid", "comment_author_name" "text", "comment_body" "text", "report_count" integer, "latest_reason" "text", "latest_report_at" timestamp with time zone, "status" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_actor_profile_id
      and p.user_id = auth.uid()
      and p.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  if not public.can_manage_circle_pulse(p_circle_id, auth.uid()) then
    raise exception 'host_required' using errcode = '42501';
  end if;

  return query
  select
    cpc.id as comment_id,
    cpc.circle_id,
    cpc.pulse_item_id,
    cpi.item_type as pulse_item_type,
    coalesce(
      nullif(btrim(cpi.title), ''),
      nullif(btrim(cp.title), ''),
      nullif(btrim(g.title), ''),
      initcap(replace(cpi.item_type, '_', ' '))
    ) as pulse_item_title,
    cpc.profile_id as comment_profile_id,
    coalesce(nullif(btrim(author.full_name), ''), 'Circle member') as comment_author_name,
    cpc.body as comment_body,
    count(cpcr.id)::integer as report_count,
    (array_agg(cpcr.reason order by cpcr.created_at desc, cpcr.id desc))[1] as latest_reason,
    max(cpcr.created_at) as latest_report_at,
    case
      when bool_or(cpcr.status = 'reviewing') then 'reviewing'::text
      else 'pending'::text
    end as status
  from public.circle_pulse_comment_reports cpcr
  join public.circle_pulse_comments cpc on cpc.id = cpcr.comment_id
  join public.circle_pulse_items cpi on cpi.id = cpc.pulse_item_id
  join public.profiles author on author.id = cpc.profile_id
  left join public.circle_prompts cp on cp.id = cpi.prompt_id
  left join public.gatherings g on g.id = cpi.gathering_id
  where cpcr.circle_id = p_circle_id
    and cpcr.status in ('pending', 'reviewing')
    and cpc.status = 'active'
  group by
    cpc.id,
    cpc.circle_id,
    cpc.pulse_item_id,
    cpi.item_type,
    cpi.title,
    cp.title,
    g.title,
    cpc.profile_id,
    author.full_name,
    cpc.body
  order by
    case when bool_or(cpcr.status = 'reviewing') then 1 else 0 end,
    max(cpcr.created_at) desc,
    cpc.id desc
  limit 100;
end;
$$;


ALTER FUNCTION "public"."rpc_list_circle_pulse_comment_reports"("p_circle_id" "uuid", "p_actor_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_list_circle_reports"("p_circle_id" "uuid", "p_profile_id" "uuid") RETURNS TABLE("id" "uuid", "circle_id" "uuid", "gathering_id" "uuid", "prompt_response_id" "uuid", "reporter_profile_id" "uuid", "reason" "text", "details" "text", "status" "text", "created_at" timestamp with time zone, "gathering_title" "text", "prompt_response_text" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_owner uuid;
  v_actor_role text;
  v_is_admin boolean := public.is_admin_user(auth.uid());
  v_is_circle_owner boolean := false;
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if p_circle_id is null then
    raise exception 'circle_not_found';
  end if;

  select p.user_id into v_owner
  from public.profiles p
  where p.id = p_profile_id
  limit 1;

  if v_owner is null or v_owner <> auth.uid() then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  v_is_circle_owner := public.is_circle_owner(p_circle_id, auth.uid());

  if not v_is_admin and not v_is_circle_owner then
    select lower(cm.role) into v_actor_role
    from public.circle_members cm
    where cm.circle_id = p_circle_id
      and cm.profile_id = p_profile_id
      and cm.status = 'active'
    limit 1;

    if coalesce(v_actor_role, '') not in ('leader', 'host', 'admin', 'moderator') then
      raise exception 'host_required' using errcode = '42501';
    end if;
  end if;

  return query
  select
    cr.id,
    cr.circle_id,
    cr.gathering_id,
    cr.prompt_response_id,
    cr.reporter_profile_id,
    cr.reason,
    cr.details,
    cr.status,
    cr.created_at,
    g.title as gathering_title,
    cpr.response as prompt_response_text
  from public.circle_reports cr
  left join public.gatherings g on g.id = cr.gathering_id
  left join public.circle_prompt_responses cpr on cpr.id = cr.prompt_response_id
  where cr.circle_id = p_circle_id
  order by
    case cr.status
      when 'pending' then 0
      when 'reviewing' then 1
      else 2
    end,
    cr.created_at desc
  limit 50;
end;
$$;


ALTER FUNCTION "public"."rpc_list_circle_reports"("p_circle_id" "uuid", "p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_list_my_circle_invitations"("p_profile_id" "uuid") RETURNS TABLE("invitation_id" "uuid", "circle_id" "uuid", "circle_name" "text", "circle_image_url" "text", "circle_image_path" "text", "inviter_name" "text", "message" "text", "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles recipient
    where recipient.id = p_profile_id
      and recipient.user_id = auth.uid()
      and recipient.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  return query
  select
    invitation.id,
    invitation.circle_id,
    circle_row.name,
    coalesce(circle_row.cover_image_url, circle_row.icon_url),
    circle_row.image_path,
    coalesce(nullif(btrim(inviter.full_name), ''), 'A Circle member'),
    invitation.message,
    invitation.expires_at
  from public.circle_invitations invitation
  join public.circles circle_row on circle_row.id = invitation.circle_id
  join public.profiles inviter on inviter.id = invitation.inviter_profile_id
  where invitation.invited_profile_id = p_profile_id
    and invitation.status = 'pending'
    and invitation.expires_at > timezone('utc'::text, now())
  order by invitation.created_at desc, invitation.id desc;
end;
$$;


ALTER FUNCTION "public"."rpc_list_my_circle_invitations"("p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_list_sent_circle_invitations"("p_circle_id" "uuid", "p_actor_profile_id" "uuid") RETURNS TABLE("id" "uuid", "invited_profile_id" "uuid", "invited_profile_name" "text", "invited_profile_avatar_url" "text", "invited_profile_age" integer, "invited_profile_location" "text", "status" "text", "created_at" timestamp with time zone, "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles actor
    where actor.id = p_actor_profile_id
      and actor.user_id = auth.uid()
      and actor.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  if not public.can_invite_to_circle(p_circle_id, auth.uid()) then
    raise exception 'circle_membership_required' using errcode = '42501';
  end if;

  return query
  select
    ci.id,
    ci.invited_profile_id,
    coalesce(nullif(btrim(invited.full_name), ''), 'Betweener member') as invited_profile_name,
    invited.avatar_url as invited_profile_avatar_url,
    invited.age as invited_profile_age,
    coalesce(nullif(btrim(invited.city), ''), nullif(btrim(invited.region), ''), nullif(btrim(invited.location), '')) as invited_profile_location,
    ci.status,
    ci.created_at,
    ci.expires_at
  from public.circle_invitations ci
  join public.profiles invited on invited.id = ci.invited_profile_id
  where ci.circle_id = p_circle_id
    and ci.status = 'pending'
    and ci.expires_at > timezone('utc'::text, now())
  order by ci.created_at desc, ci.id desc;
end;
$$;


ALTER FUNCTION "public"."rpc_list_sent_circle_invitations"("p_circle_id" "uuid", "p_actor_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_log_profile_gift_event"("p_gift_id" "uuid", "p_event_type" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_gift public.profile_gifts%rowtype;
  v_actor_profile_id uuid;
  v_actor_profile_user_id uuid;
begin
  if auth.uid() is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  if coalesce(nullif(btrim(p_event_type), ''), '') not in ('sent', 'revealed', 'archived', 'sender_profile_opened', 'recipient_profile_opened') then
    raise exception 'invalid_profile_gift_event_type' using errcode = '22023';
  end if;

  select g.*
    into v_gift
  from public.profile_gifts g
  where g.id = p_gift_id
  limit 1;

  if v_gift.id is null then
    raise exception 'gift not found' using errcode = 'P0002';
  end if;

  select p.id, p.user_id
    into v_actor_profile_id, v_actor_profile_user_id
  from public.profiles p
  where p.user_id = auth.uid()
    and p.deleted_at is null
  limit 1;

  if p_event_type in ('sent', 'recipient_profile_opened') and v_gift.sender_id <> auth.uid() then
    raise exception 'gift sender required' using errcode = '42501';
  end if;

  if p_event_type in ('revealed', 'archived', 'sender_profile_opened') and not exists (
    select 1
    from public.profiles recipient
    where recipient.id = v_gift.profile_id
      and recipient.user_id = auth.uid()
      and recipient.deleted_at is null
  ) then
    raise exception 'gift recipient required' using errcode = '42501';
  end if;

  insert into public.profile_gift_events (
    gift_id,
    actor_user_id,
    actor_profile_id,
    recipient_profile_id,
    sender_profile_id,
    event_type,
    metadata
  )
  values (
    v_gift.id,
    auth.uid(),
    v_actor_profile_id,
    v_gift.profile_id,
    v_gift.sender_profile_id,
    p_event_type,
    coalesce(p_metadata, '{}'::jsonb)
  );

  return true;
end;
$$;


ALTER FUNCTION "public"."rpc_log_profile_gift_event"("p_gift_id" "uuid", "p_event_type" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_log_suggested_move_event"("p_viewer_profile_id" "uuid", "p_candidate_profile_id" "uuid", "p_event_type" "text", "p_surface" "text" DEFAULT 'intent_suggested'::"text", "p_batch_key" "text" DEFAULT NULL::"text", "p_slot_index" integer DEFAULT NULL::integer, "p_is_hero" boolean DEFAULT NULL::boolean, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid;
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  if p_event_type not in ('impression', 'preview_profile', 'opener_revealed', 'intent_opened', 'intent_sent') then
    raise exception 'invalid suggested move event type';
  end if;

  if p_viewer_profile_id is null or p_candidate_profile_id is null or p_viewer_profile_id = p_candidate_profile_id then
    return false;
  end if;

  select p.user_id
    into v_user_id
  from public.profiles p
  where p.id = p_viewer_profile_id
  limit 1;

  if v_user_id is null or v_user_id <> auth.uid() then
    raise exception 'viewer profile does not belong to authenticated user';
  end if;

  insert into public.suggested_move_events (
    viewer_user_id,
    viewer_profile_id,
    candidate_profile_id,
    event_type,
    surface,
    batch_key,
    slot_index,
    is_hero,
    metadata
  )
  values (
    auth.uid(),
    p_viewer_profile_id,
    p_candidate_profile_id,
    p_event_type,
    coalesce(nullif(btrim(p_surface), ''), 'intent_suggested'),
    nullif(btrim(p_batch_key), ''),
    p_slot_index,
    p_is_hero,
    coalesce(p_metadata, '{}'::jsonb)
  );

  return true;
end;
$$;


ALTER FUNCTION "public"."rpc_log_suggested_move_event"("p_viewer_profile_id" "uuid", "p_candidate_profile_id" "uuid", "p_event_type" "text", "p_surface" "text", "p_batch_key" "text", "p_slot_index" integer, "p_is_hero" boolean, "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_log_vibes_event"("p_viewer_profile_id" "uuid", "p_target_profile_id" "uuid", "p_segment" "text" DEFAULT 'for_you'::"text", "p_event_type" "text" DEFAULT 'card_seen'::"text", "p_position" integer DEFAULT NULL::integer, "p_dwell_ms" integer DEFAULT NULL::integer, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_catalog'
    AS $$
declare
  v_viewer_user_id uuid;
  v_target_user_id uuid;
  v_viewer_name text;
  v_viewer_avatar text;
  v_target_plan text := 'FREE';
  v_segment text := coalesce(nullif(btrim(p_segment), ''), 'for_you');
  v_event_type text := coalesce(nullif(btrim(p_event_type), ''), 'card_seen');
  v_throttle interval;
  v_has_inbox_items boolean := to_regclass('public.inbox_items') is not null;
  v_actor_label text := 'Someone';
  v_identity_revealed boolean := false;
  v_pref_inapp_enabled boolean := true;
  v_pref_push_enabled boolean := true;
  v_pref_profile_interest boolean := true;
  v_inbox_allowed boolean := false;
  v_push_allowed boolean := false;
  v_delivered boolean := false;
  v_recent_delivery_exists boolean := false;
  v_signal_group text;
  v_signal_dedupe_scope text := 'actor';
  v_signal_dedupe_window interval := interval '6 hours';
  v_notification_title text;
  v_notification_body text;
  v_notification_actor_id uuid;
  v_notification_metadata jsonb;
  v_push_title text;
  v_push_body text;
  v_push_payload jsonb;
begin
  if auth.uid() is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  if v_segment not in ('for_you', 'nearby', 'active_now') then
    raise exception 'invalid_vibes_segment';
  end if;

  if v_event_type not in (
    'card_seen', 'profile_opened', 'full_profile_opened', 'intro_played',
    'intro_completed', 'profile_saved', 'profile_unsaved', 'pass', 'like',
    'signal_opened', 'signal_sent', 'intent_opened', 'intent_sent', 'undo'
  ) then
    raise exception 'invalid_vibes_event_type';
  end if;

  if p_viewer_profile_id is null
    or p_target_profile_id is null
    or p_viewer_profile_id = p_target_profile_id then
    return false;
  end if;

  select profile.user_id, profile.full_name, profile.avatar_url
    into v_viewer_user_id, v_viewer_name, v_viewer_avatar
  from public.profiles profile
  where profile.id = p_viewer_profile_id
    and profile.deleted_at is null
  limit 1;

  if v_viewer_user_id is null or v_viewer_user_id <> auth.uid() then
    raise exception 'viewer profile does not belong to authenticated user' using errcode = '42501';
  end if;

  select profile.user_id
    into v_target_user_id
  from public.profiles profile
  where profile.id = p_target_profile_id
    and profile.deleted_at is null
  limit 1;

  if v_target_user_id is null then
    return false;
  end if;

  v_target_plan := coalesce(public.get_active_subscription_plan(v_target_user_id)::text, 'FREE');
  if v_target_plan not in ('FREE', 'SILVER', 'GOLD') then
    v_target_plan := 'FREE';
  end if;

  if exists (
    select 1
    from public.blocks block_row
    where (block_row.blocker_id = v_viewer_user_id and block_row.blocked_id = v_target_user_id)
       or (block_row.blocker_id = v_target_user_id and block_row.blocked_id = v_viewer_user_id)
  ) then
    return false;
  end if;

  v_throttle := case
    when v_event_type = 'card_seen' then interval '6 hours'
    when v_event_type in ('profile_opened', 'full_profile_opened') then interval '30 minutes'
    when v_event_type in ('intro_played', 'intro_completed', 'intent_opened') then interval '6 hours'
    when v_event_type in ('profile_saved', 'profile_unsaved') then null
    else interval '2 minutes'
  end;

  if v_throttle is not null and exists (
    select 1
    from public.vibes_events event_row
    where event_row.viewer_profile_id = p_viewer_profile_id
      and event_row.target_profile_id = p_target_profile_id
      and event_row.event_type = v_event_type
      and event_row.segment = v_segment
      and event_row.created_at > timezone('utc'::text, now()) - v_throttle
  ) then
    return false;
  end if;

  insert into public.vibes_events (
    viewer_user_id,
    viewer_profile_id,
    target_profile_id,
    target_user_id,
    segment,
    event_type,
    position,
    dwell_ms,
    metadata
  )
  values (
    v_viewer_user_id,
    p_viewer_profile_id,
    p_target_profile_id,
    v_target_user_id,
    v_segment,
    v_event_type,
    p_position,
    greatest(coalesce(p_dwell_ms, 0), 0),
    coalesce(p_metadata, '{}'::jsonb)
  );

  v_signal_group := case
    when v_event_type = 'profile_saved' then 'save'
    when v_event_type in ('intro_played', 'intro_completed') then 'intro'
    when v_event_type = 'intent_opened' then 'intent'
    when v_event_type in ('profile_opened', 'full_profile_opened')
      and exists (
        select 1
        from public.vibes_events previous_event
        where previous_event.viewer_profile_id = p_viewer_profile_id
          and previous_event.target_profile_id = p_target_profile_id
          and previous_event.event_type in ('profile_opened', 'full_profile_opened')
          and previous_event.created_at < timezone('utc'::text, now()) - interval '30 minutes'
          and previous_event.created_at > timezone('utc'::text, now()) - interval '30 days'
      )
      then 'repeat_visit'
    else null
  end;

  if v_signal_group is null then
    return true;
  end if;

  v_signal_dedupe_scope := case
    when v_signal_group = 'repeat_visit' then 'global'
    else 'actor'
  end;

  v_signal_dedupe_window := case
    when v_signal_group = 'repeat_visit' then interval '12 hours'
    when v_signal_group = 'intro' then interval '8 hours'
    when v_signal_group = 'intent' then interval '6 hours'
    when v_signal_group = 'save' then interval '4 hours'
    else interval '6 hours'
  end;

  select
    coalesce(prefs.inapp_enabled, true),
    coalesce(prefs.push_enabled, true),
    coalesce(prefs.profile_interest, true)
    into v_pref_inapp_enabled, v_pref_push_enabled, v_pref_profile_interest
  from public.notification_prefs prefs
  where prefs.user_id = v_target_user_id
  limit 1;

  if not found then
    v_pref_inapp_enabled := true;
    v_pref_push_enabled := true;
    v_pref_profile_interest := true;
  end if;

  v_inbox_allowed := v_has_inbox_items and v_pref_inapp_enabled and v_pref_profile_interest;
  v_push_allowed := v_pref_push_enabled and v_pref_profile_interest and not public.is_quiet_hours(v_target_user_id);

  if not v_inbox_allowed and not v_push_allowed then
    return true;
  end if;

  select exists (
    select 1
    from public.profile_interest_notification_deliveries delivery
    where delivery.recipient_user_id = v_target_user_id
      and delivery.signal_group = v_signal_group
      and delivery.delivered_at > timezone('utc'::text, now()) - v_signal_dedupe_window
      and (
        v_signal_dedupe_scope = 'global'
        or delivery.actor_profile_id = p_viewer_profile_id
      )
  )
    into v_recent_delivery_exists;

  if v_recent_delivery_exists then
    return true;
  end if;

  v_actor_label := coalesce(nullif(btrim(v_viewer_name), ''), 'Someone');
  v_identity_revealed := v_target_plan in ('SILVER', 'GOLD');
  v_notification_actor_id := case when v_identity_revealed then p_viewer_profile_id else null end;

  v_notification_title := case
    when v_identity_revealed then v_actor_label
    else 'Profile Interest'
  end;

  v_notification_body := case
    when v_target_plan = 'FREE' then
      case v_signal_group
        when 'save' then 'Someone saved your profile. Upgrade to see who it is.'
        when 'intro' then 'Someone spent time with your intro video. Upgrade to see who it is.'
        when 'intent' then 'Someone opened your Intent card. Upgrade to see who it is.'
        when 'repeat_visit' then 'Someone revisited your profile. Upgrade to see who it is.'
        else null
      end
    when v_target_plan = 'GOLD' then
      case
        when v_signal_group = 'save' then 'Saved your profile. Open Profile Interest for the full signal story.'
        when v_event_type = 'intro_completed' then 'Finished your intro video. Open Profile Interest for the full signal story.'
        when v_signal_group = 'intro' then 'Spent time with your intro video. Open Profile Interest for the full signal story.'
        when v_signal_group = 'intent' then 'Opened your Intent card. Open Profile Interest for the full signal story.'
        when v_signal_group = 'repeat_visit' then 'Came back to your profile. Open Profile Interest for the full signal story.'
        else null
      end
    else
      case
        when v_signal_group = 'save' then 'Saved your profile.'
        when v_event_type = 'intro_completed' then 'Finished your intro video.'
        when v_signal_group = 'intro' then 'Spent time with your intro video.'
        when v_signal_group = 'intent' then 'Opened your Intent card.'
        when v_signal_group = 'repeat_visit' then 'Came back to your profile.'
        else null
      end
  end;

  v_push_title := case
    when v_identity_revealed then v_actor_label
    else 'Profile Interest'
  end;

  v_push_body := case
    when v_identity_revealed then
      case
        when v_signal_group = 'save' then v_actor_label || ' saved your profile.'
        when v_event_type = 'intro_completed' then v_actor_label || ' finished your intro video.'
        when v_signal_group = 'intro' then v_actor_label || ' spent time with your intro video.'
        when v_signal_group = 'intent' then v_actor_label || ' opened your Intent card.'
        when v_signal_group = 'repeat_visit' then v_actor_label || ' revisited your profile.'
        else null
      end
    else
      case
        when v_signal_group = 'save' then 'Someone saved your profile.'
        when v_event_type = 'intro_completed' then 'Someone finished your intro video.'
        when v_signal_group = 'intro' then 'Someone spent time with your intro video.'
        when v_signal_group = 'intent' then 'Someone opened your Intent card.'
        when v_signal_group = 'repeat_visit' then 'Someone revisited your profile.'
        else null
      end
  end;

  v_notification_metadata := jsonb_strip_nulls(jsonb_build_object(
    'type', 'profile_interest',
    'signal', v_event_type,
    'signal_group', v_signal_group,
    'audience_plan', v_target_plan,
    'detail_tier', case
      when v_target_plan = 'GOLD' then 'gold_story'
      when v_target_plan = 'SILVER' then 'silver_identity'
      else 'free_teaser'
    end,
    'identity_revealed', v_identity_revealed,
    'cta_plan', case
      when v_target_plan = 'FREE' then 'SILVER'
      when v_target_plan = 'SILVER' then 'GOLD'
      else null
    end,
    'profile_id', case when v_identity_revealed then p_viewer_profile_id end,
    'name', case when v_identity_revealed then v_actor_label end,
    'avatar_url', case when v_identity_revealed then v_viewer_avatar end,
    'route', '/profile-interest'
  ));

  v_push_payload := jsonb_strip_nulls(jsonb_build_object(
    'type', 'profile_interest',
    'signal', v_event_type,
    'signal_group', v_signal_group,
    'audience_plan', v_target_plan,
    'detail_tier', case
      when v_target_plan = 'GOLD' then 'gold_story'
      when v_target_plan = 'SILVER' then 'silver_identity'
      else 'free_teaser'
    end,
    'identity_revealed', v_identity_revealed,
    'cta_plan', case
      when v_target_plan = 'FREE' then 'SILVER'
      when v_target_plan = 'SILVER' then 'GOLD'
      else null
    end,
    'route', '/profile-interest',
    'profile_id', case when v_identity_revealed then p_viewer_profile_id end,
    'name', case when v_identity_revealed then v_actor_label end,
    'avatar_url', case when v_identity_revealed then v_viewer_avatar end
  ));

  if v_inbox_allowed and v_notification_body is not null then
    insert into public.inbox_items (
      user_id,
      type,
      actor_id,
      entity_id,
      entity_type,
      title,
      body,
      action_required,
      metadata
    )
    values (
      v_target_user_id,
      'SYSTEM',
      v_notification_actor_id,
      p_target_profile_id,
      'profile_interest',
      v_notification_title,
      v_notification_body,
      false,
      v_notification_metadata
    );

    v_delivered := true;
  end if;

  if v_push_allowed and v_push_body is not null then
    perform private.send_push_webhook(
      jsonb_build_object(
        'user_id', v_target_user_id,
        'title', v_push_title,
        'body', v_push_body,
        'data', v_push_payload
      )
    );

    v_delivered := true;
  end if;

  if v_delivered then
    insert into public.profile_interest_notification_deliveries (
      recipient_user_id,
      actor_profile_id,
      target_profile_id,
      signal_group,
      signal_type,
      audience_plan,
      dedupe_scope,
      delivered_at
    )
    values (
      v_target_user_id,
      case when v_signal_dedupe_scope = 'actor' then p_viewer_profile_id else null end,
      p_target_profile_id,
      v_signal_group,
      v_event_type,
      v_target_plan,
      v_signal_dedupe_scope,
      timezone('utc'::text, now())
    );
  end if;

  return true;
end;
$$;


ALTER FUNCTION "public"."rpc_log_vibes_event"("p_viewer_profile_id" "uuid", "p_target_profile_id" "uuid", "p_segment" "text", "p_event_type" "text", "p_position" integer, "p_dwell_ms" integer, "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_mark_chat_thread_read"("p_peer_user_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_count integer := 0;
begin
  if v_user_id is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if p_peer_user_id is null or p_peer_user_id = v_user_id then
    raise exception 'invalid_peer';
  end if;

  update public.messages message_row
  set delivered_at = coalesce(message_row.delivered_at, timezone('utc'::text, now())),
      read_at = coalesce(message_row.read_at, timezone('utc'::text, now())),
      is_read = true
  where message_row.sender_id = p_peer_user_id
    and message_row.receiver_id = v_user_id
    and (
      coalesce(message_row.is_read, false) = false
      or message_row.read_at is null
      or message_row.delivered_at is null
    );

  get diagnostics v_count = row_count;

  update public.chat_conversation_summaries summary
  set unread_count = 0,
      updated_at = timezone('utc'::text, now())
  where summary.owner_user_id = v_user_id
    and summary.peer_user_id = p_peer_user_id
    and summary.unread_count <> 0;

  return v_count;
end;
$$;


ALTER FUNCTION "public"."rpc_mark_chat_thread_read"("p_peer_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_mark_circle_pulse_discussion_seen"("p_pulse_item_id" "uuid", "p_profile_id" "uuid", "p_last_seen_comment_id" "uuid" DEFAULT NULL::"uuid", "p_last_seen_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_circle_id uuid;
  v_last_seen_at timestamptz := coalesce(p_last_seen_at, timezone('utc'::text, now()));
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_profile_id
      and p.user_id = auth.uid()
      and p.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  select cpi.circle_id
    into v_circle_id
  from public.circle_pulse_items cpi
  where cpi.id = p_pulse_item_id
  limit 1;

  if v_circle_id is null then
    raise exception 'pulse_item_not_found';
  end if;

  if not public.can_manage_circle_pulse(v_circle_id, auth.uid())
    and not public.is_circle_member(v_circle_id, auth.uid())
    and not public.is_circle_owner(v_circle_id, auth.uid()) then
    raise exception 'circle_membership_required' using errcode = '42501';
  end if;

  if p_last_seen_comment_id is not null and not exists (
    select 1
    from public.circle_pulse_comments cpc
    where cpc.id = p_last_seen_comment_id
      and cpc.pulse_item_id = p_pulse_item_id
      and cpc.status = 'active'
  ) then
    raise exception 'comment_not_found';
  end if;

  insert into public.circle_pulse_discussion_reads (
    circle_id,
    pulse_item_id,
    profile_id,
    user_id,
    last_seen_comment_id,
    last_seen_at
  )
  values (
    v_circle_id,
    p_pulse_item_id,
    p_profile_id,
    auth.uid(),
    p_last_seen_comment_id,
    v_last_seen_at
  )
  on conflict (pulse_item_id, profile_id)
  do update
    set circle_id = excluded.circle_id,
        user_id = excluded.user_id,
        last_seen_comment_id = case
          when public.circle_pulse_discussion_reads.last_seen_at <= excluded.last_seen_at
            then excluded.last_seen_comment_id
          else public.circle_pulse_discussion_reads.last_seen_comment_id
        end,
        last_seen_at = greatest(public.circle_pulse_discussion_reads.last_seen_at, excluded.last_seen_at),
        updated_at = timezone('utc'::text, now());

  return true;
end;
$$;


ALTER FUNCTION "public"."rpc_mark_circle_pulse_discussion_seen"("p_pulse_item_id" "uuid", "p_profile_id" "uuid", "p_last_seen_comment_id" "uuid", "p_last_seen_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_mark_expired_intent_requests"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  updated_count integer;
BEGIN
  UPDATE public.intent_requests
  SET status = 'expired'
  WHERE status = 'pending'
    AND expires_at < now();
  GET DIAGNOSTICS updated_count = ROW_COUNT;
  RETURN updated_count;
END;
$$;


ALTER FUNCTION "public"."rpc_mark_expired_intent_requests"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_mark_match_celebration_seen"("p_event_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  update public.match_celebration_events
  set seen_at = coalesce(seen_at, now())
  where id = p_event_id
    and recipient_user_id = auth.uid();

  return found;
end;
$$;


ALTER FUNCTION "public"."rpc_mark_match_celebration_seen"("p_event_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_mark_message_read"("p_message_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_count integer := 0;
begin
  if v_user_id is null then
    raise exception 'unauthenticated';
  end if;

  update public.messages
  set delivered_at = coalesce(delivered_at, now()),
      read_at = coalesce(read_at, now()),
      is_read = true
  where id = p_message_id
    and receiver_id = v_user_id
    and (
      coalesce(is_read, false) = false
      or read_at is null
      or delivered_at is null
    );

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


ALTER FUNCTION "public"."rpc_mark_message_read"("p_message_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_mark_messages_read"("p_message_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_count integer := 0;
begin
  if v_user_id is null then
    raise exception 'unauthenticated';
  end if;

  if coalesce(array_length(p_message_ids, 1), 0) = 0 then
    return 0;
  end if;

  update public.messages
  set delivered_at = coalesce(delivered_at, now()),
      read_at = coalesce(read_at, now()),
      is_read = true
  where id = any(p_message_ids)
    and receiver_id = v_user_id
    and (
      coalesce(is_read, false) = false
      or read_at is null
      or delivered_at is null
    );

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


ALTER FUNCTION "public"."rpc_mark_messages_read"("p_message_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_mark_moment_view"("p_moment_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_viewer_id uuid := auth.uid();
  v_owner_id uuid;
  v_now timestamptz := now();
begin
  if v_viewer_id is null or p_moment_id is null then
    return false;
  end if;

  select m.user_id
  into v_owner_id
  from public.moments m
  where m.id = p_moment_id
    and m.is_deleted = false
    and m.expires_at > now()
  limit 1;

  if v_owner_id is null or v_owner_id = v_viewer_id then
    return false;
  end if;

  if not public.can_view_moment(p_moment_id) then
    return false;
  end if;

  insert into public.moment_views (moment_id, viewer_user_id, viewed_at)
  values (p_moment_id, v_viewer_id, v_now)
  on conflict (moment_id, viewer_user_id)
  do update
    set viewed_at = greatest(public.moment_views.viewed_at, excluded.viewed_at);

  return true;
end;
$$;


ALTER FUNCTION "public"."rpc_mark_moment_view"("p_moment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_mark_signin_provider_disconnected"("p_provider" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_provider text := lower(trim(coalesce(p_provider, '')));
begin
  if v_user_id is null then
    raise exception 'authentication required';
  end if;

  if v_provider not in ('google', 'apple') then
    raise exception 'unsupported provider';
  end if;

  insert into public.account_disconnected_signin_providers (
    user_id,
    provider,
    active,
    disconnected_at,
    reconnected_at,
    updated_at
  )
  values (
    v_user_id,
    v_provider,
    true,
    timezone('utc'::text, now()),
    null,
    timezone('utc'::text, now())
  )
  on conflict (user_id, provider) where active = true
  do update
  set
    active = true,
    disconnected_at = timezone('utc'::text, now()),
    reconnected_at = null,
    updated_at = timezone('utc'::text, now());

  return true;
end;
$$;


ALTER FUNCTION "public"."rpc_mark_signin_provider_disconnected"("p_provider" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."circle_love_seats" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "circle_id" "uuid" NOT NULL,
    "featured_profile_id" "uuid" NOT NULL,
    "nominated_by_profile_id" "uuid",
    "approved_by_profile_id" "uuid",
    "status" "text" DEFAULT 'pending_user_approval'::"text" NOT NULL,
    "quote" "text",
    "reason" "text",
    "starts_at" timestamp with time zone,
    "ends_at" timestamp with time zone,
    "responded_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    CONSTRAINT "circle_love_seats_quote_length" CHECK ((("quote" IS NULL) OR (("char_length"("btrim"("quote")) >= 1) AND ("char_length"("btrim"("quote")) <= 320)))),
    CONSTRAINT "circle_love_seats_reason_length" CHECK ((("reason" IS NULL) OR ("char_length"("btrim"("reason")) <= 500))),
    CONSTRAINT "circle_love_seats_status_valid" CHECK (("status" = ANY (ARRAY['pending_user_approval'::"text", 'approved'::"text", 'active'::"text", 'declined'::"text", 'ended'::"text", 'archived'::"text"]))),
    CONSTRAINT "circle_love_seats_time_valid" CHECK ((("ends_at" IS NULL) OR ("starts_at" IS NULL) OR ("ends_at" > "starts_at")))
);


ALTER TABLE "public"."circle_love_seats" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_nominate_circle_love_seat"("p_circle_id" "uuid", "p_actor_profile_id" "uuid", "p_featured_profile_id" "uuid", "p_quote" "text" DEFAULT NULL::"text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "public"."circle_love_seats"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_love_seat public.circle_love_seats%rowtype;
  v_quote text := nullif(btrim(coalesce(p_quote, '')), '');
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_actor_profile_id
      and p.user_id = auth.uid()
      and p.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  if not public.can_manage_circle_pulse(p_circle_id, auth.uid()) then
    raise exception 'host_required' using errcode = '42501';
  end if;

  if v_quote is not null and char_length(v_quote) > 320 then
    raise exception 'quote_too_long';
  end if;

  if v_reason is not null and char_length(v_reason) > 500 then
    raise exception 'reason_too_long';
  end if;

  if exists (
    select 1
    from public.circle_love_seats cls
    where cls.circle_id = p_circle_id
      and cls.status = 'active'
  ) then
    raise exception 'circle_love_seat_active';
  end if;

  if not exists (
    select 1
    from public.circle_members cm
    join public.profiles p on p.id = cm.profile_id
    where cm.circle_id = p_circle_id
      and cm.profile_id = p_featured_profile_id
      and cm.status = 'active'
      and cm.is_visible is not false
      and p.deleted_at is null
  ) then
    raise exception 'featured_member_not_available';
  end if;

  insert into public.circle_love_seats (
    circle_id,
    featured_profile_id,
    nominated_by_profile_id,
    quote,
    reason
  )
  values (
    p_circle_id,
    p_featured_profile_id,
    p_actor_profile_id,
    v_quote,
    v_reason
  )
  returning * into v_love_seat;

  return v_love_seat;
end;
$$;


ALTER FUNCTION "public"."rpc_nominate_circle_love_seat"("p_circle_id" "uuid", "p_actor_profile_id" "uuid", "p_featured_profile_id" "uuid", "p_quote" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_pin_circle_pulse_comment"("p_comment_id" "uuid", "p_profile_id" "uuid", "p_pinned" boolean DEFAULT true) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_comment public.circle_pulse_comments%rowtype;
  v_now timestamptz := timezone('utc'::text, now());
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_profile_id
      and p.user_id = auth.uid()
      and p.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  select *
    into v_comment
  from public.circle_pulse_comments cpc
  where cpc.id = p_comment_id
    and cpc.status = 'active'
  for update;

  if v_comment.id is null then
    raise exception 'comment_not_found';
  end if;

  if not public.can_manage_circle_pulse(v_comment.circle_id, auth.uid()) then
    raise exception 'host_required' using errcode = '42501';
  end if;

  if coalesce(p_pinned, true) then
    update public.circle_pulse_comments as cpc
    set pinned_at = null,
        pinned_by_profile_id = null,
        pinned_by_user_id = null
    where cpc.pulse_item_id = v_comment.pulse_item_id
      and cpc.id <> v_comment.id
      and cpc.pinned_at is not null;

    update public.circle_pulse_comments as cpc
    set pinned_at = v_now,
        pinned_by_profile_id = p_profile_id,
        pinned_by_user_id = auth.uid()
    where cpc.id = v_comment.id;
  else
    update public.circle_pulse_comments as cpc
    set pinned_at = null,
        pinned_by_profile_id = null,
        pinned_by_user_id = null
    where cpc.id = v_comment.id;
  end if;

  return true;
end;
$$;


ALTER FUNCTION "public"."rpc_pin_circle_pulse_comment"("p_comment_id" "uuid", "p_profile_id" "uuid", "p_pinned" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_process_intent_request_jobs"("p_remind_before" interval DEFAULT '06:00:00'::interval, "p_window" interval DEFAULT '00:15:00'::interval) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_catalog'
    AS $$
declare
  v_expired_marked integer := 0;
  v_expired_system_messages integer := 0;
  v_reminders_sent integer := 0;
  v_last_chance interval := interval '30 minutes';
begin
  with expired as (
    update public.intent_requests ir
    set status = 'expired'
    where ir.status = 'pending'
      and ir.expires_at < now()
    returning ir.id, ir.actor_id, ir.recipient_id, ir.type
  ),
  expired_events as (
    select e.id, e.actor_id, e.recipient_id, e.type
    from expired e
    union
    select ir.id, ir.actor_id, ir.recipient_id, ir.type
    from public.intent_requests ir
    where ir.status = 'expired'
      and ir.expires_at < now()
      and ir.expires_at >= (now() - p_window)
  ),
  inserted as (
    insert into public.system_messages (
      user_id,
      peer_user_id,
      intent_request_id,
      event_type,
      text,
      metadata
    )
    select
      pa.user_id as user_id,
      pr.user_id as peer_user_id,
      e.id as intent_request_id,
      'request_expired' as event_type,
      (
        'Your ' ||
        case e.type
          when 'connect' then 'conversation opening'
          when 'date_request' then 'date invitation'
          when 'like_with_note' then 'opening'
          when 'circle_intro' then 'introduction'
          else 'opening'
        end ||
        ' to ' || coalesce(pr.full_name, 'them') ||
        ' closed. If it still feels right, come back warmer and more specific.'
      ) as text,
      jsonb_build_object(
        'role', 'requester',
        'kind', 'intent_expired',
        'request_type', e.type,
        'recipient_profile_id', pr.id
      ) as metadata
    from expired_events e
    join public.profiles pa on pa.id = e.actor_id
    join public.profiles pr on pr.id = e.recipient_id
    where pa.user_id is not null
      and pr.user_id is not null
      and not exists (
        select 1
        from public.blocks b
        where (b.blocker_id = pa.user_id and b.blocked_id = pr.user_id)
           or (b.blocker_id = pr.user_id and b.blocked_id = pa.user_id)
      )
    on conflict (intent_request_id, user_id) do nothing
    returning 1
  )
  select
    (select count(*) from expired),
    (select count(*) from inserted)
  into v_expired_marked, v_expired_system_messages;

  with candidates as (
    select
      ir.id as request_id,
      ir.type as request_type,
      ir.actor_id,
      ir.recipient_id,
      pr.user_id as recipient_user_id,
      pa.user_id as actor_user_id,
      coalesce(nullif(btrim(pa.full_name), ''), 'Someone') as actor_name,
      pa.avatar_url as actor_avatar_url,
      (ir.expires_at - now()) as time_left,
      case
        when (ir.expires_at - now()) <= v_last_chance then 'recipient_last_chance'
        else 'recipient_primary'
      end as nudge_kind
    from public.intent_requests ir
    join public.profiles pr on pr.id = ir.recipient_id
    join public.profiles pa on pa.id = ir.actor_id
    left join public.notification_prefs np on np.user_id = pr.user_id
    where ir.status = 'pending'
      and ir.expires_at > now()
      and pr.user_id is not null
      and pa.user_id is not null
      and coalesce(np.push_enabled, true) = true
      and public.is_quiet_hours(pr.user_id) = false
      and not exists (
        select 1
        from public.blocks b
        where (b.blocker_id = pa.user_id and b.blocked_id = pr.user_id)
           or (b.blocker_id = pr.user_id and b.blocked_id = pa.user_id)
      )
      and (
        (ir.expires_at - now()) <= v_last_chance
        or (
          (ir.expires_at - now()) <= (
            case ir.type
              when 'date_request' then interval '12 hours'
              when 'connect' then interval '3 hours'
              when 'like_with_note' then interval '12 hours'
              when 'circle_intro' then interval '6 hours'
              else p_remind_before
            end
          )
          and (ir.expires_at - now()) > v_last_chance
        )
      )
      and not exists (
        select 1
        from public.intent_request_nudges n
        where n.intent_request_id = ir.id
          and n.kind = (
            case
              when (ir.expires_at - now()) <= v_last_chance then 'recipient_last_chance'
              else 'recipient_primary'
            end
          )
          and n.user_id = pr.user_id
      )
  ),
  reserved as (
    insert into public.intent_request_nudges (intent_request_id, kind, user_id, metadata)
    select
      c.request_id,
      c.nudge_kind,
      c.recipient_user_id,
      jsonb_build_object(
        'request_type', c.request_type,
        'time_left_minutes', floor(extract(epoch from c.time_left) / 60)
      )
    from candidates c
    on conflict (intent_request_id, kind, user_id) do nothing
    returning intent_request_id, kind, user_id
  ),
  to_send as (
    select c.*
    from candidates c
    join reserved r
      on r.intent_request_id = c.request_id
     and r.kind = c.nudge_kind
     and r.user_id = c.recipient_user_id
  ),
  pushes as (
    select private.send_push_webhook(
      jsonb_build_object(
        'user_id', t.recipient_user_id,
        'title', t.actor_name,
        'body',
          case
            when t.nudge_kind = 'recipient_last_chance'
              then 'This opening is about to close. If you are curious, answer now.'
            when t.request_type = 'date_request'
              then 'Would still like to take this beyond the app.'
            when t.request_type = 'like_with_note'
              then 'Left you a note worth answering.'
            when t.request_type = 'circle_intro'
              then 'Opened a more personal way to connect.'
            else 'Left the door open for a thoughtful reply.'
          end,
        'data', jsonb_build_object(
          'type', case when t.nudge_kind = 'recipient_last_chance' then 'intent_last_chance' else 'intent_expiring_soon' end,
          'request_id', t.request_id,
          'request_type', t.request_type,
          'actor_id', t.actor_id,
          'recipient_id', t.recipient_id,
          'name', t.actor_name,
          'avatar_url', t.actor_avatar_url
        )
      )
    ) as _sent
    from to_send t
  )
  select count(*) into v_reminders_sent from pushes;

  return jsonb_build_object(
    'expired_marked', v_expired_marked,
    'expired_system_messages', v_expired_system_messages,
    'reminders_sent', v_reminders_sent
  );
end;
$$;


ALTER FUNCTION "public"."rpc_process_intent_request_jobs"("p_remind_before" interval, "p_window" interval) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_process_relationship_compass_jobs"("p_ready_after" interval DEFAULT '24:00:00'::interval) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_catalog'
    AS $$
declare
  v_ready_sent integer := 0;
begin
  with candidates as (
    select
      p.id as profile_id,
      p.user_id,
      (p.relationship_compass->>'updatedAt')::timestamptz as compass_updated_at
    from public.profiles p
    left join public.notification_prefs np on np.user_id = p.user_id
    where p.user_id is not null
      and jsonb_typeof(coalesce(p.relationship_compass, '{}'::jsonb)) = 'object'
      and nullif(btrim(coalesce(p.relationship_compass->>'updatedAt', '')), '') is not null
      and ((p.relationship_compass->>'updatedAt')::timestamptz + p_ready_after) <= now()
      and coalesce(np.push_enabled, true) = true
      and public.is_quiet_hours(p.user_id) = false
  ),
  reserved as (
    insert into public.relationship_compass_nudges (
      user_id,
      profile_id,
      kind,
      compass_updated_at,
      metadata
    )
    select
      c.user_id,
      c.profile_id,
      'ready',
      c.compass_updated_at,
      jsonb_build_object(
        'ready_after_hours',
        floor(extract(epoch from p_ready_after) / 3600)
      )
    from candidates c
    on conflict (user_id, kind, compass_updated_at) do nothing
    returning user_id, profile_id, compass_updated_at
  ),
  pushes as (
    select private.send_push_webhook(
      jsonb_build_object(
        'user_id', r.user_id,
        'title', 'Relationship Compass',
        'body', 'Your Love Compass is ready again. Fresh curated profiles are waiting.',
        'data', jsonb_build_object(
          'type', 'relationship_compass_ready',
          'profile_id', r.profile_id,
          'compass_updated_at', r.compass_updated_at,
          'route', '/relationship-compass'
        )
      )
    ) as _sent
    from reserved r
  )
  select count(*) into v_ready_sent from pushes;

  return jsonb_build_object(
    'ready_sent', v_ready_sent
  );
end;
$$;


ALTER FUNCTION "public"."rpc_process_relationship_compass_jobs"("p_ready_after" interval) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_process_subscription_renewal_jobs"("p_first_remind_before" interval DEFAULT '7 days'::interval, "p_final_remind_before" interval DEFAULT '24:00:00'::interval, "p_include_sandbox" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private', 'pg_catalog'
    AS $_$
declare
  v_inbox_created integer := 0;
  v_push_scheduled integer := 0;
  v_has_inbox_items boolean := to_regclass('public.inbox_items') is not null;
  v_run_key uuid := gen_random_uuid();
begin
  if p_first_remind_before <= p_final_remind_before then
    raise exception 'invalid_reminder_window';
  end if;

  create temporary table if not exists pg_temp.subscription_renewal_candidates (
    subscription_id uuid not null,
    user_id uuid not null,
    type public.subscription_type not null,
    ends_at timestamptz not null,
    inapp_enabled boolean not null,
    push_enabled boolean not null,
    kind text not null,
    title text not null,
    body text not null
  ) on commit drop;

  create temporary table if not exists pg_temp.subscription_renewal_delivery (
    subscription_id uuid not null,
    user_id uuid not null,
    type public.subscription_type not null,
    ends_at timestamptz not null,
    inapp_enabled boolean not null,
    push_enabled boolean not null,
    kind text not null,
    title text not null,
    body text not null
  ) on commit drop;

  truncate table pg_temp.subscription_renewal_candidates;
  truncate table pg_temp.subscription_renewal_delivery;

  insert into pg_temp.subscription_renewal_candidates (
    subscription_id,
    user_id,
    type,
    ends_at,
    inapp_enabled,
    push_enabled,
    kind,
    title,
    body
  )
  with base as (
    select
      s.id as subscription_id,
      s.user_id,
      s.type,
      s.ends_at,
      coalesce(np.inapp_enabled, true) as inapp_enabled,
      coalesce(np.push_enabled, true) as push_enabled
    from public.subscriptions s
    left join public.notification_prefs np
      on np.user_id = s.user_id
    where s.is_active = true
      and s.type in ('SILVER', 'GOLD')
      and s.ends_at > timezone('utc'::text, now())
      and (
        coalesce(p_include_sandbox, false)
        or upper(coalesce(s.external_environment, '')) <> 'SANDBOX'
      )
  ),
  candidates as (
    select
      b.subscription_id,
      b.user_id,
      b.type,
      b.ends_at,
      b.inapp_enabled,
      b.push_enabled,
      case
        when (b.ends_at - timezone('utc'::text, now())) <= p_final_remind_before then 'renewal_24h'
        else 'renewal_7d'
      end as kind,
      case
        when (b.ends_at - timezone('utc'::text, now())) <= p_final_remind_before
          then b.type::text || ' renews within 24 hours'
        else b.type::text || ' renews soon'
      end as title,
      case
        when (b.ends_at - timezone('utc'::text, now())) <= p_final_remind_before
          then 'Your ' || lower(b.type::text) || ' plan renews within 24 hours. Review or change it now to keep your premium signals uninterrupted.'
        else 'Your ' || lower(b.type::text) || ' plan renews in the next 7 days. Review it now so your premium visibility stays uninterrupted.'
      end as body
    from base b
    where (b.ends_at - timezone('utc'::text, now())) <= p_first_remind_before
      and not exists (
        select 1
        from public.subscription_renewal_nudges n
        where n.subscription_id = b.subscription_id
          and n.user_id = b.user_id
          and n.kind = case
            when (b.ends_at - timezone('utc'::text, now())) <= p_final_remind_before then 'renewal_24h'
            else 'renewal_7d'
          end
          and n.ends_at = b.ends_at
      )
  )
  select
    c.subscription_id,
    c.user_id,
    c.type,
    c.ends_at,
    c.inapp_enabled,
    c.push_enabled,
    c.kind,
    c.title,
    c.body
  from candidates c;

  insert into public.subscription_renewal_nudges (
    user_id,
    subscription_id,
    kind,
    ends_at,
    metadata
  )
  select
    c.user_id,
    c.subscription_id,
    c.kind,
    c.ends_at,
    jsonb_build_object(
      'subscription_type', c.type,
      'ends_at', c.ends_at,
      'run_key', v_run_key
    )
  from pg_temp.subscription_renewal_candidates c
  on conflict (user_id, subscription_id, kind, ends_at) do nothing;

  insert into pg_temp.subscription_renewal_delivery (
    subscription_id,
    user_id,
    type,
    ends_at,
    inapp_enabled,
    push_enabled,
    kind,
    title,
    body
  )
  select
    c.subscription_id,
    c.user_id,
    c.type,
    c.ends_at,
    c.inapp_enabled,
    c.push_enabled,
    c.kind,
    c.title,
    c.body
  from pg_temp.subscription_renewal_candidates c
  join public.subscription_renewal_nudges n
    on n.subscription_id = c.subscription_id
   and n.user_id = c.user_id
   and n.kind = c.kind
   and n.ends_at = c.ends_at
   and n.metadata->>'run_key' = v_run_key::text;

  if v_has_inbox_items then
    execute $sql$
      insert into public.inbox_items (
        user_id,
        type,
        actor_id,
        entity_id,
        entity_type,
        title,
        body,
        action_required,
        metadata
      )
      select
        d.user_id,
        'SYSTEM',
        null,
        d.subscription_id,
        'subscription_renewal',
        d.title,
        d.body,
        true,
        jsonb_build_object(
          'type', 'subscription_renewal',
          'kind', d.kind,
          'plan', d.type,
          'ends_at', d.ends_at,
          'route', '/premium-plans'
        )
      from pg_temp.subscription_renewal_delivery d
      where d.inapp_enabled = true
    $sql$;

    get diagnostics v_inbox_created = row_count;
  end if;

  perform private.send_push_webhook(
    jsonb_build_object(
      'user_id', d.user_id,
      'title', d.title,
      'body', d.body,
      'data', jsonb_build_object(
        'type', 'subscription_renewal',
        'kind', d.kind,
        'plan', d.type,
        'ends_at', d.ends_at,
        'route', '/premium-plans'
      )
    )
  )
  from pg_temp.subscription_renewal_delivery d
  where d.push_enabled = true
    and public.is_quiet_hours(d.user_id) = false;

  get diagnostics v_push_scheduled = row_count;

  return jsonb_build_object(
    'inbox_created', v_inbox_created,
    'push_scheduled', v_push_scheduled
  );
end;
$_$;


ALTER FUNCTION "public"."rpc_process_subscription_renewal_jobs"("p_first_remind_before" interval, "p_final_remind_before" interval, "p_include_sandbox" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_process_vibes_v4_jobs"("p_visibility_limit" integer DEFAULT 500, "p_quality_limit" integer DEFAULT 250, "p_viewer_limit" integer DEFAULT 150, "p_visibility_stale_after" interval DEFAULT '00:30:00'::interval, "p_quality_stale_after" interval DEFAULT '06:00:00'::interval, "p_viewer_stale_after" interval DEFAULT '06:00:00'::interval) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_visibility_profile_ids uuid[] := '{}'::uuid[];
  v_quality_queued_profile_ids uuid[] := '{}'::uuid[];
  v_quality_stale_profile_ids uuid[] := '{}'::uuid[];
  v_quality_profile_ids uuid[] := '{}'::uuid[];
  v_viewer_profile_ids uuid[] := '{}'::uuid[];
  v_viewer_profile_id uuid;
  v_visibility_refreshed integer := 0;
  v_quality_refreshed integer := 0;
  v_viewer_refreshed integer := 0;
begin
  select coalesce(array_agg(stale.profile_id), '{}'::uuid[])
    into v_visibility_profile_ids
  from (
    select profile.id as profile_id
    from public.profiles profile
    left join public.profile_visibility_entitlements ent
      on ent.profile_id = profile.id
    where profile.deleted_at is null
      and (
        ent.profile_id is null
        or ent.refreshed_at < timezone('utc'::text, now()) - p_visibility_stale_after
      )
    order by ent.refreshed_at asc nulls first, profile.created_at asc
    limit greatest(1, least(coalesce(p_visibility_limit, 500), 5000))
  ) stale;

  if coalesce(array_length(v_visibility_profile_ids, 1), 0) > 0 then
    v_visibility_refreshed := public.refresh_profile_visibility_entitlements(v_visibility_profile_ids);
  end if;

  with queued as (
    select queue_row.profile_id
    from public.vibes_v4_metric_refresh_queue queue_row
    join public.profiles profile
      on profile.id = queue_row.profile_id
     and profile.deleted_at is null
    where queue_row.quality_dirty = true
      and (
        queue_row.locked_at is null
        or queue_row.locked_at < timezone('utc'::text, now()) - interval '30 minutes'
      )
    order by queue_row.requested_at asc
    for update of queue_row skip locked
    limit greatest(1, least(coalesce(p_quality_limit, 250), 5000))
  ),
  locked as (
    update public.vibes_v4_metric_refresh_queue queue_row
    set locked_at = timezone('utc'::text, now()),
        attempts = queue_row.attempts + 1,
        last_error = null
    from queued
    where queue_row.profile_id = queued.profile_id
    returning queue_row.profile_id
  )
  select coalesce(array_agg(locked.profile_id), '{}'::uuid[])
    into v_quality_queued_profile_ids
  from locked;

  if coalesce(array_length(v_quality_queued_profile_ids, 1), 0) < greatest(1, least(coalesce(p_quality_limit, 250), 5000)) then
    select coalesce(array_agg(stale.profile_id), '{}'::uuid[])
      into v_quality_stale_profile_ids
    from (
      select profile.id as profile_id
      from public.profiles profile
      left join public.profile_recommendation_quality_metrics metrics
        on metrics.profile_id = profile.id
      where profile.deleted_at is null
        and (
          metrics.profile_id is null
          or metrics.refreshed_at < timezone('utc'::text, now()) - p_quality_stale_after
        )
        and not (profile.id = any(v_quality_queued_profile_ids))
      order by metrics.refreshed_at asc nulls first, profile.created_at asc
      limit greatest(
        1,
        least(coalesce(p_quality_limit, 250), 5000) - coalesce(array_length(v_quality_queued_profile_ids, 1), 0)
      )
    ) stale;
  end if;

  select coalesce(array_agg(distinct selected.profile_id), '{}'::uuid[])
    into v_quality_profile_ids
  from (
    select unnest(v_quality_queued_profile_ids) as profile_id
    union
    select unnest(v_quality_stale_profile_ids) as profile_id
  ) selected;

  if coalesce(array_length(v_quality_profile_ids, 1), 0) > 0 then
    v_quality_refreshed := public.refresh_profile_recommendation_quality_metrics(v_quality_profile_ids);
  end if;

  if coalesce(array_length(v_quality_queued_profile_ids, 1), 0) > 0 then
    update public.vibes_v4_metric_refresh_queue queue_row
    set quality_dirty = false,
        processed_at = timezone('utc'::text, now()),
        locked_at = null,
        last_error = null
    where queue_row.profile_id = any(v_quality_queued_profile_ids);

    delete from public.vibes_v4_metric_refresh_queue queue_row
    where queue_row.profile_id = any(v_quality_queued_profile_ids)
      and queue_row.visibility_dirty = false
      and queue_row.quality_dirty = false
      and queue_row.viewer_behavior_dirty = false;
  end if;

  select coalesce(array_agg(stale.viewer_profile_id), '{}'::uuid[])
    into v_viewer_profile_ids
  from (
    with active_viewers as (
      select distinct event_row.viewer_profile_id
      from public.vibes_events event_row
      join public.profiles viewer
        on viewer.id = event_row.viewer_profile_id
       and viewer.deleted_at is null
      where event_row.viewer_profile_id is not null
        and event_row.created_at >= now() - interval '60 days'
    ),
    freshness as (
      select
        summary_row.viewer_profile_id,
        max(summary_row.refreshed_at) as refreshed_at
      from public.viewer_profile_behavior_summary summary_row
      group by summary_row.viewer_profile_id
    )
    select active_viewers.viewer_profile_id
    from active_viewers
    left join freshness
      on freshness.viewer_profile_id = active_viewers.viewer_profile_id
    where freshness.viewer_profile_id is null
       or freshness.refreshed_at < timezone('utc'::text, now()) - p_viewer_stale_after
    order by freshness.refreshed_at asc nulls first, active_viewers.viewer_profile_id
    limit greatest(1, least(coalesce(p_viewer_limit, 150), 2000))
  ) stale;

  foreach v_viewer_profile_id in array v_viewer_profile_ids loop
    v_viewer_refreshed := v_viewer_refreshed + public.refresh_viewer_profile_behavior_summary(v_viewer_profile_id, null);
  end loop;

  return jsonb_build_object(
    'visibility_profiles_selected', coalesce(array_length(v_visibility_profile_ids, 1), 0),
    'visibility_rows_refreshed', v_visibility_refreshed,
    'quality_queue_profiles_selected', coalesce(array_length(v_quality_queued_profile_ids, 1), 0),
    'quality_profiles_selected', coalesce(array_length(v_quality_profile_ids, 1), 0),
    'quality_rows_refreshed', v_quality_refreshed,
    'viewer_profiles_selected', coalesce(array_length(v_viewer_profile_ids, 1), 0),
    'viewer_rows_refreshed', v_viewer_refreshed
  );
end;
$$;


ALTER FUNCTION "public"."rpc_process_vibes_v4_jobs"("p_visibility_limit" integer, "p_quality_limit" integer, "p_viewer_limit" integer, "p_visibility_stale_after" interval, "p_quality_stale_after" interval, "p_viewer_stale_after" interval) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_publish_relationship_gist"("p_gist_id" "uuid") RETURNS "public"."relationship_gists"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_gist public.relationship_gists;
begin
  if not public.is_admin_user(auth.uid()) then
    raise exception 'admin access required' using errcode = '42501';
  end if;

  update public.relationship_gists
  set status = 'published',
      published_at = coalesce(published_at, timezone('utc'::text, now())),
      created_by_admin_id = coalesce(created_by_admin_id, auth.uid()),
      updated_at = timezone('utc'::text, now())
  where id = p_gist_id
  returning * into v_gist;

  return v_gist;
end;
$$;


ALTER FUNCTION "public"."rpc_publish_relationship_gist"("p_gist_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_refund_undone_superlike"("p_profile_id" "uuid", "p_target_profile_id" "uuid", "p_window_seconds" integer DEFAULT 300) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid;
  v_profile_id uuid;
  v_deleted_swipe_id uuid;
  v_new_count integer;
begin
  v_user_id := auth.uid();
  if v_user_id is null then
    raise exception 'Not authenticated';
  end if;

  select p.id
    into v_profile_id
  from public.profiles p
  where p.id = p_profile_id
    and p.user_id = v_user_id
  limit 1;

  if v_profile_id is null then
    raise exception 'Profile not found';
  end if;

  delete from public.swipes s
  where s.swiper_id = v_profile_id
    and s.target_id = p_target_profile_id
    and s.action = 'SUPERLIKE'
    and s.created_at >= now() - make_interval(secs => greatest(30, least(coalesce(p_window_seconds, 300), 900)))
  returning s.id into v_deleted_swipe_id;

  if v_deleted_swipe_id is null then
    raise exception 'SUPERLIKE_NOT_REFUNDABLE';
  end if;

  update public.profiles
  set superlikes_left = superlikes_left + 1,
      updated_at = now()
  where id = v_profile_id
  returning superlikes_left into v_new_count;

  return v_new_count;
end;
$$;


ALTER FUNCTION "public"."rpc_refund_undone_superlike"("p_profile_id" "uuid", "p_target_profile_id" "uuid", "p_window_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_reject_circle"("p_circle_id" "uuid", "p_reason" "text") RETURNS "public"."circles"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_circle public.circles;
begin
  if not public.is_admin_user(auth.uid()) then
    raise exception 'admin access required' using errcode = '42501';
  end if;

  update public.circles
  set status = 'rejected',
      rejected_reason = nullif(btrim(coalesce(p_reason, '')), ''),
      approved_by_admin_id = null,
      approved_at = null,
      updated_at = timezone('utc'::text, now())
  where id = p_circle_id
    and status in ('draft', 'pending_review', 'approved', 'rejected')
  returning * into v_circle;

  return v_circle;
end;
$$;


ALTER FUNCTION "public"."rpc_reject_circle"("p_circle_id" "uuid", "p_reason" "text") OWNER TO "postgres";


