    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_gathering public.gatherings;
begin
  if not public.is_admin_user(auth.uid()) then
    raise exception 'admin access required' using errcode = '42501';
  end if;

  update public.gatherings
  set status = 'rejected',
      rejected_reason = nullif(btrim(coalesce(p_reason, '')), ''),
      approved_by_admin_id = null,
      approved_at = null,
      updated_at = timezone('utc'::text, now())
  where id = p_gathering_id
    and status in ('draft', 'pending_review', 'approved', 'rejected')
  returning * into v_gathering;

  return v_gathering;
end;
$$;


ALTER FUNCTION "public"."rpc_reject_gathering"("p_gathering_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_remove_circle_member"("p_circle_id" "uuid", "p_member_id" "uuid", "p_profile_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_owner uuid;
  v_actor_role text;
  v_target_role text;
  v_target_status text;
  v_is_admin boolean := public.is_admin_user(auth.uid());
  v_is_circle_owner boolean := false;
  v_updated boolean := false;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  select user_id into v_owner
  from public.profiles
  where id = p_profile_id
  limit 1;

  if v_owner is null or v_owner <> auth.uid() then
    raise exception 'Not authorized';
  end if;

  if p_member_id = p_profile_id then
    raise exception 'Use leave circle for your own membership';
  end if;

  v_is_circle_owner := public.is_circle_owner(p_circle_id, auth.uid());

  select lower(role), status
    into v_target_role, v_target_status
  from public.circle_members
  where circle_id = p_circle_id
    and profile_id = p_member_id
  for update;

  if v_target_status is null then
    raise exception 'Member not found';
  end if;

  if not v_is_admin and not v_is_circle_owner then
    select lower(role) into v_actor_role
    from public.circle_members
    where circle_id = p_circle_id
      and profile_id = p_profile_id
      and status = 'active'
    limit 1;

    if coalesce(v_actor_role, '') not in ('leader', 'host', 'admin', 'moderator') then
      raise exception 'Only hosts or moderators can remove members';
    end if;

    if coalesce(v_target_role, '') in ('leader', 'host', 'admin', 'moderator') then
      raise exception 'Only owners can remove leadership members';
    end if;
  end if;

  update public.circle_members
  set status = case
        when v_target_status = 'pending' then 'removed'
        else 'removed'
      end,
      left_at = timezone('utc'::text, now()),
      updated_at = timezone('utc'::text, now())
  where circle_id = p_circle_id
    and profile_id = p_member_id;
  v_updated := found;

  update public.circles c
  set member_count = (
    select count(*)::int
    from public.circle_members cm
    where cm.circle_id = c.id
      and cm.status = 'active'
  )
  where c.id = p_circle_id;

  return v_updated;
end;
$$;


ALTER FUNCTION "public"."rpc_remove_circle_member"("p_circle_id" "uuid", "p_member_id" "uuid", "p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_remove_circle_prompt_response"("p_response_id" "uuid", "p_profile_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_owner uuid;
  v_actor_role text;
  v_response public.circle_prompt_responses%rowtype;
  v_is_admin boolean := public.is_admin_user(auth.uid());
  v_is_circle_owner boolean := false;
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  select p.user_id into v_owner
  from public.profiles p
  where p.id = p_profile_id
  limit 1;

  if v_owner is null or v_owner <> auth.uid() then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  select *
    into v_response
  from public.circle_prompt_responses cpr
  where cpr.id = p_response_id
  for update;

  if v_response.id is null or v_response.circle_id is null then
    raise exception 'response_not_found';
  end if;

  v_is_circle_owner := public.is_circle_owner(v_response.circle_id, auth.uid());

  if not v_is_admin and not v_is_circle_owner then
    select lower(cm.role) into v_actor_role
    from public.circle_members cm
    where cm.circle_id = v_response.circle_id
      and cm.profile_id = p_profile_id
      and cm.status = 'active'
    limit 1;

    if coalesce(v_actor_role, '') not in ('leader', 'host', 'admin', 'moderator') then
      raise exception 'host_required' using errcode = '42501';
    end if;
  end if;

  delete from public.circle_prompt_responses cpr
  where cpr.id = p_response_id;

  return found;
end;
$$;


ALTER FUNCTION "public"."rpc_remove_circle_prompt_response"("p_response_id" "uuid", "p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_reorder_circle_pulse_items"("p_circle_id" "uuid", "p_actor_profile_id" "uuid", "p_item_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_updated integer := 0;
  v_expected integer := coalesce(cardinality(p_item_ids), 0);
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_actor_profile_id
      and p.user_id = auth.uid()
      and p.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  if not public.can_manage_circle_pulse(p_circle_id, auth.uid()) then
    raise exception 'host_required' using errcode = '42501';
  end if;

  if v_expected = 0
    or (select count(distinct rows.item_id) from unnest(p_item_ids) as rows(item_id)) <> v_expected
    or (
      select count(*)
      from public.circle_pulse_items cpi
      where cpi.circle_id = p_circle_id
        and cpi.id = any(p_item_ids)
        and cpi.status <> 'archived'
    ) <> v_expected then
    raise exception 'invalid_pulse_order';
  end if;

  with ordered as (
    select item_id, ordinality
    from unnest(p_item_ids) with ordinality as rows(item_id, ordinality)
  )
  update public.circle_pulse_items cpi
  set priority = v_expected - ordered.ordinality + 1
  from ordered
  where cpi.circle_id = p_circle_id
    and cpi.id = ordered.item_id;

  get diagnostics v_updated = row_count;
  return v_updated;
end;
$$;


ALTER FUNCTION "public"."rpc_reorder_circle_pulse_items"("p_circle_id" "uuid", "p_actor_profile_id" "uuid", "p_item_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_report_circle_pulse_comment"("p_comment_id" "uuid", "p_profile_id" "uuid", "p_reason" "text" DEFAULT 'concern'::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_comment public.circle_pulse_comments%rowtype;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_inserted_count integer := 0;
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_profile_id
      and p.user_id = auth.uid()
      and p.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  if v_reason is null or char_length(v_reason) > 120 then
    raise exception 'invalid_reason';
  end if;

  select *
    into v_comment
  from public.circle_pulse_comments cpc
  where cpc.id = p_comment_id
    and cpc.status = 'active'
  for update;

  if v_comment.id is null then
    raise exception 'comment_not_found';
  end if;

  if v_comment.user_id = auth.uid() then
    raise exception 'cannot_report_own_comment';
  end if;

  if not public.is_circle_member(v_comment.circle_id, auth.uid())
    and not public.is_circle_owner(v_comment.circle_id, auth.uid()) then
    raise exception 'circle_membership_required' using errcode = '42501';
  end if;

  insert into public.circle_pulse_comment_reports (
    circle_id,
    pulse_item_id,
    comment_id,
    reporter_profile_id,
    reporter_user_id,
    reason
  )
  values (
    v_comment.circle_id,
    v_comment.pulse_item_id,
    v_comment.id,
    p_profile_id,
    auth.uid(),
    v_reason
  )
  on conflict (comment_id, reporter_profile_id) do nothing;

  get diagnostics v_inserted_count = row_count;

  if v_inserted_count > 0 then
    update public.circle_pulse_comments
    set report_count = report_count + 1
    where id = p_comment_id;
  end if;

  return true;
end;
$$;


ALTER FUNCTION "public"."rpc_report_circle_pulse_comment"("p_comment_id" "uuid", "p_profile_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_request_account_recovery"("p_current_sign_in_method" "text" DEFAULT NULL::"text", "p_previous_sign_in_method" "text" DEFAULT NULL::"text", "p_contact_email" "text" DEFAULT NULL::"text", "p_previous_account_email" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT NULL::"text", "p_evidence" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_profile_id uuid;
  v_current_method text := lower(trim(coalesce(p_current_sign_in_method, '')));
  v_previous_method text := lower(trim(coalesce(p_previous_sign_in_method, '')));
  v_request_id uuid;
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  if v_current_method <> '' and v_current_method not in ('email', 'google', 'apple', 'magic_link', 'other') then
    raise exception 'invalid current sign-in method';
  end if;

  if v_previous_method <> '' and v_previous_method not in ('email', 'google', 'apple', 'magic_link', 'other') then
    raise exception 'invalid previous sign-in method';
  end if;

  select p.id
    into v_profile_id
  from public.profiles p
  where p.user_id = auth.uid()
  limit 1;

  insert into public.account_recovery_requests (
    requester_user_id,
    requester_profile_id,
    current_sign_in_method,
    previous_sign_in_method,
    contact_email,
    previous_account_email,
    note,
    evidence
  )
  values (
    auth.uid(),
    v_profile_id,
    nullif(v_current_method, ''),
    nullif(v_previous_method, ''),
    nullif(trim(coalesce(p_contact_email, '')), ''),
    nullif(trim(coalesce(p_previous_account_email, '')), ''),
    nullif(trim(coalesce(p_note, '')), ''),
    coalesce(p_evidence, '{}'::jsonb)
  )
  returning id into v_request_id;

  insert into public.account_recovery_request_events (
    request_id,
    event_type,
    actor_user_id,
    metadata
  )
  values (
    v_request_id,
    'request_created',
    auth.uid(),
    jsonb_build_object(
      'current_sign_in_method', nullif(v_current_method, ''),
      'previous_sign_in_method', nullif(v_previous_method, ''),
      'contact_email', nullif(trim(coalesce(p_contact_email, '')), ''),
      'previous_account_email', nullif(trim(coalesce(p_previous_account_email, '')), ''),
      'note_present', nullif(trim(coalesce(p_note, '')), '') is not null
    )
  );

  return v_request_id;
end;
$$;


ALTER FUNCTION "public"."rpc_request_account_recovery"("p_current_sign_in_method" "text", "p_previous_sign_in_method" "text", "p_contact_email" "text", "p_previous_account_email" "text", "p_note" "text", "p_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_request_circle_role"("p_circle_id" "uuid", "p_profile_id" "uuid", "p_requested_role" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "public"."circle_role_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_owner uuid;
  v_current_role text;
  v_status text;
  v_request public.circle_role_requests%rowtype;
  v_requested_role text := lower(coalesce(p_requested_role, ''));
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if v_requested_role not in ('moderator', 'host') then
    raise exception 'invalid_role';
  end if;

  select user_id into v_owner
  from public.profiles
  where id = p_profile_id
  limit 1;

  if v_owner is null or v_owner <> auth.uid() then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  select lower(role), status
    into v_current_role, v_status
  from public.circle_members
  where circle_id = p_circle_id
    and profile_id = p_profile_id
  limit 1;

  if coalesce(v_status, '') <> 'active' then
    raise exception 'member_not_active';
  end if;

  if v_requested_role = 'moderator' and coalesce(v_current_role, '') in ('moderator', 'host', 'admin', 'leader') then
    raise exception 'already_has_role';
  end if;

  if v_requested_role = 'host' and coalesce(v_current_role, '') in ('host', 'admin', 'leader') then
    raise exception 'already_has_role';
  end if;

  if exists (
    select 1
    from public.circle_role_requests
    where circle_id = p_circle_id
      and requester_profile_id = p_profile_id
      and requested_role = v_requested_role
      and status = 'pending'
  ) then
    raise exception 'request_already_pending';
  end if;

  insert into public.circle_role_requests (
    circle_id,
    requester_profile_id,
    requester_user_id,
    requested_role,
    note
  )
  values (
    p_circle_id,
    p_profile_id,
    auth.uid(),
    v_requested_role,
    nullif(btrim(coalesce(p_note, '')), '')
  )
  returning * into v_request;

  return v_request;
end;
$$;


ALTER FUNCTION "public"."rpc_request_circle_role"("p_circle_id" "uuid", "p_profile_id" "uuid", "p_requested_role" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_request_date_plan_concierge"("p_plan_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("request_id" "uuid", "plan_id" "uuid", "concierge_requested" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_plan public.date_plans%rowtype;
  v_actor_profile public.profiles%rowtype;
  v_request_id uuid;
  v_creator_name text;
  v_recipient_name text;
  v_first_request boolean := false;
begin
  select *
  into v_actor_profile
  from public.profiles
  where user_id = auth.uid()
  limit 1;

  if v_actor_profile.id is null then
    raise exception 'actor_profile_not_found';
  end if;

  if public.get_active_subscription_plan(auth.uid()) <> 'GOLD' then
    raise exception 'Gold is required to ask Betweener to help with a date plan.';
  end if;

  select *
  into v_plan
  from public.date_plans
  where id = p_plan_id
  limit 1;

  if v_plan.id is null then
    raise exception 'date_plan_not_found';
  end if;

  if auth.uid() not in (v_plan.creator_user_id, v_plan.recipient_user_id) then
    raise exception 'Only participants can ask Betweener to help.';
  end if;

  if v_plan.status <> 'accepted' then
    raise exception 'Accept the date suggestion before asking Betweener to help.';
  end if;

  if not v_plan.concierge_requested then
    update public.date_plans
    set concierge_requested = true,
        concierge_requested_at = now(),
        concierge_requested_by_profile_id = v_actor_profile.id,
        updated_at = now()
    where id = p_plan_id;
    v_first_request := true;
  end if;

  insert into public.date_plan_concierge_requests (
    date_plan_id,
    requested_by_profile_id,
    requested_by_user_id,
    note
  )
  values (
    p_plan_id,
    v_actor_profile.id,
    auth.uid(),
    nullif(btrim(coalesce(p_note, '')), '')
  )
  on conflict (date_plan_id)
  do update set
    note = coalesce(excluded.note, public.date_plan_concierge_requests.note),
    updated_at = now()
  returning id into v_request_id;

  if v_first_request then
    select full_name into v_creator_name from public.profiles where id = v_plan.creator_profile_id;
    select full_name into v_recipient_name from public.profiles where id = v_plan.recipient_profile_id;

    insert into public.system_messages (
      user_id,
      peer_user_id,
      event_type,
      text,
      metadata
    )
    values (
      v_plan.creator_user_id,
      v_plan.recipient_user_id,
      'date_plan_concierge_requested',
      'Betweener is helping with your date plan with ' || coalesce(v_recipient_name, 'them') || '.',
      jsonb_build_object('date_plan_id', p_plan_id, 'role', case when auth.uid() = v_plan.creator_user_id then 'requester' else 'participant' end)
    );

    insert into public.system_messages (
      user_id,
      peer_user_id,
      event_type,
      text,
      metadata
    )
    values (
      v_plan.recipient_user_id,
      v_plan.creator_user_id,
      'date_plan_concierge_requested',
      'Betweener is helping with your date plan with ' || coalesce(v_creator_name, 'them') || '.',
      jsonb_build_object('date_plan_id', p_plan_id, 'role', case when auth.uid() = v_plan.recipient_user_id then 'requester' else 'participant' end)
    );
  end if;

  return query
  select v_request_id, p_plan_id, true;
end;
$$;


ALTER FUNCTION "public"."rpc_request_date_plan_concierge"("p_plan_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_resolve_recovered_duplicate_shell"("p_recovery_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_session public.account_recovery_sessions%rowtype;
  v_shell_profile public.profiles%rowtype;
  v_effective_owner_user_id uuid := auth.uid();
  v_now timestamptz := timezone('utc'::text, now());
  v_target_profile_id uuid;
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  if p_recovery_token is null then
    raise exception 'recovery token is required';
  end if;

  select *
    into v_session
  from public.account_recovery_sessions
  where recovery_token = p_recovery_token
  order by created_at desc
  limit 1;

  if v_session.id is null then
    return jsonb_build_object(
      'resolved', false,
      'manual_review_required', true,
      'reason', 'recovery_session_not_found'
    );
  end if;

  select ma.target_user_id
    into v_effective_owner_user_id
  from public.merged_accounts ma
  where ma.source_user_id = v_session.owner_user_id
    and ma.status = 'active'
  limit 1;

  v_effective_owner_user_id := coalesce(v_effective_owner_user_id, v_session.owner_user_id);

  if auth.uid() <> v_effective_owner_user_id then
    return jsonb_build_object(
      'resolved', false,
      'manual_review_required', true,
      'reason', 'wrong_restored_account'
    );
  end if;

  select *
    into v_shell_profile
  from public.profiles
  where user_id = v_session.requester_user_id
  for update;

  if v_shell_profile.id is null then
    return jsonb_build_object(
      'resolved', false,
      'manual_review_required', true,
      'reason', 'shell_profile_missing'
    );
  end if;

  if v_shell_profile.user_id = v_effective_owner_user_id then
    return jsonb_build_object(
      'resolved', false,
      'manual_review_required', true,
      'reason', 'shell_matches_restored_account'
    );
  end if;

  if v_shell_profile.identity_status in ('recovered_into_existing_account', 'discarded_duplicate')
     and v_shell_profile.recovered_to_user_id = v_effective_owner_user_id then
    return jsonb_build_object(
      'resolved', true,
      'manual_review_required', false,
      'status', v_shell_profile.identity_status,
      'already_resolved', true,
      'shell_user_id', v_shell_profile.user_id,
      'restored_user_id', v_effective_owner_user_id
    );
  end if;

  if coalesce(v_shell_profile.profile_completed, false) then
    insert into public.account_identity_events (
      user_id,
      profile_id,
      actor_user_id,
      event_type,
      metadata
    )
    values (
      v_shell_profile.user_id,
      v_shell_profile.id,
      auth.uid(),
      'duplicate_shell_manual_review_required',
      jsonb_build_object(
        'reason', 'profile_completed_shell',
        'recovery_token', p_recovery_token,
        'restored_user_id', v_effective_owner_user_id
      )
    );

    return jsonb_build_object(
      'resolved', false,
      'manual_review_required', true,
      'reason', 'profile_completed_shell'
    );
  end if;

  select p.id
    into v_target_profile_id
  from public.profiles p
  where p.user_id = v_effective_owner_user_id
  limit 1;

  update public.profiles
     set identity_status = 'recovered_into_existing_account',
         duplicate_of_user_id = v_effective_owner_user_id,
         recovered_to_user_id = v_effective_owner_user_id,
         identity_disabled_at = coalesce(identity_disabled_at, v_now),
         identity_resolution_reason = 'verified_phone_recovery',
         discoverable_in_vibes = false,
         is_active = false,
         online = false,
         updated_at = v_now
   where id = v_shell_profile.id;

  update public.account_recovery_sessions
     set consumed_at = coalesce(consumed_at, v_now)
   where id = v_session.id;

  insert into public.account_identity_events (
    user_id,
    profile_id,
    actor_user_id,
    event_type,
    metadata
  )
  values (
    v_shell_profile.user_id,
    v_shell_profile.id,
    auth.uid(),
    'duplicate_shell_retired_after_recovery',
    jsonb_build_object(
      'recovery_token', p_recovery_token,
      'shell_user_id', v_shell_profile.user_id,
      'restored_user_id', v_effective_owner_user_id,
      'restored_profile_id', v_target_profile_id
    )
  );

  return jsonb_build_object(
    'resolved', true,
    'manual_review_required', false,
    'status', 'recovered_into_existing_account',
    'shell_user_id', v_shell_profile.user_id,
    'restored_user_id', v_effective_owner_user_id,
    'restored_profile_id', v_target_profile_id
  );
end;
$$;


ALTER FUNCTION "public"."rpc_resolve_recovered_duplicate_shell"("p_recovery_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_respond_circle_invitation"("p_circle_id" "uuid", "p_profile_id" "uuid", "p_accept" boolean) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_invitation public.circle_invitations%rowtype;
  v_status text := case when coalesce(p_accept, false) then 'accepted' else 'declined' end;
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles recipient
    where recipient.id = p_profile_id
      and recipient.user_id = auth.uid()
      and recipient.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  select *
    into v_invitation
  from public.circle_invitations ci
  where ci.circle_id = p_circle_id
    and ci.invited_profile_id = p_profile_id
    and ci.status = 'pending'
  order by ci.created_at desc
  limit 1
  for update;

  if v_invitation.id is null then
    raise exception 'circle_invitation_not_found';
  end if;

  if v_invitation.expires_at <= timezone('utc'::text, now()) then
    update public.circle_invitations
    set status = 'expired',
        responded_at = timezone('utc'::text, now())
    where id = v_invitation.id;

    update public.circle_members
    set status = 'removed',
        left_at = timezone('utc'::text, now())
    where circle_id = p_circle_id
      and profile_id = p_profile_id
      and status = 'invited';

    return 'expired';
  end if;

  update public.circle_invitations
  set status = v_status,
      responded_at = timezone('utc'::text, now())
  where id = v_invitation.id;

  if v_status = 'accepted' then
    update public.circle_members
    set status = 'active',
        joined_at = timezone('utc'::text, now()),
        left_at = null
    where circle_id = p_circle_id
      and profile_id = p_profile_id
      and status = 'invited';
  else
    update public.circle_members
    set status = 'removed',
        left_at = timezone('utc'::text, now())
    where circle_id = p_circle_id
      and profile_id = p_profile_id
      and status = 'invited';
  end if;

  update public.circles c
  set member_count = (
    select count(*)::integer
    from public.circle_members cm
    where cm.circle_id = c.id
      and cm.status = 'active'
  )
  where c.id = p_circle_id;

  return v_status;
end;
$$;


ALTER FUNCTION "public"."rpc_respond_circle_invitation"("p_circle_id" "uuid", "p_profile_id" "uuid", "p_accept" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_respond_circle_love_seat"("p_love_seat_id" "uuid", "p_profile_id" "uuid", "p_accept" boolean) RETURNS "public"."circle_love_seats"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_love_seat public.circle_love_seats%rowtype;
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_profile_id
      and p.user_id = auth.uid()
      and p.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  select *
    into v_love_seat
  from public.circle_love_seats cls
  where cls.id = p_love_seat_id
  for update;

  if v_love_seat.id is null then
    raise exception 'love_seat_not_found';
  end if;

  if v_love_seat.featured_profile_id <> p_profile_id then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  if v_love_seat.status <> 'pending_user_approval' then
    raise exception 'love_seat_already_answered';
  end if;

  if coalesce(p_accept, false) and exists (
    select 1
    from public.circle_love_seats cls
    where cls.circle_id = v_love_seat.circle_id
      and cls.status = 'active'
      and cls.id <> v_love_seat.id
  ) then
    raise exception 'circle_love_seat_active';
  end if;

  update public.circle_love_seats
  set status = case when coalesce(p_accept, false) then 'active' else 'declined' end,
      approved_by_profile_id = case when coalesce(p_accept, false) then p_profile_id else null end,
      starts_at = case when coalesce(p_accept, false) then timezone('utc'::text, now()) else starts_at end,
      responded_at = timezone('utc'::text, now())
  where id = p_love_seat_id
  returning * into v_love_seat;

  if coalesce(p_accept, false) then
    insert into public.circle_pulse_items (
      circle_id,
      item_type,
      love_seat_id,
      title,
      body,
      status,
      priority,
      starts_at,
      created_by_profile_id,
      created_by_user_id
    )
    values (
      v_love_seat.circle_id,
      'love_seat',
      v_love_seat.id,
      'Love Seat',
      v_love_seat.quote,
      'active',
      100,
      v_love_seat.starts_at,
      v_love_seat.nominated_by_profile_id,
      auth.uid()
    );
  end if;

  return v_love_seat;
end;
$$;


ALTER FUNCTION "public"."rpc_respond_circle_love_seat"("p_love_seat_id" "uuid", "p_profile_id" "uuid", "p_accept" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_respond_warm_introduction"("p_intro_id" "uuid", "p_decision" "text") RETURNS "public"."warm_introductions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_profile_id uuid;
  v_intro public.warm_introductions;
begin
  if v_user_id is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if p_decision not in ('accept', 'decline') then
    raise exception 'invalid_decision';
  end if;

  select p.id
    into v_profile_id
  from public.profiles p
  where p.user_id = v_user_id
    and p.deleted_at is null
  limit 1;

  select *
    into v_intro
  from public.warm_introductions wi
  where wi.id = p_intro_id
    and wi.status in ('pending', 'accepted_by_a', 'accepted_by_b')
    and wi.expires_at > timezone('utc'::text, now())
    and v_profile_id in (wi.profile_a_id, wi.profile_b_id)
  for update;

  if v_intro.id is null then
    raise exception 'introduction_unavailable';
  end if;

  if p_decision = 'decline' then
    update public.warm_introductions
    set status = 'declined',
        declined_by_profile_id = v_profile_id,
        updated_at = timezone('utc'::text, now())
    where id = p_intro_id
    returning * into v_intro;
    return v_intro;
  end if;

  update public.warm_introductions
  set accepted_by_a_at = case
        when profile_a_id = v_profile_id then coalesce(accepted_by_a_at, timezone('utc'::text, now()))
        else accepted_by_a_at
      end,
      accepted_by_b_at = case
        when profile_b_id = v_profile_id then coalesce(accepted_by_b_at, timezone('utc'::text, now()))
        else accepted_by_b_at
      end,
      status = case
        when (profile_a_id = v_profile_id or accepted_by_a_at is not null)
         and (profile_b_id = v_profile_id or accepted_by_b_at is not null)
          then 'accepted'
        when profile_a_id = v_profile_id then 'accepted_by_a'
        else 'accepted_by_b'
      end,
      updated_at = timezone('utc'::text, now())
  where id = p_intro_id
  returning * into v_intro;

  return v_intro;
end;
$$;


ALTER FUNCTION "public"."rpc_respond_warm_introduction"("p_intro_id" "uuid", "p_decision" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_reveal_profile_gift"("p_gift_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_row public.profile_gifts%rowtype;
  v_was_revealed_at timestamptz;
begin
  if auth.uid() is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  select g.revealed_at
    into v_was_revealed_at
  from public.profile_gifts g
  where g.id = p_gift_id
    and exists (
      select 1
      from public.profiles recipient
      where recipient.id = g.profile_id
        and recipient.user_id = auth.uid()
        and recipient.deleted_at is null
    )
  limit 1;

  update public.profile_gifts g
  set opened_at = coalesce(g.opened_at, timezone('utc'::text, now())),
      revealed_at = coalesce(g.revealed_at, timezone('utc'::text, now()))
  where g.id = p_gift_id
    and exists (
      select 1
      from public.profiles recipient
      where recipient.id = g.profile_id
        and recipient.user_id = auth.uid()
        and recipient.deleted_at is null
    )
  returning g.* into v_row;

  if v_row.id is null then
    raise exception 'gift not found' using errcode = 'P0002';
  end if;

  if v_was_revealed_at is null then
    perform public.rpc_log_profile_gift_event(
      v_row.id,
      'revealed',
      jsonb_build_object('gift_type', v_row.gift_type)
    );

    perform public.notify_profile_gift_sender_moment(v_row.id, 'revealed');
  end if;

  return jsonb_build_object(
    'gift_id', v_row.id,
    'opened_at', v_row.opened_at,
    'revealed_at', v_row.revealed_at,
    'archived_at', v_row.archived_at
  );
end;
$$;


ALTER FUNCTION "public"."rpc_reveal_profile_gift"("p_gift_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_review_circle_pulse_comment_report"("p_comment_id" "uuid", "p_actor_profile_id" "uuid", "p_action" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_comment public.circle_pulse_comments%rowtype;
  v_action text := lower(coalesce(p_action, ''));
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_actor_profile_id
      and p.user_id = auth.uid()
      and p.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  if v_action not in ('reviewing', 'dismiss', 'remove') then
    raise exception 'invalid_action';
  end if;

  select *
    into v_comment
  from public.circle_pulse_comments cpc
  where cpc.id = p_comment_id
  for update;

  if v_comment.id is null then
    raise exception 'comment_not_found';
  end if;

  if not public.can_manage_circle_pulse(v_comment.circle_id, auth.uid()) then
    raise exception 'host_required' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.circle_pulse_comment_reports cpcr
    where cpcr.comment_id = p_comment_id
      and cpcr.status in ('pending', 'reviewing')
  ) then
    raise exception 'pulse_comment_report_not_found';
  end if;

  if v_action = 'remove' then
    update public.circle_pulse_comments
    set status = 'removed',
        deleted_at = timezone('utc'::text, now())
    where id = p_comment_id
      and status = 'active';
  end if;

  update public.circle_pulse_comment_reports
  set status = case
        when v_action = 'reviewing' then 'reviewing'
        when v_action = 'dismiss' then 'dismissed'
        else 'resolved'
      end,
      reviewed_by_profile_id = p_actor_profile_id,
      reviewed_at = case
        when v_action = 'reviewing' then reviewed_at
        else timezone('utc'::text, now())
      end
  where comment_id = p_comment_id
    and status in ('pending', 'reviewing');

  return true;
end;
$$;


ALTER FUNCTION "public"."rpc_review_circle_pulse_comment_report"("p_comment_id" "uuid", "p_actor_profile_id" "uuid", "p_action" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."circle_reports" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "circle_id" "uuid",
    "gathering_id" "uuid",
    "prompt_response_id" "uuid",
    "reporter_profile_id" "uuid" NOT NULL,
    "reporter_user_id" "uuid",
    "reason" "text" NOT NULL,
    "details" "text",
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "reviewed_by_admin_id" "uuid",
    "reviewed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    CONSTRAINT "circle_reports_status_valid" CHECK (("status" = ANY (ARRAY['pending'::"text", 'reviewing'::"text", 'resolved'::"text", 'dismissed'::"text"]))),
    CONSTRAINT "circle_reports_target_present" CHECK ((("circle_id" IS NOT NULL) OR ("gathering_id" IS NOT NULL) OR ("prompt_response_id" IS NOT NULL)))
);


ALTER TABLE "public"."circle_reports" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_review_circle_report"("p_report_id" "uuid", "p_profile_id" "uuid", "p_status" "text") RETURNS "public"."circle_reports"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_owner uuid;
  v_actor_role text;
  v_report public.circle_reports%rowtype;
  v_is_admin boolean := public.is_admin_user(auth.uid());
  v_is_circle_owner boolean := false;
  v_next_status text := lower(coalesce(p_status, ''));
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if v_next_status not in ('reviewing', 'resolved', 'dismissed') then
    raise exception 'invalid_status';
  end if;

  select p.user_id into v_owner
  from public.profiles p
  where p.id = p_profile_id
  limit 1;

  if v_owner is null or v_owner <> auth.uid() then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  select *
    into v_report
  from public.circle_reports cr
  where cr.id = p_report_id
  for update;

  if v_report.id is null or v_report.circle_id is null then
    raise exception 'report_not_found';
  end if;

  v_is_circle_owner := public.is_circle_owner(v_report.circle_id, auth.uid());

  if not v_is_admin and not v_is_circle_owner then
    select lower(cm.role) into v_actor_role
    from public.circle_members cm
    where cm.circle_id = v_report.circle_id
      and cm.profile_id = p_profile_id
      and cm.status = 'active'
    limit 1;

    if coalesce(v_actor_role, '') not in ('leader', 'host', 'admin', 'moderator') then
      raise exception 'host_required' using errcode = '42501';
    end if;
  end if;

  update public.circle_reports cr
  set status = v_next_status
  where cr.id = p_report_id
  returning * into v_report;

  return v_report;
end;
$$;


ALTER FUNCTION "public"."rpc_review_circle_report"("p_report_id" "uuid", "p_profile_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_review_circle_role_request"("p_request_id" "uuid", "p_profile_id" "uuid", "p_decision" "text", "p_rejection_reason" "text" DEFAULT NULL::"text") RETURNS "public"."circle_role_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_owner uuid;
  v_actor_role text;
  v_request public.circle_role_requests%rowtype;
  v_decision text := lower(coalesce(p_decision, ''));
  v_is_admin boolean := public.is_admin_user(auth.uid());
  v_is_circle_owner boolean := false;
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if v_decision not in ('approve', 'reject') then
    raise exception 'invalid_decision';
  end if;

  select user_id into v_owner
  from public.profiles
  where id = p_profile_id
  limit 1;

  if v_owner is null or v_owner <> auth.uid() then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  select *
    into v_request
  from public.circle_role_requests
  where id = p_request_id
    and status = 'pending'
  for update;

  if v_request.id is null then
    raise exception 'request_not_found';
  end if;

  v_is_circle_owner := public.is_circle_owner(v_request.circle_id, auth.uid());

  if not v_is_admin and not v_is_circle_owner then
    select lower(role) into v_actor_role
    from public.circle_members
    where circle_id = v_request.circle_id
      and profile_id = p_profile_id
      and status = 'active'
    limit 1;

    if coalesce(v_actor_role, '') not in ('leader', 'host', 'admin') then
      raise exception 'host_required' using errcode = '42501';
    end if;

    if v_request.requested_role = 'host' then
      raise exception 'owner_required_for_host_request' using errcode = '42501';
    end if;
  end if;

  if v_decision = 'approve' then
    update public.circle_members
    set role = v_request.requested_role,
        updated_at = timezone('utc'::text, now())
    where circle_id = v_request.circle_id
      and profile_id = v_request.requester_profile_id
      and status = 'active';

    update public.circle_role_requests
    set status = 'approved',
        reviewed_by_profile_id = p_profile_id,
        reviewed_by_user_id = auth.uid(),
        rejection_reason = null,
        reviewed_at = timezone('utc'::text, now()),
        updated_at = timezone('utc'::text, now())
    where id = p_request_id
    returning * into v_request;

    return v_request;
  end if;

  update public.circle_role_requests
  set status = 'rejected',
      reviewed_by_profile_id = p_profile_id,
      reviewed_by_user_id = auth.uid(),
      rejection_reason = nullif(btrim(coalesce(p_rejection_reason, '')), ''),
      reviewed_at = timezone('utc'::text, now()),
      updated_at = timezone('utc'::text, now())
  where id = p_request_id
  returning * into v_request;

  return v_request;
end;
$$;


ALTER FUNCTION "public"."rpc_review_circle_role_request"("p_request_id" "uuid", "p_profile_id" "uuid", "p_decision" "text", "p_rejection_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_save_intent_reflection"("p_intent_request_id" "uuid", "p_target_profile_id" "uuid", "p_source" "text", "p_selected_reasons" "text"[]) RETURNS "text"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_owner_profile_id uuid;
  v_request public.intent_requests%rowtype;
  v_source text := lower(nullif(btrim(coalesce(p_source, '')), ''));
  v_selected_reasons text[];
begin
  if auth.uid() is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  select profile.id
    into v_owner_profile_id
  from public.profiles profile
  where profile.user_id = auth.uid()
    and profile.deleted_at is null
  limit 1;

  if v_owner_profile_id is null then
    raise exception 'profile required' using errcode = '42501';
  end if;

  select request_row.*
    into v_request
  from public.intent_requests request_row
  where request_row.id = p_intent_request_id
    and (
      request_row.actor_id = v_owner_profile_id
      or request_row.recipient_id = v_owner_profile_id
    )
  limit 1;

  if v_request.id is null then
    raise exception 'intent request not found' using errcode = '42501';
  end if;

  if p_target_profile_id is null
    or p_target_profile_id = v_owner_profile_id
    or p_target_profile_id not in (v_request.actor_id, v_request.recipient_id) then
    raise exception 'invalid target profile' using errcode = '42501';
  end if;

  if not (
    v_request.status in ('expired', 'passed', 'cancelled')
    or (
      v_request.status = 'pending'
      and v_request.expires_at <= timezone('utc'::text, now())
    )
  ) then
    raise exception 'intent request is not closed';
  end if;

  if v_source not in ('expired_request', 'passed_profile') then
    raise exception 'invalid reflection source';
  end if;

  select coalesce(array_agg(reason order by first_position), '{}'::text[])
    into v_selected_reasons
  from (
    select
      reason,
      min(position) as first_position
    from unnest(coalesce(p_selected_reasons, '{}'::text[])) with ordinality as selected(reason, position)
    where reason in (
      'shared_values',
      'relationship_intent',
      'personality',
      'faith_family',
      'interests_lifestyle',
      'culture_location'
    )
    group by reason
    order by min(position)
    limit 2
  ) normalized;

  insert into public.intent_reflections (
    owner_profile_id,
    target_profile_id,
    intent_request_id,
    source,
    selected_reasons,
    updated_at
  )
  values (
    v_owner_profile_id,
    p_target_profile_id,
    p_intent_request_id,
    v_source,
    coalesce(v_selected_reasons, '{}'::text[]),
    timezone('utc'::text, now())
  )
  on conflict (intent_request_id, owner_profile_id) do update
  set target_profile_id = excluded.target_profile_id,
      source = excluded.source,
      selected_reasons = excluded.selected_reasons,
      updated_at = excluded.updated_at;

  return coalesce(v_selected_reasons, '{}'::text[]);
end;
$$;


ALTER FUNCTION "public"."rpc_save_intent_reflection"("p_intent_request_id" "uuid", "p_target_profile_id" "uuid", "p_source" "text", "p_selected_reasons" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_search_circle_invite_candidates"("p_circle_id" "uuid", "p_actor_profile_id" "uuid", "p_search" "text" DEFAULT NULL::"text", "p_country" "text" DEFAULT NULL::"text", "p_interest" "text" DEFAULT NULL::"text", "p_min_age" integer DEFAULT NULL::integer, "p_max_age" integer DEFAULT NULL::integer, "p_limit" integer DEFAULT 24) RETURNS TABLE("profile_id" "uuid", "full_name" "text", "avatar_url" "text", "age" integer, "location" "text", "country" "text", "interests" "text"[])
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_search text := nullif(btrim(coalesce(p_search, '')), '');
  v_country text := nullif(btrim(coalesce(p_country, '')), '');
  v_interest text := nullif(btrim(coalesce(p_interest, '')), '');
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles actor
    where actor.id = p_actor_profile_id
      and actor.user_id = auth.uid()
      and actor.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  if not public.can_invite_to_circle(p_circle_id, auth.uid()) then
    raise exception 'circle_membership_required' using errcode = '42501';
  end if;

  return query
  select
    candidate.id,
    coalesce(nullif(btrim(candidate.full_name), ''), 'Betweener member') as full_name,
    candidate.avatar_url,
    candidate.age,
    coalesce(nullif(btrim(candidate.city), ''), nullif(btrim(candidate.region), ''), nullif(btrim(candidate.location), '')) as location,
    coalesce(nullif(btrim(candidate.current_country), ''), nullif(btrim(candidate.current_country_code), '')) as country,
    array(
      select i.name
      from public.profile_interests pi
      join public.interests i on i.id = pi.interest_id
      where pi.profile_id = candidate.id
      order by i.name
      limit 4
    ) as interests
  from public.profiles candidate
  where candidate.id <> p_actor_profile_id
    and candidate.deleted_at is null
    and coalesce(candidate.is_active, true)
    and not exists (
      select 1
      from public.circle_members cm
      where cm.circle_id = p_circle_id
        and cm.profile_id = candidate.id
        and cm.status in ('active', 'pending', 'invited')
    )
    and (
      v_search is null
      or concat_ws(' ', candidate.full_name, candidate.city, candidate.region, candidate.current_country) ilike '%' || v_search || '%'
    )
    and (
      v_country is null
      or candidate.current_country ilike '%' || v_country || '%'
      or candidate.current_country_code ilike v_country
    )
    and (p_min_age is null or candidate.age >= p_min_age)
    and (p_max_age is null or candidate.age <= p_max_age)
    and (
      v_interest is null
      or exists (
        select 1
        from public.profile_interests pi
        join public.interests i on i.id = pi.interest_id
        where pi.profile_id = candidate.id
          and i.name ilike '%' || v_interest || '%'
      )
    )
  order by
    case when v_search is not null and candidate.full_name ilike v_search || '%' then 0 else 1 end,
    candidate.full_name asc nulls last,
    candidate.id
  limit greatest(1, least(coalesce(p_limit, 24), 50));
end;
$$;


ALTER FUNCTION "public"."rpc_search_circle_invite_candidates"("p_circle_id" "uuid", "p_actor_profile_id" "uuid", "p_search" "text", "p_country" "text", "p_interest" "text", "p_min_age" integer, "p_max_age" integer, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_send_date_plan"("p_recipient_profile_id" "uuid", "p_scheduled_for" timestamp with time zone, "p_place_name" "text", "p_place_address" "text" DEFAULT NULL::"text", "p_place_source" "text" DEFAULT 'search'::"text", "p_place_badges" "jsonb" DEFAULT '[]'::"jsonb", "p_place_summary" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_lat" double precision DEFAULT NULL::double precision, "p_lng" double precision DEFAULT NULL::double precision, "p_note" "text" DEFAULT NULL::"text", "p_venue_id" "uuid" DEFAULT NULL::"uuid", "p_reply_to_message_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("plan_id" "uuid", "message_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_actor_profile public.profiles%rowtype;
  v_recipient_profile public.profiles%rowtype;
  v_message_id uuid;
  v_plan_id uuid;
  v_place_badges jsonb := coalesce(p_place_badges, '[]'::jsonb);
  v_has_match boolean := false;
  v_has_accepted_connect boolean := false;
  v_has_active_chat boolean := false;
  v_has_guess_interest boolean := false;
  v_has_strong_signals boolean := false;
  v_message_stats record;
  v_message_text text;
begin
  select *
  into v_actor_profile
  from public.profiles
  where user_id = auth.uid()
  limit 1;

  if v_actor_profile.id is null then
    raise exception 'actor_profile_not_found';
  end if;

  select *
  into v_recipient_profile
  from public.profiles
  where id = p_recipient_profile_id
  limit 1;

  if v_recipient_profile.id is null then
    raise exception 'recipient_profile_not_found';
  end if;

  if v_recipient_profile.user_id = auth.uid() then
    raise exception 'cannot_plan_date_with_yourself';
  end if;

  if p_scheduled_for <= now() then
    raise exception 'Choose a future time for the invitation.';
  end if;

  if btrim(coalesce(p_place_name, '')) = '' then
    raise exception 'Choose a place before sending the invitation.';
  end if;

  if p_place_source not in ('betweener_pick', 'nearby', 'search', 'preferred') then
    raise exception 'invalid_place_source';
  end if;

  if jsonb_typeof(v_place_badges) <> 'array' then
    raise exception 'invalid_place_badges';
  end if;

  if exists (
    select 1
    from public.blocks b
    where (b.blocker_id = auth.uid() and b.blocked_id = v_recipient_profile.user_id)
       or (b.blocker_id = v_recipient_profile.user_id and b.blocked_id = auth.uid())
  ) then
    raise exception 'blocked';
  end if;

  if p_venue_id is not null and not exists (
    select 1
    from public.betweener_venues bv
    where bv.id = p_venue_id
      and bv.is_active = true
  ) then
    raise exception 'venue_not_available';
  end if;

  select exists (
    select 1
    from public.matches m
    where m.status in ('PENDING', 'ACCEPTED')
      and (
        (m.user1_id = v_actor_profile.id and m.user2_id = v_recipient_profile.id)
        or (m.user1_id = v_recipient_profile.id and m.user2_id = v_actor_profile.id)
      )
  )
  into v_has_match;

  select exists (
    select 1
    from public.intent_requests ir
    where ir.type = 'connect'
      and ir.status in ('accepted', 'matched')
      and (
        (ir.actor_id = v_actor_profile.id and ir.recipient_id = v_recipient_profile.id)
        or (ir.actor_id = v_recipient_profile.id and ir.recipient_id = v_actor_profile.id)
      )
  )
  into v_has_accepted_connect;

  select exists (
    select 1
    from public.intent_requests ir
    where ir.type = 'connect'
      and lower(coalesce(ir.metadata->>'source', '')) = 'guess_prompt'
      and (
        (ir.actor_id = v_actor_profile.id and ir.recipient_id = v_recipient_profile.id)
        or (ir.actor_id = v_recipient_profile.id and ir.recipient_id = v_actor_profile.id)
      )
  )
  into v_has_guess_interest;

  select
    count(*) as total_count,
    count(*) filter (where sender_id = auth.uid()) as actor_count,
    count(*) filter (where sender_id = v_recipient_profile.user_id) as recipient_count
  into v_message_stats
  from public.messages m
  where (
    (m.sender_id = auth.uid() and m.receiver_id = v_recipient_profile.user_id)
    or (m.sender_id = v_recipient_profile.user_id and m.receiver_id = auth.uid())
  );

  v_has_active_chat := coalesce(v_message_stats.total_count, 0) > 0;
  v_has_strong_signals :=
    coalesce(v_message_stats.total_count, 0) >= 6
    and coalesce(v_message_stats.actor_count, 0) >= 2
    and coalesce(v_message_stats.recipient_count, 0) >= 2;

  if not (v_has_match or v_has_accepted_connect or v_has_active_chat or v_has_guess_interest or v_has_strong_signals) then
    raise exception 'Keep warming the connection first, then plan the date from chat.';
  end if;

  if exists (
    select 1
    from public.date_plans dp
    where dp.status = 'pending'
      and (
        (dp.creator_profile_id = v_actor_profile.id and dp.recipient_profile_id = v_recipient_profile.id)
        or (dp.creator_profile_id = v_recipient_profile.id and dp.recipient_profile_id = v_actor_profile.id)
      )
  ) then
    raise exception 'There is already a date invitation waiting for a response.';
  end if;

  insert into public.date_plans (
    creator_profile_id,
    creator_user_id,
    recipient_profile_id,
    recipient_user_id,
    venue_id,
    scheduled_for,
    place_name,
    place_address,
    place_source,
    place_badges,
    place_summary,
    city,
    lat,
    lng,
    note
  )
  values (
    v_actor_profile.id,
    auth.uid(),
    v_recipient_profile.id,
    v_recipient_profile.user_id,
    p_venue_id,
    p_scheduled_for,
    btrim(p_place_name),
    nullif(btrim(coalesce(p_place_address, '')), ''),
    p_place_source,
    v_place_badges,
    nullif(btrim(coalesce(p_place_summary, '')), ''),
    nullif(btrim(coalesce(p_city, '')), ''),
    p_lat,
    p_lng,
    nullif(btrim(coalesce(p_note, '')), '')
  )
  returning id into v_plan_id;

  v_message_text := 'date_plan::' || jsonb_build_object(
    'planId', v_plan_id,
    'venueId', p_venue_id,
    'scheduledFor', p_scheduled_for,
    'placeName', btrim(p_place_name),
    'placeAddress', nullif(btrim(coalesce(p_place_address, '')), ''),
    'source', p_place_source,
    'badges', v_place_badges,
    'summary', nullif(btrim(coalesce(p_place_summary, '')), ''),
    'city', nullif(btrim(coalesce(p_city, '')), ''),
    'lat', p_lat,
    'lng', p_lng,
    'note', nullif(btrim(coalesce(p_note, '')), ''),
    'status', 'pending',
    'conciergeRequested', false
  )::text;

  insert into public.messages (
    text,
    sender_id,
    receiver_id,
    is_read,
    message_type,
    reply_to_message_id
  )
  values (
    v_message_text,
    auth.uid(),
    v_recipient_profile.user_id,
    false,
    'text',
    p_reply_to_message_id
  )
  returning id into v_message_id;

  update public.date_plans
  set message_id = v_message_id
  where id = v_plan_id;

  return query
  select v_plan_id, v_message_id;
end;
$$;


ALTER FUNCTION "public"."rpc_send_date_plan"("p_recipient_profile_id" "uuid", "p_scheduled_for" timestamp with time zone, "p_place_name" "text", "p_place_address" "text", "p_place_source" "text", "p_place_badges" "jsonb", "p_place_summary" "text", "p_city" "text", "p_lat" double precision, "p_lng" double precision, "p_note" "text", "p_venue_id" "uuid", "p_reply_to_message_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_send_date_plan"("p_recipient_profile_id" "uuid", "p_scheduled_for" timestamp with time zone, "p_place_name" "text", "p_place_address" "text" DEFAULT NULL::"text", "p_place_source" "text" DEFAULT 'search'::"text", "p_place_badges" "jsonb" DEFAULT '[]'::"jsonb", "p_place_summary" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_lat" double precision DEFAULT NULL::double precision, "p_lng" double precision DEFAULT NULL::double precision, "p_note" "text" DEFAULT NULL::"text", "p_venue_id" "uuid" DEFAULT NULL::"uuid", "p_parent_plan_id" "uuid" DEFAULT NULL::"uuid", "p_response_kind" "text" DEFAULT 'initial'::"text", "p_reply_to_message_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("plan_id" "uuid", "message_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_actor_profile public.profiles%rowtype;
  v_recipient_profile public.profiles%rowtype;
  v_message_id uuid;
  v_plan_id uuid;
  v_place_badges jsonb := coalesce(p_place_badges, '[]'::jsonb);
  v_has_match boolean := false;
  v_has_accepted_connect boolean := false;
  v_has_active_chat boolean := false;
  v_has_guess_interest boolean := false;
  v_has_strong_signals boolean := false;
  v_message_stats record;
  v_message_text text;
  v_parent_plan public.date_plans%rowtype;
  v_target_profile public.profiles%rowtype;
begin
  select *
  into v_actor_profile
  from public.profiles
  where user_id = auth.uid()
  limit 1;

  if v_actor_profile.id is null then
    raise exception 'actor_profile_not_found';
  end if;

  if p_parent_plan_id is null
     and public.get_active_subscription_plan(auth.uid()) not in ('SILVER', 'GOLD') then
    raise exception 'Silver or Gold is required to suggest a new date plan.';
  end if;

  select *
  into v_recipient_profile
  from public.profiles
  where id = p_recipient_profile_id
  limit 1;

  if v_recipient_profile.id is null then
    raise exception 'recipient_profile_not_found';
  end if;

  if v_recipient_profile.user_id = auth.uid() then
    raise exception 'cannot_plan_date_with_yourself';
  end if;

  if p_scheduled_for <= now() then
    raise exception 'Choose a future time for the suggestion.';
  end if;

  if btrim(coalesce(p_place_name, '')) = '' then
    raise exception 'Choose a place before sending the suggestion.';
  end if;

  if p_place_source not in ('betweener_pick', 'nearby', 'search', 'preferred') then
    raise exception 'invalid_place_source';
  end if;

  if p_response_kind not in ('initial', 'counter_time', 'counter_place', 'counter_both') then
    raise exception 'invalid_response_kind';
  end if;

  if jsonb_typeof(v_place_badges) <> 'array' then
    raise exception 'invalid_place_badges';
  end if;

  if exists (
    select 1
    from public.blocks b
    where (b.blocker_id = auth.uid() and b.blocked_id = v_recipient_profile.user_id)
       or (b.blocker_id = v_recipient_profile.user_id and b.blocked_id = auth.uid())
  ) then
    raise exception 'blocked';
  end if;

  if p_venue_id is not null and not exists (
    select 1
    from public.betweener_venues bv
    where bv.id = p_venue_id
      and bv.is_active = true
  ) then
    raise exception 'venue_not_available';
  end if;

  select exists (
    select 1
    from public.matches m
    where m.status in ('PENDING', 'ACCEPTED')
      and (
        (m.user1_id = v_actor_profile.id and m.user2_id = v_recipient_profile.id)
        or (m.user1_id = v_recipient_profile.id and m.user2_id = v_actor_profile.id)
      )
  )
  into v_has_match;

  select exists (
    select 1
    from public.intent_requests ir
    where ir.type = 'connect'
      and ir.status in ('accepted', 'matched')
      and (
        (ir.actor_id = v_actor_profile.id and ir.recipient_id = v_recipient_profile.id)
        or (ir.actor_id = v_recipient_profile.id and ir.recipient_id = v_actor_profile.id)
      )
  )
  into v_has_accepted_connect;

  select exists (
    select 1
    from public.intent_requests ir
    where ir.type = 'connect'
      and lower(coalesce(ir.metadata->>'source', '')) = 'guess_prompt'
      and (
        (ir.actor_id = v_actor_profile.id and ir.recipient_id = v_recipient_profile.id)
        or (ir.actor_id = v_recipient_profile.id and ir.recipient_id = v_actor_profile.id)
      )
  )
  into v_has_guess_interest;

  select
    count(*) as total_count,
    count(*) filter (where sender_id = auth.uid()) as actor_count,
    count(*) filter (where sender_id = v_recipient_profile.user_id) as recipient_count
  into v_message_stats
  from public.messages m
  where (
    (m.sender_id = auth.uid() and m.receiver_id = v_recipient_profile.user_id)
    or (m.sender_id = v_recipient_profile.user_id and m.receiver_id = auth.uid())
  );

  v_has_active_chat := coalesce(v_message_stats.total_count, 0) > 0;
  v_has_strong_signals :=
    coalesce(v_message_stats.total_count, 0) >= 6
    and coalesce(v_message_stats.actor_count, 0) >= 2
    and coalesce(v_message_stats.recipient_count, 0) >= 2;

  if not (v_has_match or v_has_accepted_connect or v_has_active_chat or v_has_guess_interest or v_has_strong_signals) then
    raise exception 'Keep warming the connection first, then plan the date from chat.';
  end if;

  if p_parent_plan_id is not null then
    select *
    into v_parent_plan
    from public.date_plans
    where id = p_parent_plan_id
    limit 1;

    if v_parent_plan.id is null then
      raise exception 'date_plan_not_found';
    end if;

    if auth.uid() not in (v_parent_plan.creator_user_id, v_parent_plan.recipient_user_id) then
      raise exception 'Only participants can respond to this suggestion.';
    end if;

    if v_parent_plan.status not in ('pending', 'accepted') then
      raise exception 'This date suggestion can no longer be updated.';
    end if;

    if p_response_kind = 'initial' then
      raise exception 'counter_suggestion_requires_response_kind';
    end if;

    if auth.uid() = v_parent_plan.creator_user_id then
      select * into v_target_profile from public.profiles where id = v_parent_plan.recipient_profile_id limit 1;
    else
      select * into v_target_profile from public.profiles where id = v_parent_plan.creator_profile_id limit 1;
    end if;

    if v_target_profile.id is null then
      raise exception 'recipient_profile_not_found';
    end if;

    v_recipient_profile := v_target_profile;

  end if;

  if exists (
    select 1
    from public.date_plans dp
    where dp.status = 'pending'
      and (p_parent_plan_id is null or dp.id <> p_parent_plan_id)
      and (
        (dp.creator_profile_id = v_actor_profile.id and dp.recipient_profile_id = v_recipient_profile.id)
        or (dp.creator_profile_id = v_recipient_profile.id and dp.recipient_profile_id = v_actor_profile.id)
      )
  ) then
    raise exception 'There is already a date suggestion waiting for a response.';
  end if;

  if v_parent_plan.id is not null and v_parent_plan.status = 'pending' then
    update public.date_plans
    set status = 'countered',
        updated_at = now()
    where id = v_parent_plan.id;
  end if;

  insert into public.date_plans (
    creator_profile_id,
    creator_user_id,
    recipient_profile_id,
    recipient_user_id,
    parent_plan_id,
    venue_id,
    scheduled_for,
    place_name,
    place_address,
    place_source,
    place_badges,
    place_summary,
    city,
    lat,
    lng,
    note,
    response_kind
  )
  values (
    v_actor_profile.id,
    auth.uid(),
    v_recipient_profile.id,
    v_recipient_profile.user_id,
    p_parent_plan_id,
    p_venue_id,
    p_scheduled_for,
    btrim(p_place_name),
    nullif(btrim(coalesce(p_place_address, '')), ''),
    p_place_source,
    v_place_badges,
    nullif(btrim(coalesce(p_place_summary, '')), ''),
    nullif(btrim(coalesce(p_city, '')), ''),
    p_lat,
    p_lng,
    nullif(btrim(coalesce(p_note, '')), ''),
    p_response_kind
  )
  returning id into v_plan_id;

  v_message_text := 'date_plan::' || jsonb_build_object(
    'planId', v_plan_id,
    'parentPlanId', p_parent_plan_id,
    'venueId', p_venue_id,
    'scheduledFor', p_scheduled_for,
    'placeName', btrim(p_place_name),
    'placeAddress', nullif(btrim(coalesce(p_place_address, '')), ''),
    'source', p_place_source,
    'badges', v_place_badges,
    'summary', nullif(btrim(coalesce(p_place_summary, '')), ''),
    'city', nullif(btrim(coalesce(p_city, '')), ''),
    'lat', p_lat,
    'lng', p_lng,
    'note', nullif(btrim(coalesce(p_note, '')), ''),
    'responseKind', p_response_kind,
    'status', 'pending',
    'conciergeRequested', false
  )::text;

  insert into public.messages (
    text,
    sender_id,
    receiver_id,
    is_read,
    message_type,
    reply_to_message_id
  )
  values (
    v_message_text,
    auth.uid(),
    v_recipient_profile.user_id,
    false,
    'text',
    p_reply_to_message_id
  )
  returning id into v_message_id;

  update public.date_plans
  set message_id = v_message_id
  where id = v_plan_id;

  return query
  select v_plan_id, v_message_id;
end;
$$;


ALTER FUNCTION "public"."rpc_send_date_plan"("p_recipient_profile_id" "uuid", "p_scheduled_for" timestamp with time zone, "p_place_name" "text", "p_place_address" "text", "p_place_source" "text", "p_place_badges" "jsonb", "p_place_summary" "text", "p_city" "text", "p_lat" double precision, "p_lng" double precision, "p_note" "text", "p_venue_id" "uuid", "p_parent_plan_id" "uuid", "p_response_kind" "text", "p_reply_to_message_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_send_profile_gift"("p_recipient_profile_id" "uuid", "p_gift_type" "text", "p_include_sandbox_preview" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_sender_profile public.profiles%rowtype;
  v_recipient_profile public.profiles%rowtype;
  v_resolved_plan public.subscription_type := 'FREE';
  v_gift_id uuid;
begin
  if auth.uid() is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  if p_gift_type not in ('rose', 'teddy', 'ring') then
    raise exception 'invalid gift type' using errcode = '22023';
  end if;

  select p.*
    into v_sender_profile
  from public.profiles p
  where p.user_id = auth.uid()
    and p.deleted_at is null
  limit 1;

  if v_sender_profile.id is null then
    raise exception 'profile required' using errcode = '42501';
  end if;

  select p.*
    into v_recipient_profile
  from public.profiles p
  where p.id = p_recipient_profile_id
    and p.deleted_at is null
  limit 1;

  if v_recipient_profile.id is null then
    raise exception 'recipient profile not found' using errcode = 'P0002';
  end if;

  if v_recipient_profile.user_id = auth.uid() then
    raise exception 'cannot send gift to yourself' using errcode = '22023';
  end if;

  if exists (
    select 1
    from public.profile_gifts g
    where g.profile_id = v_recipient_profile.id
      and g.sender_id = auth.uid()
      and g.created_at >= timezone('utc'::text, now()) - interval '6 hours'
  ) then
    raise exception 'gift cooldown active' using errcode = '23514';
  end if;

  v_resolved_plan := public.get_subscription_badge_plan(
    auth.uid(),
    coalesce(p_include_sandbox_preview, false)
  );

  if p_gift_type in ('rose', 'teddy') and v_resolved_plan not in ('SILVER', 'GOLD') then
    raise exception 'premium subscription required' using errcode = '42501';
  end if;

  if p_gift_type = 'ring' and v_resolved_plan <> 'GOLD' then
    raise exception 'gold subscription required' using errcode = '42501';
  end if;

  insert into public.profile_gifts (
    profile_id,
    sender_id,
    sender_profile_id,
    sender_display_name,
    sender_avatar_url,
    sender_gender,
    gift_type
  )
  values (
    v_recipient_profile.id,
    auth.uid(),
    v_sender_profile.id,
    coalesce(nullif(v_sender_profile.full_name, ''), 'Someone'),
    v_sender_profile.avatar_url,
    v_sender_profile.gender::text,
    p_gift_type
  )
  returning id into v_gift_id;

  perform public.rpc_log_profile_gift_event(
    v_gift_id,
    'sent',
    jsonb_build_object(
      'gift_type', p_gift_type,
      'plan', v_resolved_plan
    )
  );

  return jsonb_build_object(
    'gift_id', v_gift_id,
    'gift_type', p_gift_type,
    'recipient_profile_id', v_recipient_profile.id,
    'plan', v_resolved_plan
  );
end;
$$;


ALTER FUNCTION "public"."rpc_send_profile_gift"("p_recipient_profile_id" "uuid", "p_gift_type" "text", "p_include_sandbox_preview" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_send_signal"("p_receiver_profile_id" "uuid", "p_reason_key" "text", "p_note" "text" DEFAULT NULL::"text", "p_source" "text" DEFAULT 'profile'::"text", "p_source_moment_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_sender_profile public.profiles%rowtype;
  v_receiver_profile public.profiles%rowtype;
  v_plan public.subscription_type := 'FREE';
  v_limit integer := 0;
  v_used integer := 0;
  v_remaining integer := 0;
  v_period_start timestamptz := date_trunc('week', timezone('utc', now())) at time zone 'utc';
  v_reason_key text := btrim(coalesce(p_reason_key, ''));
  v_reason_label text;
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_source text := coalesce(nullif(btrim(p_source), ''), 'profile');
  v_signal public.profile_signal_gestures%rowtype;
begin
  if v_user_id is null then
    raise exception 'unauthenticated';
  end if;

  select * into v_sender_profile
  from public.profiles
  where user_id = v_user_id
  limit 1;

  if v_sender_profile.id is null then
    raise exception 'profile_not_found';
  end if;

  select * into v_receiver_profile
  from public.profiles
  where id = p_receiver_profile_id
  limit 1;

  if v_receiver_profile.id is null then
    raise exception 'receiver_not_found';
  end if;

  if v_sender_profile.id = v_receiver_profile.id then
    raise exception 'self_signal_not_allowed';
  end if;

  if v_receiver_profile.user_id is null then
    raise exception 'receiver_not_found';
  end if;

  if exists (
    select 1
    from public.blocks b
    where (b.blocker_id = v_user_id and b.blocked_id = v_receiver_profile.user_id)
       or (b.blocker_id = v_receiver_profile.user_id and b.blocked_id = v_user_id)
  ) then
    raise exception 'blocked_or_unavailable';
  end if;

  if v_source not in ('vibes_card', 'profile', 'moment', 'intent') then
    raise exception 'invalid_source';
  end if;

  v_reason_label := public.signal_reason_label(v_reason_key);
  if v_reason_label is null then
    raise exception 'invalid_reason';
  end if;

  if v_note is not null and char_length(v_note) > 120 then
    raise exception 'invalid_note';
  end if;

  update public.profile_signal_gestures
  set status = 'expired'
  where sender_profile_id = v_sender_profile.id
    and receiver_profile_id = v_receiver_profile.id
    and status in ('sent', 'seen')
    and expires_at <= now();

  if exists (
    select 1
    from public.profile_signal_gestures
    where sender_profile_id = v_sender_profile.id
      and receiver_profile_id = v_receiver_profile.id
      and status in ('sent', 'seen')
      and expires_at > now()
  ) then
    raise exception 'duplicate_active_signal';
  end if;

  v_plan := public.get_active_subscription_plan(v_user_id);
  v_limit := public.signal_limit_for_plan(v_plan);

  if v_plan = 'FREE' then
    select count(*)::integer into v_used
    from public.profile_signal_gestures
    where sender_profile_id = v_sender_profile.id;
  else
    select count(*)::integer into v_used
    from public.profile_signal_gestures
    where sender_profile_id = v_sender_profile.id
      and created_at >= v_period_start;
  end if;

  if coalesce(v_used, 0) >= v_limit then
    if v_plan = 'FREE' then
      raise exception 'premium_required';
    else
      raise exception 'signal_quota_exceeded';
    end if;
  end if;

  insert into public.profile_signal_gestures (
    sender_profile_id,
    receiver_profile_id,
    sender_user_id,
    receiver_user_id,
    reason_key,
    reason_label,
    note,
    source,
    source_moment_id
  )
  values (
    v_sender_profile.id,
    v_receiver_profile.id,
    v_user_id,
    v_receiver_profile.user_id,
    v_reason_key,
    v_reason_label,
    v_note,
    v_source,
    p_source_moment_id
  )
  returning * into v_signal;

  v_remaining := greatest(v_limit - coalesce(v_used, 0) - 1, 0);

  insert into public.system_messages (
    user_id,
    peer_user_id,
    intent_request_id,
    event_type,
    text,
    metadata
  )
  values (
    v_receiver_profile.user_id,
    v_user_id,
    null,
    'signal_received',
    coalesce(v_sender_profile.full_name, 'Someone') || ' sent you a Signal.',
    jsonb_build_object(
      'signal_id', v_signal.id,
      'sender_profile_id', v_sender_profile.id,
      'receiver_profile_id', v_receiver_profile.id,
      'reason_key', v_reason_key,
      'reason_label', v_reason_label,
      'source', v_source,
      'expires_at', v_signal.expires_at
    )
  );

  return jsonb_build_object(
    'ok', true,
    'signal', jsonb_build_object(
      'id', v_signal.id,
      'reason_key', v_signal.reason_key,
      'reason', v_signal.reason_label,
      'note', v_signal.note,
      'expires_at', v_signal.expires_at
    ),
    'remainingSignals', v_remaining
  );
end;
$$;


ALTER FUNCTION "public"."rpc_send_signal"("p_receiver_profile_id" "uuid", "p_reason_key" "text", "p_note" "text", "p_source" "text", "p_source_moment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_set_chat_typing_state"("p_peer_user_id" "uuid", "p_typing" boolean, "p_typing_for_ms" integer DEFAULT 5000) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_count integer := 0;
  v_now timestamptz := now();
  v_typing_for_ms integer := greatest(1000, least(coalesce(p_typing_for_ms, 5000), 8000));
begin
  if v_user_id is null then
    raise exception 'unauthenticated';
  end if;

  if p_peer_user_id is null or p_peer_user_id = v_user_id then
    raise exception 'invalid_peer';
  end if;

  if coalesce(p_typing, false) = false then
    delete from public.chat_typing_state typing
    where typing.user_id = v_user_id
      and typing.peer_user_id = p_peer_user_id;
    get diagnostics v_count = row_count;
    return v_count;
  end if;

  insert into public.chat_typing_state (
    user_id,
    peer_user_id,
    typing_until,
    updated_at
  )
  values (
    v_user_id,
    p_peer_user_id,
    v_now + ((v_typing_for_ms::text || ' milliseconds')::interval),
    v_now
  )
  on conflict (user_id, peer_user_id) do update
  set typing_until = excluded.typing_until,
      updated_at = excluded.updated_at
  where chat_typing_state.updated_at <= v_now - interval '4 seconds'
     or chat_typing_state.typing_until <= v_now + interval '1 second';

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


ALTER FUNCTION "public"."rpc_set_chat_typing_state"("p_peer_user_id" "uuid", "p_typing" boolean, "p_typing_for_ms" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_set_circle_host_note"("p_circle_id" "uuid", "p_profile_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "public"."circles"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_owner uuid;
  v_actor_role text;
  v_is_admin boolean := public.is_admin_user(auth.uid());
  v_is_circle_owner boolean := false;
  v_circle public.circles%rowtype;
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  select user_id into v_owner
  from public.profiles
  where id = p_profile_id
  limit 1;

  if v_owner is null or v_owner <> auth.uid() then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  v_is_circle_owner := public.is_circle_owner(p_circle_id, auth.uid());

  if not v_is_admin and not v_is_circle_owner then
    select lower(role) into v_actor_role
    from public.circle_members
    where circle_id = p_circle_id
      and profile_id = p_profile_id
      and status = 'active'
    limit 1;

    if coalesce(v_actor_role, '') not in ('leader', 'host', 'admin', 'moderator') then
      raise exception 'host_required' using errcode = '42501';
    end if;
  end if;

  update public.circles
  set host_note = nullif(btrim(coalesce(p_note, '')), ''),
      host_note_updated_at = timezone('utc'::text, now()),
      host_note_updated_by_profile_id = p_profile_id,
      updated_at = timezone('utc'::text, now())
  where id = p_circle_id
    and archived_at is null
  returning * into v_circle;

  if v_circle.id is null then
    raise exception 'circle_not_found';
  end if;

  return v_circle;
end;
$$;


ALTER FUNCTION "public"."rpc_set_circle_host_note"("p_circle_id" "uuid", "p_profile_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_set_circle_member_role"("p_circle_id" "uuid", "p_member_id" "uuid", "p_profile_id" "uuid", "p_role" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_owner uuid;
  v_actor_role text;
  v_target_role text;
  v_target_status text;
  v_is_admin boolean := public.is_admin_user(auth.uid());
  v_is_circle_owner boolean := false;
  v_next_role text := lower(coalesce(p_role, ''));
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if v_next_role not in ('leader', 'host', 'moderator', 'matchmaker', 'member') then
    raise exception 'Invalid role';
  end if;

  select user_id into v_owner
  from public.profiles
  where id = p_profile_id
  limit 1;

  if v_owner is null or v_owner <> auth.uid() then
    raise exception 'Not authorized';
  end if;

  v_is_circle_owner := public.is_circle_owner(p_circle_id, auth.uid());

  select lower(role), status
    into v_target_role, v_target_status
  from public.circle_members
  where circle_id = p_circle_id
    and profile_id = p_member_id
  for update;

  if coalesce(v_target_status, '') <> 'active' then
    raise exception 'Member not active';
  end if;

  if not v_is_admin and not v_is_circle_owner then
    select lower(role) into v_actor_role
    from public.circle_members
    where circle_id = p_circle_id
      and profile_id = p_profile_id
      and status = 'active'
    limit 1;

    if coalesce(v_actor_role, '') not in ('leader', 'host', 'admin') then
      raise exception 'Only hosts can change roles';
    end if;

    if v_next_role in ('leader', 'host', 'admin') then
      raise exception 'Only owners can assign host roles';
    end if;

    if coalesce(v_target_role, '') in ('leader', 'host', 'admin') then
      raise exception 'Only owners can change host roles';
    end if;
  end if;

  if p_member_id = p_profile_id and v_next_role not in ('leader', 'host', 'admin') then
    raise exception 'Host cannot change own role';
  end if;

  update public.circle_members
  set role = case when v_next_role = 'leader' then 'host' else v_next_role end,
      updated_at = timezone('utc'::text, now())
  where circle_id = p_circle_id
    and profile_id = p_member_id
    and status = 'active';

  return found;
end;
$$;


ALTER FUNCTION "public"."rpc_set_circle_member_role"("p_circle_id" "uuid", "p_member_id" "uuid", "p_profile_id" "uuid", "p_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_set_profile_saved"("p_viewer_profile_id" "uuid", "p_target_profile_id" "uuid", "p_saved" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_owner_user_id uuid;
  v_rows_affected integer := 0;
begin
  if auth.uid() is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  select profile.user_id
    into v_owner_user_id
  from public.profiles profile
  where profile.id = p_viewer_profile_id
    and profile.deleted_at is null;

  if v_owner_user_id is distinct from auth.uid()
    or p_target_profile_id is null
    or p_target_profile_id = p_viewer_profile_id then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  if coalesce(p_saved, false) then
    insert into public.profile_saves (viewer_profile_id, target_profile_id)
    values (p_viewer_profile_id, p_target_profile_id)
    on conflict (viewer_profile_id, target_profile_id) do nothing;

    get diagnostics v_rows_affected = row_count;

    if v_rows_affected > 0 then
      perform public.rpc_log_vibes_event(
        p_viewer_profile_id,
        p_target_profile_id,
        'for_you',
        'profile_saved',
        null,
        null,
        jsonb_build_object(
          'source', 'profile_view',
          'saved', true
        )
      );
    end if;

    return true;
  end if;

  delete from public.profile_saves save_row
  where save_row.viewer_profile_id = p_viewer_profile_id
    and save_row.target_profile_id = p_target_profile_id;

  get diagnostics v_rows_affected = row_count;

  if v_rows_affected > 0 then
    perform public.rpc_log_vibes_event(
      p_viewer_profile_id,
      p_target_profile_id,
      'for_you',
      'profile_unsaved',
      null,
      null,
      jsonb_build_object(
        'source', 'profile_view',
        'saved', false
      )
    );
  end if;

  return false;
end;
$$;


ALTER FUNCTION "public"."rpc_set_profile_saved"("p_viewer_profile_id" "uuid", "p_target_profile_id" "uuid", "p_saved" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_set_user_presence"("p_online" boolean) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_now timestamptz := now();
  v_count integer := 0;
begin
  if v_user_id is null then
    raise exception 'unauthenticated';
  end if;

  insert into public.user_presence (
    user_id,
    online,
    last_active,
    updated_at
  )
  values (
    v_user_id,
    coalesce(p_online, false),
    v_now,
    v_now
  )
  on conflict (user_id) do update
  set online = excluded.online,
      last_active = greatest(user_presence.last_active, excluded.last_active),
      updated_at = excluded.updated_at
  where user_presence.online is distinct from excluded.online
     or user_presence.last_active <= v_now - interval '55 seconds';

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


ALTER FUNCTION "public"."rpc_set_user_presence"("p_online" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_submit_manual_verification_request"("p_profile_id" "uuid", "p_verification_type" "text", "p_document_path" "text" DEFAULT NULL::"text", "p_auto_verification_score" numeric DEFAULT NULL::numeric, "p_auto_verification_reason" "text" DEFAULT NULL::"text", "p_reference_asset_path" "text" DEFAULT NULL::"text", "p_social_platform" "text" DEFAULT NULL::"text", "p_social_profile_url" "text" DEFAULT NULL::"text", "p_social_handle" "text" DEFAULT NULL::"text") RETURNS TABLE("request_id" "uuid", "status" "text", "created_at" timestamp with time zone, "already_pending" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid;
  v_verification_type text;
  v_document_path text;
  v_reference_asset_path text;
  v_auto_verification_score numeric;
  v_auto_verification_reason text;
  v_social_platform text;
  v_social_profile_url text;
  v_social_handle text;
  v_current_verification_level integer;
  v_required_verification_level integer;
  v_refresh_required boolean;
  v_refresh_target_level integer;
  v_social_already_approved boolean;
  v_allows_refresh boolean;
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  select
    p.user_id,
    coalesce(p.verification_level, 0),
    coalesce(p.verification_refresh_required, false),
    coalesce(p.verification_refresh_target_level, p.verification_level, 1)
  into v_user_id, v_current_verification_level, v_refresh_required, v_refresh_target_level
  from public.profiles p
  where p.id = p_profile_id
    and p.user_id = auth.uid()
  limit 1;

  if v_user_id is null then
    raise exception 'profile not found for current user';
  end if;

  v_verification_type := lower(nullif(btrim(coalesce(p_verification_type, '')), ''));
  if v_verification_type is null then
    raise exception 'verification type required';
  end if;

  if v_verification_type not in ('passport', 'residence', 'social', 'workplace') then
    raise exception 'invalid manual verification type';
  end if;

  v_required_verification_level := case v_verification_type
    when 'social' then 1
    when 'passport' then 2
    when 'residence' then 2
    when 'workplace' then 2
    else 1
  end;

  v_allows_refresh := coalesce(v_refresh_required, false)
    and v_required_verification_level >= least(greatest(coalesce(v_refresh_target_level, 1), 1), 2);

  if v_verification_type = 'social' then
    select exists (
      select 1
      from public.verification_requests vr
      where vr.profile_id = p_profile_id
        and lower(coalesce(vr.verification_type, '')) = 'social'
        and coalesce(vr.status, 'pending') = 'approved'
    )
    into v_social_already_approved;

    if (v_social_already_approved or v_current_verification_level >= 2)
       and not v_allows_refresh then
      if v_social_already_approved then
        raise exception 'profile already has this verification method';
      end if;
      raise exception 'profile already has this verification level';
    end if;
  elsif v_current_verification_level >= v_required_verification_level
     and not v_allows_refresh then
    raise exception 'profile already has this verification level';
  end if;

  v_document_path := nullif(btrim(coalesce(p_document_path, '')), '');
  if v_document_path is null and v_verification_type <> 'social' then
    raise exception 'document path required';
  end if;

  v_reference_asset_path := nullif(btrim(coalesce(p_reference_asset_path, '')), '');
  v_auto_verification_score := p_auto_verification_score;
  v_auto_verification_reason := nullif(btrim(coalesce(p_auto_verification_reason, '')), '');
  v_social_platform := nullif(lower(btrim(coalesce(p_social_platform, ''))), '');
  v_social_profile_url := nullif(btrim(coalesce(p_social_profile_url, '')), '');
  v_social_handle := nullif(btrim(coalesce(p_social_handle, '')), '');

  if v_verification_type = 'social' and v_social_profile_url is null and v_social_handle is null then
    raise exception 'social evidence required';
  end if;

  return query
  with pending as (
    select
      vr.id as request_id,
      coalesce(vr.status, 'pending') as status,
      coalesce(vr.created_at, vr.submitted_at, timezone('utc'::text, now())) as created_at
    from public.verification_requests vr
    where vr.profile_id = p_profile_id
      and vr.verification_type = v_verification_type
      and coalesce(vr.status, 'pending') = 'pending'
    order by vr.created_at desc nulls last, vr.id desc
    limit 1
  ),
  inserted as (
    insert into public.verification_requests (
      user_id,
      profile_id,
      verification_type,
      document_url,
      status,
      auto_verification_score,
      auto_verification_data
    )
    select
      auth.uid(),
      p_profile_id,
      v_verification_type,
      v_document_path,
      'pending',
      v_auto_verification_score,
      jsonb_strip_nulls(
        jsonb_build_object(
          'submitted_via', 'rpc_submit_manual_verification_request',
          'auto_verification_reason', v_auto_verification_reason,
          'reference_asset_path', v_reference_asset_path,
          'social_platform', v_social_platform,
          'social_profile_url', v_social_profile_url,
          'social_handle', v_social_handle
        )
      )
    where not exists (select 1 from pending)
    returning *
  )
  select pending.request_id, pending.status, pending.created_at, true
  from pending
  union all
  select
    inserted.id as request_id,
    coalesce(inserted.status, 'pending') as status,
    coalesce(inserted.created_at, inserted.submitted_at, timezone('utc'::text, now())) as created_at,
    false as already_pending
  from inserted;
end;
$$;


ALTER FUNCTION "public"."rpc_submit_manual_verification_request"("p_profile_id" "uuid", "p_verification_type" "text", "p_document_path" "text", "p_auto_verification_score" numeric, "p_auto_verification_reason" "text", "p_reference_asset_path" "text", "p_social_platform" "text", "p_social_profile_url" "text", "p_social_handle" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_submit_report"("p_reported_id" "uuid", "p_reason" "text", "p_evidence_message_id" "uuid" DEFAULT NULL::"uuid", "p_client_evidence" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_reason text;
  v_message public.messages%rowtype;
  v_report_id uuid;
  v_client_evidence jsonb;
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  if p_reported_id is null or p_reported_id = auth.uid() then
    raise exception 'invalid reported member';
  end if;

  v_reason := nullif(btrim(coalesce(p_reason, '')), '');
  if v_reason is null then
    raise exception 'report reason required';
  end if;

  v_client_evidence := coalesce(p_client_evidence, '{}'::jsonb);
  if jsonb_typeof(v_client_evidence) <> 'object' then
    v_client_evidence := '{}'::jsonb;
  end if;

  if p_evidence_message_id is not null then
    select *
      into v_message
    from public.messages m
    where m.id = p_evidence_message_id
      and m.sender_id = p_reported_id
      and m.receiver_id = auth.uid()
    limit 1;

    if not found then
      raise exception 'message evidence not found for this report';
    end if;
  end if;

  insert into public.reports (
    reporter_id,
    reported_id,
    reason,
    evidence_message_id,
    evidence_message_text,
    evidence_message_type,
    evidence_message_sender_id,
    evidence_message_created_at,
    evidence
  )
  values (
    auth.uid(),
    p_reported_id,
    v_reason,
    case when p_evidence_message_id is null then null else v_message.id end,
    case
      when p_evidence_message_id is null then null
      when coalesce(v_message.is_view_once, false) then '[View-once message]'
      when coalesce(v_message.deleted_for_all, false) then '[Deleted message]'
      else left(coalesce(v_message.text, ''), 1200)
    end,
    case when p_evidence_message_id is null then null else coalesce(v_message.message_type, 'text') end,
    case when p_evidence_message_id is null then null else v_message.sender_id end,
    case when p_evidence_message_id is null then null else v_message.created_at end,
    jsonb_strip_nulls(
      v_client_evidence ||
      jsonb_build_object(
        'source', case when p_evidence_message_id is null then 'chat_thread' else 'chat_message' end,
        'message_id', p_evidence_message_id,
        'reported_user_id', p_reported_id
      )
    )
  )
  returning id into v_report_id;

  return v_report_id;
end;
$$;


ALTER FUNCTION "public"."rpc_submit_report"("p_reported_id" "uuid", "p_reason" "text", "p_evidence_message_id" "uuid", "p_client_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_submit_selfie_liveness_verification"("p_profile_id" "uuid", "p_document_path" "text", "p_capture_mode" "text" DEFAULT 'video'::"text", "p_challenge_type" "text" DEFAULT 'turn_left_blink'::"text", "p_reference_asset_path" "text" DEFAULT NULL::"text") RETURNS TABLE("request_id" "uuid", "status" "text", "created_at" timestamp with time zone, "already_pending" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid;
  v_refresh_required boolean;
  v_refresh_target_level integer;
  v_document_path text;
  v_reference_asset_path text;
  v_method_already_approved boolean;
begin
  if auth.uid() is null then
    raise exception 'authentication required';
  end if;

  select
    p.user_id,
    coalesce(p.verification_refresh_required, false),
    coalesce(p.verification_refresh_target_level, p.verification_level, 1)
  into v_user_id, v_refresh_required, v_refresh_target_level
  from public.profiles p
  where p.id = p_profile_id
    and p.user_id = auth.uid()
  limit 1;

  if v_user_id is null then
    raise exception 'profile not found for current user';
  end if;

  select exists (
    select 1
    from public.verification_requests vr
    where vr.profile_id = p_profile_id
      and lower(coalesce(vr.verification_type, '')) = 'selfie_liveness'
      and coalesce(vr.status, 'pending') = 'approved'
  )
  into v_method_already_approved;

  if v_method_already_approved
     and not (
       coalesce(v_refresh_required, false)
       and 2 >= least(greatest(coalesce(v_refresh_target_level, 1), 1), 2)
     ) then
    raise exception 'profile already has this verification method';
  end if;

  v_document_path := nullif(btrim(coalesce(p_document_path, '')), '');
  if v_document_path is null then
    raise exception 'document path required';
  end if;

  v_reference_asset_path := nullif(btrim(coalesce(p_reference_asset_path, '')), '');

  return query
  with pending as (
    select
      vr.id as request_id,
      coalesce(vr.status, 'pending') as status,
      coalesce(vr.created_at, vr.submitted_at, timezone('utc'::text, now())) as created_at
    from public.verification_requests vr
    where vr.profile_id = p_profile_id
      and vr.verification_type = 'selfie_liveness'
      and coalesce(vr.status, 'pending') = 'pending'
    order by vr.created_at desc nulls last, vr.id desc
    limit 1
  ),
  inserted as (
    insert into public.verification_requests (
      user_id,
      profile_id,
      verification_type,
      document_url,
      status,
      auto_verification_score,
      auto_verification_data
    )
    select
      auth.uid(),
      p_profile_id,
      'selfie_liveness',
      v_document_path,
      'pending',
      0.96,
      jsonb_strip_nulls(
        jsonb_build_object(
          'submitted_via', 'rpc_submit_selfie_liveness_verification',
          'capture_mode', nullif(btrim(coalesce(p_capture_mode, '')), ''),
          'challenge_type', nullif(btrim(coalesce(p_challenge_type, '')), ''),
          'reference_asset_path', v_reference_asset_path
        )
      )
    where not exists (select 1 from pending)
    returning *
  )
  select pending.request_id, pending.status, pending.created_at, true
  from pending
  union all
  select
    inserted.id as request_id,
    coalesce(inserted.status, 'pending') as status,
    coalesce(inserted.created_at, inserted.submitted_at, timezone('utc'::text, now())) as created_at,
    false as already_pending
  from inserted;
end;
$$;


ALTER FUNCTION "public"."rpc_submit_selfie_liveness_verification"("p_profile_id" "uuid", "p_document_path" "text", "p_capture_mode" "text", "p_challenge_type" "text", "p_reference_asset_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_sync_moment_comment_reaction"("p_comment_id" "uuid", "p_reaction" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_comment public.moment_comments;
  v_reaction text := lower(nullif(btrim(coalesce(p_reaction, '')), ''));
begin
  if v_user_id is null then
    raise exception 'not_authenticated' using errcode = '42501';
  end if;

  if p_comment_id is null then
    return false;
  end if;

  select *
    into v_comment
  from public.moment_comments
  where id = p_comment_id
    and is_deleted = false;

  if v_comment.id is null then
    return false;
  end if;

  if not public.can_view_moment(v_comment.moment_id) then
    return false;
  end if;

  if v_reaction is null then
    delete from public.moment_comment_reactions
    where comment_id = p_comment_id
      and user_id = v_user_id;
    return true;
  end if;

  if v_reaction not in ('heart', 'laugh', 'love', 'fire', 'clap') then
    raise exception 'invalid_reaction';
  end if;

  insert into public.moment_comment_reactions (
    comment_id,
    moment_id,
    user_id,
    reaction
  )
  values (
    v_comment.id,
    v_comment.moment_id,
    v_user_id,
    v_reaction
  )
  on conflict (comment_id, user_id)
  do update set
    reaction = excluded.reaction,
    created_at = now();

  return true;
end;
$$;


ALTER FUNCTION "public"."rpc_sync_moment_comment_reaction"("p_comment_id" "uuid", "p_reaction" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_sync_moment_reaction"("p_moment_id" "uuid", "p_emoji" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_emoji text := nullif(btrim(coalesce(p_emoji, '')), '');
begin
  if v_user_id is null then
    raise exception 'not_authenticated' using errcode = '42501';
  end if;

  if p_moment_id is null then
    return false;
  end if;

  if not public.can_view_moment(p_moment_id) then
    return false;
  end if;

  if v_emoji is null then
    delete from public.moment_reactions
    where moment_id = p_moment_id
      and user_id = v_user_id;
    return true;
  end if;

  insert into public.moment_reactions (moment_id, user_id, emoji)
  values (p_moment_id, v_user_id, v_emoji)
  on conflict (moment_id, user_id)
  do update set emoji = excluded.emoji;

  return true;
end;
$$;


ALTER FUNCTION "public"."rpc_sync_moment_reaction"("p_moment_id" "uuid", "p_emoji" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_toggle_circle_pulse_comment_reaction"("p_comment_id" "uuid", "p_profile_id" "uuid", "p_reaction" "text" DEFAULT 'heart'::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_comment public.circle_pulse_comments%rowtype;
  v_reaction text := lower(nullif(btrim(coalesce(p_reaction, '')), ''));
  v_existing_reaction text;
  v_reacted boolean := false;
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_profile_id
      and p.user_id = auth.uid()
      and p.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  if v_reaction is null or v_reaction not in ('heart', 'laugh', 'love', 'thumbs_up', 'fire', 'clap') then
    raise exception 'invalid_reaction';
  end if;

  select *
    into v_comment
  from public.circle_pulse_comments cpc
  where cpc.id = p_comment_id
    and cpc.status = 'active'
  for update;

  if v_comment.id is null then
    raise exception 'comment_not_found';
  end if;

  if not public.is_circle_member(v_comment.circle_id, auth.uid())
    and not public.is_circle_owner(v_comment.circle_id, auth.uid()) then
    raise exception 'circle_membership_required' using errcode = '42501';
  end if;

  select cpcr.reaction
    into v_existing_reaction
  from public.circle_pulse_comment_reactions cpcr
  where cpcr.comment_id = p_comment_id
    and cpcr.profile_id = p_profile_id
  limit 1;

  if v_existing_reaction = v_reaction then
    delete from public.circle_pulse_comment_reactions
    where comment_id = p_comment_id
      and profile_id = p_profile_id;
  else
    insert into public.circle_pulse_comment_reactions (
      circle_id,
      pulse_item_id,
      comment_id,
      profile_id,
      user_id,
      reaction
    )
    values (
      v_comment.circle_id,
      v_comment.pulse_item_id,
      v_comment.id,
      p_profile_id,
      auth.uid(),
      v_reaction
    )
    on conflict (comment_id, profile_id)
    do update set reaction = excluded.reaction;

    v_reacted := true;
  end if;

  update public.circle_pulse_comments cpc
  set reaction_count = (
    select count(*)::integer
    from public.circle_pulse_comment_reactions cpcr
    where cpcr.comment_id = p_comment_id
  )
  where cpc.id = p_comment_id;

  return v_reacted;
end;
$$;


ALTER FUNCTION "public"."rpc_toggle_circle_pulse_comment_reaction"("p_comment_id" "uuid", "p_profile_id" "uuid", "p_reaction" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_update_circle_image"("p_circle_id" "uuid", "p_actor_profile_id" "uuid", "p_image_path" "text") RETURNS "public"."circles"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_circle public.circles%rowtype;
  v_image_path text := nullif(btrim(coalesce(p_image_path, '')), '');
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if v_image_path is null or split_part(v_image_path, '/', 1) <> p_circle_id::text then
    raise exception 'invalid_circle_image_path';
  end if;

  if not exists (
    select 1
    from public.profiles actor
    where actor.id = p_actor_profile_id
      and actor.user_id = auth.uid()
      and actor.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  update public.circles circle_row
  set image_path = v_image_path,
      image_updated_at = timezone('utc'::text, now()),
      updated_at = timezone('utc'::text, now())
  where circle_row.id = p_circle_id
    and (
      circle_row.created_by_profile_id = p_actor_profile_id
      or public.is_admin_user(auth.uid())
    )
  returning circle_row.* into v_circle;

  if v_circle.id is null then
    raise exception 'circle_creator_required' using errcode = '42501';
  end if;

  return v_circle;
end;
$$;


ALTER FUNCTION "public"."rpc_update_circle_image"("p_circle_id" "uuid", "p_actor_profile_id" "uuid", "p_image_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_update_circle_name"("p_circle_id" "uuid", "p_actor_profile_id" "uuid", "p_name" "text") RETURNS "public"."circles"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    SET "row_security" TO 'off'
    AS $$
declare
  v_circle public.circles%rowtype;
  v_name text := nullif(btrim(coalesce(p_name, '')), '');
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if v_name is null or char_length(v_name) not between 3 and 80 then
    raise exception 'invalid_name';
  end if;

  if not exists (
    select 1
    from public.profiles actor
    where actor.id = p_actor_profile_id
      and actor.user_id = auth.uid()
      and actor.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  update public.circles circle_row
  set name = v_name,
      updated_at = timezone('utc'::text, now())
  where circle_row.id = p_circle_id
    and (
      circle_row.created_by_profile_id = p_actor_profile_id
      or public.is_admin_user(auth.uid())
    )
  returning circle_row.* into v_circle;

  if v_circle.id is null then
    raise exception 'circle_creator_required' using errcode = '42501';
  end if;

  return v_circle;
end;
$$;


ALTER FUNCTION "public"."rpc_update_circle_name"("p_circle_id" "uuid", "p_actor_profile_id" "uuid", "p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_update_circle_prompt"("p_prompt_id" "uuid", "p_circle_id" "uuid", "p_title" "text", "p_prompt" "text", "p_prompt_type" "text" DEFAULT 'host'::"text", "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "public"."circle_prompts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_profile public.profiles%rowtype;
  v_prompt public.circle_prompts%rowtype;
  v_circle public.circles%rowtype;
  v_title text := nullif(btrim(coalesce(p_title, '')), '');
  v_body text := nullif(btrim(coalesce(p_prompt, '')), '');
  v_is_admin boolean := false;
  v_can_publish boolean := false;
begin
  if v_user_id is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if p_prompt_id is null or p_circle_id is null then
    raise exception 'prompt_not_found';
  end if;

  if v_title is null or char_length(v_title) < 3 or char_length(v_title) > 120 then
    raise exception 'invalid_title';
  end if;

  if v_body is null or char_length(v_body) < 3 or char_length(v_body) > 500 then
    raise exception 'invalid_prompt';
  end if;

  if coalesce(p_prompt_type, 'host') not in ('daily', 'weekly', 'featured', 'host') then
    raise exception 'invalid_prompt_type';
  end if;

  select *
    into v_profile
  from public.profiles p
  where p.user_id = v_user_id
    and p.deleted_at is null
  limit 1;

  if v_profile.id is null then
    raise exception 'profile_not_found';
  end if;

  select *
    into v_circle
  from public.circles c
  where c.id = p_circle_id
    and c.archived_at is null
  limit 1;

  if v_circle.id is null or v_circle.status <> 'approved' then
    raise exception 'circle_not_found';
  end if;

  select *
    into v_prompt
  from public.circle_prompts cp
  where cp.id = p_prompt_id
    and cp.circle_id = p_circle_id
    and cp.status <> 'archived'
  for update;

  if v_prompt.id is null then
    raise exception 'prompt_not_found';
  end if;

  v_is_admin := public.is_admin_user(v_user_id);
  v_can_publish := v_is_admin
    or public.is_circle_owner(p_circle_id, v_user_id)
    or public.is_circle_host(p_circle_id, v_profile.id);

  if not v_can_publish then
    raise exception 'host_required' using errcode = '42501';
  end if;

  if p_expires_at is not null and p_expires_at <= timezone('utc'::text, now()) then
    raise exception 'invalid_expiry';
  end if;

  update public.circle_prompts
  set title = v_title,
      prompt = v_body,
      prompt_type = coalesce(p_prompt_type, 'host'),
      expires_at = p_expires_at,
      updated_at = timezone('utc'::text, now())
  where id = p_prompt_id
  returning * into v_prompt;

  return v_prompt;
end;
$$;


ALTER FUNCTION "public"."rpc_update_circle_prompt"("p_prompt_id" "uuid", "p_circle_id" "uuid", "p_title" "text", "p_prompt" "text", "p_prompt_type" "text", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_update_circle_pulse_comment"("p_comment_id" "uuid", "p_profile_id" "uuid", "p_body" "text") RETURNS TABLE("id" "uuid", "pulse_item_id" "uuid", "circle_id" "uuid", "profile_id" "uuid", "display_name" "text", "avatar_url" "text", "body" "text", "parent_comment_id" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "edited_at" timestamp with time zone, "is_own" boolean, "can_remove" boolean, "can_edit" boolean, "can_pin" boolean, "pinned_at" timestamp with time zone, "report_count" integer, "reaction_count" integer, "my_reaction" "text", "reply_preview_profile_id" "uuid", "reply_preview_display_name" "text", "reply_preview_body" "text", "reaction_summary" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_comment public.circle_pulse_comments%rowtype;
  v_body text := nullif(btrim(coalesce(p_body, '')), '');
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_profile_id
      and p.user_id = auth.uid()
      and p.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  if v_body is null or char_length(v_body) > 500 then
    raise exception 'invalid_comment';
  end if;

  select *
    into v_comment
  from public.circle_pulse_comments cpc
  where cpc.id = p_comment_id
    and cpc.status = 'active'
  for update;

  if v_comment.id is null then
    raise exception 'comment_not_found';
  end if;

  if v_comment.profile_id <> p_profile_id or v_comment.user_id <> auth.uid() then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  if v_body = v_comment.body then
    return query
    select *
    from public.rpc_get_circle_pulse_comment_snapshot(v_comment.id);
    return;
  end if;

  insert into public.circle_pulse_comment_edits (
    comment_id,
    editor_profile_id,
    editor_user_id,
    previous_body
  )
  values (
    v_comment.id,
    p_profile_id,
    auth.uid(),
    v_comment.body
  );

  update public.circle_pulse_comments as cpc
  set body = v_body,
      edited_at = timezone('utc'::text, now())
  where cpc.id = v_comment.id;

  return query
  select *
  from public.rpc_get_circle_pulse_comment_snapshot(v_comment.id);
end;
$$;


ALTER FUNCTION "public"."rpc_update_circle_pulse_comment"("p_comment_id" "uuid", "p_profile_id" "uuid", "p_body" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_update_circle_relationship_gist"("p_gist_id" "uuid", "p_circle_id" "uuid", "p_actor_profile_id" "uuid", "p_title" "text", "p_short_body" "text", "p_body" "text", "p_perspective" "text" DEFAULT 'general'::"text") RETURNS "public"."relationship_gists"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_gist public.relationship_gists%rowtype;
  v_title text := nullif(btrim(coalesce(p_title, '')), '');
  v_short_body text := nullif(btrim(coalesce(p_short_body, '')), '');
  v_body text := nullif(btrim(coalesce(p_body, '')), '');
  v_perspective text := lower(nullif(btrim(coalesce(p_perspective, '')), ''));
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles actor
    where actor.id = p_actor_profile_id
      and actor.user_id = auth.uid()
      and actor.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  if not public.can_manage_circle_pulse(p_circle_id, auth.uid()) then
    raise exception 'host_required' using errcode = '42501';
  end if;

  if v_title is null or char_length(v_title) not between 3 and 140 then
    raise exception 'gist_title_invalid';
  end if;

  if v_body is null or char_length(v_body) not between 20 and 5000 then
    raise exception 'gist_body_invalid';
  end if;

  if v_perspective not in ('general', 'christian', 'muslim', 'culture', 'safety', 'communication') then
    raise exception 'gist_perspective_invalid';
  end if;

  update public.relationship_gists
  set title = v_title,
      short_body = v_short_body,
      body = v_body,
      perspective = v_perspective,
      status = 'published',
      published_at = coalesce(published_at, timezone('utc'::text, now())),
      updated_at = timezone('utc'::text, now())
  where id = p_gist_id
    and circle_id = p_circle_id
    and status <> 'archived'
  returning * into v_gist;

  if v_gist.id is null then
    raise exception 'gist_not_found';
  end if;

  return v_gist;
end;
$$;


ALTER FUNCTION "public"."rpc_update_circle_relationship_gist"("p_gist_id" "uuid", "p_circle_id" "uuid", "p_actor_profile_id" "uuid", "p_title" "text", "p_short_body" "text", "p_body" "text", "p_perspective" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_update_circle_request"("p_circle_id" "uuid", "p_name" "text", "p_description" "text" DEFAULT NULL::"text", "p_short_description" "text" DEFAULT NULL::"text", "p_circle_type" "text" DEFAULT 'gold_community'::"text", "p_visibility_scope" "text" DEFAULT 'country'::"text", "p_country_code" "text" DEFAULT NULL::"text", "p_country_name" "text" DEFAULT NULL::"text", "p_region" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_diaspora_tags" "text"[] DEFAULT '{}'::"text"[], "p_culture_tags" "text"[] DEFAULT '{}'::"text"[], "p_faith_tags" "text"[] DEFAULT '{}'::"text"[], "p_interest_tags" "text"[] DEFAULT '{}'::"text"[], "p_audience_tags" "text"[] DEFAULT '{}'::"text"[], "p_requires_join_approval" boolean DEFAULT false, "p_rules" "text" DEFAULT NULL::"text") RETURNS "public"."circles"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_profile public.profiles%rowtype;
  v_is_admin boolean;
  v_name text := nullif(btrim(coalesce(p_name, '')), '');
  v_circle public.circles%rowtype;
  v_slug_base text;
  v_slug text;
  v_status text;
begin
  if v_user_id is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if p_circle_id is null then
    raise exception 'circle_not_found';
  end if;

  if v_name is null or char_length(v_name) < 3 or char_length(v_name) > 80 then
    raise exception 'invalid_name';
  end if;

  if p_visibility_scope not in ('local', 'country', 'diaspora', 'global', 'invite_only') then
    raise exception 'invalid_visibility';
  end if;

  select *
    into v_profile
  from public.profiles p
  where p.user_id = v_user_id
    and p.deleted_at is null
  limit 1;

  if v_profile.id is null then
    raise exception 'profile_not_found';
  end if;

  v_is_admin := public.is_admin_user(v_user_id);

  if not v_is_admin and not public.has_gold_entitlement(v_user_id, v_profile.id) then
    raise exception 'gold_required' using errcode = '42501';
  end if;

  select *
    into v_circle
  from public.circles c
  where c.id = p_circle_id
    and c.archived_at is null
    and (
      v_is_admin
      or c.created_by_user_id = v_user_id
      or c.created_by_profile_id = v_profile.id
    )
  for update;

  if v_circle.id is null then
    raise exception 'circle_not_found';
  end if;

  if not v_is_admin and v_circle.status not in ('draft', 'pending_review', 'rejected', 'approved') then
    raise exception 'circle_not_editable';
  end if;

  if not v_is_admin and coalesce(p_circle_type, 'gold_community') not in ('gold_community', 'community', 'private') then
    raise exception 'invalid_circle_type';
  end if;

  v_slug_base := public.slugify(v_name);
  v_slug := case
    when v_circle.slug is null or public.slugify(coalesce(v_circle.name, '')) <> v_slug_base then v_slug_base
    else v_circle.slug
  end;

  if exists (
    select 1
    from public.circles c
    where c.id <> p_circle_id
      and c.status = 'approved'
      and public.slugify(c.name) = v_slug_base
      and coalesce(upper(c.country_code), '') = coalesce(upper(p_country_code), '')
      and coalesce(lower(c.city), '') = coalesce(lower(p_city), '')
      and c.archived_at is null
  ) then
    raise exception 'duplicate_circle';
  end if;

  while exists (
    select 1
    from public.circles c
    where c.id <> p_circle_id
      and c.slug = v_slug
  ) loop
    v_slug := v_slug_base || '-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 6);
  end loop;

  v_status := case when v_is_admin then 'approved' else 'pending_review' end;

  update public.circles
  set name = v_name,
      slug = v_slug,
      description = nullif(btrim(coalesce(p_description, '')), ''),
      short_description = nullif(btrim(coalesce(p_short_description, '')), ''),
      visibility = case when p_visibility_scope = 'invite_only' or p_circle_type = 'private' then 'private' else 'public' end,
      circle_type = case
        when v_is_admin then coalesce(nullif(p_circle_type, ''), v_circle.circle_type, 'official')
        when p_circle_type = 'private' then 'private'
        else 'gold_community'
      end,
      status = v_status,
      visibility_scope = p_visibility_scope,
      country_code = upper(nullif(btrim(coalesce(p_country_code, '')), '')),
      country_name = nullif(btrim(coalesce(p_country_name, '')), ''),
      region = nullif(btrim(coalesce(p_region, '')), ''),
      city = nullif(btrim(coalesce(p_city, '')), ''),
      diaspora_tags = coalesce(p_diaspora_tags, '{}'),
      culture_tags = coalesce(p_culture_tags, '{}'),
      faith_tags = coalesce(p_faith_tags, '{}'),
      interest_tags = coalesce(p_interest_tags, '{}'),
      audience_tags = coalesce(p_audience_tags, '{}'),
      is_official = v_is_admin and coalesce(p_circle_type, 'official') = 'official',
      is_partner = v_is_admin and coalesce(p_circle_type, '') = 'partner',
      requires_join_approval = coalesce(p_requires_join_approval, false),
      rejected_reason = null,
      approved_by_admin_id = case when v_is_admin then v_user_id else null end,
      approved_at = case when v_is_admin then timezone('utc'::text, now()) else null end,
      rules = nullif(btrim(coalesce(p_rules, '')), ''),
      updated_at = timezone('utc'::text, now())
  where id = p_circle_id
  returning * into v_circle;

  return v_circle;
end;
$$;


ALTER FUNCTION "public"."rpc_update_circle_request"("p_circle_id" "uuid", "p_name" "text", "p_description" "text", "p_short_description" "text", "p_circle_type" "text", "p_visibility_scope" "text", "p_country_code" "text", "p_country_name" "text", "p_region" "text", "p_city" "text", "p_diaspora_tags" "text"[], "p_culture_tags" "text"[], "p_faith_tags" "text"[], "p_interest_tags" "text"[], "p_audience_tags" "text"[], "p_requires_join_approval" boolean, "p_rules" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_update_gathering_request"("p_gathering_id" "uuid", "p_circle_id" "uuid" DEFAULT NULL::"uuid", "p_title" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_gathering_type" "text" DEFAULT 'physical'::"text", "p_country_code" "text" DEFAULT NULL::"text", "p_country_name" "text" DEFAULT NULL::"text", "p_region" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_venue_name" "text" DEFAULT NULL::"text", "p_venue_address" "text" DEFAULT NULL::"text", "p_address_visibility" "text" DEFAULT 'attendees_only'::"text", "p_online_url" "text" DEFAULT NULL::"text", "p_platform" "text" DEFAULT NULL::"text", "p_starts_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_ends_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_timezone" "text" DEFAULT NULL::"text", "p_max_attendees" integer DEFAULT NULL::integer, "p_tags" "text"[] DEFAULT '{}'::"text"[], "p_safety_note" "text" DEFAULT NULL::"text", "p_poster_url" "text" DEFAULT NULL::"text", "p_presentation_mode" "text" DEFAULT NULL::"text", "p_featured_profile_id" "uuid" DEFAULT NULL::"uuid", "p_seat_context" "text" DEFAULT NULL::"text", "p_host_created_for_member" boolean DEFAULT NULL::boolean) RETURNS "public"."gatherings"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_profile public.profiles%rowtype;
  v_is_admin boolean;
  v_can_manage_circle boolean := false;
  v_title text := nullif(btrim(coalesce(p_title, '')), '');
  v_slug_base text;
  v_slug text;
  v_gathering public.gatherings%rowtype;
  v_target_circle_id uuid;
  v_presentation_mode text;
  v_featured_profile_id uuid;
  v_seat_context text;
begin
  if v_user_id is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if p_gathering_id is null then
    raise exception 'gathering_not_found';
  end if;

  if v_title is null or char_length(v_title) < 3 or char_length(v_title) > 120 then
    raise exception 'invalid_title';
  end if;

  if p_gathering_type not in ('online', 'physical', 'hybrid', 'partner_venue', 'livestream') then
    raise exception 'invalid_gathering_type';
  end if;

  if p_starts_at is null or p_starts_at <= timezone('utc'::text, now()) then
    raise exception 'invalid_start_time';
  end if;

  if p_ends_at is not null and p_ends_at <= p_starts_at then
    raise exception 'invalid_end_time';
  end if;

  select *
    into v_profile
  from public.profiles p
  where p.user_id = v_user_id
    and p.deleted_at is null
  limit 1;

  if v_profile.id is null then
    raise exception 'profile_not_found';
  end if;

  v_is_admin := public.is_admin_user(v_user_id);

  select *
    into v_gathering
  from public.gatherings g
  where g.id = p_gathering_id
    and (
      v_is_admin
      or g.created_by_user_id = v_user_id
      or g.created_by_profile_id = v_profile.id
      or (g.circle_id is not null and public.can_manage_circle_pulse(g.circle_id, v_user_id))
    )
  for update;

  if v_gathering.id is null then
    raise exception 'gathering_not_found';
  end if;

  v_can_manage_circle := v_gathering.circle_id is not null and public.can_manage_circle_pulse(v_gathering.circle_id, v_user_id);

  if not v_is_admin and not v_can_manage_circle and not public.has_gold_entitlement(v_user_id, v_profile.id) then
    raise exception 'gold_required' using errcode = '42501';
  end if;

  if not v_is_admin and v_gathering.status not in ('draft', 'pending_review', 'approved', 'rejected') then
    raise exception 'gathering_not_editable';
  end if;

  v_target_circle_id := coalesce(p_circle_id, v_gathering.circle_id);

  if v_target_circle_id is not null and not exists (
    select 1
    from public.circles c
    where c.id = v_target_circle_id
      and (c.status = 'approved' or c.created_by_user_id = v_user_id or v_is_admin)
  ) then
    raise exception 'circle_not_found';
  end if;

  v_presentation_mode := lower(coalesce(nullif(btrim(coalesce(p_presentation_mode, '')), ''), v_gathering.presentation_mode, 'general'));
  v_seat_context := lower(coalesce(nullif(btrim(coalesce(p_seat_context, '')), ''), v_gathering.seat_context));
  v_featured_profile_id := case
    when p_featured_profile_id is not null then p_featured_profile_id
    else v_gathering.featured_profile_id
  end;

  if v_presentation_mode not in ('general', 'seat_linked') then
    raise exception 'invalid_presentation_mode';
  end if;

  if v_seat_context is not null and v_seat_context not in ('welcome', 'love') then
    raise exception 'invalid_seat_context';
  end if;

  if v_presentation_mode = 'seat_linked' then
    if v_target_circle_id is null or v_featured_profile_id is null then
      raise exception 'invalid_seat_link';
    end if;

    select p.id
      into v_featured_profile_id
    from public.circle_members cm
    join public.profiles p
      on p.id = cm.profile_id
     and p.deleted_at is null
    where cm.circle_id = v_target_circle_id
      and cm.profile_id = v_featured_profile_id
      and cm.status = 'active'
      and cm.is_visible is not false
    limit 1;

    if v_featured_profile_id is null then
      raise exception 'featured_profile_unavailable';
    end if;
  else
    v_featured_profile_id := null;
    v_seat_context := null;
  end if;

  v_slug_base := public.slugify(v_title);
  v_slug := case
    when v_gathering.slug is null or public.slugify(coalesce(v_gathering.title, '')) <> v_slug_base then v_slug_base
    else v_gathering.slug
  end;

  while exists (
    select 1
    from public.gatherings g
    where g.id <> p_gathering_id
      and g.slug = v_slug
  ) loop
    v_slug := v_slug_base || '-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 6);
  end loop;

  update public.gatherings
  set circle_id = v_target_circle_id,
      title = v_title,
      slug = v_slug,
      description = nullif(btrim(coalesce(p_description, '')), ''),
      poster_url = nullif(btrim(coalesce(p_poster_url, '')), ''),
      presentation_mode = v_presentation_mode,
      featured_profile_id = v_featured_profile_id,
      seat_context = v_seat_context,
      host_created_for_member = case when v_presentation_mode = 'seat_linked' then true else false end,
      gathering_type = p_gathering_type,
      status = case
        when v_is_admin then 'approved'
        when v_gathering.status = 'approved' then 'approved'
        else 'pending_review'
      end,
      country_code = upper(nullif(btrim(coalesce(p_country_code, '')), '')),
      country_name = nullif(btrim(coalesce(p_country_name, '')), ''),
      region = nullif(btrim(coalesce(p_region, '')), ''),
      city = nullif(btrim(coalesce(p_city, '')), ''),
      venue_name = nullif(btrim(coalesce(p_venue_name, '')), ''),
      venue_address = nullif(btrim(coalesce(p_venue_address, '')), ''),
      address_visibility = case
        when v_is_admin then coalesce(nullif(p_address_visibility, ''), 'attendees_only')
        when p_gathering_type in ('physical', 'hybrid', 'partner_venue') then 'attendees_only'
        else coalesce(nullif(p_address_visibility, ''), 'hidden')
      end,
      online_url = nullif(btrim(coalesce(p_online_url, '')), ''),
      platform = nullif(btrim(coalesce(p_platform, '')), ''),
      starts_at = p_starts_at,
      ends_at = p_ends_at,
      timezone = p_timezone,
      is_official = v_is_admin,
      is_partner_venue = v_is_admin and p_gathering_type = 'partner_venue',
      safe_first_date_space = case when v_is_admin then v_gathering.safe_first_date_space else false end,
      max_attendees = p_max_attendees,
      approved_by_admin_id = case when v_is_admin then v_user_id else approved_by_admin_id end,
      approved_at = case when v_is_admin then timezone('utc'::text, now()) else approved_at end,
      tags = coalesce(p_tags, '{}'),
      safety_note = nullif(btrim(coalesce(p_safety_note, '')), ''),
      rejected_reason = null,
      updated_at = timezone('utc'::text, now())
  where id = p_gathering_id
  returning * into v_gathering;

  return v_gathering;
end;
$$;


ALTER FUNCTION "public"."rpc_update_gathering_request"("p_gathering_id" "uuid", "p_circle_id" "uuid", "p_title" "text", "p_description" "text", "p_gathering_type" "text", "p_country_code" "text", "p_country_name" "text", "p_region" "text", "p_city" "text", "p_venue_name" "text", "p_venue_address" "text", "p_address_visibility" "text", "p_online_url" "text", "p_platform" "text", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_timezone" "text", "p_max_attendees" integer, "p_tags" "text"[], "p_safety_note" "text", "p_poster_url" "text", "p_presentation_mode" "text", "p_featured_profile_id" "uuid", "p_seat_context" "text", "p_host_created_for_member" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_update_moment_comment"("p_comment_id" "uuid", "p_body" "text") RETURNS "public"."moment_comments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_body text := nullif(btrim(coalesce(p_body, '')), '');
  v_comment public.moment_comments;
begin
  if v_user_id is null then
    raise exception 'not_authenticated' using errcode = '42501';
  end if;

  if p_comment_id is null or v_body is null then
    return null;
  end if;

  update public.moment_comments
  set body = v_body
  where id = p_comment_id
    and user_id = v_user_id
    and is_deleted = false
  returning * into v_comment;

  return v_comment;
end;
$$;


ALTER FUNCTION "public"."rpc_update_moment_comment"("p_comment_id" "uuid", "p_body" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."circle_pulse_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "circle_id" "uuid" NOT NULL,
    "item_type" "text" NOT NULL,
    "prompt_id" "uuid",
    "gathering_id" "uuid",
    "moment_id" "uuid",
    "title" "text",
    "subtitle" "text",
    "body" "text",
    "image_url" "text",
    "media_url" "text",
    "media_type" "text",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "priority" integer DEFAULT 0 NOT NULL,
    "starts_at" timestamp with time zone,
    "expires_at" timestamp with time zone,
    "created_by_profile_id" "uuid",
    "created_by_user_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "love_seat_id" "uuid",
    "comment_count" integer DEFAULT 0 NOT NULL,
    "discussion_cta" "text",
    "discussion_summary" "text",
    CONSTRAINT "circle_pulse_items_body_length" CHECK ((("body" IS NULL) OR ("char_length"("btrim"("body")) <= 2000))),
    CONSTRAINT "circle_pulse_items_comment_count_valid" CHECK (("comment_count" >= 0)),
    CONSTRAINT "circle_pulse_items_media_type_valid" CHECK ((("media_type" IS NULL) OR ("media_type" = ANY (ARRAY['image'::"text", 'video'::"text", 'audio'::"text"])))),
    CONSTRAINT "circle_pulse_items_source_valid" CHECK (((("item_type" = 'prompt'::"text") AND ("prompt_id" IS NOT NULL) AND ("gathering_id" IS NULL) AND ("moment_id" IS NULL) AND ("love_seat_id" IS NULL)) OR (("item_type" = 'gathering'::"text") AND ("gathering_id" IS NOT NULL) AND ("prompt_id" IS NULL) AND ("moment_id" IS NULL) AND ("love_seat_id" IS NULL)) OR (("item_type" = 'host_note'::"text") AND ("prompt_id" IS NULL) AND ("gathering_id" IS NULL) AND ("moment_id" IS NULL) AND ("love_seat_id" IS NULL) AND (NULLIF("btrim"(COALESCE("body", ''::"text")), ''::"text") IS NOT NULL)) OR (("item_type" = 'media'::"text") AND ("prompt_id" IS NULL) AND ("gathering_id" IS NULL) AND ("love_seat_id" IS NULL) AND (("moment_id" IS NOT NULL) OR (NULLIF("btrim"(COALESCE("media_url", ''::"text")), ''::"text") IS NOT NULL))) OR (("item_type" = 'love_seat'::"text") AND ("love_seat_id" IS NOT NULL) AND ("prompt_id" IS NULL) AND ("gathering_id" IS NULL) AND ("moment_id" IS NULL)) OR (("item_type" = 'welcome'::"text") AND ("prompt_id" IS NULL) AND ("gathering_id" IS NULL) AND ("moment_id" IS NULL) AND ("love_seat_id" IS NULL)))),
    CONSTRAINT "circle_pulse_items_status_valid" CHECK (("status" = ANY (ARRAY['draft'::"text", 'active'::"text", 'expired'::"text", 'archived'::"text"]))),
    CONSTRAINT "circle_pulse_items_subtitle_length" CHECK ((("subtitle" IS NULL) OR ("char_length"("btrim"("subtitle")) <= 240))),
    CONSTRAINT "circle_pulse_items_time_valid" CHECK ((("expires_at" IS NULL) OR ("starts_at" IS NULL) OR ("expires_at" > "starts_at"))),
    CONSTRAINT "circle_pulse_items_title_length" CHECK ((("title" IS NULL) OR (("char_length"("btrim"("title")) >= 1) AND ("char_length"("btrim"("title")) <= 140)))),
    CONSTRAINT "circle_pulse_items_type_valid" CHECK (("item_type" = ANY (ARRAY['prompt'::"text", 'gathering'::"text", 'host_note'::"text", 'media'::"text", 'love_seat'::"text", 'welcome'::"text"])))
);


ALTER TABLE "public"."circle_pulse_items" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_upsert_circle_pulse_item"("p_circle_id" "uuid", "p_actor_profile_id" "uuid", "p_item_type" "text", "p_item_id" "uuid" DEFAULT NULL::"uuid", "p_prompt_id" "uuid" DEFAULT NULL::"uuid", "p_gathering_id" "uuid" DEFAULT NULL::"uuid", "p_moment_id" "uuid" DEFAULT NULL::"uuid", "p_title" "text" DEFAULT NULL::"text", "p_subtitle" "text" DEFAULT NULL::"text", "p_body" "text" DEFAULT NULL::"text", "p_image_url" "text" DEFAULT NULL::"text", "p_media_url" "text" DEFAULT NULL::"text", "p_media_type" "text" DEFAULT NULL::"text", "p_priority" integer DEFAULT 0, "p_starts_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_status" "text" DEFAULT 'active'::"text") RETURNS "public"."circle_pulse_items"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_item public.circle_pulse_items%rowtype;
  v_circle public.circles%rowtype;
  v_item_type text := lower(coalesce(p_item_type, ''));
  v_status text := lower(coalesce(p_status, 'active'));
  v_title text := nullif(btrim(coalesce(p_title, '')), '');
  v_subtitle text := nullif(btrim(coalesce(p_subtitle, '')), '');
  v_body text := nullif(btrim(coalesce(p_body, '')), '');
  v_image_url text := nullif(btrim(coalesce(p_image_url, '')), '');
  v_media_url text := nullif(btrim(coalesce(p_media_url, '')), '');
  v_media_type text := nullif(lower(btrim(coalesce(p_media_type, ''))), '');
  v_source_available boolean := false;
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_actor_profile_id
      and p.user_id = auth.uid()
      and p.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  if not public.can_manage_circle_pulse(p_circle_id, auth.uid()) then
    raise exception 'host_required' using errcode = '42501';
  end if;

  select *
    into v_circle
  from public.circles c
  where c.id = p_circle_id
    and c.archived_at is null
  limit 1;

  if v_circle.id is null then
    raise exception 'circle_not_found';
  end if;

  if v_item_type not in ('prompt', 'gathering', 'host_note', 'media') then
    raise exception 'invalid_item_type';
  end if;

  if v_status not in ('draft', 'active', 'expired', 'archived') then
    raise exception 'invalid_status';
  end if;

  if p_expires_at is not null and p_starts_at is not null and p_expires_at <= p_starts_at then
    raise exception 'invalid_expiry';
  end if;

  if v_item_type = 'prompt' then
    select exists (
      select 1
      from public.circle_prompts cp
      where cp.id = p_prompt_id
        and cp.circle_id = p_circle_id
        and (
          v_status <> 'active'
          or (
            cp.status = 'published'
            and (cp.starts_at is null or cp.starts_at <= timezone('utc'::text, now()))
            and (cp.expires_at is null or cp.expires_at > timezone('utc'::text, now()))
          )
        )
    ) into v_source_available;
  elsif v_item_type = 'gathering' then
    select exists (
      select 1
      from public.gatherings g
      where g.id = p_gathering_id
        and g.circle_id = p_circle_id
        and (
          v_status <> 'active'
          or (
            g.status = 'approved'
            and g.cancelled_at is null
            and g.starts_at > timezone('utc'::text, now())
          )
        )
    ) into v_source_available;
  elsif v_item_type = 'host_note' then
    v_title := coalesce(v_title, 'Host note');
    v_body := coalesce(v_body, nullif(btrim(coalesce(v_circle.host_note, '')), ''));
    v_source_available := v_body is not null;
  else
    if v_media_type is not null and v_media_type not in ('image', 'video', 'audio') then
      raise exception 'invalid_media_type';
    end if;

    if v_media_url is not null then
      v_source_available := v_media_type in ('image', 'video', 'audio');
    elsif p_moment_id is not null then
      select exists (
        select 1
        from public.moments m
        where m.id = p_moment_id
          and m.is_deleted = false
          and m.expires_at > timezone('utc'::text, now())
          and nullif(btrim(coalesce(m.media_url, '')), '') is not null
          and public.can_view_moment(m.id)
      ) into v_source_available;
    end if;
  end if;

  if not v_source_available then
    raise exception 'pulse_source_unavailable';
  end if;

  if p_item_id is null then
    insert into public.circle_pulse_items (
      circle_id,
      item_type,
      prompt_id,
      gathering_id,
      moment_id,
      title,
      subtitle,
      body,
      image_url,
      media_url,
      media_type,
      status,
      priority,
      starts_at,
      expires_at,
      created_by_profile_id,
      created_by_user_id
    )
    values (
      p_circle_id,
      v_item_type,
      case when v_item_type = 'prompt' then p_prompt_id else null end,
      case when v_item_type = 'gathering' then p_gathering_id else null end,
      case when v_item_type = 'media' then p_moment_id else null end,
      v_title,
      v_subtitle,
      v_body,
      v_image_url,
      v_media_url,
      v_media_type,
      v_status,
      coalesce(p_priority, 0),
      p_starts_at,
      p_expires_at,
      p_actor_profile_id,
      auth.uid()
    )
    returning * into v_item;
  else
    update public.circle_pulse_items cpi
    set item_type = v_item_type,
        prompt_id = case when v_item_type = 'prompt' then p_prompt_id else null end,
        gathering_id = case when v_item_type = 'gathering' then p_gathering_id else null end,
        moment_id = case when v_item_type = 'media' then p_moment_id else null end,
        title = v_title,
        subtitle = v_subtitle,
        body = v_body,
        image_url = v_image_url,
        media_url = v_media_url,
        media_type = v_media_type,
        status = v_status,
        priority = coalesce(p_priority, 0),
        starts_at = p_starts_at,
        expires_at = p_expires_at
    where cpi.id = p_item_id
      and cpi.circle_id = p_circle_id
    returning * into v_item;

    if v_item.id is null then
      raise exception 'pulse_item_not_found';
    end if;
  end if;

  return v_item;
end;
$$;


ALTER FUNCTION "public"."rpc_upsert_circle_pulse_item"("p_circle_id" "uuid", "p_actor_profile_id" "uuid", "p_item_type" "text", "p_item_id" "uuid", "p_prompt_id" "uuid", "p_gathering_id" "uuid", "p_moment_id" "uuid", "p_title" "text", "p_subtitle" "text", "p_body" "text", "p_image_url" "text", "p_media_url" "text", "p_media_type" "text", "p_priority" integer, "p_starts_at" timestamp with time zone, "p_expires_at" timestamp with time zone, "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_upsert_profile_signal"("p_profile_id" "uuid", "p_target_profile_id" "uuid", "p_opened_delta" integer DEFAULT 0, "p_liked" boolean DEFAULT NULL::boolean, "p_intro_video_started" boolean DEFAULT NULL::boolean, "p_intro_video_completed" boolean DEFAULT NULL::boolean, "p_dwell_delta" integer DEFAULT 0) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_owner uuid;
  v_id uuid;
  v_opened_delta int := greatest(coalesce(p_opened_delta, 0), 0);
  v_dwell_delta int := greatest(coalesce(p_dwell_delta, 0), 0);
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  select user_id into v_owner
  from public.profiles
  where id = p_profile_id
  limit 1;

  if v_owner is null or v_owner <> auth.uid() then
    raise exception 'Not authorized';
  end if;

  if p_profile_id = p_target_profile_id then
    raise exception 'Cannot signal self';
  end if;

  if not exists (select 1 from public.profiles where id = p_target_profile_id) then
    raise exception 'Target not found';
  end if;

  insert into public.profile_signals (
    profile_id,
    target_profile_id,
    opened_profile_count,
    liked,
    intro_video_started,
    intro_video_completed,
    dwell_score,
    last_interacted_at
  )
  values (
    p_profile_id,
    p_target_profile_id,
    v_opened_delta,
    coalesce(p_liked, false),
    coalesce(p_intro_video_started, false),
    coalesce(p_intro_video_completed, false),
    least(100, v_dwell_delta),
    now()
  )
  on conflict (profile_id, target_profile_id) do update
  set opened_profile_count = public.profile_signals.opened_profile_count + v_opened_delta,
      liked = public.profile_signals.liked or coalesce(p_liked, false),
      intro_video_started = public.profile_signals.intro_video_started or coalesce(p_intro_video_started, false),
      intro_video_completed = public.profile_signals.intro_video_completed or coalesce(p_intro_video_completed, false),
      dwell_score = least(100, public.profile_signals.dwell_score + v_dwell_delta),
      last_interacted_at = now()
  returning id into v_id;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."rpc_upsert_profile_signal"("p_profile_id" "uuid", "p_target_profile_id" "uuid", "p_opened_delta" integer, "p_liked" boolean, "p_intro_video_started" boolean, "p_intro_video_completed" boolean, "p_dwell_delta" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_upsert_relationship_gist_editorial"("p_gist_id" "uuid" DEFAULT NULL::"uuid", "p_actor_profile_id" "uuid" DEFAULT NULL::"uuid", "p_title" "text" DEFAULT NULL::"text", "p_short_body" "text" DEFAULT NULL::"text", "p_body" "text" DEFAULT NULL::"text", "p_perspective" "text" DEFAULT 'general'::"text", "p_status" "text" DEFAULT 'draft'::"text") RETURNS "public"."relationship_gists"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_gist public.relationship_gists%rowtype;
  v_now timestamptz := timezone('utc'::text, now());
  v_title text := nullif(btrim(coalesce(p_title, '')), '');
  v_short_body text := nullif(btrim(coalesce(p_short_body, '')), '');
  v_body text := nullif(btrim(coalesce(p_body, '')), '');
  v_perspective text := lower(nullif(btrim(coalesce(p_perspective, '')), ''));
  v_status text := lower(nullif(btrim(coalesce(p_status, '')), ''));
begin
  if auth.uid() is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not public.is_admin_user(auth.uid()) then
    raise exception 'admin access required' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles actor
    where actor.id = p_actor_profile_id
      and actor.user_id = auth.uid()
      and actor.deleted_at is null
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  if v_title is null or char_length(v_title) not between 3 and 140 then
    raise exception 'gist_title_invalid';
  end if;

  if v_body is null or char_length(v_body) not between 20 and 5000 then
    raise exception 'gist_body_invalid';
  end if;

  if v_perspective not in ('general', 'christian', 'muslim', 'culture', 'safety', 'communication') then
    raise exception 'gist_perspective_invalid';
  end if;

  if v_status not in ('draft', 'published') then
    raise exception 'gist_status_invalid';
  end if;

  if p_gist_id is null then
    insert into public.relationship_gists (
      circle_id,
      title,
      short_body,
      body,
      perspective,
      status,
      created_by_profile_id,
      created_by_admin_id,
      published_at,
      scheduled_for
    )
    values (
      null,
      v_title,
      v_short_body,
      v_body,
      v_perspective,
      v_status,
      p_actor_profile_id,
      auth.uid(),
      case when v_status = 'published' then v_now else null end,
      null
    )
    returning * into v_gist;

    return v_gist;
  end if;

  update public.relationship_gists
  set circle_id = null,
      title = v_title,
      short_body = v_short_body,
      body = v_body,
      perspective = v_perspective,
      status = v_status,
      created_by_profile_id = p_actor_profile_id,
      created_by_admin_id = auth.uid(),
      published_at = case when v_status = 'published' then coalesce(published_at, v_now) else null end,
      scheduled_for = null,
      updated_at = v_now
  where id = p_gist_id
    and status <> 'archived'
  returning * into v_gist;

  if v_gist.id is null then
    raise exception 'gist_not_found';
  end if;

  return v_gist;
end;
$$;


ALTER FUNCTION "public"."rpc_upsert_relationship_gist_editorial"("p_gist_id" "uuid", "p_actor_profile_id" "uuid", "p_title" "text", "p_short_body" "text", "p_body" "text", "p_perspective" "text", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_ghana_localities"("p_region" "text" DEFAULT NULL::"text", "p_query" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 40) RETURNS TABLE("geoname_id" bigint, "name" "text", "region" "text", "district" "text", "population" bigint, "latitude" double precision, "longitude" double precision, "feature_code" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  with input as (
    select
      nullif(regexp_replace(lower(btrim(coalesce(p_region, ''))), '\s+', ' ', 'g'), '') as region_query,
      nullif(regexp_replace(lower(btrim(regexp_replace(coalesce(p_query, ''), '[^a-zA-Z0-9\s-]+', ' ', 'g'))), '\s+', ' ', 'g'), '') as query_norm,
      greatest(1, least(coalesce(p_limit, 40), 120)) as limit_value
  ),
  tokens as (
    select
      input.region_query,
      input.query_norm,
      array_remove(regexp_split_to_array(coalesce(input.query_norm, ''), '\s+'), '') as query_tokens,
      input.limit_value
    from input
  ),
  ranked as (
    select
      locality.geoname_id,
      locality.name,
      locality.region,
      locality.district,
      locality.population,
      locality.latitude,
      locality.longitude,
      locality.feature_code,
      locality.rank_weight,
      case
        when tokenized.query_norm is null then locality.rank_weight
        else (
          case
            when locality.normalized_name = tokenized.query_norm then 900
            when tokenized.query_norm = any(locality.normalized_aliases) then 860
            when locality.normalized_name like tokenized.query_norm || '%' then 780
            when exists (
              select 1
              from unnest(locality.normalized_aliases) alias_value
              where alias_value like tokenized.query_norm || '%'
            ) then 740
            when locality.search_text like '%' || tokenized.query_norm || '%' then 620
            when not exists (
              select 1
              from unnest(tokenized.query_tokens) token
              where token <> '' and locality.search_text not like '%' || token || '%'
            ) then 540
            else -100000
          end + locality.rank_weight
        )
      end as search_score,
      tokenized.limit_value
    from public.ghana_localities locality
    cross join tokens tokenized
    where (tokenized.region_query is null or locality.normalized_region = tokenized.region_query)
      and (
        tokenized.query_norm is null
        or locality.normalized_name like '%' || tokenized.query_norm || '%'
        or locality.search_text like '%' || tokenized.query_norm || '%'
        or exists (
          select 1
          from unnest(tokenized.query_tokens) token
          where token <> '' and locality.normalized_name like token || '%'
        )
        or not exists (
          select 1
          from unnest(tokenized.query_tokens) token
          where token <> '' and locality.search_text not like '%' || token || '%'
        )
      )
  )
  select
    ranked.geoname_id,
    ranked.name,
    ranked.region,
    ranked.district,
    ranked.population,
    ranked.latitude,
    ranked.longitude,
    ranked.feature_code
  from ranked
  where ranked.search_score > -100000
  order by
    ranked.search_score desc,
    ranked.rank_weight desc,
    ranked.population desc,
    ranked.name asc,
    ranked.geoname_id asc
  limit (select limit_value from tokens limit 1);
$$;


ALTER FUNCTION "public"."search_ghana_localities"("p_region" "text", "p_query" "text", "p_limit" integer) OWNER TO "postgres";


