CREATE OR REPLACE FUNCTION "public"."trg_close_intents_on_match_accept"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
BEGIN
  -- We close mirrored like intents as soon as a mutual swipe creates a match (often status = PENDING),
  -- and we close *other* request types as soon as a match exists (PENDING or ACCEPTED) to prevent stale
  -- pending requests blocking chat-first flows.
  IF NEW.status IS DISTINCT FROM 'PENDING' AND NEW.status IS DISTINCT FROM 'ACCEPTED' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.status = NEW.status THEN
    RETURN NEW;
  END IF;

  -- Mark mirrored likes as accepted (premium: reciprocity auto-resolves the like card).
  UPDATE public.intent_requests ir
  SET status = 'accepted',
      metadata = ir.metadata || jsonb_build_object('auto_closed_by', 'match', 'match_id', NEW.id)
  WHERE ir.status = 'pending'
    AND ir.expires_at > now()
    AND ir.type = 'like_with_note'
    AND (
      (ir.actor_id = NEW.user1_id AND ir.recipient_id = NEW.user2_id)
      OR (ir.actor_id = NEW.user2_id AND ir.recipient_id = NEW.user1_id)
    );

  -- Close any other pending requests between them (they're now matched; chat is the primary channel).
  UPDATE public.intent_requests ir
  SET status = 'matched',
      metadata = ir.metadata || jsonb_build_object('auto_closed_by', 'match', 'match_id', NEW.id)
  WHERE ir.status = 'pending'
    AND ir.expires_at > now()
    AND ir.type <> 'like_with_note'
    AND (
      (ir.actor_id = NEW.user1_id AND ir.recipient_id = NEW.user2_id)
      OR (ir.actor_id = NEW.user2_id AND ir.recipient_id = NEW.user1_id)
    );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trg_close_intents_on_match_accept"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_enqueue_profile_quality_metrics_from_matches"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_profile_ids uuid[] := '{}'::uuid[];
  v_new_user1_id uuid := null;
  v_new_user2_id uuid := null;
  v_old_user1_id uuid := null;
  v_old_user2_id uuid := null;
begin
  if tg_op <> 'DELETE' then
    v_new_user1_id := new.user1_id;
    v_new_user2_id := new.user2_id;
  end if;
  if tg_op <> 'INSERT' then
    v_old_user1_id := old.user1_id;
    v_old_user2_id := old.user2_id;
  end if;

  select coalesce(array_agg(distinct changed.profile_id), '{}'::uuid[])
    into v_profile_ids
  from (
    values
      (v_new_user1_id),
      (v_new_user2_id),
      (v_old_user1_id),
      (v_old_user2_id)
  ) as changed(profile_id)
  where changed.profile_id is not null;

  if coalesce(array_length(v_profile_ids, 1), 0) > 0 then
    foreach v_new_user1_id in array v_profile_ids loop
      perform public.enqueue_vibes_v4_metric_refresh(
        v_new_user1_id,
        false,
        true,
        false,
        'matches'
      );
    end loop;
  end if;

  return null;
end;
$$;


ALTER FUNCTION "public"."trg_enqueue_profile_quality_metrics_from_matches"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_enqueue_profile_quality_metrics_from_messages"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_ids uuid[] := '{}'::uuid[];
  v_profile_ids uuid[] := '{}'::uuid[];
  v_new_sender_id uuid := null;
  v_new_receiver_id uuid := null;
  v_old_sender_id uuid := null;
  v_old_receiver_id uuid := null;
begin
  if tg_op <> 'DELETE' then
    v_new_sender_id := new.sender_id;
    v_new_receiver_id := new.receiver_id;
  end if;
  if tg_op <> 'INSERT' then
    v_old_sender_id := old.sender_id;
    v_old_receiver_id := old.receiver_id;
  end if;

  select coalesce(array_agg(distinct changed.user_id), '{}'::uuid[])
    into v_user_ids
  from (
    values
      (v_new_sender_id),
      (v_new_receiver_id),
      (v_old_sender_id),
      (v_old_receiver_id)
  ) as changed(user_id)
  where changed.user_id is not null;

  select coalesce(array_agg(profile.id), '{}'::uuid[])
    into v_profile_ids
  from public.profiles profile
  where profile.user_id = any(v_user_ids)
    and profile.deleted_at is null;

  if coalesce(array_length(v_profile_ids, 1), 0) > 0 then
    foreach v_new_sender_id in array v_profile_ids loop
      perform public.enqueue_vibes_v4_metric_refresh(
        v_new_sender_id,
        false,
        true,
        false,
        'messages'
      );
    end loop;
  end if;

  return null;
end;
$$;


ALTER FUNCTION "public"."trg_enqueue_profile_quality_metrics_from_messages"() OWNER TO "postgres";


