CREATE OR REPLACE FUNCTION "public"."trg_refresh_chat_conversation_summary_from_messages"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_is_receipt_only boolean := false;
  v_receiver_unread_delta integer := 0;
begin
  if tg_op = 'INSERT' then
    perform public.upsert_chat_conversation_summary_from_message(
      new.sender_id,
      new.receiver_id,
      new.id,
      0
    );
    perform public.upsert_chat_conversation_summary_from_message(
      new.receiver_id,
      new.sender_id,
      new.id,
      case when coalesce(new.is_read, false) then 0 else 1 end
    );
    return null;
  end if;

  if tg_op = 'DELETE' then
    perform public.refresh_chat_conversation_summary(old.sender_id, old.receiver_id);
    perform public.refresh_chat_conversation_summary(old.receiver_id, old.sender_id);
    return null;
  end if;

  v_is_receipt_only := (
    to_jsonb(new) - array['is_read', 'read_at', 'delivered_at']::text[]
  ) is not distinct from (
    to_jsonb(old) - array['is_read', 'read_at', 'delivered_at']::text[]
  );

  if v_is_receipt_only then
    update public.chat_conversation_summaries summary
    set last_message_is_read = new.is_read,
        last_message_delivered_at = new.delivered_at,
        updated_at = timezone('utc'::text, now())
    where summary.last_message_id = new.id
      and (
        (summary.owner_user_id = new.sender_id and summary.peer_user_id = new.receiver_id)
        or
        (summary.owner_user_id = new.receiver_id and summary.peer_user_id = new.sender_id)
      )
      and (
        summary.last_message_is_read is distinct from new.is_read
        or summary.last_message_delivered_at is distinct from new.delivered_at
      );

    if coalesce(old.is_read, false) = false
      and coalesce(new.is_read, false) = true
      and not exists (
        select 1
        from public.message_hides hidden
        where hidden.user_id = new.receiver_id
          and hidden.message_id = new.id
      ) then
      v_receiver_unread_delta := 1;
    end if;

    if v_receiver_unread_delta > 0 then
      update public.chat_conversation_summaries summary
      set unread_count = greatest(summary.unread_count - v_receiver_unread_delta, 0),
          updated_at = timezone('utc'::text, now())
      where summary.owner_user_id = new.receiver_id
        and summary.peer_user_id = new.sender_id
        and summary.unread_count > 0;
    end if;
    return null;
  end if;

  perform public.refresh_chat_conversation_summary(new.sender_id, new.receiver_id);
  perform public.refresh_chat_conversation_summary(new.receiver_id, new.sender_id);
  return null;
end;
$$;


ALTER FUNCTION "public"."trg_refresh_chat_conversation_summary_from_messages"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_refresh_chat_conversation_summary_from_reactions"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_message_id uuid := coalesce(new.message_id, old.message_id);
  v_sender uuid;
  v_receiver uuid;
  v_message_type text;
  v_reaction_emoji text;
  v_reaction_user_id uuid;
  v_reaction_created_at timestamptz;
begin
  select
    message_row.sender_id,
    message_row.receiver_id,
    coalesce(message_row.message_type, 'text')
  into v_sender, v_receiver, v_message_type
  from public.messages message_row
  where message_row.id = v_message_id;

  if v_sender is null or v_receiver is null then
    return null;
  end if;

  if tg_op = 'DELETE' then
    perform public.refresh_chat_conversation_summary(v_sender, v_receiver);
    perform public.refresh_chat_conversation_summary(v_receiver, v_sender);
    return null;
  end if;

  select reaction.emoji, reaction.user_id, reaction.created_at
    into v_reaction_emoji, v_reaction_user_id, v_reaction_created_at
  from public.message_reactions reaction
  where reaction.message_id = v_message_id
  order by reaction.created_at desc, reaction.id desc
  limit 1;

  update public.chat_conversation_summaries summary
  set last_message_reaction_emoji = v_reaction_emoji,
      last_message_reaction_user_id = v_reaction_user_id,
      last_message_reaction_created_at = v_reaction_created_at,
      last_message_reaction_target_type = case
        when v_reaction_user_id is null then null
        else v_message_type
      end,
      updated_at = timezone('utc'::text, now())
  where summary.last_message_id = v_message_id
    and (
      (summary.owner_user_id = v_sender and summary.peer_user_id = v_receiver)
      or
      (summary.owner_user_id = v_receiver and summary.peer_user_id = v_sender)
    );

  update public.chat_conversation_summaries summary
  set last_activity_kind = 'reaction',
      last_activity_message_id = v_message_id,
      last_activity_preview = case
        when v_reaction_user_id = summary.owner_user_id then
          case
            when nullif(btrim(v_reaction_emoji), '') is null
              then 'You reacted to their message'
            else 'You reacted ' || v_reaction_emoji || ' to their message'
          end
        else
          case
            when nullif(btrim(v_reaction_emoji), '') is null
              then 'Reacted to your message'
            else 'Reacted ' || v_reaction_emoji || ' to your message'
          end
      end,
      last_activity_at = v_reaction_created_at,
      updated_at = timezone('utc'::text, now())
  where (
      (summary.owner_user_id = v_sender and summary.peer_user_id = v_receiver)
      or
      (summary.owner_user_id = v_receiver and summary.peer_user_id = v_sender)
    )
    and v_reaction_created_at > summary.last_message_created_at
    and v_reaction_created_at >= coalesce(
      summary.last_activity_at,
      '-infinity'::timestamptz
    );

  return null;
end;
$$;


ALTER FUNCTION "public"."trg_refresh_chat_conversation_summary_from_reactions"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_refresh_profile_visibility_entitlements_from_boosts"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_profile_ids uuid[] := '{}'::uuid[];
  v_profile_id uuid;
  v_new_profile_id uuid := null;
  v_old_profile_id uuid := null;
begin
  if tg_op <> 'DELETE' then
    v_new_profile_id := new.user_id;
  end if;
  if tg_op <> 'INSERT' then
    v_old_profile_id := old.user_id;
  end if;

  select coalesce(array_agg(distinct changed.profile_id), '{}'::uuid[])
    into v_profile_ids
  from (
    values (v_new_profile_id), (v_old_profile_id)
  ) as changed(profile_id)
  where changed.profile_id is not null;

  foreach v_profile_id in array v_profile_ids loop
    perform public.refresh_profile_visibility_entitlements(array[v_profile_id]);
  end loop;

  return null;
end;
$$;


ALTER FUNCTION "public"."trg_refresh_profile_visibility_entitlements_from_boosts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_refresh_profile_visibility_entitlements_from_profiles"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_profile_id uuid;
begin
  if tg_op = 'DELETE' then
    v_profile_id := old.id;
    if v_profile_id is null then
      return null;
    end if;

    delete from public.profile_visibility_entitlements ent where ent.profile_id = v_profile_id;
    delete from public.profile_recommendation_quality_metrics metrics where metrics.profile_id = v_profile_id;
    delete from public.vibes_v4_metric_refresh_queue queue_row where queue_row.profile_id = v_profile_id;
    return null;
  else
    v_profile_id := new.id;
  end if;

  if v_profile_id is null then
    return null;
  end if;

  if new.deleted_at is not null then
    delete from public.profile_visibility_entitlements ent where ent.profile_id = v_profile_id;
    delete from public.profile_recommendation_quality_metrics metrics where metrics.profile_id = v_profile_id;
    delete from public.vibes_v4_metric_refresh_queue queue_row where queue_row.profile_id = v_profile_id;
    return null;
  end if;

  perform public.refresh_profile_visibility_entitlements(array[v_profile_id]);
  return null;
end;
$$;


ALTER FUNCTION "public"."trg_refresh_profile_visibility_entitlements_from_profiles"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_refresh_profile_visibility_entitlements_from_subscriptions"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_ids uuid[] := '{}'::uuid[];
  v_user_id uuid;
  v_profile_ids uuid[] := '{}'::uuid[];
  v_new_user_id uuid := null;
  v_old_user_id uuid := null;
begin
  if tg_op <> 'DELETE' then
    v_new_user_id := new.user_id;
  end if;
  if tg_op <> 'INSERT' then
    v_old_user_id := old.user_id;
  end if;

  select coalesce(array_agg(distinct changed.user_id), '{}'::uuid[])
    into v_user_ids
  from (
    values (v_new_user_id), (v_old_user_id)
  ) as changed(user_id)
  where changed.user_id is not null;

  foreach v_user_id in array v_user_ids loop
    select coalesce(array_agg(profile.id), '{}'::uuid[])
      into v_profile_ids
    from public.profiles profile
    where profile.user_id = v_user_id
      and profile.deleted_at is null;

    if coalesce(array_length(v_profile_ids, 1), 0) > 0 then
      perform public.refresh_profile_visibility_entitlements(v_profile_ids);
    end if;
  end loop;

  return null;
end;
$$;


ALTER FUNCTION "public"."trg_refresh_profile_visibility_entitlements_from_subscriptions"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_refresh_viewer_behavior_summary_from_vibes_events"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_changes record;
  v_new_viewer_profile_id uuid := null;
  v_new_target_profile_id uuid := null;
  v_old_viewer_profile_id uuid := null;
  v_old_target_profile_id uuid := null;
begin
  if tg_op <> 'DELETE' then
    v_new_viewer_profile_id := new.viewer_profile_id;
    v_new_target_profile_id := new.target_profile_id;
  end if;
  if tg_op <> 'INSERT' then
    v_old_viewer_profile_id := old.viewer_profile_id;
    v_old_target_profile_id := old.target_profile_id;
  end if;

  for v_changes in
    select distinct changed.viewer_profile_id, changed.target_profile_id
    from (
      values
        (v_new_viewer_profile_id, v_new_target_profile_id),
        (v_old_viewer_profile_id, v_old_target_profile_id)
    ) as changed(viewer_profile_id, target_profile_id)
    where changed.viewer_profile_id is not null
      and changed.target_profile_id is not null
  loop
    perform public.refresh_viewer_profile_behavior_summary(
      v_changes.viewer_profile_id,
      array[v_changes.target_profile_id]
    );
  end loop;

  return null;
end;
$$;


