CREATE OR REPLACE FUNCTION "public"."update_travel_status"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  travel_detection RECORD;
BEGIN
  -- Detect travel for the updated user
  SELECT * INTO travel_detection
  FROM detect_travel_for_user(NEW.user_id);

  -- Update travel fields
  NEW.is_traveling := travel_detection.is_traveling;
  NEW.current_travel_mode := travel_detection.travel_mode;
  NEW.updated_at := NOW();

  -- Record travel history if travel detected
  IF travel_detection.is_traveling AND NOT OLD.is_traveling THEN
    INSERT INTO travel_history (
      user_id,
      travel_mode,
      origin_location,
      destination_location,
      distance_km,
      start_date
    ) VALUES (
      NEW.user_id,
      travel_detection.travel_mode,
      OLD.current_location,
      NEW.current_location,
      travel_detection.distance_from_home,
      NOW()
    );
  END IF;

  RETURN NEW;
END;
$$;


