CREATE OR REPLACE FUNCTION "public"."upsert_chat_conversation_summary_from_message"("p_owner_user_id" "uuid", "p_peer_user_id" "uuid", "p_message_id" "uuid", "p_unread_increment" integer DEFAULT 0) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_message public.messages%rowtype;
begin
  if p_owner_user_id is null
    or p_peer_user_id is null
    or p_message_id is null
    or p_owner_user_id = p_peer_user_id then
    return;
  end if;

  select message_row.*
    into v_message
  from public.messages message_row
  where message_row.id = p_message_id;

  if v_message.id is null then
    return;
  end if;

  insert into public.chat_conversation_summaries (
    owner_user_id,
    peer_user_id,
    last_message_id,
    last_message_text,
    last_message_created_at,
    last_message_sender_id,
    last_message_receiver_id,
    last_message_is_read,
    last_message_delivered_at,
    last_message_type,
    last_message_is_view_once,
    last_message_deleted_for_all,
    last_message_edited_at,
    unread_count,
    updated_at
  )
  values (
    p_owner_user_id,
    p_peer_user_id,
    v_message.id,
    v_message.text,
    v_message.created_at,
    v_message.sender_id,
    v_message.receiver_id,
    v_message.is_read,
    v_message.delivered_at,
    coalesce(v_message.message_type, 'text'),
    coalesce(v_message.is_view_once, false),
    coalesce(v_message.deleted_for_all, false),
    v_message.edited_at,
    greatest(coalesce(p_unread_increment, 0), 0),
    timezone('utc'::text, now())
  )
  on conflict (owner_user_id, peer_user_id) do update
  set last_message_id = case
        when excluded.last_message_created_at > coalesce(chat_conversation_summaries.last_message_created_at, '-infinity'::timestamptz)
          or (
            excluded.last_message_created_at = chat_conversation_summaries.last_message_created_at
            and excluded.last_message_id > chat_conversation_summaries.last_message_id
          )
        then excluded.last_message_id
        else chat_conversation_summaries.last_message_id
      end,
      last_message_text = case
        when excluded.last_message_created_at > coalesce(chat_conversation_summaries.last_message_created_at, '-infinity'::timestamptz)
          or (
            excluded.last_message_created_at = chat_conversation_summaries.last_message_created_at
            and excluded.last_message_id > chat_conversation_summaries.last_message_id
          )
        then excluded.last_message_text
        else chat_conversation_summaries.last_message_text
      end,
      last_message_created_at = greatest(
        coalesce(chat_conversation_summaries.last_message_created_at, '-infinity'::timestamptz),
        excluded.last_message_created_at
      ),
      last_message_sender_id = case
        when excluded.last_message_created_at > coalesce(chat_conversation_summaries.last_message_created_at, '-infinity'::timestamptz)
          or (
            excluded.last_message_created_at = chat_conversation_summaries.last_message_created_at
            and excluded.last_message_id > chat_conversation_summaries.last_message_id
          )
        then excluded.last_message_sender_id
        else chat_conversation_summaries.last_message_sender_id
      end,
      last_message_receiver_id = case
        when excluded.last_message_created_at > coalesce(chat_conversation_summaries.last_message_created_at, '-infinity'::timestamptz)
          or (
            excluded.last_message_created_at = chat_conversation_summaries.last_message_created_at
            and excluded.last_message_id > chat_conversation_summaries.last_message_id
          )
        then excluded.last_message_receiver_id
        else chat_conversation_summaries.last_message_receiver_id
      end,
      last_message_is_read = case
        when excluded.last_message_created_at > coalesce(chat_conversation_summaries.last_message_created_at, '-infinity'::timestamptz)
          or (
            excluded.last_message_created_at = chat_conversation_summaries.last_message_created_at
            and excluded.last_message_id > chat_conversation_summaries.last_message_id
          )
        then excluded.last_message_is_read
        else chat_conversation_summaries.last_message_is_read
      end,
      last_message_delivered_at = case
        when excluded.last_message_created_at > coalesce(chat_conversation_summaries.last_message_created_at, '-infinity'::timestamptz)
          or (
            excluded.last_message_created_at = chat_conversation_summaries.last_message_created_at
            and excluded.last_message_id > chat_conversation_summaries.last_message_id
          )
        then excluded.last_message_delivered_at
        else chat_conversation_summaries.last_message_delivered_at
      end,
      last_message_type = case
        when excluded.last_message_created_at > coalesce(chat_conversation_summaries.last_message_created_at, '-infinity'::timestamptz)
          or (
            excluded.last_message_created_at = chat_conversation_summaries.last_message_created_at
            and excluded.last_message_id > chat_conversation_summaries.last_message_id
          )
        then excluded.last_message_type
        else chat_conversation_summaries.last_message_type
      end,
      last_message_is_view_once = case
        when excluded.last_message_created_at > coalesce(chat_conversation_summaries.last_message_created_at, '-infinity'::timestamptz)
          or (
            excluded.last_message_created_at = chat_conversation_summaries.last_message_created_at
            and excluded.last_message_id > chat_conversation_summaries.last_message_id
          )
        then excluded.last_message_is_view_once
        else chat_conversation_summaries.last_message_is_view_once
      end,
      last_message_deleted_for_all = case
        when excluded.last_message_created_at > coalesce(chat_conversation_summaries.last_message_created_at, '-infinity'::timestamptz)
          or (
            excluded.last_message_created_at = chat_conversation_summaries.last_message_created_at
            and excluded.last_message_id > chat_conversation_summaries.last_message_id
          )
        then excluded.last_message_deleted_for_all
        else chat_conversation_summaries.last_message_deleted_for_all
      end,
      last_message_edited_at = case
        when excluded.last_message_created_at > coalesce(chat_conversation_summaries.last_message_created_at, '-infinity'::timestamptz)
          or (
            excluded.last_message_created_at = chat_conversation_summaries.last_message_created_at
            and excluded.last_message_id > chat_conversation_summaries.last_message_id
          )
        then excluded.last_message_edited_at
        else chat_conversation_summaries.last_message_edited_at
      end,
      unread_count = greatest(
        chat_conversation_summaries.unread_count + greatest(coalesce(p_unread_increment, 0), 0),
        0
      ),
      updated_at = excluded.updated_at;
end;
$$;


ALTER FUNCTION "public"."upsert_chat_conversation_summary_from_message"("p_owner_user_id" "uuid", "p_peer_user_id" "uuid", "p_message_id" "uuid", "p_unread_increment" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_push_token"("p_user_id" "uuid", "p_token" "text", "p_platform" "text", "p_device_id" "text", "p_app_version" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Prevent callers from spoofing user_id
  IF auth.uid() IS NULL OR auth.uid() <> p_user_id THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  INSERT INTO public.push_tokens (
    user_id,
    token,
    platform,
    device_id,
    app_version,
    last_seen_at,
    updated_at
  )
  VALUES (
    p_user_id,
    p_token,
    p_platform,
    p_device_id,
    p_app_version,
    now(),
    now()
  )
  ON CONFLICT (token)
  DO UPDATE SET
    user_id = EXCLUDED.user_id,
    platform = EXCLUDED.platform,
    device_id = EXCLUDED.device_id,
    app_version = EXCLUDED.app_version,
    last_seen_at = now(),
    updated_at = now();
END;
$$;


ALTER FUNCTION "public"."upsert_push_token"("p_user_id" "uuid", "p_token" "text", "p_platform" "text", "p_device_id" "text", "p_app_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."verification_requests_guard_redundant_pending"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_current_verification_level integer;
  v_required_verification_level integer;
  v_refresh_required boolean;
  v_refresh_target_level integer;
  v_social_already_approved boolean;
  v_allows_refresh boolean;
begin
  if coalesce(new.status, 'pending') <> 'pending' then
    return new;
  end if;

  v_required_verification_level := case lower(coalesce(new.verification_type, ''))
    when 'social' then 1
    when 'selfie_liveness' then 2
    when 'passport' then 2
    when 'residence' then 2
    when 'workplace' then 2
    else null
  end;

  if v_required_verification_level is null then
    return new;
  end if;

  select
    coalesce(p.verification_level, 0),
    coalesce(p.verification_refresh_required, false),
    coalesce(p.verification_refresh_target_level, p.verification_level, 1)
  into v_current_verification_level, v_refresh_required, v_refresh_target_level
  from public.profiles p
  where p.id = new.profile_id
  limit 1;

  v_allows_refresh := coalesce(v_refresh_required, false)
    and v_required_verification_level >= least(greatest(coalesce(v_refresh_target_level, 1), 1), 2);

  if lower(coalesce(new.verification_type, '')) = 'social' then
    select exists (
      select 1
      from public.verification_requests vr
      where vr.profile_id = new.profile_id
        and lower(coalesce(vr.verification_type, '')) = 'social'
        and coalesce(vr.status, 'pending') = 'approved'
    )
    into v_social_already_approved;

    if (v_social_already_approved or coalesce(v_current_verification_level, 0) >= 2)
       and not v_allows_refresh then
      if v_social_already_approved then
        raise exception 'profile already has this verification method';
      end if;
      raise exception 'profile already has this verification level';
    end if;

    return new;
  end if;

  if coalesce(v_current_verification_level, 0) >= v_required_verification_level
     and not v_allows_refresh then
    raise exception 'profile already has this verification level';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."verification_requests_guard_redundant_pending"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vibes_real_distance_km"("p_lat1" double precision, "p_lon1" double precision, "p_lat2" double precision, "p_lon2" double precision) RETURNS double precision
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  select
    case
      when not public.has_usable_vibes_coordinates(p_lat1, p_lon1)
        or not public.has_usable_vibes_coordinates(p_lat2, p_lon2)
        then null::double precision
      else
        6371 * 2 * asin(
          sqrt(
            power(sin(radians((p_lat2 - p_lat1) / 2)), 2)
            + cos(radians(p_lat1))
            * cos(radians(p_lat2))
            * power(sin(radians((p_lon2 - p_lon1) / 2)), 2)
          )
        )
    end
$$;


ALTER FUNCTION "public"."vibes_real_distance_km"("p_lat1" double precision, "p_lon1" double precision, "p_lat2" double precision, "p_lon2" double precision) OWNER TO "postgres";


