CREATE OR REPLACE VIEW "public"."circle_location_features" AS
 SELECT "id" AS "circle_id",
    "name",
    "slug",
    "description",
    "short_description",
    "visibility",
    "category",
    "created_by_profile_id",
    "cover_image_url",
    "icon_url",
    "image_path",
    "image_updated_at",
    "circle_type",
    "status",
    "visibility_scope",
    "country_code",
    "country_name",
    "region",
    "city",
    "diaspora_tags",
    "culture_tags",
    "faith_tags",
    "interest_tags",
    "audience_tags",
    "is_official",
    "is_partner",
    "is_featured",
    "requires_join_approval",
    "member_count",
    "active_this_week_count",
    "gathering_count",
    "archived_at",
    "created_at",
    "public"."normalize_location_key"("city") AS "city_key",
    "public"."normalize_location_key"("region") AS "region_key",
    "public"."normalize_location_key"(COALESCE("country_code", "country_name")) AS "country_key",
    "upper"("btrim"(COALESCE("country_code", ''::"text"))) AS "normalized_country_code"
   FROM "public"."circles" "c";


ALTER VIEW "public"."circle_location_features" OWNER TO "postgres";


