    CONSTRAINT "profiles_last_successful_auth_provider_check" CHECK ((("last_successful_auth_provider" IS NULL) OR ("last_successful_auth_provider" = ANY (ARRAY['apple'::"text", 'google'::"text", 'email'::"text", 'magic_link'::"text"])))),
