CREATE OR REPLACE VIEW "public"."profile_location_features" AS
 SELECT "id" AS "profile_id",
    "user_id",
    "city",
    "region",
    "current_country",
    "current_country_code",
    "public"."normalize_location_key"("city") AS "city_key",
    "public"."normalize_location_key"("region") AS "region_key",
    "public"."normalize_location_key"(COALESCE("current_country_code", "current_country")) AS "country_key",
    "upper"("btrim"(COALESCE("current_country_code", ''::"text"))) AS "country_code",
        CASE
            WHEN ("upper"("btrim"(COALESCE("current_country_code", ''::"text"))) <> ''::"text") THEN ("upper"("btrim"(COALESCE("current_country_code", ''::"text"))) <> 'GH'::"text")
            WHEN ("public"."normalize_location_key"("current_country") IS NOT NULL) THEN ("public"."normalize_location_key"("current_country") <> 'ghana'::"text")
            ELSE false
        END AS "is_abroad"
   FROM "public"."profiles" "p"
  WHERE ("deleted_at" IS NULL);


ALTER VIEW "public"."profile_location_features" OWNER TO "postgres";


