CREATE OR REPLACE VIEW "public"."public_user_locations" WITH ("security_invoker"='on') AS
 SELECT "user_id",
        CASE
            WHEN ("privacy_level" = 'exact'::"text") THEN "current_location"
            WHEN ("privacy_level" = 'city'::"text") THEN ( SELECT "ghana_locations"."location"
               FROM "public"."ghana_locations"
              WHERE (("ghana_locations"."name" = ("user_location_profiles"."current_address" ->> 'city'::"text")) AND ("ghana_locations"."type" = 'city'::"text"))
             LIMIT 1)
            WHEN ("privacy_level" = 'region'::"text") THEN ( SELECT "ghana_locations"."location"
               FROM "public"."ghana_locations"
              WHERE (("ghana_locations"."name" = "user_location_profiles"."ghana_region") AND ("ghana_locations"."type" = 'region'::"text"))
             LIMIT 1)
            WHEN ("privacy_level" = 'country'::"text") THEN "public"."st_geogfromtext"('POINT(-1.0232 7.9465)'::"text")
            ELSE NULL::"public"."geography"
        END AS "display_location",
    "privacy_level",
    "ghana_region",
        CASE
            WHEN ("privacy_level" = ANY (ARRAY['exact'::"text", 'city'::"text", 'region'::"text"])) THEN "hometown"
            ELSE NULL::"text"
        END AS "display_hometown",
    "diaspora_status",
    "is_traveling",
    "current_travel_mode"
   FROM "public"."user_location_profiles"
  WHERE (("location_sharing" ->> 'isEnabled'::"text") = 'true'::"text");


ALTER VIEW "public"."public_user_locations" OWNER TO "postgres";


