CREATE TRIGGER trigger_update_travel_status BEFORE UPDATE OF current_location ON public.user_location_profiles FOR EACH ROW WHEN ((old.current_location IS DISTINCT FROM new.current_location)) EXECUTE FUNCTION public.update_travel_status();


